    task.spawn(function()
        local function setProgress(pct, statusText)
            pctLbl.Text = tostring(math.floor(pct * 100)) .. "%"
            if statusText then statusLbl.Text = "> " .. statusText end
            TweenService:Create(barFill, TweenInfo.new(0.2, Enum.EasingStyle.Quad, Enum.EasingDirection.Out), {
                Size = UDim2.new(math.clamp(pct, 0, 1), 0, 1, 0)
            }):Play()
        end
        setProgress(0.12, "Connecting to Brookhaven...")
        if not game:IsLoaded() then game.Loaded:Wait() end
        task.wait(0.04)
        local char = lp.Character or lp.CharacterAdded:Wait()
