            char:WaitForChild(_0xS(6), 3)
        end
        task.wait(0.04)
        local maxWait = 90.0
        local elapsed = 0
        local currentVisualProg = 0.15
        while not _G.BTR_ALL_LOADED and elapsed < maxWait do
            task.wait(0.05)
            elapsed = elapsed + 0.05
            local targetProg = _G.BTR_LOAD_PROGRESS or (0.15 + (0.80 * math.min(elapsed / 15, 1)))
            targetProg = math.clamp(targetProg, 0.15, 0.98)
            currentVisualProg = currentVisualProg + (targetProg - currentVisualProg) * 0.25
            local currentStatus = _G.BTR_LOAD_STATUS or "Loading interface & modules..."
            setProgress(currentVisualProg, currentStatus)
        end
