-- Auto-cleanup previous overlays if present
local function _cleanupBTRTutorial()
    local CoreGui = (gethui and gethui()) or game:GetService(_0xS(12))
    local lp = game:GetService(_0xS(1)).LocalPlayer
    local pg = lp and lp:FindFirstChild(_0xS(13))
    local existingTour = CoreGui:FindFirstChild(_0xS(23)) or (pg and pg:FindFirstChild(_0xS(23)))
    if existingTour then pcall(function() existingTour:Destroy() end) end
    local existingNotice = CoreGui:FindFirstChild(_0xS(24)) or (pg and pg:FindFirstChild(_0xS(24)))
    if existingNotice then pcall(function() existingNotice:Destroy() end) end
    local existingPatch = CoreGui:FindFirstChild(_0xS(25)) or (pg and pg:FindFirstChild(_0xS(25)))
    if existingPatch then pcall(function() existingPatch:Destroy() end) end
_cleanupBTRTutorial()
local function hasCompletedTour()
    if _G.BTR_TOUR_COMPLETED then return true end
    if isfile and type(isfile) == "function" then
        local ok, res = pcall(function() return isfile(BTR_TOUR_FLAG_FILE) end)
        if ok and res then return true end
    end
    return false
local function markTourCompleted()
    _G.BTR_TOUR_COMPLETED = true
    if writefile and type(writefile) == "function" then
        pcall(function() writefile(BTR_TOUR_FLAG_FILE, "seen") end)
    end
local function hasSeenPatchNotes()
    if _G.BTR_PATCHNOTES_SEEN then return true end
    if isfile and type(isfile) == "function" then
        local ok, res = pcall(function() return isfile(BTR_PATCH_FLAG_FILE) end)
        if ok and res then return true end
    end
    return false
local function markPatchNotesSeen()
    _G.BTR_PATCHNOTES_SEEN = true
    if writefile and type(writefile) == "function" then
        pcall(function() writefile(BTR_PATCH_FLAG_FILE, "seen") end)
    end
