    btnSkip.BackgroundColor3 = Color3.fromRGB(28, 32, 45)
    btnSkip.Font = Enum.Font.GothamBold
    btnSkip.TextSize = 11
    btnSkip.TextColor3 = Color3.fromRGB(185, 190, 205)
    btnSkip.Text = "Skip"
    btnSkip.Parent = footer
    Instance.new("UICorner", btnSkip).CornerRadius = UDim.new(0, 8)
    local isClosing = false
    local function dismiss(startTour)
        if isClosing then return end
        isClosing = true
        markTourCompleted()
        pcall(function()
            TweenService:Create(cardStroke, TweenInfo.new(0.2), { Transparency = 1 }):Play()
            TweenService:Create(card, TweenInfo.new(0.2), { BackgroundTransparency = 1 }):Play()
            TweenService:Create(bgOverlay, TweenInfo.new(0.25), { BackgroundTransparency = 1 }):Play()
        end)
        task.wait(0.26)
        pcall(function() sg:Destroy() end)
        if startTour and startBTRTutorial then
            task.spawn(function() startBTRTutorial(true) end)
        end
    end
    btnTour.Activated:Connect(function() dismiss(true) end)
    btnSkip.Activated:Connect(function() dismiss(false) end)
    closeBtn.Activated:Connect(function() dismiss(false) end)
    TweenService:Create(bgOverlay, TweenInfo.new(0.3), { BackgroundTransparency = 0.45 }):Play()
    TweenService:Create(card, TweenInfo.new(0.3), { BackgroundTransparency = 0 }):Play()
    TweenService:Create(cardStroke, TweenInfo.new(0.3), { Transparency = 0.25 }):Play()
