    local function requestHttp(url)
        local req = (syn and syn.request) or (http and http.request) or http_request or (fluxus and fluxus.request) or request
        if req then
            local ok, resp = pcall(function()
                return req({
                    Url = url,
                    Method = "GET",
                    Headers = {
                        ["User-Agent"] = "Mozilla/5.0 (Windows NT 10.0; Win64; x64)"
                    }
                })
            end)
            if ok and resp and (resp.StatusCode == 200 or resp.Status == 200) then
                return resp.Body
            end
        end
        if game.HttpGet then
            local ok, res = pcall(function()
                return game:HttpGet(url)
            end)
            if ok and res then return res end
        end
        return nil
    end
    local function translateText(text, fromLang, toLang)
        if not text or text == "" then return text, fromLang end
        fromLang = fromLang or "auto"
        toLang = toLang or "es"
        if fromLang == toLang and fromLang ~= "auto" then return text, fromLang end
        local encoded = HttpService:UrlEncode(text)
        
        local gUrl = _0xS(71) .. fromLang .. "&tl=" .. toLang .. "&q=" .. encoded
        local gRes = requestHttp(gUrl)
        if gRes then
            local ok, data = pcall(function() return HttpService:JSONDecode(gRes) end)
            if ok and data and type(data) == "table" and data[1] then
                local trans = nil
                local detected = nil
                if type(data[1]) == "table" then
                    trans = tostring(data[1][1] or "")
                    detected = tostring(data[1][2] or "")
                elseif type(data[1]) == "string" then
                    trans = tostring(data[1])
                end
                if trans and trans ~= "" then
                    return trans, detected
                end
            end
        end
        
        local gtxUrl = _0xS(72) .. fromLang .. "&tl=" .. toLang .. "&dt=t&q=" .. encoded
        local gtxRes = requestHttp(gtxUrl)
        if gtxRes then
            local ok, data = pcall(function() return HttpService:JSONDecode(gtxRes) end)
            if ok and data and type(data) == "table" and data[1] then
                local str = ""
                for _, seg in ipairs(data[1]) do
                    if type(seg) == "table" and seg[1] then
                        str = str .. tostring(seg[1])
                    end
                end
                if str ~= "" then
                    local det = nil
                    if data[3] and type(data[3]) == "string" then
                        det = data[3]
                    elseif data[2] and type(data[2]) == "string" then
                        det = data[2]
                    end
                    return str, det
                end
            end
        end
        
        local srcPair = (fromLang == "auto" and "fr" or fromLang)
        local memUrl = _0xS(73) .. encoded .. "&langpair=" .. srcPair .. "|" .. toLang
        local memRes = requestHttp(memUrl)
        if memRes then
            local ok, data = pcall(function() return HttpService:JSONDecode(memRes) end)
            if ok and data and data.responseData and data.responseData.translatedText then
                return tostring(data.responseData.translatedText), srcPair
            end
        end
        return text, fromLang
    end
    local function formatOutgoingMessage(original, translated, toLang)
        if _G.OutgoingFormat == "Translated Only" then
            return translated
        elseif _G.OutgoingFormat == "Trans + Original" then
            return translated .. " (" .. original .. ")"
        elseif _G.OutgoingFormat == "Tagged [LANG]" then
            return "[" .. string.upper(toLang) .. "] " .. translated
        end
        return translated
    end
    local function sendChatMsg(msg)
        if not msg or msg == "" then return end
        isSendingInternal = true
        local sent = false
        pcall(function()
            if TextChatService then
                local targetChannel = nil
                local cfg = TextChatService:FindFirstChildOfClass("ChatInputBarConfiguration") or TextChatService:FindFirstChild(_0xS(74))
                if cfg and cfg.TargetTextChannel then
                    targetChannel = cfg.TargetTextChannel
                end
                if not targetChannel then
                    local channels = TextChatService:FindFirstChild(_0xS(75)) or TextChatService:WaitForChild(_0xS(75), 1)
                    if channels then
                        targetChannel = channels:FindFirstChild(_0xS(76))
                        if not targetChannel then
                            for _, ch in ipairs(channels:GetChildren()) do
                                if ch:IsA("TextChannel") and ch.Name ~= "RBXSystem" then
                                    targetChannel = ch
                                    break
                                end
                            end
                        end
                    end
                end
                if targetChannel then
                    targetChannel:SendAsync(msg)
                    sent = true
                end
            end
        end)
        if not sent then
            pcall(function()
                local defaultChat = ReplicatedStorage:FindFirstChild(_0xS(77))
                local sayMsg = defaultChat and (defaultChat:FindFirstChild(_0xS(78)) or defaultChat:WaitForChild(_0xS(78), 1))
                if sayMsg then
                    sayMsg:FireServer(msg, "All")
                    sent = true
                end
            end)
        end
        if not sent then
            pcall(function()
                if TextChatService and TextChatService.TextChannels then
                    local gen = TextChatService.TextChannels:FindFirstChild(_0xS(76))
                    if gen then
                        gen:SendAsync(msg)
                        sent = true
                    end
                end
            end)
        end
        task.wait(0.12)
        isSendingInternal = false
    end
    local recentIncomingCache = {}
    local function isDuplicateIncoming(senderName, rawText)
        local now = os.clock()
        for k, t in pairs(recentIncomingCache) do
            if now - t > 4 then
                recentIncomingCache[k] = nil
            end
        end
        local key = tostring(senderName) .. "::" .. tostring(rawText)
        if recentIncomingCache[key] and (now - recentIncomingCache[key] < 3.0) then
            return true
        end
        recentIncomingCache[key] = now
        return false
    end
    local function displayTranslatedIncoming(senderName, original, translated, detected)
        local tag = string.upper(detected or "TRAD")
        local displayed = false
        
        pcall(function()
            if TextChatService then
                local channels = TextChatService:FindFirstChild(_0xS(75))
                local rbxGeneral = channels and channels:FindFirstChild(_0xS(76))
                if rbxGeneral then
                    rbxGeneral:DisplaySystemMessage(string.format("<font color='#00E5FF'>[%s] %s:</font> %s", tag, senderName, translated))
                    displayed = true
                end
            end
        end)
        
        if not displayed then
            pcall(function()
                StarterGui:SetCore("ChatMakeSystemMessage", {
                    Text = string.format("[%s] %s: %s", tag, senderName, translated),
                    Color = Color3.fromRGB(0, 229, 255),
                    Font = Enum.Font.SourceSansBold,
                    FontSize = Enum.FontSize.Size18
                })
            end)
        end
    end
    local function handleIncomingMessage(senderName, rawText)
        if not _G.AutoTranslateIncomingEnabled then return end
        if not rawText or rawText == "" then return end
        if senderName == LocalPlayer.Name or senderName == LocalPlayer.DisplayName then return end
        if isDuplicateIncoming(senderName, rawText) then return end
        task.spawn(function()
            local translated, detected = translateText(rawText, "auto", _G.IncomingTargetLang)
            if detected and detected:lower() == _G.IncomingTargetLang:lower() then return end
            if translated and translated ~= "" and translated:lower() ~= rawText:lower() then
                displayTranslatedIncoming(senderName, rawText, translated, detected)
            end
        end)
    end
    pcall(function()
        if TextChatService then
            TextChatService.MessageReceived:Connect(function(textChatMessage)
                local textSource = textChatMessage.TextSource
                if textSource then
                    local sender = Players:GetPlayerByUserId(textSource.UserId)
                    if sender and sender ~= LocalPlayer then
                        handleIncomingMessage(sender.DisplayName or sender.Name, textChatMessage.Text)
                    end
                end
            end)
        end
    end)
    local function hookPlayerLegacyChat(p)
        p.Chatted:Connect(function(msg)
            if p ~= LocalPlayer then
                handleIncomingMessage(p.DisplayName or p.Name, msg)
            end
