    Players.PlayerAdded:Connect(hookPlayerLegacyChat)
    local function isChatBar(tb)
        if not tb or not tb:IsA("TextBox") then return false end
        
        local p = tb
        while p do
            if p.Name == "RedzLib" or p.Name == "RedzLibHub" or p.Name == "BTR_UI" or p.Name == "AutoTranslateGui" then
                return false
            end
            p = p.Parent
        end
        if tb.Name == "ChatBar" then return true end
        if tb.PlaceholderText and (tb.PlaceholderText:lower():find("chat") or tb.PlaceholderText:find("Message") or tb.PlaceholderText:find("parler") or tb.PlaceholderText:find("discuter")) then
            return true
        end
        local isCore = false
        pcall(function()
            local expChat = CoreGui:FindFirstChild(_0xS(79))
            if expChat and tb:IsDescendantOf(expChat) then
                isCore = true
            end
        end)
        if isCore then return true end
        if TextChatService then
            local cfg = TextChatService:FindFirstChildOfClass("ChatInputBarConfiguration") or TextChatService:FindFirstChild(_0xS(74))
            if cfg and cfg.TextBox == tb then
                return true
            end
        end
        local pg = LocalPlayer:FindFirstChildOfClass("PlayerGui")
        if pg then
            local chat = pg:FindFirstChild(_0xS(80)) or pg:FindFirstChild(_0xS(79))
            if chat and tb:IsDescendantOf(chat) then
                return true
            end
        end
        return false
    end
    local function bindChatTextBox(tb)
        if not tb or not tb:IsA("TextBox") or hookedTextBoxes[tb] then return end
        hookedTextBoxes[tb] = true
        
        local isUpdatingLive = false
        tb:GetPropertyChangedSignal("Text"):Connect(function()
            if isUpdatingLive then return end
            if not _G.AutoCorrectEnabled then return end
            local current = tb.Text
            if not current or current == "" then return end
            local lastChar = current:sub(-1)
            if lastChar == " " or lastChar == "," or lastChar == "." or lastChar == "!" or lastChar == "?" then
                local corrected = autoCorrectText(current)
                if corrected ~= current then
                    isUpdatingLive = true
                    local oldLen = #current
                    local oldCursor = tb.CursorPosition
                    tb.Text = corrected
                    if oldCursor >= oldLen then
                        tb.CursorPosition = #corrected + 1
                    end
                    isUpdatingLive = false
                end
            end
        end)
        
        tb.FocusLost:Connect(function(enterPressed)
            if enterPressed and not isHandlingEnter then
                local rawText = tb.Text
                if rawText and rawText ~= "" and _G.AutoTranslateOutgoingEnabled then
                    isHandlingEnter = true
                    tb.Text = ""
                    task.spawn(function()
                        local toProcess = rawText
                        if _G.AutoCorrectEnabled then
                            toProcess = autoCorrectText(toProcess)
                        end
                        local trans = translateText(toProcess, "auto", _G.OutgoingTargetLang)
                        local finalMsg = formatOutgoingMessage(rawText, trans, _G.OutgoingTargetLang)
                        sendChatMsg(finalMsg)
                        task.wait(0.15)
                        isHandlingEnter = false
                    end)
                end
            end
        end)
    end
    UserInputService.InputBegan:Connect(function(input, gameProcessed)
        if input.KeyCode == Enum.KeyCode.Return or input.KeyCode == Enum.KeyCode.KeypadEnter then
            if isHandlingEnter then return end
            local focusedTb = UserInputService:GetFocusedTextBox()
            if not focusedTb then
                for tb, _ in pairs(hookedTextBoxes) do
                    if tb and tb.Parent and tb:IsFocused() then
                        focusedTb = tb
                        break
                    end
                end
            end
            if focusedTb and isChatBar(focusedTb) then
                local rawText = focusedTb.Text
                if rawText and rawText ~= "" then
                    if _G.AutoTranslateOutgoingEnabled then
                        isHandlingEnter = true
                        
                        focusedTb.Text = ""
                        pcall(function() focusedTb:ReleaseFocus() end)
                        task.spawn(function()
                            local toProcess = rawText
                            if _G.AutoCorrectEnabled then
                                toProcess = autoCorrectText(toProcess)
                            end
                            local trans = translateText(toProcess, "auto", _G.OutgoingTargetLang)
                            local finalMsg = formatOutgoingMessage(rawText, trans, _G.OutgoingTargetLang)
                            sendChatMsg(finalMsg)
                            task.wait(0.15)
                            isHandlingEnter = false
                        end)
                    elseif _G.AutoCorrectEnabled then
                        local corrected = autoCorrectText(rawText)
                        if corrected ~= rawText then
                            focusedTb.Text = corrected
