local function c3ToTable(c)
    return {math.floor(c.R * 255 + 0.5), math.floor(c.G * 255 + 0.5), math.floor(c.B * 255 + 0.5)}
local function tableToC3(t, def)
    if type(t) == "table" and #t >= 3 then
        return Color3.fromRGB(t[1], t[2], t[3])
    end
    return def
local isRainbowNameActive = (_G.BTR_RGB_NAME_ACTIVE == true)
local isRainbowBioActive  = (_G.BTR_RGB_BIO_ACTIVE == true)
local rainbowSpeed        = _G.BTR_RAINBOW_SPEED or 5
local nameColorMode       = _G.BTR_NAME_COLOR_MODE or "Full Rainbow (RGB)"
local bioColorMode        = _G.BTR_BIO_COLOR_MODE or "Full Rainbow (RGB)"
local nameCol1 = tableToC3(_G.BTR_NAME_COL1, Color3.fromRGB(0, 255, 255))
local nameCol2 = tableToC3(_G.BTR_NAME_COL2, Color3.fromRGB(170, 0, 255))
local nameCol3 = tableToC3(_G.BTR_NAME_COL3, Color3.fromRGB(255, 0, 128))
local bioCol1  = tableToC3(_G.BTR_BIO_COL1, Color3.fromRGB(50, 255, 50))
local bioCol2  = tableToC3(_G.BTR_BIO_COL2, Color3.fromRGB(255, 215, 0))
local bioCol3  = tableToC3(_G.BTR_BIO_COL3, Color3.fromRGB(255, 30, 30))
local function lerpColorHSV(c1, c2, alpha)
    local h1, s1, v1 = c1:ToHSV()
    local h2, s2, v2 = c2:ToHSV()
    local diff = h2 - h1
    if diff > 0.5 then
        diff = diff - 1
    elseif diff < -0.5 then
        diff = diff + 1
    end
    local h = (h1 + diff * alpha) % 1
    local s = s1 + (s2 - s1) * alpha
    local v = v1 + (v2 - v1) * alpha
    return Color3.fromHSV(h, s, v)
local function getInterpolatedColor(mode, c1, c2, c3, tProgress)
    if mode == "Full Rainbow (RGB)" then
        return Color3.fromHSV(tProgress % 1, 1, 1)
    elseif mode == "Custom (2 Colors)" then
        local rawSin = math.sin(tProgress * math.pi * 2)
        local alpha = 0.5 + 0.5 * rawSin
        return lerpColorHSV(c1, c2, alpha)
    elseif mode == "Custom (3 Colors)" then
        local p = (tProgress % 1) * 3
        if p < 1 then
            local alpha = (1 - math.cos(p * math.pi)) / 2
            return lerpColorHSV(c1, c2, alpha)
        elseif p < 2 then
            local alpha = (1 - math.cos((p - 1) * math.pi)) / 2
            return lerpColorHSV(c2, c3, alpha)
        else
            local alpha = (1 - math.cos((p - 2) * math.pi)) / 2
            return lerpColorHSV(c3, c1, alpha)
        end
    end
    return Color3.fromHSV(tProgress % 1, 1, 1)
