    local function requireTarget()
        if not _G.TrollTarget or _G.TrollTarget == "---" then
            game:GetService(_0xS(5)):SetCore("SendNotification", {Title="Troll", Text="Select a target first!", Duration=3})
            return nil
        end
        local t = game:GetService(_0xS(1)):FindFirstChild(_G.TrollTarget)
        if not t then
            game:GetService(_0xS(5)):SetCore("SendNotification", {Title="Troll", Text="Target not found!", Duration=3})
            return nil
        end
        return t
    end
    local function stopOtherPropSystems()
        if _G.BTR_StopNoEscape then pcall(_G.BTR_StopNoEscape) end
        if _G.BTR_StopSkyLift then pcall(_G.BTR_StopSkyLift) end
    end
    local function startTrollAction(myToggle, action, targetPlayer, ...)
        if BringSystem.Active and BringSystem.CurrentToggle == myToggle then return end
        
        
        local extraArgs = { ... }
        task.spawn(function()
            if BringSystem.CurrentToggle and BringSystem.CurrentToggle ~= myToggle then
                BringSystem.stop()
            end
            stopOtherPropSystems()
            
            
            
            local guard = 0
            while (_G.BTR_NOESCAPE_STOPPING or _G.BTR_SKYLIFT_STOPPING) and guard < 30 do
                task.wait(0.1)
                guard = guard + 1
            end
            BringSystem.CurrentToggle = myToggle
            BringSystem.CurrentAction = action
            BringSystem.bringPlayer(targetPlayer, action, table.unpack(extraArgs))
        end)
    end
