                                    local padN = math.max(math.floor(tC * 0.6), 1)
                                    local ringN = math.max(math.floor(tC * 0.267), 1)
                                    local lx = currentTargetRoot.Position.X
                                    local lz = currentTargetRoot.Position.Z
                                    local ly = currentTargetRoot.Position.Y
                                    if i <= padN then
                                        local ggx = (i - 1) % 3
                                        local ggz = math.floor((i - 1) / 3)
                                        px = lx + (ggx - 1) * 4.5
                                        pz = lz + (ggz - 1) * 4.5
