    local function blindStart(lockedName, mode)
        local Players = game:GetService(_0xS(1))
        local lp = Players.LocalPlayer
        local char = lp.Character
        local humanoid = char and char:FindFirstChildOfClass("Humanoid")
        if not char or not humanoid then return false end
        blindLockedTarget = lockedName
        _G.TrollLockedTarget = lockedName
        blindPropEntries = {}
        local RE = game:GetService(_0xS(70)):WaitForChild(_0xS(83))
        local clearTools = RE:WaitForChild(_0xS(87))
        local propsTool = getOrFetchPropMaker()
        if not propsTool then
            game:GetService(_0xS(5)):SetCore("SendNotification", {
                Title = "Blind Player", Text = _0xS(99), Duration = 4
            })
            return false
        end
        humanoid:EquipTool(propsTool)
        task.wait(0.3)
        local isFurnitureMode = (mode == "RainbowBed")
        local reqProp = isFurnitureMode and blindRainbowProp or blindPropName
        local reqCategory = isFurnitureMode and "Furniture" or "Lights"
        pcall(function()
            clearTools:FireServer("OpenPropMenu")
            task.wait(0.1)
            if not isFurnitureMode and blindPropName == "RGB" then
                
            else
                clearTools:FireServer("RequestingPropName", reqProp, reqCategory)
            end
        end)
        local toolPropMake = propsTool:FindFirstChild(_0xS(96)) or propsTool:WaitForChild(_0xS(96), 3)
        if not toolPropMake then return false end 
        local myPos = char.HumanoidRootPart.Position
        local placedPositions = {}
        local MIN_DIST = 4
        local MIN_RADIUS = 3
        local MAX_RADIUS = 9
        local INTERVAL = 0.85
        local function getRandomPos()
            for _ = 1, 20 do
                local angle = math.random() * 2 * math.pi
                local radius = MIN_RADIUS + math.random() * (MAX_RADIUS - MIN_RADIUS)
                local candidate = myPos + Vector3.new(math.cos(angle) * radius, 0, math.sin(angle) * radius)
                local tooClose = false
                for _, pos in pairs(placedPositions) do
                    if (candidate - pos).Magnitude < MIN_DIST then tooClose = true break end
                end
                if not tooClose then return candidate end
            end
            local angle = math.random() * 2 * math.pi
            return myPos + Vector3.new(math.cos(angle) * MAX_RADIUS, 0, math.sin(angle) * MAX_RADIUS)
        end
        local rgbColorsList = {"LightsSpotLightRed", "LightsSpotLightToothpaste", "LightsSpotLightPink", "LightsSpotLightGreen", "LightsSpotLightWhite"}
        if not isFurnitureMode and blindPropName == "RGB" then
            for i = 1, 15 do
                if not propsTool or not propsTool.Parent or propsTool.Parent ~= char then break end
                local rgbProp = rgbColorsList[(i % #rgbColorsList) + 1]
                pcall(function() clearTools:FireServer("RequestingPropName", rgbProp, "Lights") end)
                task.wait(0.05)
                local pos = getRandomPos()
                pcall(function() toolPropMake:FireServer(workspace.Terrain, pos) end)
                table.insert(placedPositions, pos)
                if i < 15 then task.wait(INTERVAL - 0.05) end
            end
        else
            local startPos = getRandomPos()
            local duplicated = spawnAndDuplicateProps(toolPropMake, startPos, 15, 0)
            if not duplicated then
                for i = 1, 15 do
                    if not propsTool or not propsTool.Parent or propsTool.Parent ~= char then break end
                    local pos = getRandomPos()
                    pcall(function() toolPropMake:FireServer(workspace.Terrain, pos) end)
                    table.insert(placedPositions, pos)
                    if i < 15 then task.wait(INTERVAL) end
                end
            else
                local label = isFurnitureMode and ((blindRainbowProp == "FurnitureBleachers") and "Bleachers placed: 15/15" or "Beds placed: 15/15") or "Lights placed: 15/15"
                game:GetService(_0xS(5)):SetCore("SendNotification", {
                    Title = "Blind Player", Text = label, Duration = 2
                })
            end
        end
        
        pcall(function() local h = char and char:FindFirstChildOfClass("Humanoid"); if h then h:UnequipTools() end end)
        task.spawn(function()
            task.wait(1.0)
            pcall(function() game:GetService(_0xS(70)):WaitForChild(_0xS(83)):WaitForChild(_0xS(88)):InvokeServer(_0xS(90), _0xS(89)) end)
            task.wait(0.1)
            pcall(function() clearTools:FireServer("ClearAllTools") end)
            task.wait(0.1)
            pcall(function() clearTools:FireServer("ClosePropMenu") end)
            cleanupPropMakerTool()
        end)
        
        blindLoopRunning = true
        task.spawn(function()
            local myPropName = "Prop" .. lp.Name
            local t0 = tick()
            local lastColorPropIdx = 0
            while blindLoopRunning do
                local targetPlayer = game:GetService(_0xS(1)):FindFirstChild(blindLockedTarget)
                local hrp = targetPlayer and targetPlayer.Character and targetPlayer.Character:FindFirstChild(_0xS(6))
                if not targetPlayer and not isBlindLoopEnabled then
                    
                    
                    blindLoopRunning = false
                    clearBlindProps()
                    break
                end
                local targetPos = nil
                if hrp then
                    targetPos = hrp.Position
                elseif isBlindLoopEnabled then
                    local char = targetPlayer and targetPlayer.Character
                    local hum = char and char:FindFirstChildOfClass("Humanoid")
                    if not char or not hum or hum.Health <= 0 then
                        task.wait(0.5)
                    end
                end
                if targetPos then
                    local currentProps = {}
                    local wc = workspace:FindFirstChild(_0xS(93))
                    if wc then
                        for _, folder in pairs(wc:GetChildren()) do
                            for _, prop in pairs(folder:GetChildren()) do
                                if prop.Name == myPropName then
                                    local scf = prop:FindFirstChild(_0xS(97))
                                    local cpc = prop:FindFirstChild(_0xS(98))
                                    if scf then
                                        local entry = blindPropEntries[scf]
                                        if not entry then
                                            entry = {
                                                scf = scf,
                                                cpc = cpc,
                                                prop = prop,
                                                scfInFlight = false,
                                                cpcInFlight = false,
                                                colorApplied = false,
                                                lastColorTime = 0
                                            }
                                            blindPropEntries[scf] = entry
                                        end
                                        table.insert(currentProps, entry)
                                    end
                                end
                            end
                        end
                    end
                    local t = tick() - t0
                    local propCount = math.max(#currentProps, 1)
                    for i, entry in pairs(currentProps) do
                        if not blindLoopRunning then break end
                        local targetCF
                        if mode == "V1" then
                            
                            local angle = (i / propCount) * (2 * math.pi)
                            local offset = Vector3.new(math.cos(angle) * 0.5, -2.5, math.sin(angle) * 0.5)
                            targetCF = CFrame.new(targetPos + offset)
                        elseif mode == "V2" then
                            
                            local angle = (i / propCount) * (2 * math.pi)
                            local yOffset = -2.5 + ((i - 1) / math.max(propCount - 1, 1)) * 4.0
                            local offset = Vector3.new(math.cos(angle) * 0.5, yOffset, math.sin(angle) * 0.5)
                            targetCF = CFrame.new(targetPos + offset)
                        elseif mode == "V3" then
                            
                            local phi = math.acos(-1 + (2 * (i - 1)) / propCount)
                            local theta = math.sqrt(propCount * math.pi) * phi + t * 9
                            local r = 0.9 
                            local x = r * math.sin(phi) * math.cos(theta)
                            local y = r * math.sin(phi) * math.sin(theta) + 0.8
                            local z = r * math.cos(phi)
                            targetCF = CFrame.new(targetPos + Vector3.new(x, y, z), targetPos + Vector3.new(0, 0.8, 0))
                        elseif mode == "V4" then
                            
                            local isSecondHelix = (i % 2 == 0)
                            local baseAngle = (i / propCount) * (4 * math.pi) + (isSecondHelix and (t * 12 + math.pi) or (-t * 12))
                            local yProgress = ((i - 1) / math.max(propCount - 1, 1)) * 3.2 - 1.0
                            local r = 1.0 + math.sin(t * 8 + yProgress) * 0.3
                            local offset = Vector3.new(math.cos(baseAngle) * r, yProgress + 0.5, math.sin(baseAngle) * r)
                            targetCF = CFrame.new(targetPos + offset, targetPos + Vector3.new(0, yProgress + 0.5, 0))
                        elseif mode == "V5" then
                            
                            local angle = (i / propCount) * (2 * math.pi) + t * 16
                            local jitterX = math.sin(t * 50 + i) * 0.5
                            local jitterY = math.cos(t * 45 + i) * 0.5
                            local r = 0.7 + math.sin(t * 20 + i) * 0.3
                            local offset = Vector3.new(math.cos(angle) * r + jitterX, 0.8 + jitterY, math.sin(angle) * r)
                            targetCF = CFrame.new(targetPos + offset, targetPos + Vector3.new(0, 0.8, 0))
                        elseif mode == "V6" then
                            
                            
                            local pulse = (math.sin(t * 10) + 1) * 0.5
                            local r = 0.25 + pulse * 3.4
                            local phi = math.acos(-1 + (2 * (i - 1)) / propCount)
                            local theta = (i * 2.39996) + t * 14
                            local x = r * math.sin(phi) * math.cos(theta)
                            local y = r * math.sin(phi) * math.sin(theta) + 0.5
                            local z = r * math.cos(phi)
                            targetCF = CFrame.new(targetPos + Vector3.new(x, y, z), targetPos + Vector3.new(0, 0.5, 0))
                        elseif mode == "V7" then
                            
                            
                            local tier = (i - 1) % 3
                            local tierIdx = math.floor((i - 1) / 3)
                            local tierCount = math.max(math.floor(propCount / 3), 1)
                            local baseAng = (tierIdx / tierCount) * (2 * math.pi)
                            local r = 1.6 + math.sin(t * 6 + tier) * 0.4
                            local posOff = Vector3.new(0, 0.5, 0)
                            if tier == 0 then
                                
                                local ang = baseAng + t * 10
                                posOff = Vector3.new(math.cos(ang) * r, 0.5, math.sin(ang) * r)
                            elseif tier == 1 then
                                
                                local ang = baseAng - t * 8
                                posOff = Vector3.new(0, 0.5 + math.cos(ang) * r, math.sin(ang) * r)
                            else
                                
                                local ang = baseAng + t * 12
                                local diagX = math.cos(ang) * r * 0.707
                                local diagY = math.cos(ang) * r * 0.707 + 0.5
                                local diagZ = math.sin(ang) * r
                                posOff = Vector3.new(diagX, diagY, diagZ)
                            end
                            targetCF = CFrame.new(targetPos + posOff, targetPos + Vector3.new(0, 0.5, 0))
                        elseif mode == "RainbowBed" then
                            
                            
                            local tier = (i - 1) % 3
                            local tierIdx = math.floor((i - 1) / 3)
                            local tierCount = math.max(math.floor(propCount / 3), 1)
                            local baseAng = (tierIdx / tierCount) * (2 * math.pi)
                            local r = (blindRainbowProp == "FurnitureBleachers") and 4.0 or 3.0
                            local yOff = (tier == 0) and 0.5 or ((tier == 1) and 3.2 or -1.8)
                            local rotSpeed = (tier == 1) and -4.5 or 5.2
                            local ang = baseAng + t * rotSpeed
                            local posOff = Vector3.new(math.cos(ang) * r, yOff, math.sin(ang) * r)
                            local targetLook = targetPos + Vector3.new(0, 0.5, 0)
                            targetCF = CFrame.new(targetPos + posOff, targetLook)
                        else
                            targetCF = CFrame.new(targetPos)
                        end
                        if not entry.scfInFlight then
                            entry.scfInFlight = true
                            task.spawn(function()
                                pcall(function() entry.scf:InvokeServer(targetCF) end)
                                entry.scfInFlight = false
                            end)
                        end
                    end
                    
                    if #currentProps > 0 then
                        if mode == "RainbowBed" or blindColorMode == "RGB (Rainbow)" then
                            
                            lastColorPropIdx = (lastColorPropIdx % #currentProps) + 1
                            local colEntry = currentProps[lastColorPropIdx]
                            if colEntry and colEntry.cpc and not colEntry.cpcInFlight then
                                local now = tick()
                                if not colEntry.colorApplied or (now - colEntry.lastColorTime >= 0.25) then
                                    colEntry.cpcInFlight = true
                                    colEntry.lastColorTime = now
                                    colEntry.colorApplied = true
                                    local hue = (t * 0.4 + (lastColorPropIdx / #currentProps)) % 1
                                    local rainbowCol = Color3.fromHSV(hue, 1, 1)
                                    task.spawn(function()
                                        pcall(function() colEntry.cpc:InvokeServer(rainbowCol) end)
                                        colEntry.cpcInFlight = false
                                    end)
                                end
                            end
                        elseif blindColorValue then
                            
                            for _, colEntry in ipairs(currentProps) do
                                if colEntry.cpc and not colEntry.colorApplied and not colEntry.cpcInFlight then
                                    colEntry.cpcInFlight = true
                                    local staticCol = blindColorValue
                                    task.spawn(function()
                                        pcall(function() colEntry.cpc:InvokeServer(staticCol) end)
                                        colEntry.colorApplied = true
                                        colEntry.cpcInFlight = false
                                    end)
                                end
                            end
                        end
                    end
                end
                task.wait(0.08)
            end
        end)
        return true
    end
    local function clearBlindProps()
        local RE = game:GetService(_0xS(70)):FindFirstChild(_0xS(83))
        if RE then
            local clearTools = RE:FindFirstChild(_0xS(87))
            if clearTools then
                pcall(function() clearTools:FireServer(_0xS(95)) end)
            end
        end
    end
    local function blindStop()
        blindLoopRunning = false
        _G.TrollLockedTarget = nil
        blindPropEntries = {}
        clearBlindProps()
        local RE = game:GetService(_0xS(70)):FindFirstChild(_0xS(83))
        if RE then
            local clearTools = RE:FindFirstChild(_0xS(87))
            local toolRemote = RE:FindFirstChild(_0xS(88))
            if clearTools then
                
                task.wait(0.1)
                pcall(function() clearTools:FireServer("ClearAllTools") end)
                task.wait(0.1)
                pcall(function() clearTools:FireServer("ClosePropMenu") end)
            end
        end
        local lp = game:GetService(_0xS(1)).LocalPlayer
        local char = lp.Character
        local humanoid = char and char:FindFirstChildOfClass("Humanoid")
        if humanoid then pcall(function() humanoid:UnequipTools() end) end
        cleanupPropMakerTool()
    end
    _G.BTR_StartBlind = function(targetName)
        if not targetName then return false end
        return blindStart(targetName, "V1")
    end
    _G.BTR_StopBlind = blindStop
    local function checkOtherBlinds(currentRef)
        local allBlinds = {blindV1Toggle, blindV2Toggle, blindV3Toggle, blindV4Toggle, blindV5Toggle, blindV6Toggle, blindV7Toggle, blindRainbowToggle}
        for _, b in ipairs(allBlinds) do
            if b and b ~= currentRef and b.Value then
                return true
            end
        end
        return false
    end
