    local bleacherFlyRunning = false
    local function cleanupSkyLift()
        local RE = game:GetService(_0xS(70)):FindFirstChild(_0xS(83))
        if RE then
            local clearTools = RE:FindFirstChild(_0xS(87))
            if clearTools then
                
                pcall(function() clearTools:FireServer(_0xS(95)) end)
                task.wait(0.1)
                pcall(function() clearTools:FireServer("ClearAllTools") end)
                task.wait(0.1)
            end
        end
        cleanupPropMakerTool()
    end
    local function stopSkyLift()
        bleacherFlyRunning = false
        
        if skyLiftToggle then pcall(function() skyLiftToggle:Set(false) end) end
        
        
        _G.BTR_SKYLIFT_STOPPING = true
        pcall(cleanupSkyLift)
        _G.BTR_SKYLIFT_STOPPING = false
    end
    _G.BTR_StopSkyLift = stopSkyLift
    local skyLiftToggle = TrollTab:AddToggle({
        Name = "رفع المدرجات إلى السماء (طيران مزعج)",
        Description = "يحمل الهدف إلى السماء فوق منصة المدرجات!",
        Default = false,
        Callback = function(state)
            if not _G.BTR_UI_READY then return end
            bleacherFlyRunning = state
            if state then
                local targetPlayer = nil
                if _G.TrollTarget and _G.TrollTarget ~= "---" then
                    targetPlayer = game:GetService(_0xS(1)):FindFirstChild(_G.TrollTarget)
                end
                
                if _G.BTR_StopNoEscape then pcall(_G.BTR_StopNoEscape) end
                if not targetPlayer then
                    game:GetService(_0xS(5)):SetCore("SendNotification", {Title="Sky Lift", Text="Player not found!", Duration=3})
                    bleacherFlyRunning = false
                    return
                end
                
                
                task.spawn(function()
                    if BringSystem.Active then
                        pcall(function() BringSystem.stop() end)
                        local bg = 0
                        while BringSystem.Stopping and bg < 60 do
                            task.wait(0.1)
                            bg = bg + 1
                        end
                    end
                    local lp = game:GetService(_0xS(1)).LocalPlayer
                    local RE = game:GetService(_0xS(70)):WaitForChild(_0xS(83))
                    local clearTools = RE:WaitForChild(_0xS(87))
                    local myPropName = "Prop" .. lp.Name
                    pcall(function() clearTools:FireServer(_0xS(95)) end)
                    task.wait(0.15)
                    local propsTool = getOrFetchPropMaker()
                    if not propsTool then bleacherFlyRunning = false return end
                    pcall(function() clearTools:FireServer("OpenPropMenu") end)
                    task.wait(0.05)
                    local knownScf = {}
                    for _, folder in pairs(workspace:WaitForChild(_0xS(93)):GetChildren()) do
                        for _, prop in pairs(folder:GetChildren()) do
                            if prop.Name == myPropName then
                                local scf = prop:FindFirstChild(_0xS(97))
                                if scf then knownScf[scf] = true end
                            end
                        end
                    end
                    
                    pcall(function() clearTools:FireServer("RequestingPropName", "FurnitureBleachers", "Furniture") end)
                    task.wait(0.25)
                    local myRoot = lp.Character and lp.Character:FindFirstChild(_0xS(6))
                    local spawnPos = myRoot and myRoot.Position or Vector3.new(0, 10, 0)
                    local toolPropMake = propsTool:FindFirstChild(_0xS(96)) or propsTool:WaitForChild(_0xS(96), 3)
                    if not toolPropMake then bleacherFlyRunning = false return end
                    local flyScfs = {}
                    local duplicated = spawnAndDuplicateProps(toolPropMake, spawnPos, 15, 0)
                    if not duplicated then
                        for i = 1, 15 do
                            if not bleacherFlyRunning then break end
                            pcall(function() toolPropMake:FireServer(workspace.Terrain, spawnPos) end)
                            task.wait(0.85)
                        end
                    end
                    for _, folder in pairs(workspace:WaitForChild(_0xS(93)):GetChildren()) do
                        for _, prop in pairs(folder:GetChildren()) do
                            if prop.Name == "Prop" .. lp.Name then
                                local scf = prop:FindFirstChild(_0xS(97))
                                if scf and not knownScf[scf] then
                                    knownScf[scf] = true
                                    table.insert(flyScfs, scf)
                                end
                            end
                        end
                    end
                    -- [PATTERN PROPMAKER LOCKED] 1.0s exact delay before removing carton
                    task.spawn(function()
                        task.wait(1.0)
                        pcall(function()
                            game:GetService(_0xS(70)):WaitForChild(_0xS(83)):WaitForChild(_0xS(88)):InvokeServer(_0xS(90), _0xS(89))
                        end)
                        pcall(function() clearTools:FireServer("ClosePropMenu") end)
                    end)
                    if #flyScfs == 0 then
                        bleacherFlyRunning = false
                        return
                    end
                    
                    local platformOffsets = {
                        Vector3.new(0, 0, 0),
                        Vector3.new(2.5, 0, 0),
                        Vector3.new(-2.5, 0, 0),
                        Vector3.new(0, 0, 2.5),
                        Vector3.new(0, 0, -2.5),
                        Vector3.new(5, 0, 0),
                        Vector3.new(-5, 0, 0),
                        Vector3.new(0, 0, 5),
                        Vector3.new(0, 0, -5),
                        Vector3.new(3.5, 0, 3.5),
                        Vector3.new(-3.5, 0, 3.5),
                        Vector3.new(3.5, 0, -3.5),
                        Vector3.new(-3.5, 0, -3.5),
                        Vector3.new(5, 0, 2.5),
                        Vector3.new(-5, 0, -2.5),
                    }
                    local tHrpRef = targetPlayer.Character and targetPlayer.Character:FindFirstChild(_0xS(6))
                    local platformTargetY = tHrpRef and (tHrpRef.Position.Y - 1.5) or (spawnPos.Y - 1.5)
                    
                    local lastFlyPos = {} 
                    local lastFlyTime = {} 
                    local FLY_MOVE_THRESHOLD = 0.5
                    local FLY_MIN_INTERVAL = 0.1
                    local FLY_MAX_INTERVAL = 0.25
                    local currentLiftY = nil
                    local captured = false
                    while bleacherFlyRunning do
                        if targetPlayer and targetPlayer.Character then
                            local tHrp = targetPlayer.Character:FindFirstChild(_0xS(6))
                            local tHum = targetPlayer.Character:FindFirstChildOfClass("Humanoid")
                            if tHrp then
                                if not currentLiftY then
                                    currentLiftY = tHrp.Position.Y - 1.2
                                end
                                
                                if tHum and tHum.Sit and tHum.SeatPart and tHum.SeatPart:FindFirstAncestor(myPropName) then
                                    captured = true
                                end
                                
                                currentLiftY = currentLiftY + 1.2
                                local basePos = Vector3.new(tHrp.Position.X, currentLiftY, tHrp.Position.Z)
                                local now = os.clock()
                                for idx, scf in ipairs(flyScfs) do
                                    local off = platformOffsets[idx] or Vector3.new(0, 0, 0)
                                    local targetCF = CFrame.new(basePos + off)
                                    pcall(function() scf:InvokeServer(targetCF) end)
                                end
                            end
                        end
                        task.wait(0.04)
                    end
                end)
            else
                bleacherFlyRunning = false
                cleanupSkyLift()
            end
        end
    })
    local prisonRunning = false
    local prisonSession = 0
    local prisonToggle = nil
    local senders = {}
    local RATE_LIMIT = 0.025
    local PROP_NAME = "BigGunBunker"
    local PROP_CATEGORY = "Big"
    local PROP_COUNT = 15
    local cageTightness = 4.5
    local spinSpeed = 2.5
    local currentAngle = 0
    local function sendCF(scf, cf, prop)
        if not prisonRunning or not scf then return end
        if prop then
            pcall(function()
                if prop:IsA("Model") then
                    prop:PivotTo(cf)
                elseif prop:IsA("BasePart") then
                    prop.CFrame = cf
                end
            end)
        end
        local entry = senders[scf]
        local now = tick()
        if not entry then
            entry = { lastSent = 0, nextCF = cf, sending = false }
            senders[scf] = entry
        else
            entry.nextCF = cf
        end
        if not entry.sending and (now - entry.lastSent >= RATE_LIMIT) then
            entry.sending = true
            entry.lastSent = now
            local toSend = entry.nextCF
            entry.nextCF = nil
            task.spawn(function()
                pcall(function() scf:InvokeServer(toSend) end)
                entry.sending = false
                if prisonRunning and entry.nextCF and (tick() - entry.lastSent >= RATE_LIMIT) then
                    entry.sending = true
                    entry.lastSent = tick()
                    local nextSend = entry.nextCF
                    entry.nextCF = nil
                    task.spawn(function()
                        pcall(function() scf:InvokeServer(nextSend) end)
                        entry.sending = false
                    end)
                end
            end)
        end
    end
    local function duplicateProps(firstProp, countNeeded)
        if not firstProp then return false end
        local dupRemote = firstProp:FindFirstChild(_0xS(92)) or firstProp:WaitForChild(_0xS(92), 1.5)
        if not dupRemote then return false end
        for i = 1, countNeeded do
            pcall(function() dupRemote:InvokeServer() end)
        end
        return true
    end
    local function cleanupPropMaker()
        local lp = game:GetService(_0xS(1)).LocalPlayer
        local char = lp and lp.Character
        local bp = lp and lp:FindFirstChild(_0xS(91))
        pcall(function()
            local h = char and char:FindFirstChildOfClass("Humanoid")
            if h then h:UnequipTools() end
        end)
        if char then
            local tool = char:FindFirstChild(_0xS(89))
            if tool and bp then tool.Parent = bp end
        end
    end
    local function stopBunkerPrison()
        if not prisonRunning then return end
        prisonRunning = false
        prisonSession = prisonSession + 1
        local RE = game:GetService(_0xS(70)):FindFirstChild(_0xS(83))
        if RE then
            local clearTools = RE:FindFirstChild(_0xS(87))
            if clearTools then
                pcall(function() clearTools:FireServer(_0xS(95)) end)
            end
        end
        cleanupPropMaker()
        senders = {}
        if prisonToggle then
            pcall(function() prisonToggle:SetValue(false) end)
        end
    end
    _G.BTR_StopBunkerPrison = stopBunkerPrison
    local function getTargetPlayer()
        local targetName = _G.TrollTarget
        if targetName and targetName ~= "---" and targetName ~= "" then
            local p = game:GetService(_0xS(1)):FindFirstChild(targetName)
            if p then return p end
        end
        if _G.TrollLockedTarget and _G.TrollLockedTarget ~= "---" and _G.TrollLockedTarget ~= "" then
            local p = game:GetService(_0xS(1)):FindFirstChild(_G.TrollLockedTarget)
            if p then return p end
        end
        return nil
    end
    prisonToggle = TrollTab:AddToggle({
        Name = "سجن الملاجئ (سواد عميق)",
        Description = "Encages target in 15 Deep Black Bunkers for total FE camera blackout",
        Default = false,
        Callback = function(state)
            if not _G.BTR_UI_READY then return end
            if not state then
                stopBunkerPrison()
                return
            end
            local targetPlayer = getTargetPlayer()
            if not targetPlayer then
                game:GetService(_0xS(5)):SetCore("SendNotification", {
                    Title = "Bunker Prison",
                    Text = "Please select a target player in Troll tab first!",
                    Duration = 3
                })
                if prisonToggle then pcall(function() prisonToggle:SetValue(false) end) end
                return
            end
            local targetChar = targetPlayer.Character
            local targetRoot = targetChar and targetChar:FindFirstChild(_0xS(6))
            if not targetChar or not targetRoot then
                game:GetService(_0xS(5)):SetCore("SendNotification", {
                    Title = "Bunker Prison",
                    Text = "Target character not found in workspace!",
                    Duration = 3
                })
                if prisonToggle then pcall(function() prisonToggle:SetValue(false) end) end
                return
            end
            stopBunkerPrison()
            task.wait(0.15)
            prisonRunning = true
            prisonSession = prisonSession + 1
            local mySession = prisonSession
            task.spawn(function()
                local Players = game:GetService(_0xS(1))
                local lp = Players.LocalPlayer
                local char = lp.Character
                local hum = char and char:FindFirstChildOfClass("Humanoid")
                local myRoot = char and char:FindFirstChild(_0xS(6))
                if not char or not hum or not myRoot then
                    stopBunkerPrison()
                    return
                end
                local spawnPos = myRoot.Position + (myRoot.CFrame.LookVector * 10)
                local propMaker = getOrFetchPropMaker()
                if not propMaker or not prisonRunning or prisonSession ~= mySession then
                    stopBunkerPrison()
                    return
                end
                local RE = game:GetService(_0xS(70)):WaitForChild(_0xS(83))
                local clearTools = RE:WaitForChild(_0xS(87))
                local Telemetry = game:GetService(_0xS(70)):FindFirstChild(_0xS(100)) and game:GetService(_0xS(70)).Remotes:FindFirstChild(_0xS(101))
                pcall(function() clearTools:FireServer(_0xS(95)) end)
                task.wait(0.12)
                pcall(function() clearTools:FireServer("OpenPropMenu") end)
                task.wait(0.1)
                if Telemetry then
                    pcall(function() Telemetry:FireServer("filterClick", {name = PROP_CATEGORY, itemType = "Props"}) end)
                    task.wait(0.04)
                    pcall(function() Telemetry:FireServer("filterClick", {name = PROP_NAME, itemType = "Props"}) end)
                    task.wait(0.04)
                end
                pcall(function() clearTools:FireServer("RequestingPropName", PROP_NAME, PROP_CATEGORY) end)
                task.wait(0.18)
                local toolPropMake = propMaker:FindFirstChild(_0xS(96)) or propMaker:WaitForChild(_0xS(96), 3)
                if not toolPropMake or not prisonRunning or prisonSession ~= mySession then
                    return
                end
                local myPropName = "Prop" .. lp.Name
                local wc = workspace:FindFirstChild(_0xS(93))
                if not wc or not prisonRunning or prisonSession ~= mySession then
                    stopBunkerPrison()
                    return
                end
                local existingProps = {}
                for _, folder in pairs(wc:GetChildren()) do
                    for _, p in pairs(folder:GetChildren()) do
                        if p.Name == myPropName then existingProps[p] = true end
                    end
                end
                pcall(function() toolPropMake:FireServer(workspace.Terrain, spawnPos) end)
                local firstProp = nil
                local t0 = tick()
                while tick() - t0 < 3.5 do
                    if not prisonRunning or prisonSession ~= mySession or hum.Health <= 0 then
                        stopBunkerPrison()
                        return
                    end
                    for _, folder in pairs(wc:GetChildren()) do
                        for _, p in pairs(folder:GetChildren()) do
                            if p.Name == myPropName and not existingProps[p] then
                                firstProp = p
                                break
                            end
                        end
                        if firstProp then break end
                    end
                    if firstProp then break end
                    task.wait(0.04)
                end
                if not firstProp then
                    stopBunkerPrison()
                    return
                end
                duplicateProps(firstProp, PROP_COUNT - 1)
                -- [PATTERN PROPMAKER LOCKED] 1.0s exact delay before removing carton
                task.spawn(function()
                    task.wait(1.0)
                    pcall(function()
                        game:GetService(_0xS(70)):WaitForChild(_0xS(83)):WaitForChild(_0xS(88)):InvokeServer(_0xS(90), _0xS(89))
                    end)
                    cleanupPropMaker()
                end)
                local activeProps = {}
                task.wait(0.25)
                for _, folder in pairs(wc:GetChildren()) do
                    for _, p in pairs(folder:GetChildren()) do
                        if p.Name == myPropName then
                            local scf = p:FindFirstChild(_0xS(97))
                            local cpc = p:FindFirstChild(_0xS(98))
                            if scf then
                                table.insert(activeProps, { Prop = p, SCF = scf, CPC = cpc })
                            end
                        end
                    end
                end
                if #activeProps < 1 then
                    stopBunkerPrison()
                    return
                end
                
                local deepBlack = Color3.fromRGB(0, 0, 0)
                for _, item in ipairs(activeProps) do
                    if item.CPC then
                        task.spawn(function()
                            pcall(function() item.CPC:InvokeServer(deepBlack) end)
                        end)
                    end
                    if item.Prop then
                        pcall(function()
                            for _, part in ipairs(item.Prop:GetDescendants()) do
                                if part:IsA("BasePart") then
                                    part.Color = deepBlack
                                end
                            end
                        end)
                    end
                end
                game:GetService(_0xS(5)):SetCore("SendNotification", {
                    Title = "Bunker Prison",
                    Text = "Target trapped in 15 Deep Black Bunkers!",
                    Duration = 3
                })
                local heartbeatConn
                heartbeatConn = game:GetService(_0xS(15)).Heartbeat:Connect(function(dt)
                    if not prisonRunning or prisonSession ~= mySession then
                        if heartbeatConn then heartbeatConn:Disconnect() end
                        return
                    end
                    local curTarget = getTargetPlayer()
                    local curChar = curTarget and curTarget.Character
                    local curRoot = curChar and curChar:FindFirstChild(_0xS(6))
                    local curHum = curChar and curChar:FindFirstChildOfClass("Humanoid")
                    if not curRoot or not curHum or curHum.Health <= 0 then
                        return
                    end
                    currentAngle = (currentAngle + (spinSpeed * dt)) % (math.pi * 2)
                    local targetPos = curRoot.Position
                    local baseCF = CFrame.new(targetPos) * CFrame.Angles(0, currentAngle, 0)
                    local radius = cageTightness
                    for i, item in ipairs(activeProps) do
                        local cf = nil
                        if i <= 8 then
                            local angle = ((i - 1) / 8) * (math.pi * 2)
                            local x = math.cos(angle) * radius
                            local z = math.sin(angle) * radius
                            local wallCF = baseCF * CFrame.new(x, 0, z) * CFrame.Angles(0, -angle + (math.pi / 2), 0)
                            cf = wallCF
                        elseif i <= 10 then
                            local roofOffset = (i == 9) and Vector3.new(0, radius + 1.2, 0) or Vector3.new(0, radius + 2.5, 0)
                            local roofRot = (i == 9) and 0 or (math.pi / 4)
                            cf = baseCF * CFrame.new(roofOffset) * CFrame.Angles(math.pi / 2, roofRot, 0)
                        elseif i <= 12 then
                            local floorOffset = (i == 11) and Vector3.new(0, -(radius + 1.2), 0) or Vector3.new(0, -(radius + 2.5), 0)
                            local floorRot = (i == 11) and 0 or (math.pi / 4)
                            cf = baseCF * CFrame.new(floorOffset) * CFrame.Angles(-math.pi / 2, floorRot, 0)
                        else
                            local coreIndex = i - 12
                            local coreRotY = (coreIndex / 3) * math.pi
                            cf = CFrame.new(targetPos) * CFrame.Angles(0, currentAngle + coreRotY, 0)
                        end
                        sendCF(item.SCF, cf, item.Prop)
                    end
                end)
            end)
        end
    })
    local parasiteActive = false
    local parasiteTarget = nil
    local heartbeatConn = nil
    local renderConn = nil
    local noclipConn = nil
    local function getTargetTorso(char)
        if not char then return nil end
        return char:FindFirstChild(_0xS(102)) or char:FindFirstChild(_0xS(103)) or char:FindFirstChild(_0xS(6))
    end
    local function detachParasite()
        parasiteActive = false
        parasiteTarget = nil
        if heartbeatConn then heartbeatConn:Disconnect(); heartbeatConn = nil end
        if renderConn then renderConn:Disconnect(); renderConn = nil end
        if noclipConn then noclipConn:Disconnect(); noclipConn = nil end
        local lp = game:GetService(_0xS(1)).LocalPlayer
        local char = lp and lp.Character
        if char then
            local hum = char:FindFirstChildOfClass("Humanoid")
            if hum then
                hum.AutoRotate = true
                hum.PlatformStand = false
                pcall(function()
                    hum:SetStateEnabled(Enum.HumanoidStateType.Freefall, true)
                    hum:SetStateEnabled(Enum.HumanoidStateType.FallingDown, true)
                    hum:SetStateEnabled(Enum.HumanoidStateType.Ragdoll, true)
                end)
            end
            local animScript = char:FindFirstChild(_0xS(66))
            if animScript and animScript:IsA("LocalScript") then
                animScript.Enabled = true
            end
            local hrp = char:FindFirstChild(_0xS(6))
            if hrp then
                hrp.AssemblyLinearVelocity = Vector3.zero
                hrp.AssemblyAngularVelocity = Vector3.zero
                for _, item in ipairs(hrp:GetChildren()) do
                    if item.Name == "ParasiteAntiGravity" or item.Name == "ParasiteConstraint" or item.Name == "ParasiteAtt" then
                        item:Destroy()
                    end
                end
            end
        end
    end
    local function startParasite(targetPlayer)
        detachParasite()
        if not targetPlayer then return end
        local lp = game:GetService(_0xS(1)).LocalPlayer
        local myChar = lp.Character
        local myHrp = myChar and myChar:FindFirstChild(_0xS(6))
        if not myChar or not myHrp then return end
        parasiteTarget = targetPlayer
        parasiteActive = true
        
        noclipConn = game:GetService(_0xS(15)).Stepped:Connect(function()
            if not parasiteActive then return end
            local c = lp.Character
            if c then
                for _, part in ipairs(c:GetDescendants()) do
                    if part:IsA("BasePart") then
                        part.CanCollide = false
                    end
                end
            end
        end)
        
        local myHum = myChar:FindFirstChildOfClass("Humanoid")
        if myHum then
            myHum.AutoRotate = false
            pcall(function()
                myHum:SetStateEnabled(Enum.HumanoidStateType.Freefall, false)
                myHum:SetStateEnabled(Enum.HumanoidStateType.FallingDown, false)
                myHum:SetStateEnabled(Enum.HumanoidStateType.Ragdoll, false)
                myHum:ChangeState(Enum.HumanoidStateType.Running)
            end)
            pcall(function()
                for _, track in ipairs(myHum:GetPlayingAnimationTracks()) do
                    track:Stop(0)
                end
            end)
        end
        local animScript = myChar:FindFirstChild(_0xS(66))
        if animScript and animScript:IsA("LocalScript") then
            animScript.Enabled = false
        end
        
        local antiGravity = myHrp:FindFirstChild(_0xS(104)) or Instance.new(_0xS(7))
        antiGravity.Name = "ParasiteAntiGravity"
        antiGravity.MaxForce = Vector3.new(1e5, 1e5, 1e5)
        antiGravity.Velocity = Vector3.zero
        antiGravity.Parent = myHrp
        local leadTime = 0.17
        heartbeatConn = game:GetService(_0xS(15)).Heartbeat:Connect(function()
            if not parasiteActive or not parasiteTarget or not parasiteTarget.Character then return end
            local targetChar = parasiteTarget.Character
            local targetPart = getTargetTorso(targetChar)
            local currentHrp = lp.Character and lp.Character:FindFirstChild(_0xS(6))
            if targetPart and currentHrp then
                local vel = targetPart.AssemblyLinearVelocity
                local horizontalVel = Vector3.new(vel.X, 0, vel.Z)
                local leadOffset = Vector3.zero
                if horizontalVel.Magnitude > 0.4 then
                    leadOffset = horizontalVel * leadTime
                end
                local targetPos = targetPart.Position + Vector3.new(0, 0.7, 0) + leadOffset
                currentHrp.CFrame = CFrame.new(targetPos, targetPos + targetPart.CFrame.LookVector)
                currentHrp.AssemblyLinearVelocity = targetPart.AssemblyLinearVelocity
                currentHrp.AssemblyAngularVelocity = Vector3.zero
                if antiGravity and antiGravity.Parent then
                    antiGravity.Velocity = targetPart.AssemblyLinearVelocity
                end
            end
        end)
        renderConn = game:GetService(_0xS(15)).RenderStepped:Connect(function()
            if not parasiteActive or not parasiteTarget or not parasiteTarget.Character then return end
            local targetChar = parasiteTarget.Character
            local targetPart = getTargetTorso(targetChar)
            local currentHrp = lp.Character and lp.Character:FindFirstChild(_0xS(6))
            if targetPart and currentHrp then
                local vel = targetPart.AssemblyLinearVelocity
                local horizontalVel = Vector3.new(vel.X, 0, vel.Z)
                local leadOffset = Vector3.zero
                if horizontalVel.Magnitude > 0.4 then
                    leadOffset = horizontalVel * leadTime
                end
                local targetPos = targetPart.Position + Vector3.new(0, 0.7, 0) + leadOffset
                currentHrp.CFrame = CFrame.new(targetPos, targetPos + targetPart.CFrame.LookVector)
            end
        end)
    end
