        if lock then
            isMovementLocked = true
            if hum then
                originalWalkSpeed = hum.WalkSpeed > 0 and hum.WalkSpeed or originalWalkSpeed
                originalJumpPower = hum.JumpPower > 0 and hum.JumpPower or originalJumpPower
                hum.WalkSpeed = 0
