        local wc = Workspace:FindFirstChild(_0xS(93))
        local helis = wc and wc:FindFirstChild(_0xS(119))
        if helis and part:IsDescendantOf(helis) then
            return false
        end
        local n = part.Name:lower()
        if n:find("door") or n:find("porte") or n:find("gate") then
            return true
        end
        if part.Parent and (part.Parent.Name:lower():find("door") or part.Parent.Name:lower():find("gate")) then
            return true
        end
        return false
    end
