    local function getBarrelPropMaker()
        local lp = game:GetService(_0xS(1)).LocalPlayer
        local char = lp.Character
        local bp = lp:FindFirstChild(_0xS(91))
        if not char and not bp then return nil end
        local tool = (char and char:FindFirstChild(_0xS(89))) or (bp and bp:FindFirstChild(_0xS(89)))
        if not tool then
            local toolRE = game:GetService(_0xS(70)):WaitForChild(_0xS(83)):WaitForChild(_0xS(88))
            pcall(function() toolRE:InvokeServer(_0xS(90), _0xS(89)) end)
            local t0 = tick()
            while tick() - t0 < 2.5 do
                tool = (char and char:FindFirstChild(_0xS(89))) or (bp and bp:FindFirstChild(_0xS(89)))
                if tool then break end
                task.wait(0.05)
            end
        end
        if not tool then return nil end
        if char and tool.Parent ~= char then
            local hum = char:FindFirstChildOfClass("Humanoid")
            if hum then
                hum:EquipTool(tool)
                task.wait(0.1)
            end
        end
        return tool
    end
    local function spawnSingleNuclearBarrel(targetPos)
        local tool = getBarrelPropMaker()
        if not tool then return nil end
        local clearTools = game:GetService(_0xS(70)):WaitForChild(_0xS(83)):WaitForChild(_0xS(87))
        pcall(function() clearTools:FireServer("RequestingPropName", "NuclearWasteBarrel", "Building") end)
        task.wait(0.3)
        local lp = game:GetService(_0xS(1)).LocalPlayer
        local char = lp.Character
        local hum = char and char:FindFirstChildOfClass("Humanoid")
        if hum and tool.Parent ~= char then
            hum:EquipTool(tool)
            task.wait(0.1)
        end
        local tpm = tool:FindFirstChild(_0xS(96))
        local t0 = tick()
        while not tpm and tick() - t0 < 3.0 do
            tpm = tool:FindFirstChild(_0xS(96))
            if not tpm then
                local bp = lp:FindFirstChild(_0xS(91)) and lp.Backpack:FindFirstChild(_0xS(89))
                if bp then tpm = bp:FindFirstChild(_0xS(96)) end
            end
            if not tpm then task.wait(0.1) end
        end
        -- [PATTERN PROPMAKER LOCKED] Silent exit on missing Tool_PropMake
        if not tpm then return nil end
        local wc = workspace:FindFirstChild(_0xS(93))
        local myPropName = "Prop" .. lp.Name
        local beforeList = {}
        if wc then
            for _, folder in ipairs(wc:GetChildren()) do
                for _, prop in ipairs(folder:GetChildren()) do
                    if prop.Name == myPropName then
                        beforeList[prop] = true
                    end
                end
            end
        end
        pcall(function() tpm:FireServer(workspace.Terrain, targetPos) end)
        local spawned = nil
        local tDetect = tick()
        while tick() - tDetect < 3.5 do
            if wc then
                for _, folder in ipairs(wc:GetChildren()) do
                    for _, prop in ipairs(folder:GetChildren()) do
                        if prop.Name == myPropName and not beforeList[prop] then
                            spawned = prop
                            break
                        end
                    end
                    if spawned then break end
                end
            end
            if spawned then break end
            task.wait(0.05)
        end
        return spawned
    end
    local function duplicateNuclearBarrel(firstProp, count)
        if not firstProp or count <= 0 then return end
        local dupRemote = firstProp:FindFirstChild(_0xS(92)) or firstProp:WaitForChild(_0xS(92), 2)
        if not dupRemote then return end
        for i = 1, count do
            pcall(function() dupRemote:InvokeServer() end)
            task.wait(0.05)
        end
    end
    local function scanBarrelProps()
        table.clear(barrelBotPartsCache)
        local wc = workspace:FindFirstChild(_0xS(93))
        if not wc then return end
        local lp = game:GetService(_0xS(1)).LocalPlayer
        local myPropName = "Prop" .. lp.Name
        for _, folder in ipairs(wc:GetChildren()) do
            for _, prop in ipairs(folder:GetChildren()) do
                if prop.Name == myPropName then
                    local scf = prop:FindFirstChild(_0xS(97)) or prop:WaitForChild(_0xS(97), 0.5)
                    local cpc = prop:FindFirstChild(_0xS(98)) or prop:FindFirstChild(_0xS(98), true)
                    if scf then
                        table.insert(barrelBotPartsCache, {
                            prop = prop,
                            remote = scf,
