            CopyColors = Value
        end
    })
    AvatarTab:AddButton({
        Name = "نسخ الشخصية المحددة",
        Callback = function()
            if CopyAvatarTarget == "" then
                game:GetService(_0xS(5)):SetCore("SendNotification", {Title="Copy Avatar", Text="Please select a player first!", Duration=3})
                return
            end
            if CopyAvatarActive then
                game:GetService(_0xS(5)):SetCore("SendNotification", {Title="Copy Avatar", Text="A copy is already in progress...", Duration=3})
                return
            end
            local Players = game:GetService(_0xS(1))
            local RS = game:GetService(_0xS(70))
            local Remotes = RS:FindFirstChild(_0xS(100)) or RS:FindFirstChild(_0xS(83))
            local wearRemote = Remotes and Remotes:FindFirstChild(_0xS(132))
            local setColorRemote = Remotes and Remotes:FindFirstChild(_0xS(133))
            local TPlayer = Players:FindFirstChild(CopyAvatarTarget)
            if not TPlayer or not TPlayer.Character then
                game:GetService(_0xS(5)):SetCore("SendNotification", {Title="Copy Avatar", Text="Player or character not found!", Duration=3})
                return
            end
            CopyAvatarActive = true
            _G.BTR_IS_COPYING_AVATAR = true
            _G.BTR_COPIED_PLAYERS = _G.BTR_COPIED_PLAYERS or {}
            _G.BTR_COPIED_PLAYERS[TPlayer.UserId] = true
            _G.BTR_LAST_COPY_TIME = os.clock()
            game:GetService(_0xS(5)):SetCore("SendNotification", {
                Title = "Copy Avatar",
                Text = "Copy Item Colors: " .. (CopyColors and "ON" or "OFF"),
                Duration = 3
            })
            task.spawn(function()
                local THumanoid = TPlayer.Character:FindFirstChildOfClass("Humanoid")
                if not THumanoid then
                    game:GetService(_0xS(5)):SetCore("SendNotification", {Title="Copy Avatar", Text="Humanoid not found on target!", Duration=3})
                    CopyAvatarActive = false
                    _G.BTR_IS_COPYING_AVATAR = false
                    return
                end
                local PDesc = nil
                pcall(function() PDesc = THumanoid:GetAppliedDescription() end)
                if not PDesc then
                    pcall(function() PDesc = Players:GetHumanoidDescriptionFromUserId(TPlayer.UserId) end)
                end
                if not PDesc then
                    game:GetService(_0xS(5)):SetCore("SendNotification", {Title="Copy Avatar", Text="Unable to read target outfit!", Duration=3})
                    CopyAvatarActive = false
                    _G.BTR_IS_COPYING_AVATAR = false
                    return
                end
                local colorByName = {}
                local colorByMeshId = {}
                
                local function getMeshId(acc)
                    local handle = acc:FindFirstChild(_0xS(134))
                    if not handle then return nil end
                    if handle:IsA("MeshPart") then return handle.MeshId:match("%d+") end
                    local smesh = handle:FindFirstChildOfClass("SpecialMesh")
                    if smesh and smesh.MeshId then return smesh.MeshId:match("%d+") end
                    local fmesh = handle:FindFirstChildOfClass("FileMesh")
                    if fmesh and fmesh.MeshId then return fmesh.MeshId:match("%d+") end
                    return nil
                end
                if TPlayer.Character then
                    for _, child in ipairs(TPlayer.Character:GetChildren()) do
                        if child:IsA("Accessory") then
                            local handle = child:FindFirstChild(_0xS(134))
                            if handle then
                                local surfApp = handle:FindFirstChild(_0xS(135))
                                if surfApp then
                                    local col = surfApp.Color
                                    colorByName[child.Name] = col
                                    local meshId = getMeshId(child)
                                    if meshId then colorByMeshId[meshId] = col end
                                end
                            end
                        end
                    end
                end
                local wearQueue = {}
                local alreadyQueued = {}
                local function addToQueue(id)
                    if not tonumber(id) or tonumber(id) == 0 then return end
                    local idStr = tostring(math.floor(tonumber(id)))
                    if alreadyQueued[idStr] then return end
                    alreadyQueued[idStr] = true
                    table.insert(wearQueue, tonumber(id))
                end
                local accessories = PDesc:GetAccessories(true)
                for _, acc in ipairs(accessories) do
                    addToQueue(acc.AssetId)
                end
                if TPlayer.Character then
                    for _, child in ipairs(TPlayer.Character:GetChildren()) do
                        if child:IsA("Accessory") then
                            local meshId = getMeshId(child)
                            if meshId then addToQueue(meshId) end
                        end
                    end
                end
                local total = #wearQueue
                game:GetService(_0xS(5)):SetCore("SendNotification", {
                    Title = "Copy Avatar",
                    Text = "Copying " .. total .. " items (Brookhaven cooldown active)...",
                    Duration = 5
                })
                local myChar = Players.LocalPlayer.Character
                if myChar and TPlayer.Character then
                    local myAnimate = myChar:FindFirstChild(_0xS(66))
                    local targetAnimate = TPlayer.Character:FindFirstChild(_0xS(66))
                    if myAnimate and targetAnimate then
                        for _, animFolder in ipairs(targetAnimate:GetChildren()) do
                            local myFolder = myAnimate:FindFirstChild(animFolder.Name)
                            if myFolder then
                                for _, animObj in ipairs(animFolder:GetChildren()) do
                                    if animObj:IsA("Animation") then
                                        local myAnimObj = myFolder:FindFirstChildOfClass("Animation")
                                        if myAnimObj then
                                            myAnimObj.AnimationId = animObj.AnimationId
                                        end
                                    end
                                end
                            end
                        end
                    end
                end
                if CopyAvatarActive and TPlayer.Character then
                    local SkinColor = TPlayer.Character:FindFirstChild(_0xS(136))
                    if SkinColor and Remotes and Remotes:FindFirstChild(_0xS(137)) then
                        pcall(function() Remotes.ChangeBodyColor:FireServer(tostring(SkinColor.HeadColor)) end)
                        task.wait(0.2)
                    end
                end
                if CopyAvatarActive and Remotes and Remotes:FindFirstChild(_0xS(138)) then
                    local incrementSizeRemote = Remotes:FindFirstChild(_0xS(138))
                    local targetHeight = THumanoid:FindFirstChild(_0xS(139))
                    if targetHeight then
                        local attempts = 0
                        while CopyAvatarActive and attempts < 15 do
                            myChar = Players.LocalPlayer.Character
                            local myHum = myChar and myChar:FindFirstChildOfClass("Humanoid")
                            if not myHum then break end
                            local myHeight = myHum:FindFirstChild(_0xS(139))
                            if not myHeight then break end
                            local diff = targetHeight.Value - myHeight.Value
                            if math.abs(diff) <= 0.05 then break end
                            pcall(function() incrementSizeRemote:FireServer(diff > 0) end)
                            task.wait(0.2)
                            attempts = attempts + 1
                        end
                    end
                end
                for i, id in ipairs(wearQueue) do
                    if not CopyAvatarActive then break end
                    if i == 1 or i % 3 == 0 or i == total then
                        game:GetService(_0xS(5)):SetCore("SendNotification", {
                            Title = "Copy Avatar",
                            Text = "Item " .. i .. "/" .. total .. " being applied...",
                            Duration = 2.5
                        })
                    end
                    local myChar = Players.LocalPlayer.Character
                    local existingAccs = {}
                    if myChar and CopyColors then
                        for _, child in ipairs(myChar:GetChildren()) do
                            if child:IsA("Accessory") then
                                existingAccs[child] = true
                            end
                        end
                    end
                    if wearRemote then
                        pcall(function() wearRemote:InvokeServer(id) end)
                    end
                    local detectTime = 0
                    if CopyColors and setColorRemote then
                        local newAcc = nil
                        local attempts = 0
                        while attempts < 35 do
                            task.wait(0.1)
                            detectTime = detectTime + 0.1
                            if myChar then
                                for _, child in ipairs(myChar:GetChildren()) do
                                    if child:IsA("Accessory") and not existingAccs[child] then
                                        newAcc = child
                                        break
                                    end
                                end
                            end
                            if newAcc then break end
                            attempts = attempts + 1
                        end
                        if newAcc then
                            local meshId = getMeshId(newAcc)
                            local col = nil
                            if meshId and colorByMeshId[meshId] then
                                col = colorByMeshId[meshId]
                            elseif colorByName[newAcc.Name] then
                                col = colorByName[newAcc.Name]
                            end
                            if col then
                                pcall(function()
                                    setColorRemote:InvokeServer(id, {
                                        color = { r = col.R, g = col.G, b = col.B }
                                    })
                                end)
                            end
                        end
                    end
                    local waitTime = 2.1 - detectTime
                    if waitTime < 0 then waitTime = 0 end
                    task.wait(waitTime)
                end
                if CopyAvatarActive then
                    local msg = "Avatar copied 100%! (" .. total .. " items)"
                    if CopyColors then
                        msg = "Avatar + RGB colors copied 100%! (" .. total .. " items)"
                    end
                    game:GetService(_0xS(5)):SetCore("SendNotification", { Title = "Copy Avatar", Text = msg, Duration = 5 })
                end
                CopyAvatarActive = false
                _G.BTR_LAST_COPY_TIME = os.clock()
                task.spawn(function()
                    task.wait(3)
                    _G.BTR_IS_COPYING_AVATAR = false
                    if _G.BTR_SYNC_ANTI_COPY_BASELINE then
                        _G.BTR_SYNC_ANTI_COPY_BASELINE()
                    end
                end)
            end)
        end
    })
    AvatarTab:AddButton({
