                    end
                    local resetRemote = Remotes:FindFirstChild(_0xS(141))
                    if resetRemote then
                        pcall(function()
                            resetRemote:FireServer()
                        end)
                    end
                    bigBodySaved = nil
                    game:GetService(_0xS(5)):SetCore("SendNotification", { Title = "Giant (FE)", Text = "Normal size restored!", Duration = 3 })
                end
            end)
        end
    })
    AvatarTab:AddSection({"Chakra Armor (FE)"})
    local astralActive = false
    local astralTheme = "Purple"
    local astralScale = 11.0
    local astralIntensity = 1.0
    local astralLoop = nil
    local astralPhysicsLoop = nil
    local astralChest = nil
    local astralTurbines = {}
    local astralSmoothPos = nil
    local astralSmoothSpeed = 18.0
    local astralSenders = {}
    local ASTRAL_RATE = 0.03
    local astralRgbActive = false
    local ASTRAL_THEMES = {
        ["Purple"] = Color3.fromRGB(165, 30, 255),
        ["Blue"]   = Color3.fromRGB(0, 140, 255),
        ["Red"]    = Color3.fromRGB(240, 30, 20),
        ["Cyan"]   = Color3.fromRGB(0, 230, 230),
        ["Green"]  = Color3.fromRGB(30, 240, 80),
        ["Gold"]   = Color3.fromRGB(255, 215, 0),
        ["Black"]  = Color3.fromRGB(20, 15, 30),
        ["White"]  = Color3.fromRGB(255, 255, 255),
    local function sendAstralCF(scf, cf, prop)
        if not astralActive or not scf then return end
        if prop then
            pcall(function()
                if prop:IsA("Model") then
                    prop:PivotTo(cf)
                elseif prop:IsA("BasePart") then
                    prop.CFrame = cf
                end
            end)
        end
        local entry = astralSenders[scf]
        local now = tick()
        if not entry then
            entry = { lastSent = 0, nextCF = cf, sending = false }
            astralSenders[scf] = entry
        else
            entry.nextCF = cf
        end
        if not entry.sending and (now - entry.lastSent >= ASTRAL_RATE) then
            entry.sending = true
            entry.lastSent = now
            local toSend = entry.nextCF
            entry.nextCF = nil
            task.spawn(function()
                pcall(function() scf:InvokeServer(toSend) end)
                entry.sending = false
                if astralActive and entry.nextCF and (tick() - entry.lastSent >= ASTRAL_RATE) then
                    entry.sending = true
                    entry.lastSent = tick()
                    local nextSend = entry.nextCF
                    entry.nextCF = nil
                    task.spawn(function()
                        pcall(function() scf:InvokeServer(nextSend) end)
                        entry.sending = false
                    end)
                end
            end)
        end
    end
    local function applyAstralNeon(prop, col)
        if not prop then return end
        pcall(function()
            for _, p in ipairs(prop:GetDescendants()) do
                if p:IsA("BasePart") then
                    p.Material = Enum.Material.Neon
                    p.Color = col
                    p.CanCollide = false
                    p.CanTouch = false
                    p.CanQuery = false
                    p.Massless = true
                end
            end
        end)
    end
    local function applyAstralColorToPart(prop, cpc, col)
        if prop then
            pcall(function()
                for _, p in ipairs(prop:GetDescendants()) do
                    if p:IsA("BasePart") then
                        p.Material = Enum.Material.Neon
                        p.Color = col
                    end
                end
            end)
        end
        if cpc then
            task.spawn(function()
                pcall(function() cpc:InvokeServer(col) end)
            end)
        end
    end
    local function setAstralTheme(themeName)
        astralTheme = themeName
        if themeName == "Rainbow RGB" then
            astralRgbActive = true
            return
        else
            astralRgbActive = false
        end
        local solidCol = ASTRAL_THEMES[themeName] or Color3.fromRGB(165, 30, 255)
        if astralChest and astralChest.prop then
            applyAstralColorToPart(astralChest.prop, astralChest.cpc, solidCol)
        end
        for _, entry in ipairs(astralTurbines) do
            if entry.prop then
                applyAstralColorToPart(entry.prop, entry.cpc, solidCol)
            end
        end
    end
    local function stopAstralSovereign()
        astralActive = false
        if astralLoop then
            astralLoop:Disconnect()
            astralLoop = nil
        end
        if astralPhysicsLoop then
            astralPhysicsLoop:Disconnect()
            astralPhysicsLoop = nil
        end
        astralSenders = {}
        astralChest = nil
        astralTurbines = {}
        astralSmoothPos = nil
        astralRgbActive = false
        pcall(function()
            local RS = game:GetService(_0xS(70))
            local clearRE = RS:WaitForChild(_0xS(83)):WaitForChild(_0xS(87))
            clearRE:FireServer(_0xS(95))
        end)
    end
    _G.BTR_StopAstralSovereign = stopAstralSovereign
    local function spawnAstralSovereign()
        if astralActive then
            stopAstralSovereign()
            task.wait(0.3)
        end
        astralActive = true
        astralSmoothPos = nil
        local RS = game:GetService(_0xS(70))
        local RE = RS:WaitForChild(_0xS(83))
        local clearTools = RE:WaitForChild(_0xS(87))
        local toolRE = RE:WaitForChild(_0xS(88))
        local Telemetry = RS:FindFirstChild(_0xS(100)) and RS.Remotes:FindFirstChild(_0xS(101))
        local lp = game:GetService(_0xS(1)).LocalPlayer
        local myPropName = "Prop" .. lp.Name
        local char = lp.Character or lp.CharacterAdded:Wait()
        local hrp = char:WaitForChild(_0xS(6))
        local hum = char:WaitForChild(_0xS(94))
        pcall(function() clearTools:FireServer(_0xS(95)) end)
        task.wait(0.4)
        local function getPropMaker()
            local bp = lp:FindFirstChild(_0xS(91))
            local c = lp.Character
            if not bp or not c then return nil end
            local tool = c:FindFirstChild(_0xS(89)) or bp:FindFirstChild(_0xS(89))
            if not tool then
                pcall(function() toolRE:InvokeServer(_0xS(90), _0xS(89)) end)
                task.wait(0.3)
                tool = c:FindFirstChild(_0xS(89)) or bp:FindFirstChild(_0xS(89))
            end
            return tool
        end
        local pm = getPropMaker()
        if not pm then astralActive = false return end
        pcall(function() clearTools:FireServer("OpenPropMenu") end)
        task.wait(0.2)
        local wc = workspace:FindFirstChild(_0xS(93))
        if not wc then astralActive = false return end
        local existingProps = {}
        for _, folder in pairs(wc:GetChildren()) do
            for _, prop in pairs(folder:GetChildren()) do
                if prop.Name == myPropName then
                    existingProps[prop] = true
                end
            end
        end
        local function getSurfacePos(targetWorldPos)
            local rayParams = RaycastParams.new()
            rayParams.FilterDescendantsInstances = {lp.Character, workspace:FindFirstChild(_0xS(93))}
            rayParams.FilterType = Enum.RaycastFilterType.Exclude
            local ray = workspace:Raycast(targetWorldPos + Vector3.new(0, 10, 0), Vector3.new(0, -30, 0), rayParams)
            return (ray and ray.Instance) or workspace.Terrain, (ray and ray.Position) or targetWorldPos
        end
        local function spawnSingleProp(propNameStr, categoryStr, targetInst, targetPos)
            local tool = getPropMaker()
            if not tool then return nil end
            if Telemetry then
                pcall(function() Telemetry:FireServer("filterClick", {name = categoryStr, itemType = "Props"}) end)
                task.wait(0.05)
                pcall(function() Telemetry:FireServer("filterClick", {name = propNameStr, itemType = "Props"}) end)
                task.wait(0.05)
            end
            pcall(function() clearTools:FireServer("RequestingPropName", propNameStr, categoryStr) end)
            task.wait(0.3)
            local currentHum = lp.Character and lp.Character:FindFirstChildOfClass("Humanoid")
            if currentHum and tool.Parent ~= lp.Character then
                currentHum:EquipTool(tool)
                task.wait(0.1)
            end
            local tpm = tool:FindFirstChild(_0xS(96))
            local startW = tick()
            while not tpm and tick() - startW < 3.0 and astralActive do
                tpm = tool:FindFirstChild(_0xS(96))
                if not tpm then
                    local bp = lp.Backpack:FindFirstChild(_0xS(89))
                    if bp then tpm = bp:FindFirstChild(_0xS(96)) end
                end
                if not tpm then task.wait(0.1) end
            end
            if not tpm then return nil end
            pcall(function() tpm:FireServer(targetInst, targetPos) end)
            local spawned = nil
            local t0 = tick()
            while tick() - t0 < 3.5 and astralActive do
                for _, folder in pairs(wc:GetChildren()) do
                    for _, prop in pairs(folder:GetChildren()) do
                        if prop.Name == myPropName and not existingProps[prop] then
                            spawned = prop
                            existingProps[prop] = true
                            break
                        end
                    end
                    if spawned then break end
                end
                if spawned then break end
                task.wait(0.05)
            end
            return spawned
        end
        local function duplicateProp(firstProp, countNeeded)
            if not firstProp then return false end
            local dupRemote = firstProp:FindFirstChild(_0xS(92)) or firstProp:WaitForChild(_0xS(92), 2)
            if not dupRemote then return false end
            for _ = 1, countNeeded do
                pcall(function() dupRemote:InvokeServer() end)
                task.wait(0.05)
            end
            return true
        end
        
        local bunkerTarget = hrp.Position + (hrp.CFrame.LookVector * 12)
        local bunkerHitInst, bunkerHitPos = getSurfacePos(bunkerTarget)
        local chestProp = spawnSingleProp("BigGunBunker", "Big", bunkerHitInst, bunkerHitPos)
        if not chestProp then
            chestProp = spawnSingleProp("BigGunBunker", "Big", bunkerHitInst, bunkerHitPos)
        end
        if not chestProp or not astralActive then
            stopAstralSovereign()
            return
        end
        
        local turbineTarget = hrp.Position - (hrp.CFrame.LookVector * 12)
        local turbineHitInst, turbineHitPos = getSurfacePos(turbineTarget)
        local firstTurbine = spawnSingleProp("PowerTurbine", "Barrel", turbineHitInst, turbineHitPos)
        if not firstTurbine then
            firstTurbine = spawnSingleProp("PowerTurbine", "001_TrafficCones", turbineHitInst, turbineHitPos)
        end
        if not firstTurbine or not astralActive then
            stopAstralSovereign()
            return
        end
        duplicateProp(firstTurbine, 13)
        task.wait(0.8)
        -- Remove cardboard after 1 second (LOCKED Rule 7)
        task.wait(1.0)
        pcall(function() toolRE:InvokeServer(_0xS(90), _0xS(89)) end)
        pcall(function() clearTools:FireServer("ClosePropMenu") end)
        task.wait(0.2)
        
        local function setupPropEntry(prop)
            local scf = prop:FindFirstChild(_0xS(97)) or prop:FindFirstChildWhichIsA("RemoteFunction", true)
            local cpc = prop:FindFirstChild(_0xS(98)) or prop:FindFirstChild(_0xS(98), true)
            return { prop = prop, scf = scf, cpc = cpc }
        end
        astralChest = nil
        astralTurbines = {}
        for _, folder in pairs(wc:GetChildren()) do
            for _, prop in pairs(folder:GetChildren()) do
                if prop.Name == myPropName then
                    local entry = setupPropEntry(prop)
                    if entry.scf then
                        local isBunker = false
                        pcall(function()
                            for _, p in ipairs(prop:GetDescendants()) do
                                if p:IsA("BasePart") and p.Size.Magnitude > 25 then
                                    isBunker = true
                                    break
                                end
                            end
                        end)
                        if isBunker and not astralChest then
                            astralChest = entry
                        else
                            table.insert(astralTurbines, entry)
                        end
                    end
                end
            end
        end
        local defaultCol = ASTRAL_THEMES[astralTheme] or Color3.fromRGB(165, 30, 255)
        if astralChest then applyAstralNeon(astralChest.prop, defaultCol) end
        for _, node in ipairs(astralTurbines) do
            applyAstralNeon(node.prop, defaultCol)
        end
        
        local rs = game:GetService(_0xS(15))
        astralPhysicsLoop = rs.Stepped:Connect(function()
            if not astralActive then return end
            local cc = lp.Character
            if cc then
                for _, part in ipairs(cc:GetDescendants()) do
                    if part:IsA("BasePart") and part.Name ~= _0xS(6) then
                        part.CanCollide = false
                        part.CanTouch = false
                    end
                end
            end
            if astralChest and astralChest.prop then
                pcall(function()
                    for _, p in ipairs(astralChest.prop:GetDescendants()) do
