            local humNow = cc:FindFirstChildOfClass("Humanoid")
            if not hrpNow or not humNow then return end
            local hrpCF = hrpNow.CFrame
            local t = tick() - startTime
            local intensity = astralIntensity
            local scale = astralScale
            local breathSlow = math.sin(t * 1.8) * 0.35 * intensity
            local breathFast = math.sin(t * 3.5) * 0.15 * intensity
            local breathCombo = breathSlow + breathFast
            local ribBreathe = math.sin(t * 2.2) * 0.6 * intensity
            local shoulderSway = math.sin(t * 1.4) * 0.3 * intensity
            local haloSpin = t * 22
            local haloPulse = math.sin(t * 4.0) * 0.15 * intensity
            local tailWave = math.sin(t * 2.8) * 0.4 * intensity
            local headDrift = math.sin(t * 1.0) * 2.5 * intensity
            local moveIntensity = 1.0
            if humNow.MoveDirection.Magnitude > 0.05 then
                moveIntensity = 1.5
            end
            for _, track in ipairs(humNow:GetPlayingAnimationTracks()) do
                if track.IsPlaying and track.Priority == Enum.AnimationPriority.Action4 then
                    moveIntensity = 2.0
