                astralSmoothPos = targetPos
            else
                local lerpFactor = math.clamp(astralSmoothSpeed * dt, 0, 1)
                astralSmoothPos = astralSmoothPos:Lerp(targetPos, lerpFactor)
            end
            local centerCF = CFrame.new(astralSmoothPos) * (hrpCF - hrpCF.Position)
            
            if astralChest and astralChest.scf then
