                    * CFrame.Angles(math.rad(-90 + headDrift), math.rad(math.sin(t * 0.8) * 3), 0)
                sendAstralCF(tN[1].scf, headCF, tN[1].prop)
            end
            
            local lUpperArm = cc:FindFirstChild(_0xS(143))
