                    shoulderCF = centerCF
                        * CFrame.new(-6.2 * (scale / 11.0) - 1.5, 4.0 * (scale / 11.0) + shoulderBob + shoulderSway, 0)
                        * relRot
                        * CFrame.Angles(math.rad(90), 0, math.rad(90 + math.sin(t * 1.8) * 8))
                else
                    shoulderCF = centerCF
                        * CFrame.new(-7.5, 4.0 + shoulderBob, 0)
                        * CFrame.Angles(0, 0, math.rad(-30 + math.sin(t * 2) * 10))
