                sendAstralCF(tN[3].scf, shoulderCF, tN[3].prop)
            end
            
            local lArmParts = {"LeftUpperArm", "LeftLowerArm", "LeftHand"}
            for idx, limbName in ipairs(lArmParts) do
                local node = tN[3 + idx]
