                        )
                        local armCF = centerCF * CFrame.new(scaledPos) * relRot * CFrame.Angles(math.rad(90), 0, math.rad(90))
                        sendAstralCF(node.scf, armCF, node.prop)
                    end
                end
            end
            
            local rArmParts = {"RightUpperArm", "RightLowerArm", "RightHand"}
            for idx, limbName in ipairs(rArmParts) do
