                end
            end
            
            if tN[10] and tN[10].scf then
                local ribExpand = ribBreathe * 0.8
                local ribLCF = centerCF
                    * CFrame.new((-3.5 - ribExpand) * (scale / 11.0), -2.0 + breathCombo * 0.3, (-2.8 + ribExpand * 0.3) * (scale / 11.0))
                    * CFrame.Angles(math.rad(25 + math.sin(t * 2.2) * 6), math.rad(55 + math.sin(t * 1.5) * 8 * intensity), math.rad(-25 + ribBreathe * 5))
                sendAstralCF(tN[10].scf, ribLCF, tN[10].prop)
            end
            if tN[11] and tN[11].scf then
                local ribExpand = ribBreathe * 0.8
                local ribRCF = centerCF
                    * CFrame.new((3.5 + ribExpand) * (scale / 11.0), -2.0 + breathCombo * 0.3, (-2.8 + ribExpand * 0.3) * (scale / 11.0))
