                    * CFrame.new(3.0 * (scale / 11.0) + rel.Position.X * scale * 0.5 - tailWave, -5.8 * (scale / 11.0) + rel.Position.Y * scale * 0.5 + tailSwing, rel.Position.Z * scale * 0.5)
                    * relRot * CFrame.Angles(math.rad(90), 0, math.rad(-90 - tailWave * 20))
                sendAstralCF(tN[13].scf, legCF, tN[13].prop)
            end
            
            if tN[14] and tN[14].scf then
