                    local waveColor = Color3.fromHSV((nowTick * 0.5 + phase + math.sin(nowTick * 2 + i) * 0.1) % 1, 1, 1)
                    if node.prop then
                        pcall(function()
                            for _, p in ipairs(node.prop:GetDescendants()) do
                                if p:IsA("BasePart") then
