        local function makeAdminToggle(name, desc, mode)
            local tg = AdminTab:AddToggle({
                Name = name,
                Description = desc,
                Default = false
            })
            tg:Callback(function(value)
                if not _G.BTR_UI_READY then return end
                if value then
                    for otherMode, otherTg in pairs(adminToggles) do
                        if otherMode ~= mode then
                            pcall(function() otherTg:Set(false) end)
                        end
                    end
                    
                    if BringSystem and BringSystem.Active then BringSystem.stop() end
                    
                    if adminRunning then adminStopAll() end
                    task.wait(0.2)
                    runAdmin(mode, tg)
                else
                    adminStopAll(tg)
                end
            end)
            adminToggles[mode] = tg
            return tg
        end
        
