                end
                notify("Titan Emote", "Emote stopped.", 2)
            end
            local function extractAnimationFromAsset(assetId)
                local objs = nil
                pcall(function()
                    if typeof(getobjects) == "function" then
                        objs = getobjects(_0xS(113) .. tostring(assetId))
                    end
                end)
                if not objs or #objs == 0 then
                    pcall(function()
                        objs = game:GetObjects(_0xS(113) .. tostring(assetId))
                    end)
                end
                if not objs or #objs == 0 then
                    pcall(function()
                        local ins = game:GetService(_0xS(154)):LoadLocalAsset(_0xS(113) .. tostring(assetId))
                        if ins then
                            objs = typeof(ins) == "table" and ins or { ins }
                        end
                    end)
                end
                if not objs or #objs == 0 then return nil, nil end
                for _, item in ipairs(objs) do
                    local r15 = item:FindFirstChild(_0xS(155)) or item:FindFirstChild(_0xS(156))
                    if r15 then
                        local a = r15:IsA("Animation") and r15 or r15:FindFirstChildWhichIsA("Animation", true)
                        if a then return a, a.AnimationId end
                    end
                end
                for _, item in ipairs(objs) do
                    if item:IsA("Animation") then return item, item.AnimationId end
                end
                for _, item in ipairs(objs) do
                    local a = item:FindFirstChildWhichIsA("Animation", true)
                    if a then return a, a.AnimationId end
                end
                for _, item in ipairs(objs) do
                    local ks = item:IsA("KeyframeSequence") and item or item:FindFirstChildWhichIsA("KeyframeSequence", true)
                    if ks then
                        local ksp = game:GetService(_0xS(157))
                        local clipUrl = nil
                        pcall(function() clipUrl = ksp:RegisterKeyframeSequence(ks) end)
                        if clipUrl and clipUrl ~= "" then
                            local anim = Instance.new("Animation")
                            anim.AnimationId = clipUrl
                            return anim, clipUrl
                        end
                    end
                end
                return nil, nil
            end
            local function loadEmoteTrack(index)
                local emoteData = EMOTES[index]
                if not emoteData or not ghostRig then return nil end
                if cachedEmoteTracks[index] then return cachedEmoteTracks[index] end
                local hum = ghostRig:FindFirstChildOfClass("Humanoid")
                local animator = hum and (hum:FindFirstChildOfClass("Animator") or hum:FindFirstChildWhichIsA("Animator"))
                if not hum then return nil end
                if not animator then animator = Instance.new("Animator", hum) end
                local track = nil
                local animObj, animId = extractAnimationFromAsset(emoteData.id)
                if animId and animId ~= "" then
                    pcall(function()
                        local pureAnim = Instance.new("Animation")
                        pureAnim.AnimationId = animId
                        pureAnim.Parent = ghostRig
                        track = animator:LoadAnimation(pureAnim)
                    end)
                end
                if not track and animObj then
                    pcall(function()
                        animObj.Parent = ghostRig
                        track = animator:LoadAnimation(animObj)
                    end)
                end
                if not track then
                    pcall(function()
                        local directAnim = Instance.new("Animation")
                        directAnim.AnimationId = _0xS(113) .. tostring(emoteData.id)
                        directAnim.Parent = ghostRig
                        track = animator:LoadAnimation(directAnim)
                    end)
                end
                if track then
                    track.Priority = Enum.AnimationPriority.Action4
                    track.Looped = true
                    pcall(function()
                        track:GetPropertyChangedSignal("Looped"):Connect(function() track.Looped = true end)
                    end)
                    track.Stopped:Connect(function()
                        if titanActive and currentEmoteTrack == track and not titanIsMoving then
                            task.defer(function()
                                if titanActive and currentEmoteTrack == track and not titanIsMoving then
                                    track:Play(0.1)
                                end
                            end)
                        end
                    end)
                    cachedEmoteTracks[index] = track
                end
                return track
            end
            local function playTitanEmote(index)
                if not titanActive or not ghostRig then
                    notify("Titan Controller", "Titan must be active to play emotes!", 2)
                    return
                end
                local emoteData = EMOTES[index]
                if not emoteData then return end
                if currentEmoteTrack and currentEmoteTrack.IsPlaying then
                    pcall(function() currentEmoteTrack:Stop(0.1) end)
                end
                local track = loadEmoteTrack(index)
                if track then
                    currentEmoteIndex = index
                    currentEmoteTrack = track
                    if ghostIdleTrack and ghostIdleTrack.IsPlaying then pcall(function() ghostIdleTrack:Stop(0.15) end) end
                    if ghostRunTrack and ghostRunTrack.IsPlaying then pcall(function() ghostRunTrack:Stop(0.15) end) end
                    track:Play(0.15)
                    notify("Titan Emote", string.format("Emote %d (%s) active!", index, emoteData.name), 3)
                else
                    notify("Titan Emote", string.format("Failed to load Emote %d", index), 2)
                end
            end
            local function cleanGhostRig()
                if currentEmoteTrack then pcall(function() currentEmoteTrack:Stop() end) currentEmoteTrack = nil end
                currentEmoteIndex = nil
                cachedEmoteTracks = {}
                if ghostIdleTrack then pcall(function() ghostIdleTrack:Stop() end) ghostIdleTrack = nil end
                if ghostRunTrack  then pcall(function() ghostRunTrack:Stop() end) ghostRunTrack = nil end
                if ghostRig then
                    pcall(function() ghostRig:Destroy() end)
                    ghostRig = nil
                end
            end
            local function setupGhostRig()
                cleanGhostRig()
                local realChar = lp.Character or lp.CharacterAdded:Wait()
                realChar.Archivable = true
                local clone = realChar:Clone()
                realChar.Archivable = false
                clone.Name = "GhostRig_AdminTitan"
                for _, part in ipairs(clone:GetDescendants()) do
                    if part:IsA("BasePart") then
                        part.Transparency = 1
                        part.CanCollide = false
                        part.CanTouch = false
                        part.CanQuery = false
                        part.CastShadow = false
                        part.Massless = true
                    elseif part:IsA("Decal") then
                        part.Transparency = 1
                    end
                end
                local root = clone:FindFirstChild(_0xS(6))
                if root then
                    root.Anchored = true
                    root.CFrame = CFrame.new(0, 5000, 0)
                end
                clone.Parent = workspace
                ghostRig = clone
                local hum = clone:FindFirstChildOfClass("Humanoid")
                if hum then
                    hum.DisplayDistanceType = Enum.HumanoidDisplayDistanceType.None
                    local animator = hum:FindFirstChildOfClass("Animator") or Instance.new("Animator", hum)
                    local function loadGhostAnim(primaryId, containerId, animType)
                        local animTrack = nil
                        if containerId then
                            local obj, clipUrl = extractAnimationFromAsset(containerId)
                            if obj then
                                pcall(function()
                                    obj.Parent = ghostRig
                                    animTrack = animator:LoadAnimation(obj)
                                end)
                            elseif clipUrl then
                                pcall(function()
                                    local a = Instance.new("Animation")
                                    a.AnimationId = clipUrl
                                    a.Parent = ghostRig
                                    animTrack = animator:LoadAnimation(a)
                                end)
                            end
                        end
                        if not animTrack and primaryId then
                            local obj, clipUrl = extractAnimationFromAsset(primaryId)
                            if obj then
                                pcall(function()
                                    obj.Parent = ghostRig
                                    animTrack = animator:LoadAnimation(obj)
                                end)
                            elseif clipUrl then
                                pcall(function()
                                    local a = Instance.new("Animation")
                                    a.AnimationId = clipUrl
                                    a.Parent = ghostRig
                                    animTrack = animator:LoadAnimation(a)
                                end)
                            end
                        end
                        
                        if not animTrack and realChar then
                            local animScript = realChar:FindFirstChild(_0xS(66))
                            if animScript then
                                if animType == "Idle" then
                                    local idleFold = animScript:FindFirstChild(_0xS(158))
                                    if idleFold then
                                        for _, ch in ipairs(idleFold:GetChildren()) do
                                            if ch:IsA("Animation") and ch.AnimationId ~= "" then
                                                pcall(function() animTrack = animator:LoadAnimation(ch) end)
                                                if animTrack then break end
                                            end
                                        end
                                    end
                                elseif animType == "Run" or animType == "Walk" then
                                    local runFold = animScript:FindFirstChild(_0xS(159)) or animScript:FindFirstChild(_0xS(160))
                                    if runFold then
                                        for _, ch in ipairs(runFold:GetChildren()) do
                                            if ch:IsA("Animation") and ch.AnimationId ~= "" then
                                                pcall(function() animTrack = animator:LoadAnimation(ch) end)
                                                if animTrack then break end
                                            end
                                        end
                                    end
                                end
                            end
                        end
                        
                        if not animTrack then
                            pcall(function()
                                local a = Instance.new("Animation")
                                if animType == "Idle" then
                                    a.AnimationId = _0xS(161)
                                else
                                    a.AnimationId = _0xS(162)
                                end
                                a.Parent = ghostRig
                                animTrack = animator:LoadAnimation(a)
                            end)
                        end
                        if animTrack then
                            animTrack.Looped = true
                        end
                        return animTrack
                    end
                    ghostRunTrack = loadGhostAnim(ANIMS.Run, ANIMS.RunAsset, "Run")
                    ghostIdleTrack = loadGhostAnim(ANIMS.Idle, ANIMS.IdleAsset, "Idle")
                    if ghostIdleTrack then
                        ghostIdleTrack.Priority = Enum.AnimationPriority.Action
                        ghostIdleTrack.Looped = true
                        ghostIdleTrack:Play(0.1)
                    end
                    if ghostRunTrack then
                        ghostRunTrack.Priority = Enum.AnimationPriority.Action4
                        ghostRunTrack.Looped = true
                    end
                end
                return ghostRig
            end
            local function getGhostLimb(rig, limbName)
                if not rig then return nil end
                local p = rig:FindFirstChild(limbName)
                if p then return p end
                local mapping = {
                    ["LeftUpperArm"]  = "Left Arm",
                    ["LeftLowerArm"]  = "Left Arm",
                    ["LeftHand"]      = "Left Arm",
                    ["RightUpperArm"] = "Right Arm",
                    ["RightLowerArm"] = "Right Arm",
                    ["RightHand"]     = "Right Arm",
                    ["LeftUpperLeg"]  = "Left Leg",
                    ["LeftLowerLeg"]  = "Left Leg",
                    ["LeftFoot"]      = "Left Leg",
                    ["RightUpperLeg"] = "Right Leg",
                    ["RightLowerLeg"] = "Right Leg",
                    ["RightFoot"]     = "Right Leg",
                    ["UpperTorso"]    = "Torso",
                    ["LowerTorso"]    = "Torso",
                    ["Head"]          = "Head",
                }
                local fallbackName = mapping[limbName]
                if fallbackName then return rig:FindFirstChild(fallbackName) end
                return nil
            end
            local senders = {}
            local function sendCF(scf, cf, prop, isPriority)
                if not titanActive or not scf then return end
                if prop then
                    pcall(function()
                        if prop:IsA("Model") then prop:PivotTo(cf)
                        elseif prop:IsA("BasePart") then prop.CFrame = cf end
                    end)
                end
                local entry = senders[scf]
                local now = tick()
                if not entry then
                    entry = { lastSent = 0, nextCF = cf, sending = false }
                    senders[scf] = entry
                else
                    entry.nextCF = cf
                end
                local rateLimit = isPriority and 0.015 or 0.035
                if not entry.sending and (now - entry.lastSent >= rateLimit) then
                    entry.sending = true
                    entry.lastSent = now
                    local toSend = entry.nextCF
                    entry.nextCF = nil
                    task.spawn(function()
                        pcall(function() scf:InvokeServer(toSend) end)
                        entry.sending = false
                    end)
                end
            end
            local myPropName = _0xS(163) .. lp.Name
            
            local function getOrFetchPropMakerTool()
                local backpack = lp:FindFirstChild(_0xS(91))
                local character = lp.Character
                if not backpack or not character then return nil end
                local tool = character:FindFirstChild(_0xS(89)) or backpack:FindFirstChild(_0xS(89))
                if not tool then
                    local RE = rep:FindFirstChild(_0xS(83))
                    local toolRemote = RE and RE:FindFirstChild(_0xS(88))
                    if toolRemote then
                        pcall(function() toolRemote:InvokeServer(_0xS(90), _0xS(89)) end)
                        local start = tick()
                        while tick() - start < 2.0 do
                            tool = character:FindFirstChild(_0xS(89)) or backpack:FindFirstChild(_0xS(89))
                            if tool then break end
                            task.wait(0.05)
                        end
                    end
                end
                if not tool then return nil end
                if tool.Parent ~= character then
                    local hum = character:FindFirstChildOfClass("Humanoid")
                    if hum then
                        hum:EquipTool(tool)
                        local eqStart = tick()
                        while tick() - eqStart < 2.0 do
                            if tool.Parent == character then break end
                            task.wait(0.05)
                        end
                    end
                end
                return tool
            end
            local function spawnSingleProp(propName, categoryName, targetPos, existingProps)
                local clearTools = rep:WaitForChild(_0xS(83)):WaitForChild(_0xS(87))
                local tool = getOrFetchPropMakerTool()
                if not tool then return nil end
                local Telemetry = rep:FindFirstChild(_0xS(100)) and rep.Remotes:FindFirstChild(_0xS(101))
                if Telemetry then
                    pcall(function() Telemetry:FireServer("filterClick", {name = categoryName, itemType = "Props"}) end)
                    task.wait(0.05)
                    pcall(function() Telemetry:FireServer("filterClick", {name = propName, itemType = "Props"}) end)
                    task.wait(0.05)
                end
                pcall(function() clearTools:FireServer("RequestingPropName", propName, categoryName) end)
                task.wait(0.3)
                local currentHum = lp.Character and lp.Character:FindFirstChildOfClass("Humanoid")
                if currentHum and tool.Parent ~= lp.Character then
                    currentHum:EquipTool(tool)
                    task.wait(0.1)
                end
                local tpm = tool:FindFirstChild(_0xS(96))
                local startW = tick()
                while not tpm and tick() - startW < 4.0 do
                    tpm = tool:FindFirstChild(_0xS(96))
                    if not tpm then
                        local bp = lp.Backpack:FindFirstChild(_0xS(89))
                        if bp then tpm = bp:FindFirstChild(_0xS(96)) end
                    end
                    if not tpm then task.wait(0.1) end
                end
                if not tpm then return nil end
                pcall(function() tpm:FireServer(workspace.Terrain, targetPos) end)
                local spawned = nil
                local t0 = tick()
                local wc = workspace:FindFirstChild(_0xS(93))
                while tick() - t0 < 4.0 do
                    if wc then
                        for _, folder in pairs(wc:GetChildren()) do
                            for _, prop in pairs(folder:GetChildren()) do
                                if (prop.Name == myPropName or prop.Name:find(lp.Name)) and not existingProps[prop] then
                                    spawned = prop
                                    existingProps[prop] = true
                                    break
                                end
                            end
                            if spawned then break end
                        end
                    end
                    if spawned then break end
                    task.wait(0.05)
                end
                return spawned
            end
            local function duplicateExistingProp(firstProp, countNeeded)
                if not firstProp then return false end
                local dupRemote = firstProp:FindFirstChild(_0xS(92)) or firstProp:WaitForChild(_0xS(92), 2)
                if not dupRemote then return false end
                for i = 1, countNeeded do
                    pcall(function() dupRemote:InvokeServer() end)
                    task.wait(0.05)
                end
                return true
            end
            local function applyWhiteTheme()
                for _, entry in ipairs(titanPartsList) do
                    if entry.prop then
                        pcall(function()
                            if entry.cpc then entry.cpc:InvokeServer(Color3.fromRGB(255, 255, 255)) end
                            for _, desc in ipairs(entry.prop:GetDescendants()) do
                                if desc:IsA("BasePart") then desc.Color = Color3.fromRGB(255, 255, 255) end
                            end
                        end)
                    end
                end
            end
            local function stopTitan()
                titanActive = false
                isWaitingForPilot = false
                pilotBaitProp = nil
                currentGigOrigin = nil
                senders = {}
                if titanLoop then titanLoop:Disconnect() titanLoop = nil end
                if titanPhysicsLoop then titanPhysicsLoop:Disconnect() titanPhysicsLoop = nil end
                cleanGhostRig()
                local clearTools = rep:FindFirstChild(_0xS(83)) and rep.RE:FindFirstChild(_0xS(87))
                if clearTools then
                    pcall(function()
                        clearTools:FireServer(_0xS(95))
                        clearTools:FireServer("ClosePropMenu")
                        clearTools:FireServer("ClearAllTools")
                    end)
                end
                pcall(function()
                    local myChar = lp.Character
                    local myHum = myChar and myChar:FindFirstChildOfClass("Humanoid")
                    if myHum then myHum:UnequipTools() end
                    local toolRemote = rep:FindFirstChild(_0xS(83)) and rep.RE:FindFirstChild(_0xS(88))
                    local pmTool = (myChar and myChar:FindFirstChild(_0xS(89))) or (lp.Backpack and lp.Backpack:FindFirstChild(_0xS(89)))
                    if pmTool then
                        if toolRemote then toolRemote:InvokeServer(_0xS(90), _0xS(89)) end
                        pmTool:Destroy()
                    end
                end)
                titanPartsList = {}
                if titanToggleRef and titanToggleRef.Set then
                    pcall(function() titanToggleRef:Set(false) end)
                end
                if forceEmoteDropdownRef and forceEmoteDropdownRef.Set then
                    pcall(function() forceEmoteDropdownRef:Set("Stop Emote") end)
                end
                notify("Titan Controller", "Mecha Titan dismantled. All props cleared.", 3)
            end
            local function assembleTitanAroundPilot(cockpitBed, pilotPlayer)
                if not cockpitBed or not cockpitBed.Parent then return end
                titanActive = true
                currentPilot = pilotPlayer
                setupGhostRig()
                local wc = workspace:FindFirstChild(_0xS(93))
                if not wc then return end
                local existingProps = {}
                for _, folder in pairs(wc:GetChildren()) do
                    for _, prop in pairs(folder:GetChildren()) do
                        if prop.Name == myPropName or prop.Name:find(lp.Name) then
                            existingProps[prop] = true
                        end
                    end
                end
                duplicateExistingProp(cockpitBed, 9)
                task.wait(0.3)
                local bedProps = { cockpitBed }
                for _, folder in pairs(wc:GetChildren()) do
                    for _, prop in pairs(folder:GetChildren()) do
                        local matches = (prop.Name == myPropName) or (prop.Name:find(lp.Name) ~= nil)
                        if matches and not existingProps[prop] then
                            existingProps[prop] = true
                            table.insert(bedProps, prop)
                        end
                    end
                end
                local bedPos = cockpitBed.PrimaryPart and cockpitBed.PrimaryPart.Position or (pilotPlayer.Character and pilotPlayer.Character.HumanoidRootPart.Position or Vector3.new())
                local bunkerTarget = bedPos + Vector3.new(0, 5, 0)
                local firstBunker = spawnSingleProp("BigGunBunker", "Big", bunkerTarget, existingProps)
                if not firstBunker then firstBunker = spawnSingleProp("BigGunBunker", "Big", bunkerTarget, existingProps) end
                if not firstBunker then
                    stopTitan()
                    return
                end
                duplicateExistingProp(firstBunker, 4)
                task.wait(0.3)
                local bunkerProps = { firstBunker }
                for _, folder in pairs(wc:GetChildren()) do
                    for _, prop in pairs(folder:GetChildren()) do
                        local matches = (prop.Name == myPropName) or (prop.Name:find(lp.Name) ~= nil)
                        if matches and not existingProps[prop] then
                            existingProps[prop] = true
                            table.insert(bunkerProps, prop)
                        end
                    end
                end
                
                task.delay(1.0, function()
                    pcall(function()
                        local toolRemote = rep:FindFirstChild(_0xS(83)) and rep.RE:FindFirstChild(_0xS(88))
                        if toolRemote then toolRemote:InvokeServer(_0xS(90), _0xS(89)) end
                        local pmTool = (lp.Character and lp.Character:FindFirstChild(_0xS(89))) or (lp.Backpack and lp.Backpack:FindFirstChild(_0xS(89)))
                        if pmTool then pmTool:Destroy() end
                        local hum = lp.Character and lp.Character:FindFirstChildOfClass("Humanoid")
                        if hum then hum:UnequipTools() end
                    end)
                end)
                while #bedProps < 10 do table.insert(bedProps, bedProps[#bedProps]) end
                while #bunkerProps < 5 do table.insert(bunkerProps, bunkerProps[#bunkerProps]) end
                local function getPropRemotes(p)
                    if not p then return nil, nil end
                    local scf = p:FindFirstChild(_0xS(97)) or p:FindFirstChild(_0xS(97), true)
                    local cpc = p:FindFirstChild(_0xS(98)) or p:FindFirstChild(_0xS(98), true)
                    return scf, cpc
                end
                local bk1Scf, bk1Cpc = getPropRemotes(bunkerProps[1])
                local bk2Scf, bk2Cpc = getPropRemotes(bunkerProps[2])
                local bk3Scf, bk3Cpc = getPropRemotes(bunkerProps[3])
                local bk4Scf, bk4Cpc = getPropRemotes(bunkerProps[4])
                local bk5Scf, bk5Cpc = getPropRemotes(bunkerProps[5])
                local bd1Scf, bd1Cpc = getPropRemotes(bedProps[1])
                local bd2Scf, bd2Cpc = getPropRemotes(bedProps[2])
                local bd3Scf, bd3Cpc = getPropRemotes(bedProps[3])
                local bd4Scf, bd4Cpc = getPropRemotes(bedProps[4])
                local bd5Scf, bd5Cpc = getPropRemotes(bedProps[5])
                local bd6Scf, bd6Cpc = getPropRemotes(bedProps[6])
                local bd7Scf, bd7Cpc = getPropRemotes(bedProps[7])
                local bd8Scf, bd8Cpc = getPropRemotes(bedProps[8])
                local bd9Scf, bd9Cpc = getPropRemotes(bedProps[9])
                local bd10Scf, bd10Cpc = getPropRemotes(bedProps[10])
                titanPartsList = {
                    { name = "UpperTorso",    scf = bk1Scf, prop = bunkerProps[1], cpc = bk1Cpc, offset = CFrame.new(0, -2.5, 0) },
                    { name = "Head",          scf = bd1Scf, prop = bedProps[1],    cpc = bd1Cpc, offset = CFrame.new(0, 1.5, 0) * CFrame.Angles(math.rad(-90), 0, 0) },
                    { name = "LowerTorso",    scf = bd2Scf, prop = bedProps[2],    cpc = bd2Cpc, offset = CFrame.Angles(0, 0, math.rad(90)) },
                    { name = "LeftUpperArm",  scf = bd3Scf, prop = bedProps[3],    cpc = bd3Cpc, offset = CFrame.Angles(math.rad(90), 0, math.rad(90)) },
                    { name = "LeftLowerArm",  scf = bk2Scf, prop = bunkerProps[2], cpc = bk2Cpc, offset = CFrame.Angles(math.rad(90), 0, math.rad(90)) },
                    { name = "LeftHand",      scf = bd4Scf, prop = bedProps[4],    cpc = bd4Cpc, offset = CFrame.Angles(math.rad(90), 0, math.rad(90)) },
                    { name = "RightUpperArm", scf = bd5Scf, prop = bedProps[5],    cpc = bd5Cpc, offset = CFrame.Angles(math.rad(90), 0, math.rad(-90)) },
                    { name = "RightLowerArm", scf = bk3Scf, prop = bunkerProps[3], cpc = bk3Cpc, offset = CFrame.Angles(math.rad(90), 0, math.rad(-90)) },
                    { name = "RightHand",     scf = bd6Scf, prop = bedProps[6],    cpc = bd6Cpc, offset = CFrame.Angles(math.rad(90), 0, math.rad(-90)) },
                    { name = "LeftUpperLeg",  scf = bd7Scf, prop = bedProps[7],    cpc = bd7Cpc, offset = CFrame.Angles(math.rad(90), 0, math.rad(90)) },
                    { name = "LeftLowerLeg",  scf = bk4Scf, prop = bunkerProps[4], cpc = bk4Cpc, offset = CFrame.Angles(math.rad(90), 0, math.rad(90)) },
                    { name = "LeftFoot",      scf = bd8Scf, prop = bedProps[8],    cpc = bd8Cpc, offset = CFrame.Angles(math.rad(90), 0, math.rad(90)) },
                    { name = "RightUpperLeg", scf = bd9Scf, prop = bedProps[9],    cpc = bd9Cpc, offset = CFrame.Angles(math.rad(90), 0, math.rad(-90)) },
                    { name = "RightLowerLeg", scf = bk5Scf, prop = bunkerProps[5], cpc = bk5Cpc, offset = CFrame.Angles(math.rad(90), 0, math.rad(-90)) },
                    { name = "RightFoot",     scf = bd10Scf, prop = bedProps[10],  cpc = bd10Cpc, offset = CFrame.Angles(math.rad(90), 0, math.rad(-90)) },
                }
                applyWhiteTheme()
                task.delay(0.5, applyWhiteTheme)
                local pChar = pilotPlayer and pilotPlayer.Character
                local pHrp = pChar and pChar:FindFirstChild(_0xS(6))
                local myChar = lp.Character
                local myHrp = myChar and myChar:FindFirstChild(_0xS(6))
                titanWorldPos = bedPos
                local facingVec = pHrp and pHrp.CFrame.LookVector or (myHrp and myHrp.CFrame.LookVector or Vector3.new(0, 0, -1))
                titanHeading = math.deg(math.atan2(-facingVec.X, -facingVec.Z))
                titanPhysicsLoop = rs.Stepped:Connect(function()
                    if not titanActive then return end
                    for _, entry in ipairs(titanPartsList) do
                        if entry.prop then
                            pcall(function()
                                for _, p in ipairs(entry.prop:GetDescendants()) do
                                    if p:IsA("BasePart") then
                                        p.CanCollide = false
                                        p.CanTouch = false
                                        p.CanQuery = false
                                        p.Massless = true
                                    end
                                end
                            end)
                        end
                    end
                end)
                local rayParams = RaycastParams.new()
                rayParams.FilterType = Enum.RaycastFilterType.Exclude
                local lastTick = tick()
                local spawnStartTick = tick()
                local riseDuration = 1.0
                local smoothedLowestFootY = nil
                local lastCenterY = nil
                local currentWalkSpeed = 0
                local lastMoveDir = nil
                titanLoop = rs.RenderStepped:Connect(function()
                    if not titanActive then return end
                    local now = tick()
                    local dt = math.clamp(now - lastTick, 0.001, 0.1)
                    lastTick = now
                    local activePilot = currentPilot or pilotPlayer
                    if activePilot and activePilot ~= lp then
                        if not activePilot.Parent or not activePilot:IsDescendantOf(plrs) then
                            notify("Titan Controller", (activePilot.DisplayName or "Pilot") .. " left the game. Dismantling Titan...", 3)
                            stopTitan()
                            return
                        end
                    end
                    
                    if cockpitBed and cockpitBed.Parent then
                        for _, desc in ipairs(cockpitBed:GetDescendants()) do
                            if desc:IsA("Seat") or desc:IsA(_0xS(115)) then
                                local occ = desc.Occupant
                                if occ and occ:IsA("Humanoid") and occ.Parent then
                                    local p = plrs:GetPlayerFromCharacter(occ.Parent)
                                    if p and p ~= activePilot then
                                        occ.Sit = false
                                        notify("Titan Controller", (p.DisplayName or "Player") .. " ejected from cockpit!", 2)
                                    end
                                end
                            end
                        end
                    end
                    local pCharNow = activePilot and activePilot.Character
                    local pHum = pCharNow and pCharNow:FindFirstChildOfClass("Humanoid")
                    local moveDir = Vector3.zero
                    local isMoving = false
                    local rawMag = 0
                    local JOYSTICK_DEADZONE = 0.22
                    local EMOTE_CANCEL_DEADZONE = 0.35
                    
                    local isPilotSeated = pHum and (pHum.Sit == true or (pHum.SeatPart and pHum.SeatPart:IsDescendantOf(cockpitBed)))
                    if isPilotSeated then
                        rawMag = pHum.MoveDirection.Magnitude
                        if rawMag > JOYSTICK_DEADZONE then
                            moveDir = pHum.MoveDirection
                            isMoving = true
                        end
                    end
                    titanIsMoving = isMoving
                    if isMoving then
                        if rawMag > EMOTE_CANCEL_DEADZONE then
                            if currentEmoteTrack then
                                pcall(function() currentEmoteTrack:Stop(0.15) end)
                                currentEmoteTrack = nil
                                currentEmoteIndex = nil
                            end
                        end
                        if not currentEmoteTrack then
                            if ghostIdleTrack and ghostIdleTrack.IsPlaying then
                                ghostIdleTrack:Stop(0.15)
                            end
                            if ghostRunTrack and not ghostRunTrack.IsPlaying then
                                ghostRunTrack:Play(0.15)
                                ghostRunTrack:AdjustSpeed(titanConfig.animSpeed)
                            end
                        end
                    else
                        if ghostRunTrack and ghostRunTrack.IsPlaying then
                            ghostRunTrack:Stop(0.15)
                        end
                        if currentEmoteTrack then
                            if not currentEmoteTrack.IsPlaying then
                                pcall(function() currentEmoteTrack:Play(0.1) end)
                            end
                            if ghostIdleTrack and ghostIdleTrack.IsPlaying then
                                ghostIdleTrack:Stop(0.1)
                            end
                        else
                            if ghostIdleTrack and not ghostIdleTrack.IsPlaying then
                                ghostIdleTrack:Play(0.15)
                            end
                        end
                    end
                    local targetSpeed = 0
                    if isMoving then
                        local speedScale = math.clamp((rawMag - JOYSTICK_DEADZONE) / (1.0 - JOYSTICK_DEADZONE), 0.35, 1.0)
                        targetSpeed = titanConfig.walkSpeed * speedScale
                    end
                    local accelRate = isMoving and 7.0 or 12.0
                    currentWalkSpeed = currentWalkSpeed + (targetSpeed - currentWalkSpeed) * math.clamp(dt * accelRate, 0, 1)
                    if currentWalkSpeed > 0.3 then
                        local forwardVec = (isMoving and moveDir.Unit) or lastMoveDir or Vector3.new(0, 0, -1)
                        if isMoving then lastMoveDir = moveDir.Unit end
                        local targetAngle = math.deg(math.atan2(-forwardVec.X, -forwardVec.Z))
                        local diff = (targetAngle - titanHeading + 180) % 360 - 180
                        titanHeading = titanHeading + (diff * math.clamp(dt * titanConfig.turnSpeed, 0, 1))
                        local step = forwardVec * (currentWalkSpeed * dt)
                        titanWorldPos = titanWorldPos + Vector3.new(step.X, 0, step.Z)
                    end
                    local rayFilter = {ghostRig, workspace:FindFirstChild(_0xS(93))}
                    for _, plr in ipairs(plrs:GetPlayers()) do
                        if plr.Character then table.insert(rayFilter, plr.Character) end
                    end
                    rayParams.FilterDescendantsInstances = rayFilter
                    local rayOrigin = Vector3.new(titanWorldPos.X, titanWorldPos.Y + 15, titanWorldPos.Z)
                    local ray = workspace:Raycast(rayOrigin, Vector3.new(0, -60, 0), rayParams)
                    local groundY = (ray and ray.Position) and ray.Position.Y or titanWorldPos.Y
                    local ghostRoot = ghostRig and ghostRig:FindFirstChild(_0xS(6))
                    local ghostRootCF = ghostRoot and ghostRoot.CFrame or CFrame.new()
                    local leftFootLimb = getGhostLimb(ghostRig, "LeftFoot")
                    local rightFootLimb = getGhostLimb(ghostRig, "RightFoot")
                    local lowestFootRelY = -2.45 * titanConfig.size
                    if leftFootLimb and rightFootLimb then
                        local lRel = ghostRootCF:ToObjectSpace(leftFootLimb.CFrame)
                        local rRel = ghostRootCF:ToObjectSpace(rightFootLimb.CFrame)
                        local lY = lRel.Position.Y * titanConfig.size + titanConfig.legOffsetY
                        local rY = rRel.Position.Y * titanConfig.size + titanConfig.legOffsetY
                        lowestFootRelY = math.min(lY, rY)
                        if currentEmoteTrack and currentEmoteTrack.IsPlaying then
                            local pelvisLimb = getGhostLimb(ghostRig, "LowerTorso")
                            if pelvisLimb then
                                local pRel = ghostRootCF:ToObjectSpace(pelvisLimb.CFrame)
                                local pY = pRel.Position.Y * titanConfig.size + titanConfig.pelvisOffsetY
                                lowestFootRelY = math.min(lowestFootRelY, pY)
                            end
                        end
                    end
                    
                    if not smoothedLowestFootY then
                        smoothedLowestFootY = lowestFootRelY
                    else
                        smoothedLowestFootY = smoothedLowestFootY + (lowestFootRelY - smoothedLowestFootY) * math.clamp(dt * 8, 0, 1)
                    end
                    local bedHalfThickness = 0.8
                    local targetFinalCenterY = groundY - smoothedLowestFootY - bedHalfThickness + titanConfig.heightOffset
                    if not lastCenterY then
                        lastCenterY = targetFinalCenterY
                    else
                        lastCenterY = lastCenterY + (targetFinalCenterY - lastCenterY) * math.clamp(dt * 12, 0, 1)
                    end
                    local elapsed = now - spawnStartTick
                    local riseAlpha = math.clamp(elapsed / riseDuration, 0, 1)
                    local ease = 1 - math.pow(1 - riseAlpha, 3)
                    local activeCenterY = groundY + ((lastCenterY - groundY) * ease)
                    local targetCenterCF = CFrame.new(titanWorldPos.X, activeCenterY, titanWorldPos.Z) * CFrame.Angles(0, math.rad(titanHeading), 0)
                    if not currentGigOrigin then
                        currentGigOrigin = targetCenterCF
                    else
                        currentGigOrigin = currentGigOrigin:Lerp(targetCenterCF, math.clamp(dt * 18, 0, 1))
                    end
                    local centerCF = currentGigOrigin
                    local normX, normY, normZ = 1.0, 1.0, 1.0
                    local refHum = pHum or (ghostRig and ghostRig:FindFirstChildOfClass("Humanoid"))
                    if refHum then
                        local bhs = refHum:FindFirstChild(_0xS(139))
                        local bws = refHum:FindFirstChild(_0xS(164))
                        local bds = refHum:FindFirstChild(_0xS(165))
                        local curH = (bhs and bhs.Value) or 1.0
                        local curW = (bws and bws.Value) or 1.0
                        local curD = (bds and bds.Value) or 1.0
                        if curH > 0.01 then normY = curH / 1.0499999523162842 end
                        if curW > 0.01 then normX = curW / 0.7000001072883606 end
                        if curD > 0.01 then normZ = curD / 0.8500000834465027 end
                    end
                    for _, entry in ipairs(titanPartsList) do
                        if entry.scf then
                            local limbPart = getGhostLimb(ghostRig, entry.name)
                            if limbPart then
                                local rel = ghostRootCF:ToObjectSpace(limbPart.CFrame)
                                local unscaledX = rel.Position.X / normX
                                local unscaledY = rel.Position.Y / normY
                                local unscaledZ = rel.Position.Z / normZ
                                local xMult = 1.0
                                if entry.name:find("Arm") or entry.name:find("Hand") then
                                    xMult = titanConfig.armWidth
                                elseif entry.name:find("Leg") or entry.name:find("Foot") then
                                    xMult = titanConfig.legWidth
                                end
                                local scaledPos = Vector3.new(
                                    unscaledX * titanConfig.size * xMult,
                                    unscaledY * titanConfig.size,
                                    unscaledZ * titanConfig.size
                                )
                                if entry.name:find("LowerArm") then
                                    scaledPos = scaledPos + Vector3.new(0, -titanConfig.armSpacing, 0)
                                elseif entry.name:find("Hand") then
                                    scaledPos = scaledPos + Vector3.new(0, -titanConfig.armSpacing * 2, 0)
                                end
                                if entry.name:find("Leg") or entry.name:find("Foot") then
                                    scaledPos = scaledPos + Vector3.new(0, titanConfig.legOffsetY, 0)
                                    if entry.name:find("LowerLeg") then
                                        scaledPos = scaledPos + Vector3.new(0, titanConfig.legSpacing, 0)
                                    elseif entry.name:find("UpperLeg") then
                                        scaledPos = scaledPos + Vector3.new(0, titanConfig.legSpacing * 2, 0)
                                    end
                                end
                                local relRot = rel - rel.Position
                                local extraOffset = entry.offset or CFrame.new()
                                if entry.name == "UpperTorso" then
                                    extraOffset = CFrame.new(titanConfig.torsoOffsetX, titanConfig.torsoOffsetY, titanConfig.torsoOffsetZ)
                                        * CFrame.Angles(math.rad(titanConfig.torsoRotX), math.rad(titanConfig.torsoRotY), math.rad(titanConfig.torsoRotZ))
                                elseif entry.name == "LowerTorso" then
                                    extraOffset = (entry.offset or CFrame.new())
                                        * CFrame.new(titanConfig.pelvisOffsetX, titanConfig.pelvisOffsetY, titanConfig.pelvisOffsetZ)
                                        * CFrame.Angles(math.rad(titanConfig.pelvisRotX), math.rad(titanConfig.pelvisRotY), math.rad(titanConfig.pelvisRotZ))
                                end
                                local targetCF = centerCF * CFrame.new(scaledPos) * relRot * extraOffset
                                local isCockpit = (entry.prop == cockpitBed) or (entry.name == "Head")
                                sendCF(entry.scf, targetCF, entry.prop, isCockpit)
                            end
                        end
                    end
                end)
                notify("Gigantic Titan", "Robot 6 assembled in Pure White! 15/15 Props firmly grounded.", 4)
            end
            local function deployPilotSeatTrap(targetPlr)
                if not targetPlr then
                    notify("Titan Trap", "Please select a Target Pilot in dropdown first!", 3)
                    if titanToggleRef and titanToggleRef.Set then pcall(function() titanToggleRef:Set(false) end) end
                    return
                end
                if titanActive or isWaitingForPilot then
                    stopTitan()
                    task.wait(0.4)
                end
                local char = lp.Character or lp.CharacterAdded:Wait()
                local hrp = char:WaitForChild(_0xS(6))
                local clearTools = rep:WaitForChild(_0xS(83)):WaitForChild(_0xS(87))
                pcall(function() clearTools:FireServer(_0xS(95)) end)
                task.wait(0.4)
                pcall(function() clearTools:FireServer("OpenPropMenu") end)
                task.wait(0.2)
                local targetChar = targetPlr and targetPlr.Character
                local targetHrp = targetChar and targetChar:FindFirstChild(_0xS(6))
                local spawnPos = targetHrp and (targetHrp.Position + (targetHrp.CFrame.LookVector * 4.5)) or (hrp.Position + (hrp.CFrame.LookVector * 8))
                notify("Titan Trap", "Deploying Cockpit Bed in front of " .. targetPlr.DisplayName .. "...", 3)
                
                local existingProps = {}
                local wc = workspace:FindFirstChild(_0xS(93))
                if wc then
                    for _, folder in pairs(wc:GetChildren()) do
                        for _, prop in pairs(folder:GetChildren()) do
                            if prop.Name == myPropName or prop.Name:find(lp.Name) then
                                existingProps[prop] = true
                            end
                        end
                    end
                end
                local firstBed = spawnSingleProp("FuturisticLargeBed", "Furniture", spawnPos, existingProps)
                if not firstBed then firstBed = spawnSingleProp("FuturisticLargeBed", "Furniture", spawnPos, existingProps) end
                if not firstBed then
                    notify("Titan Trap", "Failed to deploy cockpit prop!", 3)
                    if titanToggleRef and titanToggleRef.Set then pcall(function() titanToggleRef:Set(false) end) end
                    return
                end
                
                task.delay(1.0, function()
                    pcall(function()
                        local toolRemote = rep:FindFirstChild(_0xS(83)) and rep.RE:FindFirstChild(_0xS(88))
                        if toolRemote then toolRemote:InvokeServer(_0xS(90), _0xS(89)) end
                        local pmTool = (lp.Character and lp.Character:FindFirstChild(_0xS(89))) or (lp.Backpack and lp.Backpack:FindFirstChild(_0xS(89)))
                        if pmTool then pmTool:Destroy() end
                        local hum = lp.Character and lp.Character:FindFirstChildOfClass("Humanoid")
                        if hum then hum:UnequipTools() end
                    end)
                end)
                pcall(function()
                    local cpc = firstBed:FindFirstChild(_0xS(98)) or firstBed:FindFirstChild(_0xS(98), true)
                    if cpc then cpc:InvokeServer(Color3.fromRGB(255, 255, 255)) end
                    for _, p in ipairs(firstBed:GetDescendants()) do
                        if p:IsA("BasePart") then p.Color = Color3.fromRGB(255, 255, 255) end
                    end
                end)
                pilotBaitProp = firstBed
                isWaitingForPilot = true
                notify("Titan Trap", "Bed deployed! Waiting for " .. targetPlr.DisplayName .. " to sit...", 5)
                task.spawn(function()
                    local timeout = tick() + 120
                    while isWaitingForPilot and tick() < timeout do
                        if not pilotBaitProp or not pilotBaitProp.Parent then break end
                        if targetPlr and (not targetPlr.Parent or not targetPlr:IsDescendantOf(plrs)) then
                            notify("Titan Trap", "Target player left the game. Cancelling...", 3)
                            stopTitan()
                            return
                        end
                        local foundPilot = nil
                        for _, desc in ipairs(pilotBaitProp:GetDescendants()) do
                            if desc:IsA("Seat") or desc:IsA(_0xS(115)) then
                                local occ = desc.Occupant
                                if occ and occ:IsA("Humanoid") and occ.Parent then
                                    local p = plrs:GetPlayerFromCharacter(occ.Parent)
                                    if p then
                                        if p == targetPlr then
                                            foundPilot = p
                                            break
                                        else
                                            
                                            occ.Sit = false
                                            notify("Titan Trap", (p.DisplayName or "Player") .. " ejected! Only " .. targetPlr.DisplayName .. " can pilot!", 2)
                                        end
                                    end
                                end
                            end
                        end
                        if foundPilot then
                            isWaitingForPilot = false
                            currentPilot = foundPilot
                            notify("Gigantic Titan", foundPilot.DisplayName .. " seated in cockpit! Forging Robot 6...", 4)
                            task.spawn(function()
                                assembleTitanAroundPilot(pilotBaitProp, foundPilot)
                            end)
                            return
                        end
                        task.wait(0.1)
                    end
                    if isWaitingForPilot then
                        notify("Titan Trap", "Boarding timeout or cancelled.", 3)
                        isWaitingForPilot = false
                        if titanToggleRef and titanToggleRef.Set then pcall(function() titanToggleRef:Set(false) end) end
                    end
                end)
            end
            
            local function handleChatCommand(senderPlayer, message)
                if not titanActive then return end
                if not senderPlayer or not message then return end
                local senderUserId = senderPlayer.UserId
                local pilotUserId = currentPilot and currentPilot.UserId
                local localUserId = lp and lp.UserId
                local isAllowed = (senderUserId == localUserId) or (pilotUserId and senderUserId == pilotUserId)
                if not isAllowed then return end
                local cleanMsg = message:lower():gsub("^%s+", ""):gsub("%s+$", "")
                local emoteNumStr = cleanMsg:match("[:/]?[e%s]*emote%s*(%d+)")
                    or cleanMsg:match("^:?(%d+)$")
                if emoteNumStr then
                    local num = tonumber(emoteNumStr)
                    if num and num >= 1 and num <= 5 then
                        playTitanEmote(num)
                        return
                    elseif num == 0 then
                        stopTitanEmote()
                        return
                    end
                end
                if cleanMsg:find("stop") and (cleanMsg:find("emote") or cleanMsg:find("^[:/!]?stop") or cleanMsg == "stop") then
                    stopTitanEmote()
                end
            end
            pcall(function()
                local TextChatService = game:GetService(_0xS(69))
                TextChatService.MessageReceived:Connect(function(textChatMessage)
                    local sender = nil
                    if textChatMessage.TextSource then
                        sender = plrs:GetPlayerByUserId(textChatMessage.TextSource.UserId)
                    end
                    if sender then handleChatCommand(sender, textChatMessage.Text) end
                end)
            end)
            local function hookPlayerChat(p)
                p.Chatted:Connect(function(msg) handleChatCommand(p, msg) end)
            end
            for _, p in ipairs(plrs:GetPlayers()) do hookPlayerChat(p) end
            plrs.PlayerAdded:Connect(hookPlayerChat)
            plrs.PlayerRemoving:Connect(function(leavingPlr)
                local isTargetPilot = (currentPilot and leavingPlr.UserId == currentPilot.UserId)
                if isTargetPilot then
                    notify("Titan Controller", (leavingPlr.DisplayName or "Pilot") .. " left the game. Dismantling Titan...", 3)
                    stopTitan()
                end
            end)
            
            
            
            targetPilotDropdownRef = AdminTab:AddDropdown({
                Name = "الطيار المستهدف",
                Description = "Select player who will pilot the Titan (or '---')",
                Options = getPilotPlayersList(),
                Default = "---",
                Callback = function(val)
                    selectedPilotName = val
                    if val ~= "---" then
                        currentPilot = plrs:FindFirstChild(val)
                        if currentPilot then
                            notify("Titan Controller", "Selected target pilot: " .. currentPilot.DisplayName, 3)
                        end
                    else
                        currentPilot = nil
                    end
                end
            })
            AdminTab:AddButton({
                Name = "تحديث قائمة الطيارين",
                Description = "Refreshes player names in target pilot dropdown",
                Callback = function()
                    local updated = getPilotPlayersList()
                    if targetPilotDropdownRef and targetPilotDropdownRef.Set then
                        pcall(function() targetPilotDropdownRef:Set(updated) end)
                    end
                    notify("Titan Controller", "Pilot list refreshed!", 2)
                end
            })
            
            titanToggleRef = AdminTab:AddToggle({
                Name = "إنشاء قمرة القيادة (تُبنى عند الجلوس)",
                Description = "Spawns cockpit bed. When target sits, Titan builds & activates automatically!",
                Default = false,
                Callback = function(val)
                    if val then
                        local target = currentPilot
                        if not target and selectedPilotName ~= "---" then
                            target = plrs:FindFirstChild(selectedPilotName)
                        end
                        if not target then
                            notify("Titan Controller", "Please select a Target Pilot in dropdown first!", 3)
                            if titanToggleRef and titanToggleRef.Set then
                                pcall(function() titanToggleRef:Set(false) end)
                            end
                            return
                        end
                        task.spawn(function()
                            deployPilotSeatTrap(target)
                        end)
                    else
                        if titanActive or isWaitingForPilot then
                            stopTitan()
                        end
                    end
                end
            })
            
            forceEmoteDropdownRef = AdminTab:AddDropdown({
                Name = "فرض حركة العملاق",
                Description = "Select emote to immediately force on Titan (or Stop)",
                Options = {
                    "Stop Emote",
                    "1: Cute Sit",
                    "2: Dia Delicia Dance",
                    "3: Dance 3",
                    "4: Best Dance",
                    "5: Low Cortisol Dance"
                },
                Default = "Stop Emote",
                Callback = function(val)
                    if val == "Stop Emote" then
                        stopTitanEmote()
                    else
                        local num = tonumber(val:match("^(%d+)"))
                        if num then
                            playTitanEmote(num)
                        end
                    end
                end
            })
            AdminTab:AddButton({
                Name = "إيقاف العملاق / تنظيف المجسمات",
                Description = "إيقاف طارئ وتنظيف جميع المجسمات",
                Callback = function()
                    stopTitan()
                end
            })
        end
    end
