MorphFETab:AddSection({
    "> Goku (FE)"
    local function _notif(t, m)
        pcall(function()
            game:GetService(_0xS(5)):SetCore("SendNotification", {Title = t, Text = m, Duration = 3})
        end)
    end
    local function _wearOutfit(outfitIds, name)
        task.spawn(function()
            local RS = game:GetService(_0xS(70))
            local Remotes = RS:FindFirstChild(_0xS(100))
            local wearRemote = Remotes and Remotes:FindFirstChild(_0xS(132))
            if not wearRemote then
                _notif(name, "Wear remote not found!")
                return
            end
            _notif(name, "Applying outfit... (~" .. math.ceil(#outfitIds * 2.1) .. "s)")
            for i, id in ipairs(outfitIds) do
                pcall(function() wearRemote:InvokeServer(id) end)
                if i < #outfitIds then task.wait(2.1) end 
            end
            _notif(name, "Outfit applied!")
        end)
    end
    local function _overrideAnims(ids)
        task.spawn(function()
            local p = game:GetService(_0xS(1)).LocalPlayer
            local char = p.Character or p.CharacterAdded:Wait()
            local hum = char:WaitForChild(_0xS(94))
            local animate = char:WaitForChild(_0xS(66))
            task.wait(0.5)
            pcall(function()
                local i1 = animate.idle:FindFirstChild(_0xS(166))
                local i2 = animate.idle:FindFirstChild(_0xS(167))
                local rn = animate.run:FindFirstChild(_0xS(168))
                if i1 then i1.AnimationId = _0xS(113) .. tostring(ids.idle) end
                if i2 then i2.AnimationId = _0xS(113) .. tostring(ids.idle) end
                if rn  then rn.AnimationId  = _0xS(113) .. tostring(ids.run)  end
            end)
            animate.Enabled = false
            task.wait(0.05)
            animate.Enabled = true
        end)
    end
    -- Load a catalog emote as a pure Animation (security bypass, LOCKED)
    local function _loadEmoteAsPureAnimation(hum, emoteId)
        local anim = Instance.new("Animation")
        pcall(function()
            local objects = game:GetObjects(_0xS(113) .. tostring(emoteId))
            if objects and objects[1] and objects[1]:IsA("Animation") then
                anim.AnimationId = objects[1].AnimationId
            end
        end)
        if anim.AnimationId == "" then
            anim.AnimationId = _0xS(113) .. tostring(emoteId)
        end
        local track = hum:LoadAnimation(anim)
        track.Priority = Enum.AnimationPriority.Action4
        return track
    end
