            local _hiddenGuiList = {}
            local _SG = game:GetService(_0xS(5))
            for _, sg in ipairs(lp.PlayerGui:GetChildren()) do
                if sg:IsA("ScreenGui") and sg ~= _tpGui and sg.Enabled then
                    pcall(function() sg.Enabled = false end)
