                if not _tpGui then return end
                local myHRP = _hrp()
                local others = {}
                for _, pl in ipairs(PLR:GetPlayers()) do
                    if pl ~= lp then table.insert(others, pl) end
                end
                if myHRP then
                    table.sort(others, function(a, b)
                        local aHRP = a.Character and a.Character:FindFirstChild(_0xS(6))
                        local bHRP = b.Character and b.Character:FindFirstChild(_0xS(6))
                        local ad = aHRP and (myHRP.Position-aHRP.Position).Magnitude or math.huge
                        local bd = bHRP and (myHRP.Position-bHRP.Position).Magnitude or math.huge
                        return ad < bd
                    end)
                end
                local RS2    = game:GetService(_0xS(15))
                local cam    = workspace.CurrentCamera
                local origCT = cam.CameraType
                cam.CameraType = Enum.CameraType.Scriptable
                local selectedIdx = 1
                local navConn = nil
                local function focusOnPlayer(idx)
                    local tgt  = others[idx]
                    if not tgt or not myHRP then return end
                    local pHRP   = tgt.Character and tgt.Character:FindFirstChild(_0xS(6))
                    local myPos  = myHRP.Position
                    local tgtPos = pHRP and pHRP.Position or (myPos + Vector3.new(0,2,-20))
                    local dir    = (tgtPos - myPos)
                    dir = dir.Magnitude > 0.5 and dir.Unit or Vector3.new(0,0,-1)
                    local camPos = myPos + Vector3.new(0,4.5,0) - dir*9
                    local toCF   = CFrame.lookAt(camPos, tgtPos + Vector3.new(0,2,0))
                    local fromCF = cam.CFrame
                    if navConn then navConn:Disconnect() end
                    local elapsed = 0
                    navConn = RS2.RenderStepped:Connect(function(dt)
                        if not _tpGui then if navConn then navConn:Disconnect() end; return end
                        elapsed = elapsed + dt
                        local t = math.clamp(elapsed/0.55, 0, 1)
                        cam.CFrame = fromCF:Lerp(toCF, 1-(1-t)^3)
                        if elapsed >= 0.55 then navConn:Disconnect(); navConn=nil end
                    end)
                end
                
                local BAR_H = 0.13
                local barTopSel = Instance.new("Frame")
                barTopSel.Size = UDim2.new(1,0,0,0); barTopSel.Position = UDim2.new(0,0,0,0)
                barTopSel.BackgroundColor3 = Color3.fromRGB(0,0,0); barTopSel.BackgroundTransparency = 0
                barTopSel.BorderSizePixel = 0; barTopSel.ZIndex = 30; barTopSel.Parent = _tpGui
                local barBotSel = Instance.new("Frame")
                barBotSel.Size = UDim2.new(1,0,0,0); barBotSel.Position = UDim2.new(0,0,1,0)
                barBotSel.BackgroundColor3 = Color3.fromRGB(0,0,0); barBotSel.BackgroundTransparency = 0
                barBotSel.BorderSizePixel = 0; barBotSel.ZIndex = 30; barBotSel.Parent = _tpGui
                TW:Create(barTopSel, TweenInfo.new(0.4, Enum.EasingStyle.Quint), {Size = UDim2.new(1,0,BAR_H,0)}):Play()
                TW:Create(barBotSel, TweenInfo.new(0.4, Enum.EasingStyle.Quint), {
                    Size = UDim2.new(1,0,BAR_H,0), Position = UDim2.new(0,0,1-BAR_H,0)
                }):Play()
                task.wait(0.4)
                if not _tpGui then cam.CameraType=origCT; return end
                
