                            local t=easeFn and easeFn(raw) or raw
                            cam.CFrame=fromCF:Lerp(toCF,t)
                            if elapsed>=duration then conn:Disconnect() end
                        end)
                        task.wait(duration)
                        if conn.Connected then conn:Disconnect() end
                    end
                    local function orbitCam(center, radius, startAngle, endAngle, height, duration, easeFn)
                        local elapsed=0; local conn
                        conn=RS2.RenderStepped:Connect(function(dt)
                            elapsed=elapsed+dt
                            local raw=math.clamp(elapsed/duration,0,1)
                            local t=easeFn and easeFn(raw) or raw
                            local angle=startAngle+(endAngle-startAngle)*t
                            local camPos=center+Vector3.new(math.cos(angle)*radius,height,math.sin(angle)*radius)
                            cam.CFrame=CFrame.lookAt(camPos,center+Vector3.new(0,2,0))
                            if elapsed>=duration then conn:Disconnect() end
                        end)
                        task.wait(duration)
