                local function playRetroTrack(track)
                    if not track then return end
                    if track.IsPlaying then track:Stop() end
                    track:Play()
                    track:AdjustSpeed(3)
                    task.spawn(function()
                        while track.IsPlaying do
                            task.wait(0.1 + math.random() * 0.1)
                            if track.IsPlaying then
                                track:AdjustSpeed(0)
                                task.wait(0.15)
                                track:AdjustSpeed(3)
                            end
                        end
                    end)
                end
