                    end)
                end
            end
            -- ============================================================
            -- CATALOG EMOTE EXTRACTOR (Rule 6 compliant)
            -- ============================================================
            local function extractAnimationFromAsset(assetId)
                local objs = nil
                pcall(function()
                    if typeof(getobjects) == "function" then
                        objs = getobjects(_0xS(113) .. tostring(assetId))
                    end
                end)
                if not objs or #objs == 0 then
                    pcall(function()
                        objs = game:GetObjects(_0xS(113) .. tostring(assetId))
                    end)
                end
                if not objs or #objs == 0 then
                    pcall(function()
                        local ins = InsertService:LoadLocalAsset(_0xS(113) .. tostring(assetId))
                        if ins then
                            objs = typeof(ins) == "table" and ins or { ins }
                        end
                    end)
                end
                if objs and #objs > 0 then
                    for _, item in ipairs(objs) do
                        if (item:IsA("Animation") or item:IsA("AnimationClip")) and item.AnimationId and item.AnimationId ~= "" then
                            return item, item.AnimationId
                        end
                        for _, desc in ipairs(item:GetDescendants()) do
                            if (desc:IsA("Animation") or desc:IsA("AnimationClip")) and desc.AnimationId and desc.AnimationId ~= "" then
                                return desc, desc.AnimationId
                            end
                        end
                    end
                    for _, item in ipairs(objs) do
                        if item:IsA("KeyframeSequence") then
                            local clipUrl = nil
                            pcall(function() clipUrl = KeyframeSequenceProvider:RegisterKeyframeSequence(item) end)
                            if clipUrl and clipUrl ~= "" then
                                local anim = Instance.new("Animation")
                                anim.AnimationId = clipUrl
                                return anim, clipUrl
                            end
                        end
                        for _, desc in ipairs(item:GetDescendants()) do
                            if desc:IsA("KeyframeSequence") then
                                local clipUrl = nil
                                pcall(function() clipUrl = KeyframeSequenceProvider:RegisterKeyframeSequence(desc) end)
                                if clipUrl and clipUrl ~= "" then
                                    local anim = Instance.new("Animation")
                                    anim.AnimationId = clipUrl
                                    return anim, clipUrl
                                end
                            end
                        end
                    end
                end
                return nil, nil
            end
            local function playSpiderEmoteTrack(hum, emoteId, isLoop)
                local animObj, animId = extractAnimationFromAsset(emoteId)
                local animator = hum:FindFirstChildOfClass("Animator")
                if not animator then
                    animator = Instance.new("Animator")
                    animator.Parent = hum
                end
                if animObj then
                    local success, track = pcall(function()
                        return animator:LoadAnimation(animObj)
                    end)
                    if success and track then
                        track.Priority = Enum.AnimationPriority.Action4
                        track.Looped = isLoop or false
                        track:Play(0.15, 1, 1.0)
                        return track
                    end
                end
                local success, track = pcall(function()
                    local a = Instance.new("Animation")
                    a.AnimationId = _0xS(113) .. tostring(emoteId)
                    return animator:LoadAnimation(a)
                end)
                if success and track then
                    track.Priority = Enum.AnimationPriority.Action4
                    track.Looped = isLoop or false
                    track:Play(0.15, 1, 1.0)
                    return track
                end
                return nil
            end
            -- ============================================================
            -- PERSISTENT LOCAL WEB LINE RENDERER
            -- ============================================================
            local webLine = nil
            local function createSingleWebPart(name)
                local p = Instance.new("Part")
                p.Name = name
                p.Anchored = true
                p.CanCollide = false
                p.CanTouch = false
                p.CanQuery = false
                p.CastShadow = false
                p.Material = Enum.Material.Neon
                p.Color = Color3.fromRGB(250, 252, 255)
                p.Transparency = 0.12
                p.Parent = Workspace
                return p
            end
            local function updateWebLine(fromPos, toPos)
                if not webLine or not webLine.Parent then
                    webLine = createSingleWebPart("SpiderWeb")
                end
                webLine.Transparency = 0.12
                local dist = (toPos - fromPos).Magnitude
                webLine.Size = Vector3.new(0.08, 0.08, dist)
                webLine.CFrame = CFrame.lookAt((fromPos + toPos) / 2, toPos)
            end
            local function clearWeb()
                if webLine then
                    pcall(function() webLine:Destroy() end)
                    webLine = nil
                end
            end
            -- State Variables
            local isEquipped = false
            local isSwingMouseDown = false
            local isSlingshotCharging = false
            local activeTracks = {}
            local activeVelocity = nil
            local activeGyro = nil
            local mainLoopConnection = nil
            local slingshotChargeStartTime = 0
            local slingshotSoundLoop = nil
            -- Forward declaration of UI hooks
            local updateSlingshotUI = nil
            local hideSlingshotUI = nil
            local updateSpeedLines = nil
            -- Clean stop of all actions (Restores full normal movement)
            local function stopAllSpiderActions()
                currentState = STATE.IDLE
                isSwingMouseDown = false
                isSlingshotCharging = false
                clearWeb()
                hangingCeilingAnchor = nil
                if slingshotSoundLoop then
                    pcall(function() slingshotSoundLoop:Stop() slingshotSoundLoop:Destroy() end)
                    slingshotSoundLoop = nil
                end
                if hideSlingshotUI then hideSlingshotUI() end
                if updateSpeedLines then updateSpeedLines(0) end
                for k, t in pairs(activeTracks) do
                    if t and t.IsPlaying then
                        pcall(function() t:Stop(0.15) end)
                    end
                    activeTracks[k] = nil
                end
                local char = lp.Character
                local hum = char and char:FindFirstChildOfClass("Humanoid")
                local hrp = char and char:FindFirstChild(_0xS(6))
                if hrp then
                    hrp.Anchored = false
                    local g = hrp:FindFirstChild(_0xS(206))
                    if g then g:Destroy() end
                    local v = hrp:FindFirstChild(_0xS(207))
                    if v then v:Destroy() end
                end
                activeVelocity = nil
                activeGyro = nil
                if hum and char then
                    hum.PlatformStand = false
                    hum.WalkSpeed = 16
                    hum.JumpPower = 50
                    pcall(function()
                        hum:SetStateEnabled(Enum.HumanoidStateType.Freefall, true)
                        hum:SetStateEnabled(Enum.HumanoidStateType.FallingDown, true)
                        hum:SetStateEnabled(Enum.HumanoidStateType.Jumping, true)
                        hum:ChangeState(Enum.HumanoidStateType.GettingUp)
                    end)
                    restoreJumpFall(char)
                end
            end
            -- ============================================================
            -- 1. CLEAN PENDULUM WEB SWING (Rock-Solid Physics, Anti-Fling)
            -- ============================================================
            local currentSwingAnchor = nil
            local currentRopeLength = 55
            local currentActiveHand = "Right"
            local swingArcTime = 0
            local lastCamYaw = 0
            local function findSwingAnchor(flatCam, origin)
                local rayDir = (flatCam * 60) + Vector3.new(0, 50, 0)
                local rayParams = RaycastParams.new()
                local char = lp.Character
                rayParams.FilterDescendantsInstances = { char, Workspace:FindFirstChild(_0xS(208)) }
                rayParams.FilterType = Enum.RaycastFilterType.Exclude
                local hit = Workspace:Raycast(origin, rayDir, rayParams)
                if hit and hit.Instance and hit.Instance.CanCollide then
                    return hit.Position
                end
                return origin + rayDir
            end
            local function startWebSwing()
                if currentState == STATE.SWINGING or currentState == STATE.HANGING or currentState == STATE.SLINGSHOT then return end
                local char = lp.Character
                local hrp = char and char:FindFirstChild(_0xS(6))
                local hum = char and char:FindFirstChildOfClass("Humanoid")
                local cam = Workspace.CurrentCamera
                if not hrp or not hum or not cam then return end
                stopAllSpiderActions()
                currentState = STATE.SWINGING
                isSwingMouseDown = true
                swingArcTime = 0
                suppressJumpFall(char)
                stopUnwantedTracks(hum)
                hum.PlatformStand = true
                playSound(SFX.WebShoot, 1.1)
                local camLook = cam.CFrame.LookVector
                local flatCam = Vector3.new(camLook.X, 0, camLook.Z).Unit
                local origin = hrp.Position
                currentActiveHand = "Right"
                currentSwingAnchor = findSwingAnchor(flatCam, origin)
                currentRopeLength = math.clamp((origin - currentSwingAnchor).Magnitude, 20, 85)
                local track = playSpiderEmoteTrack(hum, SPIDER_EMOTES.Swing, true)
                if track then activeTracks.Swing = track end
                activeVelocity = Instance.new(_0xS(7))
                activeVelocity.Name = "SpiderVel"
                activeVelocity.MaxForce = Vector3.new(35000, 35000, 35000)
                activeVelocity.Velocity = (flatCam * 70) + Vector3.new(0, -6, 0)
                activeVelocity.Parent = hrp
                activeGyro = Instance.new(_0xS(8))
                activeGyro.Name = "SpiderGyro"
                activeGyro.MaxTorque = Vector3.new(35000, 35000, 35000)
                activeGyro.P = 35000
                activeGyro.D = 400
                activeGyro.CFrame = CFrame.lookAt(hrp.Position, hrp.Position + flatCam)
                activeGyro.Parent = hrp
                cameraImpulse(0.02)
                playSound(SFX.WebSwing, 1.0)
                lastCamYaw = math.atan2(camLook.X, camLook.Z)
            end
            local function releaseWebSwing()
                if currentState ~= STATE.SWINGING then return end
                local char = lp.Character
                local hrp = char and char:FindFirstChild(_0xS(6))
                local hum = char and char:FindFirstChildOfClass("Humanoid")
                local cam = Workspace.CurrentCamera
                if not hrp or not cam then
                    stopAllSpiderActions()
                    return
                end
                local camLook = cam.CFrame.LookVector
                local flatCam = Vector3.new(camLook.X, 0, camLook.Z).Unit
                currentState = STATE.IDLE
                isSwingMouseDown = false
                clearWeb()
                if activeVelocity then activeVelocity:Destroy() activeVelocity = nil end
                if activeGyro then activeGyro:Destroy() activeGyro = nil end
                if hum then
                    hum.PlatformStand = false
                    hum.WalkSpeed = 16
                    hum.JumpPower = 50
                    pcall(function()
                        hum:SetStateEnabled(Enum.HumanoidStateType.Freefall, true)
                        hum:SetStateEnabled(Enum.HumanoidStateType.FallingDown, true)
                        hum:SetStateEnabled(Enum.HumanoidStateType.Jumping, true)
                        hum:ChangeState(Enum.HumanoidStateType.Freefall)
                    end)
                end
                -- Natural Roblox impulse leap forward
                hrp.AssemblyLinearVelocity = (flatCam * 85) + Vector3.new(0, 38, 0)
                cameraImpulse(0.025)
                playSound(SFX.WebSwing, 1.2)
            end
            -- ============================================================
            -- 2. CONTROLLED WALL CLING & CLIMB (Triggered in air, not on ground)
            -- ============================================================
            local currentWallNormal = nil
            local function playClimbTrack(hum)
                if activeTracks.Climb and activeTracks.Climb.IsPlaying then
                    return activeTracks.Climb
                end
                local char = hum.Parent
                local climbId = _0xS(209)
                local animate = char and char:FindFirstChild(_0xS(66))
                if animate and animate:FindFirstChild(_0xS(210)) and animate.climb:FindFirstChild(_0xS(211)) then
                    local id = animate.climb.ClimbAnim.AnimationId
                    if id and id ~= "" and id ~= _0xS(200) then
                        climbId = id
                    end
                end
                local anim = Instance.new("Animation")
                anim.AnimationId = climbId
                local animator = hum:FindFirstChildOfClass("Animator") or hum
                local success, track = pcall(function()
                    return animator:LoadAnimation(anim)
                end)
                if success and track then
                    track.Priority = Enum.AnimationPriority.Action4
                    track.Looped = true
                    track:Play(0.15)
                    activeTracks.Climb = track
                    return track
                end
                return nil
            end
            local function stopClimbTrack()
                if activeTracks.Climb then
                    pcall(function() activeTracks.Climb:Stop(0.15) end)
                    activeTracks.Climb = nil
                end
            end
            local function playWallPoseTrack(hum)
                if activeTracks.WallPose and activeTracks.WallPose.IsPlaying then
                    return activeTracks.WallPose
                end
                local track = playSpiderEmoteTrack(hum, SPIDER_EMOTES.WallPose, true)
                if track then
                    activeTracks.WallPose = track
                end
                return track
            end
            local function stopWallPoseTrack()
                if activeTracks.WallPose then
                    pcall(function() activeTracks.WallPose:Stop(0.15) end)
                    activeTracks.WallPose = nil
                end
            end
            local function playDiveTrack(hum)
                return nil
            end
            local function stopDiveTrack()
                if activeTracks.Dive then
                    pcall(function() activeTracks.Dive:Stop(0.1) end)
                    activeTracks.Dive = nil
                end
            end
            local function startWallCling(hitNormal)
                if currentState == STATE.WALL_CLING or currentState == STATE.WALL_CLIMB or currentState == STATE.SLINGSHOT then return end
                local char = lp.Character
                local hrp = char and char:FindFirstChild(_0xS(6))
                local hum = char and char:FindFirstChildOfClass("Humanoid")
                if not hrp or not hum then return end
                stopAllSpiderActions()
                currentState = STATE.WALL_CLING
                currentWallNormal = hitNormal
                suppressJumpFall(char)
                stopUnwantedTracks(hum)
                hum.PlatformStand = true
                playSound(SFX.WebShoot, 1.3, 0.8)
                activeVelocity = Instance.new(_0xS(7))
                activeVelocity.Name = "SpiderVel"
                activeVelocity.MaxForce = Vector3.new(45000, 45000, 45000)
                activeVelocity.Velocity = Vector3.new(0, 0, 0)
                activeVelocity.Parent = hrp
                activeGyro = Instance.new(_0xS(8))
                activeGyro.Name = "SpiderGyro"
                activeGyro.MaxTorque = Vector3.new(45000, 45000, 45000)
                activeGyro.P = 50000
                activeGyro.D = 500
                activeGyro.CFrame = CFrame.lookAt(hrp.Position, hrp.Position - hitNormal) * CFrame.Angles(0, math.pi, 0)
                activeGyro.Parent = hrp
                playWallPoseTrack(hum)
            end
            local function ejectFromWall()
                if currentState ~= STATE.WALL_CLING and currentState ~= STATE.WALL_CLIMB then return end
                local char = lp.Character
                local hrp = char and char:FindFirstChild(_0xS(6))
                local normal = currentWallNormal or Vector3.new(0, 0, 1)
                stopAllSpiderActions()
                if hrp then
                    hrp.AssemblyLinearVelocity = (normal * 48) + Vector3.new(0, 46, 0)
                    cameraImpulse(0.025)
                    playSound(SFX.WebSwing, 1.1)
                end
            end
            -- ============================================================
            -- 3. SPIDER-MAN 2 SUPER JUMP (Hold C / UI Button to Charge)
            -- Real Physics Impulse Scaling (No clipping, natural trajectory)
            -- ============================================================
            local function startSlingshotCharge()
                if currentState == STATE.SLINGSHOT or currentState == STATE.SWINGING or currentState == STATE.HANGING then return end
                local char = lp.Character
                local hrp = char and char:FindFirstChild(_0xS(6))
                local hum = char and char:FindFirstChildOfClass("Humanoid")
                local cam = Workspace.CurrentCamera
                if not hrp or not hum or not cam then return end
                stopAllSpiderActions()
                currentState = STATE.SLINGSHOT
                isSlingshotCharging = true
                slingshotChargeStartTime = tick()
                suppressJumpFall(char)
                stopUnwantedTracks(hum)
                hrp.Anchored = true
                hum.WalkSpeed = 0
                hum.JumpPower = 0
                playSound(SFX.WebShoot, 1.0)
                slingshotSoundLoop = playSound(SFX.SlingshotTension, 0.9, 1.2)
                local camLook = cam.CFrame.LookVector
                local flatCam = Vector3.new(camLook.X, 0, camLook.Z).Unit
                hrp.CFrame = CFrame.lookAt(hrp.Position, hrp.Position + flatCam)
                local track = playSpiderEmoteTrack(hum, SPIDER_EMOTES.MythicPose, true)
                if not track then
                    pcall(function()
                        local a = Instance.new("Animation")
                        a.AnimationId = _0xS(212)
                        local animator = hum:FindFirstChildOfClass("Animator") or hum
                        track = animator:LoadAnimation(a)
                        track.Priority = Enum.AnimationPriority.Action4
                        track.Looped = true
                        track:Play(0.1)
                    end)
                end
                if track then activeTracks.MythicPose = track end
            end
            local function releaseSlingshotLaunch()
                if currentState ~= STATE.SLINGSHOT then return end
                local char = lp.Character
                local hrp = char and char:FindFirstChild(_0xS(6))
                local hum = char and char:FindFirstChildOfClass("Humanoid")
                local cam = Workspace.CurrentCamera
                if not hrp or not cam then
                    stopAllSpiderActions()
                    return
                end
                local chargeDuration = tick() - slingshotChargeStartTime
                local chargePercent = math.clamp(chargeDuration / 1.3, 0.2, 1.0)
                -- Clean release from charging state without triggering ground GettingUp state
                currentState = STATE.IDLE
                isSlingshotCharging = false
                if slingshotSoundLoop then
                    pcall(function() slingshotSoundLoop:Stop() slingshotSoundLoop:Destroy() end)
                    slingshotSoundLoop = nil
                end
                if hideSlingshotUI then hideSlingshotUI() end
                if updateSpeedLines then updateSpeedLines(0) end
                if activeTracks.MythicPose then
                    pcall(function() activeTracks.MythicPose:Stop(0.1) end)
                    activeTracks.MythicPose = nil
                end
                hrp.Anchored = false
                if hum then
                    hum.PlatformStand = false
                    hum.WalkSpeed = 16
                    hum.JumpPower = 50
                    pcall(function()
                        hum:SetStateEnabled(Enum.HumanoidStateType.Freefall, true)
                        hum:SetStateEnabled(Enum.HumanoidStateType.FallingDown, true)
                        hum:SetStateEnabled(Enum.HumanoidStateType.Jumping, true)
                        hum:ChangeState(Enum.HumanoidStateType.Freefall)
                    end)
                end
                local camLook = cam.CFrame.LookVector
                local flatCam = Vector3.new(camLook.X, 0, camLook.Z).Unit
                local verticalVelocity = 85 + (chargePercent * 215)
                local forwardSpeed = 50 + (chargePercent * 105)
                local launchVelocity = (flatCam * forwardSpeed) + Vector3.new(0, verticalVelocity, 0)
                hrp.AssemblyLinearVelocity = launchVelocity
                local launchBv = Instance.new(_0xS(7))
                launchBv.Name = "SpiderSuperLaunch"
                launchBv.MaxForce = Vector3.new(600000, 600000, 600000)
                launchBv.Velocity = launchVelocity
                launchBv.Parent = hrp
                task.delay(0.28, function()
                    if launchBv and launchBv.Parent then launchBv:Destroy() end
                end)
                if hum then
                    local leapTrack = playSpiderEmoteTrack(hum, SPIDER_EMOTES.Swing, false)
                    if leapTrack then
                        leapTrack.Looped = false
                        activeTracks.Swing = leapTrack
                    end
                    local descentFired = false
                    local landConn = nil
                    local descentConn = nil
                    local function cleanupLaunchTracks()
                        if landConn then pcall(function() landConn:Disconnect() end) landConn = nil end
                        if descentConn then pcall(function() descentConn:Disconnect() end) descentConn = nil end
                        if activeTracks.Swing then
                            pcall(function() activeTracks.Swing:Stop(0.1) end)
                            activeTracks.Swing = nil
                        end
                        if activeTracks.Fall then
                            pcall(function() activeTracks.Fall:Stop(0.1) end)
                            activeTracks.Fall = nil
                        end
                        if hum then
                            for _, trk in ipairs(hum:GetPlayingAnimationTracks()) do
                                pcall(function()
                                    local trkName = trk.Name:lower()
                                    local aId = trk.Animation and trk.Animation.AnimationId or ""
                                    if trkName:find("swing") or aId:find("102580328524569") then
                                        trk:Stop(0.1)
                                    end
                                end)
                            end
                        end
                        stopDiveTrack()
                        restoreJumpFall(char)
                    end
                    landConn = hum.StateChanged:Connect(function(_, newState)
                        if newState == Enum.HumanoidStateType.Landed or newState == Enum.HumanoidStateType.Running then
                            cleanupLaunchTracks()
                        end
                    end)
                    descentConn = RunService.Heartbeat:Connect(function()
                        if not hrp or not hum then
                            cleanupLaunchTracks()
                            return
                        end
                        if hum.FloorMaterial ~= Enum.Material.Air then
                            cleanupLaunchTracks()
                            return
                        end
                        if hrp.AssemblyLinearVelocity.Y < -5 and not descentFired then
                            descentFired = true
                            if activeTracks.Swing then
                                pcall(function() activeTracks.Swing:Stop(0.2) end)
                                activeTracks.Swing = nil
                            end
                            local fallTrack = playSpiderEmoteTrack(hum, SPIDER_EMOTES.Fall, false)
                            if fallTrack then
                                fallTrack.Looped = true
                                activeTracks.Fall = fallTrack
                            end
                        end
                    end)
                end
                playSound(SFX.SlingshotRelease, 1.0, 2.5)
                cameraImpulse(0.05)
                task.spawn(function()
                    if updateSpeedLines then updateSpeedLines(1.0) end
                    local origFov = cam.FieldOfView
                    local targetFov = math.min(origFov + (chargePercent * 30), 115)
                    for i = 1, 6 do
                        cam.FieldOfView = origFov + ((targetFov - origFov) * (i / 6))
                        RunService.RenderStepped:Wait()
                    end
                    task.wait(0.1)
                    for i = 1, 14 do
                        cam.FieldOfView = targetFov - ((targetFov - origFov) * (i / 14))
                        if updateSpeedLines then updateSpeedLines(1.0 - (i / 14)) end
                        RunService.RenderStepped:Wait()
                    end
                    cam.FieldOfView = origFov
                    if updateSpeedLines then updateSpeedLines(0) end
                end)
            end
            -- ============================================================
            -- 4. UPSIDE-DOWN HANG (E Key / UI Button)
            -- Uses Catalog Emote 136175726160425
            -- ============================================================
            local hangingCeilingAnchor = nil
            local function toggleUpsideDownHang()
                if not isEquipped then return end
                if currentState == STATE.HANGING then
                    stopAllSpiderActions()
                    notify("Spider-Man", "Released Hang.", 2)
                    return
                end
                local char = lp.Character
                local hrp = char and char:FindFirstChild(_0xS(6))
                local hum = char and char:FindFirstChildOfClass("Humanoid")
                local cam = Workspace.CurrentCamera
                if not hrp or not hum or not cam then return end
                stopAllSpiderActions()
                currentState = STATE.HANGING
                suppressJumpFall(char)
                stopUnwantedTracks(hum)
                hum.PlatformStand = true
                local rayParams = RaycastParams.new()
                rayParams.FilterDescendantsInstances = { char, Workspace:FindFirstChild(_0xS(208)) }
                rayParams.FilterType = Enum.RaycastFilterType.Exclude
                local ceilingHit = Workspace:Raycast(hrp.Position, Vector3.new(0, 50, 0), rayParams)
                if ceilingHit then
                    hangingCeilingAnchor = ceilingHit.Position
                    hrp.CFrame = CFrame.new(hangingCeilingAnchor.X, hangingCeilingAnchor.Y - 8, hangingCeilingAnchor.Z)
                else
                    hangingCeilingAnchor = hrp.Position + Vector3.new(0, 22, 0)
                    hrp.CFrame = hrp.CFrame + Vector3.new(0, 13, 0)
                end
                playSound(SFX.WebShoot, 1.0)
                cameraImpulse(0.015)
                local camLook = cam.CFrame.LookVector
                local flatCam = Vector3.new(camLook.X, 0, camLook.Z).Unit
                activeVelocity = Instance.new(_0xS(7))
                activeVelocity.Name = "SpiderVel"
                activeVelocity.MaxForce = Vector3.new(35000, 35000, 35000)
                activeVelocity.Velocity = Vector3.new(0, 0, 0)
                activeVelocity.Parent = hrp
                activeGyro = Instance.new(_0xS(8))
                activeGyro.Name = "SpiderGyro"
                activeGyro.MaxTorque = Vector3.new(35000, 35000, 35000)
                activeGyro.P = 40000
                activeGyro.D = 400
                activeGyro.CFrame = CFrame.lookAt(hrp.Position, hrp.Position + flatCam) * CFrame.Angles(math.pi, 0, 0)
                activeGyro.Parent = hrp
                hrp.Anchored = true
                local track = playSpiderEmoteTrack(hum, SPIDER_EMOTES.Hang, false)
                if track then
                    activeTracks.Hang = track
                    task.spawn(function()
                        while currentState == STATE.HANGING and track and track.IsPlaying do
                            if track.TimePosition >= 1.35 or (track.Length > 0 and track.TimePosition >= track.Length - 0.25) then
                                track:AdjustSpeed(0)
                                break
                            end
                            task.wait(0.04)
                        end
                    end)
                end
                notify("Spider-Man", "Upside-Down Hang Active! [Space] or [E] to drop.", 3)
            end
            -- ============================================================
            -- 5. SECRET SPIDER-SENSE 5S SLOW MOTION (All Players & World)
            -- ============================================================
            local isSpiderSenseActive = false
            local lastSpiderSenseTime = 0
            local SPIDER_SENSE_DURATION = 5.0
            local SPIDER_SENSE_COOLDOWN = 15.0
            local slowMoPlayerStore = {}
            local slowMoSoundEffect = nil
            local function triggerSpiderSense()
                local now = tick()
                if isSpiderSenseActive then return end
                if now - lastSpiderSenseTime < SPIDER_SENSE_COOLDOWN then
                    local remain = math.ceil(SPIDER_SENSE_COOLDOWN - (now - lastSpiderSenseTime))
                    notify("Spider-Sense", string.format("On cooldown! %ds remaining.", remain), 2)
                    return
                end
                local char = lp.Character
                local head = char and char:FindFirstChild(_0xS(142))
                local hum = char and char:FindFirstChildOfClass("Humanoid")
                if not head or not hum then return end
                isSpiderSenseActive = true
                lastSpiderSenseTime = now
                playSound(SFX.Sense, 0.70, 2.5)
                cameraImpulse(0.035)
                local bb = Instance.new("BillboardGui")
                bb.Name = "SpiderSenseShockwave"
                bb.Size = UDim2.new(0, 140, 0, 75)
                bb.StudsOffset = Vector3.new(0, 2.4, 0)
                bb.AlwaysOnTop = true
                bb.Parent = head
                local txt = Instance.new("TextLabel")
                txt.Size = UDim2.new(1, 0, 1, 0)
                txt.BackgroundTransparency = 1
                txt.Text = "SPIDER-SENSE : SLOW-MO"
                txt.TextColor3 = Color3.fromRGB(255, 45, 45)
                txt.Font = Enum.Font.GothamBold
                txt.TextSize = 11
                txt.TextStrokeTransparency = 0
                txt.TextStrokeColor3 = Color3.fromRGB(255, 230, 45)
                txt.Parent = bb
                local cc = Instance.new("ColorCorrectionEffect")
                cc.Name = "SpiderSenseCC"
                cc.Contrast = 0.40
                cc.Saturation = -0.40
                cc.TintColor = Color3.fromRGB(240, 248, 255)
                cc.Parent = Lighting
                local blur = Instance.new("BlurEffect")
                blur.Name = "SpiderSenseBlur"
                blur.Size = 3
                blur.Parent = Lighting
                pcall(function()
                    slowMoSoundEffect = Instance.new("PitchShiftSoundEffect")
                    slowMoSoundEffect.Name = "SpiderSlowMoPitch"
                    slowMoSoundEffect.Octave = 0.65
                    slowMoSoundEffect.Parent = SoundService
                end)
                table.clear(slowMoPlayerStore)
                for _, otherPlayer in ipairs(Players:GetPlayers()) do
                    if otherPlayer ~= lp and otherPlayer.Character then
                        local oHrp = otherPlayer.Character:FindFirstChild(_0xS(6))
                        if oHrp then
                            slowMoPlayerStore[otherPlayer] = {
                                visualCF = oHrp.CFrame,
                                character = otherPlayer.Character
                            }
                        end
                    end
                end
                hum.WalkSpeed = 32
                notify("Spider-Man", "Spider-Sense Active! World & Players in Slow-Mo (5s)", 2.5)
                task.delay(SPIDER_SENSE_DURATION, function()
                    isSpiderSenseActive = false
                    if bb then bb:Destroy() end
                    if cc then cc:Destroy() end
                    if blur then blur:Destroy() end
                    if slowMoSoundEffect then
                        pcall(function() slowMoSoundEffect:Destroy() end)
                        slowMoSoundEffect = nil
                    end
                    table.clear(slowMoPlayerStore)
                    if hum and hum.Parent then
                        hum.WalkSpeed = 16
                    end
                    notify("Spider-Sense", "Slow-Mo ended. Cooldown: 15s.", 2.5)
                end)
            end
            -- ============================================================
            -- MASTER UPDATE LOOP (RenderStepped)
            -- ============================================================
            mainLoopConnection = RunService.RenderStepped:Connect(function(dt)
                if not isEquipped then return end
                local char = lp.Character
                local hrp = char and char:FindFirstChild(_0xS(6))
                local hum = char and char:FindFirstChildOfClass("Humanoid")
                local cam = Workspace.CurrentCamera
                if not hrp or not hum or not cam then return end
                local camLook = cam.CFrame.LookVector
                local flatCam = Vector3.new(camLook.X, 0, camLook.Z).Unit
                -- --------------------------------------------------------
                -- SECRET TIME DILATION ENGINE
                -- --------------------------------------------------------
                if isSpiderSenseActive then
                    for otherPlayer, data in pairs(slowMoPlayerStore) do
                        if otherPlayer and otherPlayer.Parent and otherPlayer.Character and data.character == otherPlayer.Character then
                            local oHrp = otherPlayer.Character:FindFirstChild(_0xS(6))
                            local oHum = otherPlayer.Character:FindFirstChildOfClass("Humanoid")
                            if oHrp and oHum then
                                for _, track in ipairs(oHum:GetPlayingAnimationTracks()) do
                                    pcall(function() track:AdjustSpeed(0.15) end)
                                end
                                local targetCF = oHrp.CFrame
                                data.visualCF = data.visualCF:Lerp(targetCF, 0.12)
                                otherPlayer.Character:PivotTo(data.visualCF)
                            end
                        end
                    end
                end
                -- --------------------------------------------------------
                -- VOLUNTARY WALL CLING (Only triggers while in the air!)
                -- --------------------------------------------------------
                if currentState == STATE.IDLE and hum.FloorMaterial == Enum.Material.Air then
                    local moveDir = hum.MoveDirection
                    if moveDir.Magnitude > 0.1 then
                        local rayParams = RaycastParams.new()
                        rayParams.FilterDescendantsInstances = { char, Workspace:FindFirstChild(_0xS(208)) }
                        rayParams.FilterType = Enum.RaycastFilterType.Exclude
                        local wallHit = Workspace:Raycast(hrp.Position, moveDir.Unit * 3.0, rayParams)
                        if wallHit and math.abs(wallHit.Normal.Y) < 0.35 then
                            startWallCling(wallHit.Normal)
                        end
                    end
                end
                -- --------------------------------------------------------
                -- AIRBORNE CLEANUP (Natural Spider-Man Fall / Jump preservation)
                -- --------------------------------------------------------
                if currentState == STATE.IDLE then
                    if hum.FloorMaterial ~= Enum.Material.Air then
                        if activeTracks.Swing then
                            pcall(function() activeTracks.Swing:Stop(0.1) end)
                            activeTracks.Swing = nil
                        end
                    end
                end
                -- Process Wall Cling / Climb (Smooth Multi-Directional Crawl + Ground Auto-Detach)
                if currentState == STATE.WALL_CLING or currentState == STATE.WALL_CLIMB then
                    local normal = currentWallNormal or Vector3.new(0, 0, 1)
                    local isUp = UserInputService:IsKeyDown(Enum.KeyCode.W) or UserInputService:IsKeyDown(Enum.KeyCode.Z)
                    local isDown = UserInputService:IsKeyDown(Enum.KeyCode.S)
                    local isLeft = UserInputService:IsKeyDown(Enum.KeyCode.A) or UserInputService:IsKeyDown(Enum.KeyCode.Q)
                    local isRight = UserInputService:IsKeyDown(Enum.KeyCode.D)
                    -- Mobile Touch Joystick & Gamepad support
                    if hum.MoveDirection.Magnitude > 0.15 then
                        local camCF = Workspace.CurrentCamera.CFrame
                        local localMove = camCF:VectorToObjectSpace(hum.MoveDirection)
                        if localMove.Z < -0.3 then isUp = true end
                        if localMove.Z > 0.3 then isDown = true end
                        if localMove.X < -0.3 then isLeft = true end
                        if localMove.X > 0.3 then isRight = true end
                    end
                    local climbSpeed = 22
                    local crawlVelocity = Vector3.new(0, 0, 0)
                    if isUp and not isDown then
                        crawlVelocity = crawlVelocity + Vector3.new(0, climbSpeed, 0)
                    elseif isDown and not isUp then
                        crawlVelocity = crawlVelocity - Vector3.new(0, climbSpeed, 0)
                    end
                    local wallTangent = Vector3.new(0, 1, 0):Cross(normal)
                    if wallTangent.Magnitude > 0.01 then
                        wallTangent = wallTangent.Unit
                    else
                        wallTangent = Vector3.new(1, 0, 0)
                    end
                    if isRight and not isLeft then
                        crawlVelocity = crawlVelocity + (wallTangent * climbSpeed)
                    elseif isLeft and not isRight then
                        crawlVelocity = crawlVelocity - (wallTangent * climbSpeed)
                    end
                    local isMoving = isUp or isDown or isLeft or isRight
                    if isMoving then
                        currentState = STATE.WALL_CLIMB
                        -- Stop WallPose emote immediately so it only shows when still
                        stopWallPoseTrack()
                        -- Play Spider-Man active climbing animation
                        local climbTrack = playClimbTrack(hum)
                        if climbTrack then
                            if isDown and not isUp then
                                climbTrack:AdjustSpeed(-1.2)
                            else
                                climbTrack:AdjustSpeed(1.2)
                            end
                        end
                        -- Face directly into the wall while climbing
                        if activeGyro then
                            activeGyro.CFrame = CFrame.lookAt(hrp.Position, hrp.Position - normal)
                        end
                        if activeVelocity then
                            activeVelocity.Velocity = crawlVelocity - (normal * 3.5)
                        end
                    else
                        currentState = STATE.WALL_CLING
                        -- Stop climbing animation
                        stopClimbTrack()
                        -- Play WallPose emote (Stationary AFK wall pose)
                        playWallPoseTrack(hum)
                        -- Keep 180
 rotation for the WallPose emote
                        if activeGyro then
                            activeGyro.CFrame = CFrame.lookAt(hrp.Position, hrp.Position - normal) * CFrame.Angles(0, math.pi, 0)
                        end
                        if activeVelocity then
                            activeVelocity.Velocity = -normal * 2.5
                        end
                    end
                    -- Check Ground Distance: If descending or near ground, cleanly detach onto sidewalk
                    local rayParams = RaycastParams.new()
                    rayParams.FilterDescendantsInstances = { char, Workspace:FindFirstChild(_0xS(208)) }
                    rayParams.FilterType = Enum.RaycastFilterType.Exclude
                    local groundCheck = Workspace:Raycast(hrp.Position, Vector3.new(0, -3.8, 0), rayParams)
                    if groundCheck and (isDown or hrp.Position.Y <= groundCheck.Position.Y + 3.2) then
                        stopAllSpiderActions()
                        return
                    end
                    -- Update wall normal dynamically if wall surface angles change
                    local wallCheck = Workspace:Raycast(hrp.Position, -normal * 4.5, rayParams)
                    if wallCheck and math.abs(wallCheck.Normal.Y) < 0.35 then
                        currentWallNormal = wallCheck.Normal
                    elseif not wallCheck and isUp then
                        -- Reached the top of the wall ledge! Boost character slightly over the ledge
                        stopAllSpiderActions()
                        hrp.AssemblyLinearVelocity = Vector3.new(0, 28, 0) - (normal * 18)
                        return
                    end
                    return
                end
                -- --------------------------------------------------------
                -- PROCESS WEB SWING
                -- --------------------------------------------------------
                if currentState == STATE.SWINGING then
                    if not isSwingMouseDown then
                        releaseWebSwing()
                        return
                    end
                    swingArcTime = swingArcTime + dt
                    -- Dynamic Hand Tracking from Emote
                    local rightHand = char:FindFirstChild(_0xS(213)) or char:FindFirstChild(_0xS(214))
                    local leftHand = char:FindFirstChild(_0xS(215)) or char:FindFirstChild(_0xS(216))
                    local rightY = rightHand and (rightHand.Position.Y - hrp.Position.Y) or 0
                    local leftY = leftHand and (leftHand.Position.Y - hrp.Position.Y) or 0
                    local activeHandPart = (leftY > rightY + 0.3) and leftHand or rightHand
                    if currentSwingAnchor and activeHandPart then
                        updateWebLine(activeHandPart.Position, currentSwingAnchor)
                    end
                    -- Smooth pendulum arc (diving down, sweeping through bottom, rising up)
                    local swingSpeed = 72 + math.sin(swingArcTime * 2.8) * 12
                    local vertSpeed = -10 + math.sin(swingArcTime * 2.8 + math.pi/4) * 26
                    -- Ground Cushion: never hit pavement
                    local rayParams = RaycastParams.new()
                    rayParams.FilterDescendantsInstances = { char, Workspace:FindFirstChild(_0xS(208)) }
                    rayParams.FilterType = Enum.RaycastFilterType.Exclude
                    local groundHit = Workspace:Raycast(hrp.Position, Vector3.new(0, -4.5, 0), rayParams)
                    if groundHit and vertSpeed < 0 then
                        vertSpeed = math.max(vertSpeed * 0.1, 14)
                    end
                    local currentYaw = math.atan2(camLook.X, camLook.Z)
                    local yawDelta = (currentYaw - lastCamYaw)
                    if yawDelta > math.pi then yawDelta = yawDelta - 2 * math.pi end
                    if yawDelta < -math.pi then yawDelta = yawDelta + 2 * math.pi end
                    lastCamYaw = currentYaw
                    local bankRoll = math.clamp(-yawDelta * 6.0, -math.rad(25), math.rad(25))
                    if activeGyro then
                        activeGyro.CFrame = CFrame.lookAt(hrp.Position, hrp.Position + flatCam) * CFrame.Angles(math.rad(-6), 0, bankRoll)
                    end
                    if activeVelocity then
                        activeVelocity.Velocity = (flatCam * swingSpeed) + Vector3.new(0, vertSpeed, 0)
                    end
                    return
                end
                -- --------------------------------------------------------
                -- PROCESS SUPER JUMP CHARGE
                -- --------------------------------------------------------
                if currentState == STATE.SLINGSHOT then
                    local elapsed = tick() - slingshotChargeStartTime
                    local chargePercent = math.clamp(elapsed / 1.5, 0.0, 1.0)
                    if updateSlingshotUI then
                        updateSlingshotUI(chargePercent)
                    end
                    if updateSpeedLines then
                        updateSpeedLines(chargePercent)
                    end
                    local shakeAmount = 0.003 + (chargePercent * 0.014)
                    local shake = Vector3.new(
                        (math.random() - 0.5) * shakeAmount,
                        (math.random() - 0.5) * shakeAmount,
                        (math.random() - 0.5) * shakeAmount
                    )
                    cam.CFrame = cam.CFrame * CFrame.Angles(shake.X, shake.Y, shake.Z)
                    if slingshotSoundLoop then
                        slingshotSoundLoop.PlaybackSpeed = 0.9 + (chargePercent * 0.6)
                    end
                    clearWeb()
                    return
                end
                -- --------------------------------------------------------
                -- PROCESS UPSIDE-DOWN HANG
                -- --------------------------------------------------------
                if currentState == STATE.HANGING then
                    local t = tick()
                    local camYaw = math.atan2(camLook.X, camLook.Z)
                    local anchor = hangingCeilingAnchor or (hrp.Position + Vector3.new(0, 22, 0))
                    local swayX = math.sin(t * 1.6) * 0.6
                    local swayZ = math.sin(t * 1.1) * 0.5
                    if activeVelocity then
                        activeVelocity.Velocity = Vector3.new(swayX, math.cos(t * 2.5) * 0.08, swayZ)
                    end
                    if activeGyro then
                        activeGyro.CFrame = CFrame.new(hrp.Position) 
                            * CFrame.Angles(0, camYaw, 0) 
                            * CFrame.Angles(math.pi, 0, swayX * 0.05)
                    end
                    local leftFoot = char:FindFirstChild(_0xS(217)) or char:FindFirstChild(_0xS(218))
                    local rightFoot = char:FindFirstChild(_0xS(219)) or char:FindFirstChild(_0xS(220))
                    local attachPos = (leftFoot and rightFoot) and ((leftFoot.Position + rightFoot.Position) / 2) or (hrp.Position + Vector3.new(0, 1.5, 0))
                    updateWebLine(attachPos, anchor)
                    return
                end
            end)
            -- ============================================================
            -- HIGH-END RESPONSIVE UI (PC & Mobile Touch Adaptation)
            -- ============================================================
            local isMobile = UserInputService.TouchEnabled and not UserInputService.KeyboardEnabled
            local screenGui = Instance.new("ScreenGui")
            screenGui.Name = "SpiderManGui"
            screenGui.ResetOnSpawn = false
            pcall(function() screenGui.Parent = CoreGui end)
            if not screenGui.Parent then screenGui.Parent = lp:WaitForChild(_0xS(13)) end
            -- 1. Speed Lines Overlay for Super Jump
            local speedLinesFrame = Instance.new("Frame")
            speedLinesFrame.Name = "SpeedLinesHUD"
            speedLinesFrame.Size = UDim2.new(1, 0, 1, 0)
            speedLinesFrame.BackgroundTransparency = 1
            speedLinesFrame.Visible = false
            speedLinesFrame.Parent = screenGui
            local speedLineElements = {}
            for i = 1, 24 do
                local line = Instance.new("Frame")
                line.Name = "SpeedLine_" .. i
                line.AnchorPoint = Vector2.new(0.5, 0.5)
                line.BackgroundColor3 = Color3.fromRGB(245, 250, 255)
                line.BorderSizePixel = 0
                line.Parent = speedLinesFrame
                Instance.new("UICorner", line).CornerRadius = UDim.new(1, 0)
                table.insert(speedLineElements, {
                    frame = line,
                    angle = (i / 24) * (2 * math.pi),
                    baseDist = 0.42 + (math.random() * 0.08)
                })
            end
            updateSpeedLines = function(intensity)
                if intensity <= 0.03 then
                    speedLinesFrame.Visible = false
                    return
                end
                speedLinesFrame.Visible = true
                for _, item in ipairs(speedLineElements) do
                    local r = item.baseDist - (intensity * 0.16) + ((math.random() - 0.5) * 0.03)
                    local cx = 0.5 + math.cos(item.angle) * r
                    local cy = 0.5 + math.sin(item.angle) * r
                    item.frame.Position = UDim2.new(cx, 0, cy, 0)
                    item.frame.Rotation = math.deg(item.angle) + 90
                    local len = 25 + (intensity * 95) + (math.random() * 25)
                    local thick = 1.5 + (intensity * 2.2)
                    item.frame.Size = UDim2.new(0, thick, 0, len)
                    item.frame.BackgroundTransparency = math.clamp(1.0 - (intensity * 0.9) + (math.random() * 0.12), 0.1, 0.95)
                end
            end
            -- 2. Super Jump Charge HUD Center Screen
            local slingshotFrame = Instance.new("Frame")
            slingshotFrame.Name = "SlingshotHUD"
            slingshotFrame.Size = UDim2.new(0, 260, 0, 48)
            slingshotFrame.Position = UDim2.new(0.5, -130, 0.68, 0)
            slingshotFrame.BackgroundColor3 = Color3.fromRGB(15, 18, 26)
            slingshotFrame.BackgroundTransparency = 0.2
            slingshotFrame.BorderSizePixel = 0
            slingshotFrame.Visible = false
            slingshotFrame.Parent = screenGui
            Instance.new("UICorner", slingshotFrame).CornerRadius = UDim.new(0, 8)
            local sStroke = Instance.new("UIStroke", slingshotFrame)
            sStroke.Color = Color3.fromRGB(240, 45, 45)
            sStroke.Thickness = 1.5
            local slingshotTitle = Instance.new("TextLabel")
            slingshotTitle.Size = UDim2.new(1, 0, 0, 20)
            slingshotTitle.BackgroundTransparency = 1
            slingshotTitle.Text = "SUPER JUMP CHARGE : 0%"
            slingshotTitle.TextColor3 = Color3.fromRGB(255, 230, 45)
            slingshotTitle.Font = Enum.Font.GothamBold
            slingshotTitle.TextSize = 10
            slingshotTitle.Parent = slingshotFrame
            local barBg = Instance.new("Frame")
            barBg.Size = UDim2.new(0.9, 0, 0, 12)
            barBg.Position = UDim2.new(0.05, 0, 0, 26)
            barBg.BackgroundColor3 = Color3.fromRGB(25, 30, 42)
            barBg.BorderSizePixel = 0
            barBg.Parent = slingshotFrame
            Instance.new("UICorner", barBg).CornerRadius = UDim.new(0, 6)
            local barFill = Instance.new("Frame")
            barFill.Size = UDim2.new(0, 0, 1, 0)
            barFill.BackgroundColor3 = Color3.fromRGB(245, 40, 40)
            barFill.BorderSizePixel = 0
            barFill.Parent = barBg
            Instance.new("UICorner", barFill).CornerRadius = UDim.new(0, 6)
            updateSlingshotUI = function(percent)
                slingshotFrame.Visible = true
                barFill.Size = UDim2.new(percent, 0, 1, 0)
                local estimatedHeight = math.floor(35 + (percent * 180))
                slingshotTitle.Text = string.format("SUPER JUMP : %d%%  (HEIGHT : ~%d STUDS)", math.floor(percent * 100), estimatedHeight)
            end
            hideSlingshotUI = function()
                slingshotFrame.Visible = false
                barFill.Size = UDim2.new(0, 0, 1, 0)
            end
            -- 3. Desktop HUD (Bottom Center)
            local desktopFrame = Instance.new("Frame")
            desktopFrame.Name = "DesktopHUD"
            desktopFrame.Size = UDim2.new(0, 560, 0, 40)
            desktopFrame.Position = UDim2.new(0.5, -280, 0.92, 0)
            desktopFrame.BackgroundColor3 = Color3.fromRGB(12, 14, 20)
            desktopFrame.BackgroundTransparency = 0.15
            desktopFrame.BorderSizePixel = 0
            desktopFrame.Visible = false
            desktopFrame.Parent = screenGui
            Instance.new("UICorner", desktopFrame).CornerRadius = UDim.new(0, 8)
            local dStroke = Instance.new("UIStroke", desktopFrame)
            dStroke.Color = Color3.fromRGB(220, 38, 38)
            dStroke.Thickness = 1.2
            dStroke.Transparency = 0.3
            local dLayout = Instance.new("UIListLayout", desktopFrame)
            dLayout.FillDirection = Enum.FillDirection.Horizontal
            dLayout.HorizontalAlignment = Enum.HorizontalAlignment.Center
            dLayout.VerticalAlignment = Enum.VerticalAlignment.Center
            dLayout.Padding = UDim.new(0, 14)
            local function addKeyBadge(keyText, actionText, onClick)
                local badge = onClick and Instance.new("TextButton") or Instance.new("Frame")
                badge.Name = keyText .. "Badge"
                badge.Size = UDim2.new(0, 0, 0, 26)
                badge.AutomaticSize = Enum.AutomaticSize.X
                badge.BackgroundTransparency = 1
                if onClick then
                    badge.Text = ""
                    badge.MouseButton1Click:Connect(onClick)
                end
                badge.Parent = desktopFrame
                local bLayout = Instance.new("UIListLayout", badge)
                bLayout.FillDirection = Enum.FillDirection.Horizontal
                bLayout.VerticalAlignment = Enum.VerticalAlignment.Center
                bLayout.Padding = UDim.new(0, 5)
                local keyBox = Instance.new("Frame")
                keyBox.Size = UDim2.new(0, 0, 0, 22)
                keyBox.AutomaticSize = Enum.AutomaticSize.X
                keyBox.BackgroundColor3 = Color3.fromRGB(26, 30, 42)
                keyBox.BorderSizePixel = 0
                keyBox.Parent = badge
                Instance.new("UICorner", keyBox).CornerRadius = UDim.new(0, 4)
                local keyStroke = Instance.new("UIStroke", keyBox)
                keyStroke.Color = Color3.fromRGB(60, 70, 95)
                keyStroke.Thickness = 1
                local keyPadding = Instance.new("UIPadding", keyBox)
                keyPadding.PaddingLeft = UDim.new(0, 6)
                keyPadding.PaddingRight = UDim.new(0, 6)
                local kText = Instance.new("TextLabel")
                kText.Size = UDim2.new(0, 0, 1, 0)
                kText.AutomaticSize = Enum.AutomaticSize.X
                kText.BackgroundTransparency = 1
                kText.Text = keyText
                kText.TextColor3 = Color3.fromRGB(255, 70, 70)
                kText.Font = Enum.Font.GothamBold
                kText.TextSize = 11
                kText.Parent = keyBox
                local aText = Instance.new("TextLabel")
                aText.Size = UDim2.new(0, 0, 1, 0)
                aText.AutomaticSize = Enum.AutomaticSize.X
                aText.BackgroundTransparency = 1
                aText.Text = actionText
                aText.TextColor3 = Color3.fromRGB(220, 225, 235)
                aText.Font = Enum.Font.GothamMedium
                aText.TextSize = 11
                aText.Parent = badge
            end
            addKeyBadge("LMB", "Swing")
            addKeyBadge("C", "Super Jump")
            addKeyBadge("E", "Hang")
            addKeyBadge("R", "Sense")
            addKeyBadge("SPACE", "Eject")
            addKeyBadge("M", "Mobile UI", function()
    mobileFrame.Visible = not mobileFrame.Visible
    notify("Spider-Man", "Mobile Touch Controls: " .. (mobileFrame.Visible and "VISIBLE" or "HIDDEN"), 2)
            -- 4. Mobile Touch Controller (Right side touch buttons)
            local mobileFrame = Instance.new("Frame")
            mobileFrame.Name = "MobileController"
            mobileFrame.Size = UDim2.new(0, 220, 0, 200)
            mobileFrame.Position = UDim2.new(1, -235, 0.55, -100)
            mobileFrame.BackgroundTransparency = 1
            mobileFrame.Visible = false
            mobileFrame.Parent = screenGui
            local function createMobileButton(name, text, pos, color)
                local btn = Instance.new("TextButton")
                btn.Name = name
                btn.Size = UDim2.new(0, 64, 0, 64)
                btn.Position = pos
                btn.BackgroundColor3 = Color3.fromRGB(18, 22, 32)
                btn.BackgroundTransparency = 0.2
                btn.Text = text
                btn.TextColor3 = color or Color3.fromRGB(255, 255, 255)
                btn.Font = Enum.Font.GothamBold
                btn.TextSize = 10
                btn.BorderSizePixel = 0
                btn.Parent = mobileFrame
                Instance.new("UICorner", btn).CornerRadius = UDim.new(0, 32)
                local stroke = Instance.new("UIStroke", btn)
                stroke.Color = color or Color3.fromRGB(240, 45, 45)
                stroke.Thickness = 1.6
                return btn
            end
            local btnSwing     = createMobileButton("BtnSwing", "SWING", UDim2.new(0.65, 0, 0.40, 0), Color3.fromRGB(255, 60, 60))
            local btnSlingshot = createMobileButton("BtnSling", "JUMP", UDim2.new(0.32, 0, 0.10, 0), Color3.fromRGB(255, 225, 45))
            local btnHang      = createMobileButton("BtnHang", "HANG", UDim2.new(0.02, 0, 0.40, 0), Color3.fromRGB(60, 160, 255))
            local btnSense     = createMobileButton("BtnSense", "SENSE", UDim2.new(0.32, 0, 0.70, 0), Color3.fromRGB(255, 120, 40))
            btnSwing.InputBegan:Connect(function(input)
                if input.UserInputType == Enum.UserInputType.Touch or input.UserInputType == Enum.UserInputType.MouseButton1 then
                    startWebSwing()
                end
            end)
            btnSwing.InputEnded:Connect(function(input)
                if input.UserInputType == Enum.UserInputType.Touch or input.UserInputType == Enum.UserInputType.MouseButton1 then
                    releaseWebSwing()
                end
            end)
            btnSlingshot.InputBegan:Connect(function(input)
                if input.UserInputType == Enum.UserInputType.Touch or input.UserInputType == Enum.UserInputType.MouseButton1 then
                    startSlingshotCharge()
                end
            end)
            btnSlingshot.InputEnded:Connect(function(input)
                if input.UserInputType == Enum.UserInputType.Touch or input.UserInputType == Enum.UserInputType.MouseButton1 then
                    releaseSlingshotLaunch()
                end
            end)
            btnHang.Activated:Connect(function()
                toggleUpsideDownHang()
            end)
            btnSense.Activated:Connect(function()
                triggerSpiderSense()
            end)
            -- ============================================================
            -- TOOL CREATION IN BACKPACK
            -- ============================================================
            local function createSpiderTool()
                cleanOldTool()
                local tool = Instance.new("Tool")
                tool.Name = "Web Shooter"
                tool.RequiresHandle = false
                tool.CanBeDropped = false
                tool.Equipped:Connect(function()
                    isEquipped = true
                    playSound(SFX.WebShoot, 1.2)
                    local c = lp.Character
                    if c then
                        disableToolAnimation(c)
                        syncSpiderAnims(c)
                    end
                    if UserInputService.TouchEnabled then
                        mobileFrame.Visible = true
                    end
                    if UserInputService.KeyboardEnabled then
                        desktopFrame.Visible = true
                    end
                end)
                tool.Unequipped:Connect(function()
                    isEquipped = false
                    mobileFrame.Visible = false
                    desktopFrame.Visible = false
                    hideSlingshotUI()
                    stopAllSpiderActions()
                end)
                tool.Activated:Connect(function()
                    if currentState == STATE.IDLE then
                        startWebSwing()
                    end
                end)
                local bp = lp:WaitForChild(_0xS(91))
                tool.Parent = bp
                task.spawn(function()
                    local c = lp.Character or lp.CharacterAdded:Wait()
                    local h = c:WaitForChild(_0xS(94), 3)
                    if h then
                        h:EquipTool(tool)
                    end
                end)
                return tool
            end
            -- ============================================================
            -- INPUT MANAGEMENT (Zero WASD / ZQSD Movement Conflicts)
            -- ============================================================
            UserInputService.InputBegan:Connect(function(input, gameProcessed)
                if not isEquipped then return end
                -- Space / Jump can be processed by Roblox CoreScripts, so check it before gameProcessed
                if input.KeyCode == Enum.KeyCode.Space then
                    if currentState == STATE.WALL_CLING or currentState == STATE.WALL_CLIMB then
                        ejectFromWall()
                        return
                    elseif currentState == STATE.HANGING then
                        stopAllSpiderActions()
                        notify("Spider-Man", "Dropped from Hang.", 2)
                        return
                    end
                end
                if gameProcessed then return end
                if input.UserInputType == Enum.UserInputType.MouseButton1 then
                    if currentState == STATE.IDLE then
                        startWebSwing()
                    end
                elseif input.KeyCode == Enum.KeyCode.C then
                    startSlingshotCharge()
                elseif input.KeyCode == Enum.KeyCode.E then
                    toggleUpsideDownHang()
                elseif input.KeyCode == Enum.KeyCode.R then
                    triggerSpiderSense()
                elseif input.KeyCode == Enum.KeyCode.M then
                    mobileFrame.Visible = not mobileFrame.Visible
                    notify("Spider-Man", "Mobile Touch Controls: " .. (mobileFrame.Visible and "VISIBLE" or "HIDDEN"), 2)
                end
            end)
            UserInputService.JumpRequest:Connect(function()
                if not isEquipped then return end
                if currentState == STATE.WALL_CLING or currentState == STATE.WALL_CLIMB then
                    ejectFromWall()
                elseif currentState == STATE.HANGING then
                    stopAllSpiderActions()
                end
            end)
            UserInputService.InputEnded:Connect(function(input, gameProcessed)
                if input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch then
                    if currentState == STATE.SWINGING then
                        releaseWebSwing()
                    end
                elseif input.KeyCode == Enum.KeyCode.C then
                    if currentState == STATE.SLINGSHOT then
                        releaseSlingshotLaunch()
                    end
                end
            end)
            -- Respawn handling
            lp.CharacterAdded:Connect(function()
                stopAllSpiderActions()
                task.wait(0.5)
                createSpiderTool()
            end)
            createSpiderTool()
            notify("Spider-Man FE", "Web Shooter active! Hold Click to swing, Hold C for Super Jump.", 4)
        end
