    local function canDo(actionKey, cooldownSec)
        local now = tick()
        if robotCooldowns[actionKey] and (now - robotCooldowns[actionKey]) < cooldownSec then
            return false
        end
        robotCooldowns[actionKey] = now
        return true
    end
    local function getPartColor(layout, partIndex, t, state, colorMode)
        local pulse = (math.sin(t * 6) + 1) * 0.5
        local wave = (math.sin(t * 5 + partIndex * 0.45) + 1) * 0.5
        if state == "attack" then
            if layout.key == "armL_gun" or layout.key == "armR_blade" then
                return (math.sin(t * 40) > 0) and Color3.fromRGB(255, 255, 255) or Color3.fromRGB(255, 60, 20)
            end
            return Color3.fromRGB(255, math.floor(40 + pulse * 60), 10)
        elseif state == "roar" then
            return Color3.fromRGB(255, math.floor(180 + pulse * 75), 0)
        elseif state == "shield" then
            return Color3.fromRGB(0, math.floor(200 + pulse * 55), 255)
        end
        if colorMode == "Mecha Blue" then
            if layout.key == "head" or layout.key == "core" then
                return Color3.new(0.3 + pulse * 0.3, 0.8 + pulse * 0.2, 1.0)
            else
                return Color3.new(0.05 + wave * 0.15, 0.4 + wave * 0.35, 0.9 + wave * 0.1)
            end
        elseif colorMode == "Shadow Arise (Violet)" then
            if layout.key == "eyeL" or layout.key == "eyeR" then
                return Color3.fromRGB(160, 0, 255)
            end
            return Color3.new(0.45 + wave * 0.4, 0.02 + wave * 0.08, 0.85 + wave * 0.15)
        elseif colorMode == "Magma Red" then
            return Color3.new(0.5 + pulse * 0.5, 0.05 + pulse * 0.15, 0.0)
        elseif colorMode == "Sacrificial Gold" then
            return Color3.new(0.85 + pulse * 0.15, 0.65 + pulse * 0.25, 0.1 + pulse * 0.2)
        elseif colorMode == "Rainbow" then
            local hue = ((t * 0.2) + (partIndex * 0.065)) % 1
            return Color3.fromHSV(hue, 1, 1)
        elseif colorMode == "Plasma Wave" then
            local phase = ((t * 0.35) + (partIndex * 0.08)) % 1
            if phase < 0.5 then
                return Color3.fromRGB(0, 220, 255):Lerp(Color3.fromRGB(255, 0, 180), phase * 2)
            else
                return Color3.fromRGB(255, 0, 180):Lerp(Color3.fromRGB(0, 220, 255), (phase - 0.5) * 2)
            end
        else
            return Color3.fromRGB(0, 160, 255)
        end
    end
    local function getPartCFrame(layout, t, state, risingProg, partIndex)
        local robotCF = CFrame.new(robotAnchor) * CFrame.Angles(0, robotAngle, 0)
        local baseOff = layout.off
        local baseRot = layout.rot or CFrame.new()
        local animCF = CFrame.new()
        if state == "dormant" then
            if layout.key == "core" then
                animCF = CFrame.new(0, -22, 0)
            elseif layout.key == "armL_gun" or layout.key == "armR_blade" then
                animCF = CFrame.new(0, -10, -8) * CFrame.Angles(-math.pi/1.5, 0, 0)
            else
                animCF = CFrame.new(0, -40, 0)
            end
        elseif state == "idle" then
            local breatheY = math.sin(t * 1.8) * 0.35
            local swayX = math.sin(t * 0.9) * 0.15
            if layout.key == "head" or layout.key == "eyeL" or layout.key == "eyeR" then
                local scan = math.sin(t * 0.8) * 0.25
                animCF = CFrame.new(swayX, breatheY, 0) * CFrame.Angles(0, scan, 0)
            elseif layout.key == "armL_gun" then
                animCF = CFrame.new(0, breatheY * 0.5, 0) * CFrame.Angles(math.sin(t * 1.8) * 0.08, 0, 0)
            elseif layout.key == "armR_blade" then
                animCF = CFrame.new(0, breatheY * 0.5, 0) * CFrame.Angles(-math.sin(t * 1.8) * 0.08, 0, 0)
            elseif layout.key == "thighL" or layout.key == "thighR" or layout.key == "footL" or layout.key == "footR" then
                animCF = CFrame.new()
            else
                animCF = CFrame.new(swayX, breatheY, 0)
            end
        elseif state == "walk" then
            local walkFreq = 3.6
            local walkCycle = t * walkFreq
            local legLift = 2.0
            local legStride = 3.5
            if layout.key == "thighL" then
                local sL = math.sin(walkCycle)
                animCF = CFrame.new(0, math.max(0, -sL) * legLift * 0.6, -sL * legStride * 0.5) * CFrame.Angles(sL * 0.35, 0, 0)
            elseif layout.key == "footL" then
                local sL = math.sin(walkCycle)
                animCF = CFrame.new(0, math.max(0, -sL) * legLift, -sL * legStride) * CFrame.Angles(sL * 0.2, 0, 0)
            elseif layout.key == "thighR" then
                local sR = math.sin(walkCycle + math.pi)
                animCF = CFrame.new(0, math.max(0, -sR) * legLift * 0.6, -sR * legStride * 0.5) * CFrame.Angles(sR * 0.35, 0, 0)
            elseif layout.key == "footR" then
                local sR = math.sin(walkCycle + math.pi)
                animCF = CFrame.new(0, math.max(0, -sR) * legLift, -sR * legStride) * CFrame.Angles(sR * 0.2, 0, 0)
            elseif layout.key == "armL_gun" then
                animCF = CFrame.Angles(math.sin(walkCycle + math.pi) * 0.7, 0, 0)
            elseif layout.key == "armR_blade" then
                animCF = CFrame.Angles(math.sin(walkCycle) * 0.7, 0, 0)
            elseif layout.key == "head" or layout.key == "eyeL" or layout.key == "eyeR" then
                animCF = CFrame.new(math.sin(walkCycle) * 0.4, math.abs(math.sin(walkCycle)) * 0.5, 0) * CFrame.Angles(0, 0, -math.sin(walkCycle) * 0.05)
            else
                animCF = CFrame.new(math.sin(walkCycle) * 0.5, math.abs(math.sin(walkCycle)) * 0.6, 0) * CFrame.Angles(0, 0, -math.sin(walkCycle) * 0.06)
            end
        elseif state == "attack" then
            local recoil = math.sin(t * 45) * 0.45
            if layout.key == "armL_gun" then
                animCF = CFrame.new(0, 0, -4.5 + recoil) * CFrame.Angles(-math.pi/2.2, 0, 0)
            elseif layout.key == "armR_blade" then
                animCF = CFrame.new(0, 0, -4.5 - recoil) * CFrame.Angles(-math.pi/2.2, 0, 0)
            elseif layout.key == "head" or layout.key == "eyeL" or layout.key == "eyeR" then
                animCF = CFrame.Angles(-0.3, 0, 0)
            elseif layout.key == "thighL" or layout.key == "footL" then
                animCF = CFrame.new(-1, 0, 1.5) * CFrame.Angles(0.2, 0, 0)
            elseif layout.key == "thighR" or layout.key == "footR" then
                animCF = CFrame.new(1, 0, -1.5) * CFrame.Angles(-0.2, 0, 0)
            else
                animCF = CFrame.new(0, -0.5, -0.8) * CFrame.Angles(0.25, 0, 0)
            end
        elseif state == "stomp" then
            local p = robotStateTimer
            if layout.key == "thighR" or layout.key == "footR" then
                if p < 1.0 then
                    local lift = math.sin(p * math.pi) * 5
                    animCF = CFrame.new(0, lift, -lift * 0.4) * CFrame.Angles(-0.6, 0, 0)
                else
                    animCF = CFrame.new(0, 0, 0)
                end
            elseif layout.key == "armR_blade" then
                animCF = CFrame.new(0, 1, 0) * CFrame.Angles(-0.5, 0, 0)
            else
                animCF = CFrame.new(0, -math.abs(math.sin(p * 4)) * 1.5, 0)
            end
        elseif state == "roar" then
            local shake = math.sin(t * 50) * 0.25
            if layout.key == "head" or layout.key == "eyeL" or layout.key == "eyeR" then
                animCF = CFrame.new(shake, shake, 0) * CFrame.Angles(0.9, 0, 0)
            elseif layout.key == "armL_gun" then
                animCF = CFrame.new(-1, 2, 0) * CFrame.Angles(0.8, 0, -0.8)
            elseif layout.key == "armR_blade" then
                animCF = CFrame.new(1, 2, 0) * CFrame.Angles(0.8, 0, 0.8)
            else
                animCF = CFrame.new(shake, 0.8 + shake, 0) * CFrame.Angles(-0.15, 0, 0)
            end
        elseif state == "kneel" then
            if layout.key == "thighL" or layout.key == "thighR" then
                animCF = CFrame.new(0, -6, -2) * CFrame.Angles(math.rad(65), 0, 0)
            elseif layout.key == "footL" or layout.key == "footR" then
                animCF = CFrame.new(0, -1, 3) * CFrame.Angles(math.rad(-45), 0, 0)
            elseif layout.key == "core" then
                animCF = CFrame.new(0, -11, 0)
            elseif layout.key == "armL_gun" or layout.key == "armR_blade" then
                animCF = CFrame.new(0, -10, -2) * CFrame.Angles(-math.rad(40), 0, 0)
            else
                animCF = CFrame.new(0, -11, 0)
            end
        elseif state == "shield" then
            local totalParts = #ROBOT_LAYOUT
            local spinAngle = robotAnimT * 8 + partIndex * (math.pi * 2 / totalParts)
            local orbitR = 19
            local spinY = math.sin(robotAnimT * 4 + partIndex * 1.3) * 10
            baseOff = Vector3.new(
                math.cos(spinAngle) * orbitR,
                14 + spinY,
                math.sin(spinAngle) * orbitR
            )
            baseRot = CFrame.new()
            animCF = CFrame.Angles(robotAnimT * 12, robotAnimT * 9, partIndex)
        end
        local smoothProg = math.clamp(risingProg, 0, 1)
        smoothProg = smoothProg * smoothProg * (3 - 2 * smoothProg)
        local spinFactor = (1 - smoothProg)
        local spiralAngle = spinFactor * math.pi * 5 * (partIndex % 2 == 0 and 1 or -1)
        local spiralRadius = 25 * spinFactor
        local undergroundY = -40 * spinFactor
        local vortexOff = Vector3.new(
            math.cos(spiralAngle) * spiralRadius,
            undergroundY,
            math.sin(spiralAngle) * spiralRadius
        )
        local localPos = baseOff + vortexOff
        local worldPos = (robotCF * CFrame.new(localPos)).Position
        local vortexRot = CFrame.Angles(spiralAngle * 0.4, spiralAngle * 0.6, spiralAngle * 0.2)
        local worldCF = CFrame.new(worldPos) * CFrame.Angles(0, robotAngle, 0) * baseRot * animCF * vortexRot
        if risingProg < 1 and risingProg > 0.05 then
            local shake = math.sin(t * 30) * 0.3 * spinFactor
            worldCF = worldCF * CFrame.new(shake, shake, shake)
        end
        return worldCF
    end
    local function startWorkers(w)
        if w.scf then
            task.spawn(function()
                while robotActive and w.scf do
                    local now = tick()
                    if w.targetCF then
                        local cf = w.targetCF
                        local sendCF = false
                        if not w.lastSentCF then
                            sendCF = true
                        else
                            local moved = (cf.Position - w.lastSentCF.Position).Magnitude > 0.35
                            if moved or (now - w.lastSendTimeCF > 0.3) then
                                sendCF = true
                            end
                        end
                        if sendCF then
                            w.lastSentCF = cf
                            w.lastSendTimeCF = now
                            pcall(function() w.scf:InvokeServer(cf) end)
                        end
                    end
                    task.wait(0.04)
                end
            end)
        end
        if w.cpc then
            task.spawn(function()
                while robotActive and w.cpc do
                    local now = tick()
                    if w.targetColor then
                        local col = w.targetColor
                        local sendCol = false
                        if not w.lastSentColor then
                            sendCol = true
                        else
                            if (now - w.lastSendTimeColor >= 0.08) then
                                local dr = math.abs(col.R - w.lastSentColor.R)
                                local dg = math.abs(col.G - w.lastSentColor.G)
                                local db = math.abs(col.B - w.lastSentColor.B)
                                if (dr + dg + db) > 0.035 then
                                    sendCol = true
                                end
                            end
                        end
                        if sendCol then
                            w.lastSentColor = col
                            w.lastSendTimeColor = now
                            pcall(function() w.cpc:InvokeServer(col) end)
                        end
                    end
                    task.wait(0.04)
                end
            end)
        end
    end
    local function startRobotLoop()
        if robotLoop then robotLoop:Disconnect() end
        robotAnimT = 0
        robotRisingProgress = 0
        robotLoop = game:GetService(_0xS(15)).Heartbeat:Connect(function(dt)
            if not robotActive then return end
            robotAnimT = robotAnimT + dt
            robotStateTimer = robotStateTimer + dt
            local uis = game:GetService(_0xS(18))
            local lp = game:GetService(_0xS(1)).LocalPlayer
            local myHum = lp.Character and lp.Character:FindFirstChildOfClass("Humanoid")
            local isRiding = false
            if robotDriverSeat and myHum and robotDriverSeat.Occupant == myHum then
                isRiding = true
            end
            if isRiding then
                local moveDir = Vector3.new(0, 0, 0)
                local turnSpeed = 2.4
                if uis:IsKeyDown(Enum.KeyCode.A) then
                    robotAngle = robotAngle - turnSpeed * dt
                end
                if uis:IsKeyDown(Enum.KeyCode.D) then
                    robotAngle = robotAngle + turnSpeed * dt
                end
                local fwd = Vector3.new(math.sin(robotAngle), 0, math.cos(robotAngle))
                if uis:IsKeyDown(Enum.KeyCode.W) then
                    moveDir = moveDir + fwd
                end
                if uis:IsKeyDown(Enum.KeyCode.S) then
                    moveDir = moveDir - fwd * 0.5
                end
                if moveDir.Magnitude > 0 then
                    robotAnchor = robotAnchor + moveDir.Unit * robotSpeed * dt
                    if robotState ~= "attack" and robotState ~= "stomp" and robotState ~= "roar" then
                        robotState = "walk"
                    end
                else
                    if robotState == "walk" then
                        robotState = "idle"
                    end
                end
            elseif robotState == "attack" then
                local fwd = Vector3.new(math.sin(robotAngle), 0, math.cos(robotAngle))
                robotAnchor = robotAnchor + fwd * 45 * dt
                if robotTarget and robotTarget ~= "---" then
                    local targetPlayer = game:GetService(_0xS(1)):FindFirstChild(robotTarget)
                    local targetChar = targetPlayer and targetPlayer.Character or workspace:FindFirstChild(robotTarget)
                    local hrp = targetChar and targetChar:FindFirstChild(_0xS(6))
                    if hrp then
                        local dir = (hrp.Position - robotAnchor)
                        dir = Vector3.new(dir.X, 0, dir.Z)
                        if dir.Magnitude > 0 then
                            local targetAngle = math.atan2(dir.X, dir.Z)
                            local angleDiff = (targetAngle - robotAngle + math.pi) % (2 * math.pi) - math.pi
                            robotAngle = robotAngle + math.clamp(angleDiff, -6, 6) * dt
                        end
                    end
                end
            elseif robotState == "walk" then
                if robotMode == "follow" and robotFollowName ~= "" and robotFollowName ~= "---" then
                    local tp = game:GetService(_0xS(1)):FindFirstChild(robotFollowName)
                    local hrp = tp and tp.Character and tp.Character:FindFirstChild(_0xS(6))
                    if hrp then
                        local toTarget = hrp.Position - robotAnchor
                        toTarget = Vector3.new(toTarget.X, 0, toTarget.Z)
                        if toTarget.Magnitude > 7 then
                            local targetAngle = math.atan2(toTarget.X, toTarget.Z)
                            local angleDiff = (targetAngle - robotAngle + math.pi) % (2 * math.pi) - math.pi
                            robotAngle = robotAngle + math.clamp(angleDiff, -3.0, 3.0) * dt
                            local dist = toTarget.Magnitude
                            local adaptSpeed = math.clamp(dist * 0.7, robotSpeed, 65)
                            local fwdF = Vector3.new(math.sin(robotAngle), 0, math.cos(robotAngle))
                            robotAnchor = robotAnchor + fwdF * adaptSpeed * dt
                        else
                            robotState = "idle"
                        end
                    end
                elseif robotMode == "free" then
                    if not robotWaypoint then
                        local rAngle = math.random() * 2 * math.pi
                        local rDist  = math.random(40, 120)
                        local nx = math.clamp(robotAnchor.X + math.cos(rAngle) * rDist, -350, 350)
                        local nz = math.clamp(robotAnchor.Z + math.sin(rAngle) * rDist, -350, 350)
                        robotWaypoint = Vector3.new(nx, robotAnchor.Y, nz)
                    end
                    local toWp = robotWaypoint - robotAnchor
                    toWp = Vector3.new(toWp.X, 0, toWp.Z)
                    if toWp.Magnitude < 8 then
                        robotWaypoint = nil
                        robotState = "idle"
                        task.delay(math.random(2, 6), function()
                            if not robotActive or robotMode ~= "free" then return end
                            if robotState == "idle" then robotState = "walk" end
                        end)
                    else
                        local targetAngle = math.atan2(toWp.X, toWp.Z)
                        local angleDiff = (targetAngle - robotAngle + math.pi) % (2 * math.pi) - math.pi
                        local turnRate = math.clamp(math.abs(angleDiff) * 3, 1.8, 5.0)
                        robotAngle = robotAngle + math.clamp(angleDiff, -turnRate, turnRate) * dt
                        local fwdF = Vector3.new(math.sin(robotAngle), 0, math.cos(robotAngle))
                        robotAnchor = robotAnchor + fwdF * robotSpeed * dt
                    end
                else
                    local fwd = Vector3.new(math.sin(robotAngle), 0, math.cos(robotAngle))
                    robotAnchor = robotAnchor + fwd * robotSpeed * dt
                end
            end
            if robotState == "rising" then
                robotRisingProgress = math.min(robotRisingProgress + dt * 0.25, 1)
                if robotRisingProgress >= 1 then
                    robotState = "idle"
                    robotStateTimer = 0
                    rNotif("MECHA ROBOT", "TITAN SYSTEMS 100% ONLINE!", 5)
                end
            end
            if robotState == "attack" and robotStateTimer > 3.5 then
                robotState = "idle" robotStateTimer = 0
            end
            if robotState == "stomp" and robotStateTimer > 2.2 then
                robotState = "idle" robotStateTimer = 0
            end
            if robotState == "roar" and robotStateTimer > 4.5 then
                robotState = "idle" robotStateTimer = 0
            end
            local ignoreList = { workspace:FindFirstChild(_0xS(93)) }
            for _, p in ipairs(game:GetService(_0xS(1)):GetPlayers()) do
                if p.Character then table.insert(ignoreList, p.Character) end
            end
            local rayParams = RaycastParams.new()
            rayParams.FilterType = Enum.RaycastFilterType.Exclude
            rayParams.FilterDescendantsInstances = ignoreList
            local rayOrigin = Vector3.new(robotAnchor.X, robotAnchor.Y + 8, robotAnchor.Z)
            local rayResult = workspace:Raycast(rayOrigin, Vector3.new(0, -40, 0), rayParams)
            if rayResult then
                local targetY = rayResult.Position.Y
                local diffY = targetY - robotAnchor.Y
                diffY = math.clamp(diffY, -25 * dt, 14 * dt)
                robotAnchor = Vector3.new(robotAnchor.X, robotAnchor.Y + diffY, robotAnchor.Z)
            end
            for partIndex, layout in ipairs(ROBOT_LAYOUT) do
                local w = robotWorkers[layout.key]
                if w then
                    w.targetCF = getPartCFrame(layout, robotAnimT, robotState, robotRisingProgress, partIndex)
                    w.targetColor = getPartColor(layout, partIndex, robotAnimT, robotState, robotColorMode)
                end
            end
        end)
    end
    local function spawnRobot()
        local lp = game:GetService(_0xS(1)).LocalPlayer
        local char = lp.Character or lp.CharacterAdded:Wait()
        local myRoot = char:WaitForChild(_0xS(6))
        rNotif("MECHA ROBOT", "Summoning Titan Mecha... (15 parts, ~13s)", 5)
        local RE         = game:GetService(_0xS(70)):WaitForChild(_0xS(83))
        local clearTools = RE:WaitForChild(_0xS(87))
        local toolRE     = RE:WaitForChild(_0xS(88))
        local myPropName = "Prop" .. lp.Name
        local wc         = workspace:WaitForChild(_0xS(93))
        local Telemetry  = game:GetService(_0xS(70)):WaitForChild(_0xS(100)):WaitForChild(_0xS(101))
        local defaultColor = Color3.fromRGB(0, 160, 255)
        pcall(function() clearTools:FireServer(_0xS(95)) end)
        task.wait(0.3)
        local propsTool = getOrFetchPropMaker()
        if not propsTool then return end
        local hum = char:FindFirstChildOfClass("Humanoid")
        if hum and propsTool.Parent ~= char then
            hum:EquipTool(propsTool)
            task.wait(0.2)
        end
        local toolPropMake = propsTool:FindFirstChild(_0xS(96)) or propsTool:WaitForChild(_0xS(96), 3)
        if not toolPropMake then
            local bpTool = lp.Backpack:FindFirstChild(_0xS(89))
            if bpTool then toolPropMake = bpTool:FindFirstChild(_0xS(96)) end
        end
        if not toolPropMake then return end
        ROBOT_GROUND_Y = myRoot.Position.Y
        robotAnchor    = myRoot.Position + (myRoot.CFrame.LookVector * 15)
        robotAnchor    = Vector3.new(robotAnchor.X, ROBOT_GROUND_Y, robotAnchor.Z)
        robotWorkers = {}
        robotDriverSeat = nil
        local assignedProps = {}
        for idx, layout in ipairs(ROBOT_LAYOUT) do
            if not robotActive then break end
            local playerPos = (lp.Character and lp.Character:FindFirstChild(_0xS(6)) and lp.Character.HumanoidRootPart.Position) or myRoot.Position
            local spawnPos = playerPos + Vector3.new(math.cos(idx) * 4, 2, math.sin(idx) * 4)
            
            local currentHum = lp.Character and lp.Character:FindFirstChildOfClass("Humanoid")
            if currentHum and propsTool.Parent ~= lp.Character then
                currentHum:EquipTool(propsTool)
                task.wait(0.1)
            end
            local tpm = propsTool:FindFirstChild(_0xS(96))
            if not tpm then
                local bp = lp.Backpack:FindFirstChild(_0xS(89))
                if bp then tpm = bp:FindFirstChild(_0xS(96)) end
            end
            if not tpm then return end
            pcall(function() Telemetry:FireServer("filterClick", {name = layout.cat, itemType = "Props"}) end)
            task.wait(0.05)
            pcall(function() Telemetry:FireServer("filterClick", {name = layout.prop, itemType = "Props"}) end)
            task.wait(0.05)
            pcall(function() clearTools:FireServer("RequestingPropName", layout.prop, layout.cat) end)
            task.wait(0.1)
            
            pcall(function() tpm:FireServer(workspace.Terrain, spawnPos) end)
            task.wait(0.85)
            if not robotActive then break end
            local foundProp = nil
            local scf = nil
            local cpc = nil
            for _, folder in pairs(wc:GetChildren()) do
                if foundProp then break end
                for _, prop in pairs(folder:GetChildren()) do
                    if prop.Name == myPropName and not assignedProps[prop] then
                        local propScf = prop:FindFirstChild(_0xS(97)) or prop:FindFirstChild(_0xS(97), true) or prop:FindFirstChildWhichIsA("RemoteFunction", true)
                        if propScf then
                            foundProp = prop
                            scf = propScf
                            cpc = prop:FindFirstChild(_0xS(98)) or prop:FindFirstChild(_0xS(98), true)
                            assignedProps[prop] = true
                            break
                        end
                    end
                end
            end
            if layout.key == "core" and foundProp then
                local seat = foundProp:FindFirstChildWhichIsA("Seat", true)
                if seat then robotDriverSeat = seat end
            end
            local initialCF = getPartCFrame(layout, 0, "dormant", 0, idx)
            local w = {
                key = layout.key, scf = scf, cpc = cpc,
                targetCF = initialCF, targetColor = defaultColor,
                lastSentCF = nil, lastSentColor = nil,
                lastSendTimeCF = 0, lastSendTimeColor = 0
            }
            robotWorkers[layout.key] = w
            if scf then pcall(function() scf:InvokeServer(initialCF) end) end
            if cpc then pcall(function() cpc:InvokeServer(defaultColor) end) end
            startWorkers(w)
        end
        -- Retrait du carton apres 1 seconde (LOCKED Rule 7)
        task.wait(1.0)
        pcall(function() toolRE:InvokeServer(_0xS(90), _0xS(89)) end)
        pcall(function() clearTools:FireServer("ClosePropMenu") end)
        local count = 0
        for _, w in pairs(robotWorkers) do if w.scf then count = count + 1 end end
        rNotif("MECHA ROBOT", "Titan online! " .. count .. "/15 parts assembled. Say 'wake up' to activate!", 6)
    end
    local function setupChatListener()
        if robotChatConn then
            if type(robotChatConn) == "table" then
                for _, c in pairs(robotChatConn) do pcall(function() c:Disconnect() end) end
            else pcall(function() robotChatConn:Disconnect() end) end
        end
        robotChatConn = {}
        local function onChat(player, message)
            if not robotActive or not player or not message then return end
            local isWhitelisted = (player == game:GetService(_0xS(1)).LocalPlayer)
            if not isWhitelisted then return end
            local text = message:lower():match("^%s*(.-)%s*$")
            if string.find(text, "wake up") or string.find(text, "arise") or string.find(text, "reveil") then
                if robotState == "rising" or robotState == "walk" or robotState == "attack" then return end
                robotState = "rising"
                robotStateTimer = 0
                robotRisingProgress = 0
                rNotif("MECHA ROBOT", "Titan Awakening... WAKE UP!", 6)
            end
        end
        pcall(function()
            local TCS = game:GetService(_0xS(69))
            if TCS and TCS.MessageReceived then
                table.insert(robotChatConn, TCS.MessageReceived:Connect(function(msg)
                    if msg and msg.TextSource then
                        local p = game:GetService(_0xS(1)):GetPlayerByUserId(msg.TextSource.UserId)
                        if p then onChat(p, msg.Text) end
                    end
                end))
            end
        end)
        for _, p in pairs(game:GetService(_0xS(1)):GetPlayers()) do
            table.insert(robotChatConn, p.Chatted:Connect(function(msg) onChat(p, msg) end))
        end
        table.insert(robotChatConn, game:GetService(_0xS(1)).PlayerAdded:Connect(function(p)
            table.insert(robotChatConn, p.Chatted:Connect(function(msg) onChat(p, msg) end))
        end))
    end
