         anim=function(t) return CFrame.Angles(math.sin(t*7 + math.pi)*0.5, 0, 0) end},
        
        {key="aile_G",    prop="QuarterFloor",         cat="Building",
         off=Vector3.new(-4, 0, 0), rot=CFrame.Angles(0, 0, math.rad(-10)),
         color=Color3.fromRGB(255,255,255),
         anim=function(t) return CFrame.Angles(0, 0, math.sin(t*10)*0.4) * CFrame.new(0, math.sin(t*7)*0.35, 0) end},
        
        {key="aile_D",    prop="QuarterFloor",         cat="Building",
         off=Vector3.new(4, 0, 0), rot=CFrame.Angles(0, 0, math.rad(10)),
         color=Color3.fromRGB(255,255,255),
         anim=function(t) return CFrame.Angles(0, 0, -math.sin(t*10)*0.4) * CFrame.new(0, math.sin(t*7)*0.35, 0) end},
        
