    local function spawnUnicorn()
        local lp = game:GetService(_0xS(1)).LocalPlayer
        local RE = game:GetService(_0xS(70)):WaitForChild(_0xS(83))
        local clearTools  = RE:WaitForChild(_0xS(87))
        local toolRemote  = RE:WaitForChild(_0xS(88))
        local Telemetry   = game:GetService(_0xS(70)):WaitForChild(_0xS(100)):WaitForChild(_0xS(101))
        pcall(function() clearTools:FireServer(_0xS(95)) end)
        task.wait(0.3)
        local propsTool = getOrFetchPropMaker()
        if not propsTool then uNotif(_0xS(222), 4) return end
        
        local hum = lp.Character and lp.Character:FindFirstChild(_0xS(94))
        if hum and propsTool.Parent ~= lp.Character then
            hum:EquipTool(propsTool)
            task.wait(0.2)
        end
        local toolPropMake = propsTool:FindFirstChild(_0xS(96)) or propsTool:WaitForChild(_0xS(96), 3)
            if not toolPropMake then return end
        unicornParts = {}
        uNotif("Summoning the unicorn... ("..#blueprint.." parts, ~"..#blueprint.."s)", 5)
        for idx, bp in ipairs(blueprint) do
            if not unicornActive then break end
            local spawnPos = (lp.Character and lp.Character:FindFirstChild(_0xS(6)) and lp.Character.HumanoidRootPart.Position) or Vector3.new(0,5,0)
            local offsetSpawn = Vector3.new(math.cos(idx)*4, 3, math.sin(idx)*4)
            
            pcall(function() Telemetry:FireServer("filterClick", {name=bp.cat,  itemType="Props"}) end)
            task.wait(0.05)
            pcall(function() Telemetry:FireServer("filterClick", {name=bp.prop, itemType="Props"}) end)
            task.wait(0.05)
            pcall(function() if bp.prop == "FloorCushion" then clearTools:FireServer("RequestingPropFeatureName", bp.prop, bp.cat) else clearTools:FireServer("RequestingPropName", bp.prop, bp.cat) end end)
            task.wait(0.1)
            
            pcall(function() toolPropMake:FireServer(workspace.Terrain, spawnPos + offsetSpawn) end)
            task.wait(0.85)
            if not unicornActive then break end
            
            local myPropName = "Prop" .. lp.Name
            local found = false
            for _, folder in pairs(workspace:WaitForChild(_0xS(93)):GetChildren()) do
                if found then break end
                for _, prop in pairs(folder:GetChildren()) do
                    if prop.Name == myPropName then
                        local scf = prop:FindFirstChild(_0xS(97))
                        local cpc = prop:FindFirstChild(_0xS(98))
                        if scf then
                            local alreadyHave = false
                            for _, p in ipairs(unicornParts) do
                                if p.scf == scf then alreadyHave = true break end
                            end
                            if not alreadyHave then
                                
                                if cpc and bp.color then
                                    pcall(function() cpc:InvokeServer(bp.color) end)
                                end
                                table.insert(unicornParts, {key=bp.key, scf=scf, cpc=cpc, blueprint=bp, propModel=prop})
                                found = true
                                break
                            end
                        end
                    end
                end
            end
        end
        for _, _p in ipairs(unicornParts) do uStream:add(_p.scf, _p.cpc) end
        uStream:start()
        cleanupPropMakerTool()
                uNotif("Unicorn ready! It is waiting for you on the ground. Climb on!", 5)
    end
    local unicornGui = nil
    local isUIUp = false
    local isUIDown = false
    local isUIBoost = false
    local function removeUnicornGUI()
        if unicornGui then
            unicornGui:Destroy()
            unicornGui = nil
        end
        local hum = lp.Character and lp.Character:FindFirstChildOfClass("Humanoid")
        if hum then hum:SetStateEnabled(Enum.HumanoidStateType.Jumping, true) end
    end
    local function setupUnicornGUI()
        if unicornGui then return end
        
        
        local hum = lp.Character and lp.Character:FindFirstChildOfClass("Humanoid")
        if hum then hum:SetStateEnabled(Enum.HumanoidStateType.Jumping, false) end
        
        local sg = Instance.new("ScreenGui")
        sg.Name = "UnicornRiderGui"
        sg.Parent = game:GetService(_0xS(12))
        unicornGui = sg
        
        local panel = Instance.new("Frame")
        panel.Size = UDim2.new(0, 200, 0, 200)
        panel.Position = UDim2.new(1, -220, 0.5, -100)
        panel.BackgroundColor3 = Color3.fromRGB(30, 30, 30)
        panel.BackgroundTransparency = 0.2
        Instance.new("UICorner", panel).CornerRadius = UDim.new(0, 10)
        panel.Parent = sg
        
        local title = Instance.new("TextLabel")
        title.Size = UDim2.new(1, 0, 0, 30)
        title.BackgroundTransparency = 1
        title.Text = "Unicorn Controls"
        title.TextColor3 = Color3.fromRGB(255, 200, 255)
        title.Font = Enum.Font.GothamBold
        title.TextSize = 16
        title.Parent = panel
        
        local function makeBtn(txt, posY, col, callback)
            local btn = Instance.new("TextButton")
            btn.Size = UDim2.new(1, -20, 0, 35)
            btn.Position = UDim2.new(0, 10, 0, posY)
            btn.BackgroundColor3 = col
            btn.TextColor3 = Color3.new(1,1,1)
            btn.Text = txt
            btn.TextScaled = true
            btn.Font = Enum.Font.GothamBold
            Instance.new("UICorner", btn).CornerRadius = UDim.new(0, 6)
            btn.Parent = panel
            
            local down = false
            btn.InputBegan:Connect(function(i)
                if i.UserInputType == Enum.UserInputType.MouseButton1 or i.UserInputType == Enum.UserInputType.Touch then
                    down = true
                    callback(true)
                end
            end)
            btn.InputEnded:Connect(function(i)
                if i.UserInputType == Enum.UserInputType.MouseButton1 or i.UserInputType == Enum.UserInputType.Touch then
                    down = false
                    callback(false)
                end
            end)
            return btn
        end
        
        makeBtn("Up (Space)", 40, Color3.fromRGB(80, 150, 200), function(val) isUIUp = val end)
        makeBtn("Down (Ctrl)", 80, Color3.fromRGB(200, 120, 80), function(val) isUIDown = val end)
        makeBtn("Sprint (Shift)", 120, Color3.fromRGB(150, 80, 200), function(val) isUIBoost = val end)
        
        local quitBtn = Instance.new("TextButton")
        quitBtn.Size = UDim2.new(1, -20, 0, 30)
        quitBtn.Position = UDim2.new(0, 10, 0, 160)
        quitBtn.BackgroundColor3 = Color3.fromRGB(200, 50, 50)
        quitBtn.TextColor3 = Color3.new(1,1,1)
        quitBtn.Text = "Dismount"
        quitBtn.Font = Enum.Font.GothamBold
        Instance.new("UICorner", quitBtn).CornerRadius = UDim.new(0, 6)
        quitBtn.Parent = panel
        
        quitBtn.MouseButton1Click:Connect(function()
            removeUnicornGUI()
            local h = lp.Character and lp.Character:FindFirstChildOfClass("Humanoid")
            if h then 
                h.Sit = false 
            end
        end)
    end
    local function isDriverSitting()
        local h = lp.Character and lp.Character:FindFirstChildOfClass("Humanoid")
        if not h then return false end
        for _, p in ipairs(unicornParts) do
            if p.key == "selle" and p.propModel then
                for _, child in pairs(p.propModel:GetDescendants()) do
                    if child:IsA("Seat") and child.Occupant == h then
                        return true
                    end
                end
            end
        end
        return false
    end
    local function isAnyoneSitting()
        for _, p in ipairs(unicornParts) do
            if (p.key == "selle" or p.key == "passagers") and p.propModel then
                for _, child in pairs(p.propModel:GetDescendants()) do
                    if child:IsA("Seat") and child.Occupant ~= nil then
                        return true
                    end
                end
            end
        end
        return false
    end
    local function getFoldedAnim(bpKey, t2)
        
        if bpKey:sub(1,5) == "patte" then
            if bpKey:sub(7,8) == "av" then
                return CFrame.Angles(math.rad(70), 0, 0)
            else
                return CFrame.Angles(math.rad(-70), 0, 0)
            end
        elseif bpKey:sub(1,4) == "aile" then
            return CFrame.Angles(0, 0, 0)
        elseif bpKey:sub(1,3) == "cou" or bpKey == "tete" or bpKey == "corne" or bpKey == "oeil" then
            return CFrame.new(0, math.sin(t2*2)*0.2 - 2, 0)
        else
            return CFrame.new(0, math.sin(t2*2)*0.2 - 3, 0)
        end
    end
    local function startUnicornLoop()
        local lp  = game:GetService(_0xS(1)).LocalPlayer
        local RS  = game:GetService(_0xS(15))
        local t   = 0
        local animTime = 0
        local lastUpdate = 0
        
        local rideState = "resting"
        local waitStartTime = 0
        local flightTime = 0
        local flightDistance = 0
        local returnStartCF = nil
        
        local myRoot = lp.Character and lp.Character:FindFirstChild(_0xS(6))
        local spawnOrigin = myRoot and myRoot.CFrame or CFrame.new(0,5,0)
        spawnOrigin = CFrame.new(spawnOrigin.Position) * CFrame.Angles(0, math.rad(90), 0)
        local orbitCenter = spawnOrigin.Position
        
        local currentVelocity = 0
        local unicornWorldPos = spawnOrigin.Position
        local currentYaw = 0
        local unicornTargetWp = nil
        local currentPitch = 0
        local currentBank = 0
        local uis = game:GetService(_0xS(18))
        local ws = game:GetService(_0xS(117))
        unicornLoop = RS.RenderStepped:Connect(function(dt)
            if not unicornActive then return end
            local _uNow = tick(); if _uNow - lastUpdate < (1/24) then return end; lastUpdate = _uNow 
            t = t + dt
            local unicornCF
            local useFolded = false
            unicornCF = spawnOrigin * CFrame.new(0, 1, 0)
            if rideState == "resting" then
                useFolded = true
                
                if isDriverSitting() then
                    setupUnicornGUI()
                    rideState = "manual_ground"
                    waitStartTime = tick()
                    uNotif("Unicorn tamed! WASD to walk, SHIFT to run, SPACE to take off.", 6)
                    
                    local _, yaw, _ = spawnOrigin:ToEulerAnglesYXZ()
                    currentYaw = yaw
                    currentPitch = 0
                    currentBank = 0
                    currentVelocity = 0
                    unicornWorldPos = unicornCF.Position
                elseif unicornForceTakeoff then
                    unicornForceTakeoff = false
                    rideState = "auto_flight"
                    flightTime = 0
                    flightDistance = 0
                    uNotif("Auto-ride started! Enjoy the view.", 5)
                elseif isAnyoneSitting() then
                    rideState = "waiting"
                    uNotif("Passenger seated! Climb on the throne to drive or click 'Take Off'.", 5)
                end
            elseif rideState == "waiting" then
                useFolded = false 
                
                if isDriverSitting() then
                    setupUnicornGUI()
                    rideState = "manual_ground"
                    waitStartTime = tick()
                    uNotif("Unicorn tamed! WASD to walk, SHIFT to run, SPACE to take off.", 6)
                    
                    local _, yaw, _ = spawnOrigin:ToEulerAnglesYXZ()
                    currentYaw = yaw
                    currentPitch = 0
                    currentBank = 0
                    currentVelocity = 0
                    unicornWorldPos = unicornCF.Position
                elseif unicornForceTakeoff then
                    unicornForceTakeoff = false
                    rideState = "auto_flight"
                    flightTime = 0
                    flightDistance = 0
                    uNotif("Auto-ride started! Enjoy the view.", 5)
                elseif not isAnyoneSitting() then
                    rideState = "resting"
                end
            elseif rideState == "manual_ground" then
                useFolded = false
                
                local moveDir = Vector3.new(0,0,0)
                if uis:IsKeyDown(Enum.KeyCode.W) then moveDir = moveDir + Vector3.new(0,0,-1) end
                if uis:IsKeyDown(Enum.KeyCode.S) then moveDir = moveDir + Vector3.new(0,0,1) end
                if uis:IsKeyDown(Enum.KeyCode.A) then moveDir = moveDir + Vector3.new(-1,0,0) end
                if uis:IsKeyDown(Enum.KeyCode.D) then moveDir = moveDir + Vector3.new(1,0,0) end
                
                local isRunning = uis:IsKeyDown(Enum.KeyCode.LeftShift) or isUIBoost
                local targetSpeed = 0
                
                if moveDir.Magnitude > 0.1 then
                    targetSpeed = isRunning and 140 or 50
                    
                    local cam = ws.CurrentCamera
                    local camLook = cam.CFrame.LookVector
                    local camYaw = (math.atan2 or math.atan)(-camLook.X, -camLook.Z)
                    local localYaw = (math.atan2 or math.atan)(-moveDir.X, -moveDir.Z)
                    local targetYaw = camYaw + localYaw
                    
                    local angleDiff = targetYaw - currentYaw
                    while angleDiff >  math.pi do angleDiff = angleDiff - 2*math.pi end
                    while angleDiff < -math.pi do angleDiff = angleDiff + 2*math.pi end
                    currentYaw = currentYaw + angleDiff * 10 * dt
                end
                
                currentVelocity = currentVelocity + (targetSpeed - currentVelocity) * 8 * dt
                local forwardDir = (CFrame.new(Vector3.new(), Vector3.new(0,0,-1)) * CFrame.Angles(0, currentYaw, 0)).LookVector
                unicornWorldPos = unicornWorldPos + forwardDir * currentVelocity * dt
                
                
                local rayOrigin = unicornWorldPos + Vector3.new(0, 100, 0)
                local rayDirection = Vector3.new(0, -200, 0)
                local rayParams = RaycastParams.new()
                local _ignoreList = {lp.Character}
                for _, pd in ipairs(unicornParts) do if pd.propModel then table.insert(_ignoreList, pd.propModel) end end
                rayParams.FilterDescendantsInstances = _ignoreList
                rayParams.FilterType = Enum.RaycastFilterType.Exclude
                local result = ws:Raycast(rayOrigin, rayDirection, rayParams)
                local groundY = result and result.Position.Y or (unicornWorldPos.Y - 10)
                local targetY = groundY + UNICORN_HEIGHT
                
                local maxCorr = 60 * dt
                unicornWorldPos = Vector3.new(unicornWorldPos.X, unicornWorldPos.Y + math.clamp(targetY - unicornWorldPos.Y, -maxCorr, maxCorr), unicornWorldPos.Z)
                
                local pitchTarget = 0
                if result and currentVelocity > 5 then
                    local fOrigin = rayOrigin + forwardDir * 8
                    local fResult = ws:Raycast(fOrigin, rayDirection, rayParams)
                    if fResult then
                        local slopeDiff = fResult.Position.Y - groundY
                        pitchTarget = (math.atan2 or math.atan)(slopeDiff, 8)
                    end
                end
                currentPitch = currentPitch + (pitchTarget - currentPitch) * 6 * dt
                currentBank = currentBank + (0 - currentBank) * 6 * dt
                
                unicornCF = CFrame.new(unicornWorldPos) * CFrame.Angles(0, currentYaw, 0) * CFrame.Angles(currentPitch, 0, currentBank) * CFrame.Angles(0, math.pi, 0)
                animTime = animTime + dt * (1 + currentVelocity / 30)
                
                if uis:IsKeyDown(Enum.KeyCode.Space) or isUIUp or unicornForceTakeoff then
                    unicornForceTakeoff = false
                    rideState = "manual_flight"
                    flightTime = 0
                    uNotif("Take off! WASD to fly, Space = Ascend, Ctrl = Descend.", 5)
                end
                
                if not isSomeoneSitting() then
                    removeUnicornGUI()
                    rideState = "idle"
                end
            elseif rideState == "idle" then
                useFolded = false
                unicornCF = CFrame.new(unicornWorldPos) * CFrame.Angles(0, currentYaw, 0) * CFrame.Angles(currentPitch, 0, currentBank) * CFrame.Angles(0, math.pi, 0)
                animTime = animTime + dt
                
                if isDriverSitting() then
                    setupUnicornGUI()
                    rideState = "manual_ground"
                    waitStartTime = tick()
                    uNotif("Unicorn tamed! WASD to walk, SHIFT to run, SPACE to take off.", 6)
                elseif unicornForceTakeoff then
                    unicornForceTakeoff = false
                    rideState = "auto_flight"
                    flightTime = 0
                    flightDistance = 0
                    uNotif("Auto-ride started! Enjoy the view.", 5)
                elseif not isAnyoneSitting() then
                    rideState = "resting"
                end
            elseif rideState == "manual_flight" then
                flightTime = flightTime + dt
                
                local moveDir = Vector3.new(0,0,0)
                if uis:IsKeyDown(Enum.KeyCode.W) then moveDir = moveDir + Vector3.new(0,0,-1) end
                if uis:IsKeyDown(Enum.KeyCode.S) then moveDir = moveDir + Vector3.new(0,0,1) end
                if uis:IsKeyDown(Enum.KeyCode.A) then moveDir = moveDir + Vector3.new(-1,0,0) end
                if uis:IsKeyDown(Enum.KeyCode.D) then moveDir = moveDir + Vector3.new(1,0,0) end
                
                local isRunning = uis:IsKeyDown(Enum.KeyCode.LeftShift) or isUIBoost
                local targetSpeed = isRunning and 300 or 120
                
                local bankTarget = 0
                if moveDir.Magnitude > 0.1 then
                    local cam = ws.CurrentCamera
                    local camLook = cam.CFrame.LookVector
                    local camYaw = (math.atan2 or math.atan)(-camLook.X, -camLook.Z)
                    local localYaw = (math.atan2 or math.atan)(-moveDir.X, -moveDir.Z)
                    local targetYaw = camYaw + localYaw
                    
                    local angleDiff = targetYaw - currentYaw
                    while angleDiff >  math.pi do angleDiff = angleDiff - 2*math.pi end
                    while angleDiff < -math.pi do angleDiff = angleDiff + 2*math.pi end
                    currentYaw = currentYaw + angleDiff * 8 * dt
                    
                    currentVelocity = currentVelocity + (targetSpeed - currentVelocity) * 5 * dt
                    bankTarget = -angleDiff * 0.35
                else
                    currentVelocity = currentVelocity + (0 - currentVelocity) * 2 * dt
                end
                
                local vSpeed = 0
                if uis:IsKeyDown(Enum.KeyCode.Space) or isUIUp then vSpeed = 100 end
                if uis:IsKeyDown(Enum.KeyCode.LeftControl) or isUIDown then vSpeed = -100 end
                
                local forwardDir = (CFrame.new(Vector3.new(), Vector3.new(0,0,-1)) * CFrame.Angles(0, currentYaw, 0)).LookVector
                unicornWorldPos = unicornWorldPos + forwardDir * currentVelocity * dt
                unicornWorldPos = unicornWorldPos + Vector3.new(0, vSpeed * dt, 0)
                
                local pitchTarget = (vSpeed / 100) * math.rad(20)
                currentPitch = currentPitch + (pitchTarget - currentPitch) * 5 * dt
                currentBank = currentBank + (bankTarget - currentBank) * 5 * dt
                
                
                local minX, maxX = -1425, 1454
                local minZ, maxZ = -1476, 1403
                if unicornWorldPos.X < minX or unicornWorldPos.X > maxX or unicornWorldPos.Z < minZ or unicornWorldPos.Z > maxZ then
                    local toCenter = Vector3.new(0, 0, 0) - unicornWorldPos
                    unicornWorldPos = unicornWorldPos + toCenter.Unit * currentVelocity * dt
                end
                
                unicornCF = CFrame.new(unicornWorldPos) * CFrame.Angles(0, currentYaw, 0) * CFrame.Angles(currentPitch, 0, currentBank) * CFrame.Angles(0, math.pi, 0)
                animTime = animTime + dt * (1 + currentVelocity / 50)
                
                
                local rayOrigin = unicornWorldPos
                local rayDirection = Vector3.new(0, -UNICORN_HEIGHT - 10, 0)
                local rayParams = RaycastParams.new()
                local _ignoreList2 = {lp.Character}
                for _, pd in ipairs(unicornParts) do if pd.propModel then table.insert(_ignoreList2, pd.propModel) end end
                rayParams.FilterDescendantsInstances = _ignoreList2
                rayParams.FilterType = Enum.RaycastFilterType.Exclude
                local result = ws:Raycast(rayOrigin, rayDirection, rayParams)
                if result and vSpeed < 0 then
                    rideState = "manual_ground"
                    uNotif("Landing successful!", 3)
                end
                
                if unicornForceReturn then
                    removeUnicornGUI()
                    unicornForceReturn = false
                    rideState = "returning"
                    waitStartTime = tick()
                    returnStartCF = unicornCF
                end
                
                if not isDriverSitting() then
                    removeUnicornGUI()
                    rideState = "idle"
                end
                
            elseif rideState == "auto_flight" then
                useFolded = false
                flightTime = flightTime + dt
                
                local currentSpeed = 100 + math.sin(flightTime * 0.5) * 50
                if uis:IsKeyDown(Enum.KeyCode.LeftShift) then
                    currentSpeed = 300
                end
                
                flightDistance = flightDistance + currentSpeed * dt
                local tSpeed = flightDistance / 800
                local maxRadX = 1400
                local maxRadZ = 1200
                
                local targetX = math.sin(tSpeed * 0.8) * maxRadX + math.sin(tSpeed * 1.5) * 200
                local targetZ = (1 - math.cos(tSpeed * 1.1)) * maxRadZ + math.sin(tSpeed * 0.7) * 250
                local heightOffset = math.sin(tSpeed * 2.0) * 80 + math.cos(tSpeed * 0.9) * 40
                
                unicornWorldPos = orbitCenter + Vector3.new(targetX, 140 + heightOffset, targetZ)
                
                local tNext = (flightDistance + 40) / 800
                local nextX = math.sin(tNext * 0.8) * maxRadX + math.sin(tNext * 1.5) * 200
                local nextZ = (1 - math.cos(tNext * 1.1)) * maxRadZ + math.sin(tNext * 0.7) * 250
                
                local dir = Vector3.new(nextX - targetX, 0, nextZ - targetZ).Unit
                
                local barrelRoll = 0
                if math.sin(tSpeed * 3) > 0.95 then
                    barrelRoll = (math.sin(tSpeed * 3) - 0.95) * 20 * math.pi
                end
                
                local bankAngle = math.sin(tSpeed * 1.5) * 0.5
                
                unicornCF = CFrame.lookAt(unicornWorldPos, unicornWorldPos - dir) * CFrame.Angles(0, 0, bankAngle + barrelRoll)
                animTime = animTime + dt * 1.5
                
                if flightTime > 60 or unicornForceReturn then
                    unicornForceReturn = false
                    rideState = "returning"
                    waitStartTime = tick()
                    returnStartCF = unicornCF
                    uNotif("Ride over! Returning to base.", 4)
                end
                
                
                if isDriverSitting() and (uis:IsKeyDown(Enum.KeyCode.W) or uis:IsKeyDown(Enum.KeyCode.A) or uis:IsKeyDown(Enum.KeyCode.S) or uis:IsKeyDown(Enum.KeyCode.D)) then
                    setupUnicornGUI()
                    rideState = "manual_flight"
                    local _, yaw, _ = unicornCF:ToEulerAnglesYXZ()
                    currentYaw = yaw
                    currentPitch = 0
                    currentBank = 0
                    currentVelocity = currentSpeed
                    uNotif("You took back manual controls!", 4)
                end
            elseif rideState == "returning" then
                local elapsed = tick() - waitStartTime
                local returnTime = 10
                local returnProgress = math.min(elapsed / returnTime, 1)
                local currentRoot = lp.Character and lp.Character:FindFirstChild(_0xS(6))
                local targetPos = currentRoot and currentRoot.Position or orbitCenter
                local targetOrigin = CFrame.new(targetPos + Vector3.new(0,0,-15)) * CFrame.Angles(0, math.rad(90), 0)
                
                local targetCF = targetOrigin * CFrame.new(0, 38, 0)
                unicornCF = returnStartCF:Lerp(targetCF, returnProgress)
                
                if elapsed > returnTime then
                    rideState = "landing"
                    waitStartTime = tick()
                    spawnOrigin = targetOrigin
                end
            elseif rideState == "landing" then
                local elapsed = tick() - waitStartTime
                local landProgress = math.min(elapsed / 4, 1)
                
                local startH = 38
                local currentH = startH - (landProgress * (startH - 1))
                
                unicornCF = spawnOrigin * CFrame.new(0, currentH, 0)
                useFolded = (landProgress > 0.8) 
                
                if elapsed > 4 then
                    unicornForceTakeoff = false
                    unicornForceReturn = false
                    rideState = "resting"
                end
            end
            
                if rideState ~= "flying" then
                    animTime = animTime + dt
                end
            for _, pData in ipairs(unicornParts) do
                local bp = pData.blueprint
                if bp and pData.scf then
                    local animDelta
                    if useFolded then
                        animDelta = getFoldedAnim(bp.key, animTime)
                    elseif bp.anim then
                        animDelta = bp.anim(animTime)
                    else
                        animDelta = CFrame.new()
                    end
                    local finalRot = bp.rot or CFrame.Angles(0,0,0)
                    local partCF = unicornCF * CFrame.new(bp.off) * finalRot * animDelta
                    uStream:setCF(pData.scf, partCF)
                end
            end
        end)
    end
