    local function canDo(actionKey, cd)
        local now = tick()
        if leviathanCooldowns[actionKey] and (now - leviathanCooldowns[actionKey]) < cd then
            return false
        end
        leviathanCooldowns[actionKey] = now
        return true
    end
    local function triggerBreach()
        if not leviathanActive then lNotif("Summon the Leviathan first!", 2) return end
        if not canDo("breach", 6.5) then lNotif("Breach on cooldown...", 2) return end
        leviathanMode = "manual"
        leviathanState = "breach"
        leviathanStateTimer = 0
        leviathanBreachedNotif = false
        lNotif("THE LEVIATHAN PLUNGES INTO THE ABYSS!", 2.5)
    end
