    local function getPartAnimDelta(bpKey, animTime, currentVelocity, rideState)
        local walkSpeed = math.min(currentVelocity / 50, 2)
        local walkPhase = animTime * (6 + walkSpeed * 4)
        local idlePhase = animTime * 2.5
        if bpKey:sub(1,5) == "patte" then
            local isFront = bpKey:find("av") ~= nil
            local isMid   = bpKey:find("mil") ~= nil
            local isLeft  = bpKey:find("G") ~= nil
            if rideState == "manual_flight" then
                local foldAngle = math.rad(-25) + math.sin(animTime * 2) * math.rad(3)
                return CFrame.Angles(foldAngle, 0, 0)
            else
                local phaseShift = 0
                if isFront then phaseShift = isLeft and 0 or math.pi
                elseif isMid then phaseShift = isLeft and math.pi or 0
                else phaseShift = isLeft and 0 or math.pi end
                local swing = math.sin(walkPhase + phaseShift) * (0.15 + walkSpeed * 0.25)
                local lift  = math.max(0, math.cos(walkPhase + phaseShift)) * (0.2 + walkSpeed * 0.3)
                return CFrame.new(0, lift, 0) * CFrame.Angles(swing, 0, 0)
            end
        elseif bpKey:sub(1,7) == "oreille" then
            local isLeft = bpKey:find("G") ~= nil
            local flapFreq = (rideState == "manual_flight") and 5 or 2.5
            local flapAmp  = (rideState == "manual_flight") and math.rad(22) or math.rad(8)
            local flap = math.sin(animTime * flapFreq) * flapAmp
            local dir = isLeft and -1 or 1
            return CFrame.Angles(0, 0, flap * dir)
        elseif bpKey:sub(1,6) == "trompe" then
            local isTip = bpKey:find("2") ~= nil
            local wave  = math.sin(idlePhase + (isTip and 1.5 or 0)) * math.rad(10)
            return CFrame.Angles(wave, 0, 0)
        elseif bpKey == "tete" or bpKey == "cou" then
            local breathe = math.sin(idlePhase) * 0.08
            return CFrame.new(0, breathe, 0) * CFrame.Angles(breathe * 0.5, 0, 0)
        end
        return CFrame.new(0, math.sin(idlePhase) * 0.05, 0)
    end
    local function isDriverSitting()
        local char = lp.Character
        local hum = char and char:FindFirstChildOfClass("Humanoid")
        if not hum then return false end
        for _, p in ipairs(creatureParts) do
            if p.key == "selle" and p.propModel then
                for _, child in pairs(p.propModel:GetDescendants()) do
                    if child:IsA("Seat") and child.Occupant ~= nil then
                        if child.Occupant == hum or (child.Occupant.Parent and child.Occupant.Parent.Name == lp.Name) then
                            return true
                        end
                    end
                end
            end
        end
        return false
    end
    local function isAnyoneSitting()
        for _, p in ipairs(creatureParts) do
            if (p.key == "selle" or p.key == "passagers") and p.propModel then
                for _, child in pairs(p.propModel:GetDescendants()) do
                    if child:IsA("Seat") and child.Occupant ~= nil then
                        return true
                    end
                end
            end
        end
        return false
    end
