BuildTab:AddToggle({
    Name = "بناء (عطّل للتنظيف)",
    Description = "Starts the build. Toggle OFF to clear.",
    Default = false,
    Callback = function(Value)
        if not _G.BTR_UI_READY then return end
        BuildSystem.Active = Value
        local lp = game:GetService(_0xS(1)).LocalPlayer
        local hrp = lp.Character and lp.Character:FindFirstChild(_0xS(6))
        local clearTools = game:GetService(_0xS(70)):WaitForChild(_0xS(83)):WaitForChild(_0xS(87))
        if Value then
            if not hrp then BuildSystem.Active = false return end
            if hrp then hrp.Anchored = true end
            task.spawn(function()
                
                local tool = getOrFetchPropMaker()
                
                if tool and hrp and hrp.Parent then
                    local hum = hrp.Parent:FindFirstChild(_0xS(94))
                    if hum then 
                        hum:EquipTool(tool) 
                        
                        lp.Character:WaitForChild(_0xS(89), 2)
                    end
                end
                task.wait(0.5)
                pcall(function() clearTools:FireServer("OpenPropMenu") end)
                task.wait(0.2)
                
                local startCFrame = hrp.CFrame * CFrame.new(0, 2, -12)
                local points = getPoints(BuildSystem.CurrentShape)
                local lastProp = ""
                local lastCat = ""
                
                
                local spawnedProps = {}
                local connection
                local myPropName = "Prop" .. lp.Name
                connection = workspace:WaitForChild(_0xS(93)).DescendantAdded:Connect(function(desc)
                    if desc:IsA("Model") and desc.Name == myPropName then
                        table.insert(spawnedProps, desc)
                    end
                end)
                local allSameProp = true
                local firstP = points[1]
                for _, pt in ipairs(points) do
                    if pt.prop ~= firstP.prop or pt.cat ~= firstP.cat then
                        allSameProp = false
                        break
                    end
                end
                if allSameProp and #points > 1 then
                    pcall(function() game:GetService(_0xS(70)):WaitForChild(_0xS(100)):WaitForChild(_0xS(101)):FireServer("filterClick", {name = firstP.cat, itemType = "Props"}) end)
                    task.wait(0.1)
                    pcall(function() game:GetService(_0xS(70)):WaitForChild(_0xS(100)):WaitForChild(_0xS(101)):FireServer("filterClick", {name = firstP.prop, itemType = "Props"}) end)
                    task.wait(0.1)
                    pcall(function() clearTools:FireServer("RequestingPropName", firstP.prop, firstP.cat) end)
                    task.wait(0.3)
                    local currentTool = lp.Character:FindFirstChild(_0xS(89))
                    local propMake = currentTool and currentTool:FindFirstChild(_0xS(96))
                    if propMake then
                        local dup = spawnAndDuplicateProps(propMake, startCFrame.Position, #points, 0)
                        if not dup then
                            for i, pt in ipairs(points) do
                                if not BuildSystem.Active then break end
                                local actualScale = (BuildSystem.CurrentShape == "AK-47" or BuildSystem.CurrentShape == "AK47 HD" or BuildSystem.CurrentShape == "Zizi") and 1.5 or BuildSystem.Scale
                                local targetPos = (startCFrame * CFrame.new(pt.x * actualScale, pt.y * actualScale, (pt.z or 0) * actualScale)).Position
                                pcall(function() propMake:FireServer(workspace.Terrain, targetPos) end)
                                task.wait(0.85)
                            end
                        end
                    end
                else
                    for i, pt in ipairs(points) do
                        if not BuildSystem.Active then break end
                        local useProp = pt.prop
                        local useCat  = pt.cat
                        if useProp ~= lastProp or useCat ~= lastCat then
                            pcall(function() game:GetService(_0xS(70)):WaitForChild(_0xS(100)):WaitForChild(_0xS(101)):FireServer("filterClick", {name = useCat, itemType = "Props"}) end)
                            task.wait(0.1)
                            pcall(function() game:GetService(_0xS(70)):WaitForChild(_0xS(100)):WaitForChild(_0xS(101)):FireServer("filterClick", {name = useProp, itemType = "Props"}) end)
                            task.wait(0.1)
                            pcall(function() clearTools:FireServer("RequestingPropName", useProp, useCat) end)
                            task.wait(0.3)
                            lastProp = useProp
                            lastCat  = useCat
                        end
                        local actualScale = (BuildSystem.CurrentShape == "AK-47" or BuildSystem.CurrentShape == "AK47 HD" or BuildSystem.CurrentShape == "Zizi") and 1.5 or BuildSystem.Scale
                        local targetPos = (startCFrame * CFrame.new(pt.x * actualScale, pt.y * actualScale, (pt.z or 0) * actualScale)).Position
                        local currentTool = lp.Character:FindFirstChild(_0xS(89))
                        if currentTool then
                            local propMake = currentTool:FindFirstChild(_0xS(96))
                            if propMake then
                                propMake:FireServer(workspace.Terrain, targetPos)
                            end
                        end
                        task.wait(0.85)
                    end
                end
                
                if connection then connection:Disconnect() end
                
                
                task.wait(0.5)
                for i, pt in ipairs(points) do
                    if not BuildSystem.Active then break end
                    local propModel = spawnedProps[i]
                    if propModel then
                        local scf = propModel:FindFirstChild(_0xS(97))
                        if scf then
                            local rx = pt.rx and math.rad(pt.rx) or 0
                            local ry = pt.ry and math.rad(pt.ry) or 0
                            local rz = pt.rz and math.rad(pt.rz) or 0
                            local actualScale = (BuildSystem.CurrentShape == "AK-47" or BuildSystem.CurrentShape == "AK47 HD" or BuildSystem.CurrentShape == "Zizi") and 1.5 or BuildSystem.Scale
                            local targetCF = startCFrame * CFrame.new(pt.x * actualScale, pt.y * actualScale, (pt.z or 0) * actualScale) * CFrame.Angles(rx, ry, rz)
                            task.spawn(function() pcall(function() scf:InvokeServer(targetCF) end) end)
                        end
                    end
                end
                task.wait(1)
                pcall(function() game:GetService(_0xS(70)):WaitForChild(_0xS(83)):WaitForChild(_0xS(88)):InvokeServer(_0xS(90), _0xS(89)) end)
                local humanoid = lp.Character and lp.Character:FindFirstChildOfClass("Humanoid")
                if humanoid then pcall(function() humanoid:UnequipTools() end) end
                pcall(function() clearTools:FireServer("ClosePropMenu") end)
                cleanupPropMakerTool()
                if hrp then hrp.Anchored = false end
                BuildSystem.Active = false
            end)
        else
            if hrp then hrp.Anchored = false end
            pcall(function() clearTools:FireServer(_0xS(95)) end)
        end
    end
