    local function getSpiderPartColor(layout, partIdx, t, state, colorMode)
        if state == "scare" then
            
            if layout.key == "fangL" or layout.key == "fangR" then
                return Color3.fromRGB(12, 12, 14)
            elseif layout.key == "head" then
                return Color3.fromRGB(14, 14, 16)
            end
        end
        if colorMode == "Black Widow" then
            if layout.key == "saddle" then
                return Color3.fromRGB(22, 22, 26)
            elseif layout.key == "fangL" or layout.key == "fangR" then
                return Color3.fromRGB(18, 18, 22)
            elseif layout.key == "abdomen" then
                return Color3.fromRGB(10, 10, 12)
            else
                return Color3.fromRGB(14, 14, 16)
            end
        elseif colorMode == "Acid Broodmother" then
            if layout.key == "fangL" or layout.key == "fangR" then
                return Color3.fromRGB(40, 255, 50)
            elseif layout.key == "abdomen" then
                return Color3.fromRGB(12, 35, 16)
            else
                return Color3.fromRGB(15, 45, 20)
            end
        elseif colorMode == "Tarantula Gold" then
            if layout.key == "fangL" or layout.key == "fangR" then
                return Color3.fromRGB(190, 130, 30)
            elseif layout.key == "abdomen" then
                return Color3.fromRGB(48, 28, 14)
            elseif layout.legIdx then
                return (layout.legIdx % 2 == 0) and Color3.fromRGB(210, 140, 45) or Color3.fromRGB(65, 40, 20)
            else
                return Color3.fromRGB(55, 32, 18)
            end
        elseif colorMode == "Shadow Void" then
            if layout.key == "fangL" or layout.key == "fangR" then
                return Color3.fromRGB(210, 50, 255)
            elseif layout.key == "abdomen" then
                return Color3.fromRGB(25, 10, 42)
            else
                return Color3.fromRGB(30, 12, 50)
            end
        elseif colorMode == "Glacial Weaver" then
            if layout.key == "fangL" or layout.key == "fangR" then
                return Color3.fromRGB(0, 220, 255)
            elseif layout.key == "abdomen" then
                return Color3.fromRGB(210, 240, 255)
            else
                return Color3.fromRGB(175, 225, 250)
            end
        elseif colorMode == "Rainbow Venom" then
            return Color3.fromHSV((t * 0.5 + partIdx * 0.065) % 1, 0.9, 1)
        end
        return Color3.fromRGB(14, 14, 16)
    end
    local function getSpiderPartCFrame(layout, t, state, centerPos, yaw, strideSpeed, slopePitch, slopeRoll)
        local baseCF = CFrame.new(centerPos) * CFrame.Angles(0, yaw, 0) * CFrame.Angles(slopePitch or 0, 0, slopeRoll or 0)
        local bodyLift = 0
        local bodyPitch = 0
        local bodyRoll = 0
        local fangPinch = math.sin(t * 5) * 0.18
        if state == "scare" then
            bodyLift = 1.8 + math.sin(t * 7.0) * 0.9
            bodyPitch = math.rad(-14) + math.sin(t * 7.0) * math.rad(8)
            fangPinch = math.sin(t * 14.0) * 0.55
        elseif state == "walk" then
            local freq = 6.0 + (strideSpeed / 26.0) * 3.0
            bodyLift = math.abs(math.cos(t * freq)) * 0.28
            bodyRoll = math.sin(t * freq) * 0.03
            fangPinch = math.sin(t * 8) * 0.25
        else
            bodyLift = math.sin(t * 2.0) * 0.10
        end
        local rootCF = baseCF * CFrame.new(0, bodyLift, 0) * CFrame.Angles(bodyPitch, 0, bodyRoll)
        if layout.key == "core" then
            return rootCF * CFrame.new(layout.hip)
        elseif layout.key == "head" then
            local headTwitch = (state == "idle") and math.sin(t * 1.5) * 0.04 or 0
            return rootCF * CFrame.new(layout.hip) * CFrame.Angles(headTwitch, 0, 0)
        elseif layout.key == "saddle" then
            return rootCF * CFrame.new(layout.hip) * CFrame.Angles(0, math.pi, 0)
        elseif layout.key == "abdomen" then
            local abdoSway = (state == "walk") and math.sin(t * 6) * 0.06 or math.sin(t * 2.0) * 0.03
            local abdoPitch = math.sin(t * 2.5) * 0.04 + math.rad(5)
            return rootCF * CFrame.new(layout.hip) * CFrame.Angles(abdoPitch, abdoSway, 0)
        elseif layout.key == "spinneret" then
            local spinSway = (state == "walk") and math.sin(t * 6) * 0.08 or math.sin(t * 2.0) * 0.03
            return rootCF * CFrame.new(layout.hip) * CFrame.Angles(math.rad(10), spinSway, 0)
        elseif layout.key == "fangL" then
            local pinch = (state == "scare") and (math.sin(t * 14.0) * 0.25) or (math.sin(t * 2.0) * 0.08)
            return rootCF * CFrame.new(layout.hip) * CFrame.Angles(math.rad(15), math.rad(12) - pinch, 0)
        elseif layout.key == "fangR" then
            local pinch = (state == "scare") and (math.sin(t * 14.0) * 0.25) or (math.sin(t * 2.0) * 0.08)
            return rootCF * CFrame.new(layout.hip) * CFrame.Angles(math.rad(15), math.rad(-12) + pinch, 0)
        elseif layout.legIdx then
            local groupA = (layout.side == -1 and (layout.legIdx == 1 or layout.legIdx == 3)) or (layout.side == 1 and (layout.legIdx == 2 or layout.legIdx == 4))
            local freq = 6.0 + (strideSpeed / 26.0) * 3.0
            local phase = groupA and (t * freq) or (t * freq + math.pi)
            phase = phase % (2 * math.pi)
            local footX = layout.footBase.X
            local footY = layout.footBase.Y
            local footZ = layout.footBase.Z
            if state == "scare" then
                local freq = 7.0
                if layout.legIdx == 1 or layout.legIdx == 2 then
                    
                    local phase = t * freq + (layout.side * 1.2) + (layout.legIdx * 0.8)
                    footY = 3.2 + math.sin(phase) * 2.0
                    footZ = layout.footBase.Z + 4.2 + math.cos(phase) * 1.8
                    footX = layout.footBase.X * 0.75 + math.sin(phase * 0.5) * 1.0
                else
                    
                    local phase = t * freq + (layout.side * 1.8) + (layout.legIdx * 0.8)
                    footY = math.max(0.0, math.sin(phase) * 1.4)
                    footZ = layout.footBase.Z + math.cos(phase) * 1.0
                    footX = layout.footBase.X
                end
            elseif state == "walk" then
                local cycle = phase / (2 * math.pi)
                local strideLen = 3.6
                local liftHeight = 2.6
                if cycle < 0.35 then
                    local swingT = cycle / 0.35
                    footY = math.sin(swingT * math.pi) * liftHeight
                    footZ = layout.footBase.Z + (strideLen * (swingT * 2.0 - 1.0))
                    footX = layout.footBase.X + math.sin(swingT * math.pi) * (layout.side * 0.7)
                else
                    local stanceT = (cycle - 0.35) / 0.65
                    footY = 0.0
                    footZ = layout.footBase.Z + (strideLen * (1.0 - stanceT * 2.0))
                    footX = layout.footBase.X
                end
            else
                local twitch = math.sin(t * 2.0 + layout.legIdx * 1.2 + layout.side) * 0.2
                footY = 0.0
                footZ = layout.footBase.Z + twitch
            end
            local hipWorld = rootCF:PointToWorldSpace(layout.hip)
            local footWorld = baseCF:PointToWorldSpace(Vector3.new(footX, footY, footZ))
            local midWorld = (hipWorld + footWorld) * 0.5
            local legRot = CFrame.lookAt(midWorld, footWorld) * CFrame.Angles(math.rad(90), 0, 0)
            return legRot
        end
        return rootCF
    end
    local function isDriverSitting()
        if not spiderDriverSeat or not isSpiderMounted then return false end
        local char = lp.Character
        local hum = char and char:FindFirstChildOfClass("Humanoid")
        local hrp = char and char:FindFirstChild(_0xS(6))
        if not hum or not hrp then
            isSpiderMounted = false
            return false
        end
        if not hum.Sit then
            isSpiderMounted = false
            return false
        end
        if (hrp.Position - spiderAnchor).Magnitude > 8.0 then
            isSpiderMounted = false
            return false
        end
        if hum.SeatPart == spiderDriverSeat or (spiderDriverSeat:IsA("Seat") and spiderDriverSeat.Occupant == hum) then
            return true
        end
        isSpiderMounted = false
        return false
    end
    local function startSpiderWorkers(w)
        task.spawn(function()
            while spiderActive and w.scf do
                local now = tick()
                if w.targetCF then
                    local cf = w.targetCF
                    local send = false
                    if not w.lastSentCF then
                        send = true
                    else
                        local pDiff = (cf.Position - w.lastSentCF.Position).Magnitude
                        if pDiff > 0.04 or (now - w.lastSendTimeCF > 0.055) then
                            send = true
                        end
                    end
                    if send then
                        w.lastSentCF = cf
                        w.lastSendTimeCF = now
                        pcall(function() w.scf:InvokeServer(cf) end)
                    end
                end
                task.wait(0.035)
            end
        end)
        task.spawn(function()
            while spiderActive and w.cpc do
                local now = tick()
                if w.targetColor then
                    local col = w.targetColor
                    local sendCol = false
                    if not w.lastSentColor then
                        sendCol = true
                    else
                        local diff = math.abs(col.R - w.lastSentColor.R) + math.abs(col.G - w.lastSentColor.G) + math.abs(col.B - w.lastSentColor.B)
                        if diff > 0.04 or (now - w.lastSendTimeCol > 0.35) then
                            sendCol = true
                        end
                    end
                    if sendCol then
                        w.lastSentColor = col
                        w.lastSendTimeCol = now
                        pcall(function() w.cpc:InvokeServer(col) end)
                    end
                end
                task.wait(0.08)
            end
        end)
    end
    local function spawnSpider()
