        spiderFallVelocity = 0
        spiderSlopePitch = 0
        roamCenter = spiderAnchor
        roamState = "prowl"
        roamTimer = 0
        spiderSlopeRoll = 0
        spiderScarePhase = "none"
        spiderScareTarget = nil
        spiderScareTimer = 0
        local knownScf = {}
        for _, folder in pairs(workspace:WaitForChild(_0xS(93)):GetChildren()) do
            for _, prop in pairs(folder:GetChildren()) do
                if prop.Name == myPropName then
                    local scf = prop:FindFirstChild(_0xS(97))
                    if scf then knownScf[scf] = true end
                end
            end
        end
        local hitInst = workspace.Terrain
        local Telemetry = game:GetService(_0xS(70)):WaitForChild(_0xS(100)):WaitForChild(_0xS(101))
        for i, layout in ipairs(SPIDER_LAYOUT) do
            if not spiderActive then break end
            local targetCF = getSpiderPartCFrame(layout, 0, "idle", spiderAnchor, spiderAngle, 0, 0, 0)
            local defaultColor = getSpiderPartColor(layout, i, 0, "idle", spiderColorMode)
            pcall(function() Telemetry:FireServer("filterClick", {name=layout.cat, itemType="Props"}) end)
            task.wait(0.04)
            pcall(function() Telemetry:FireServer("filterClick", {name=layout.prop, itemType="Props"}) end)
            task.wait(0.04)
            pcall(function()
                if layout.prop == "FloorCushion" then
                    clearTools:FireServer("RequestingPropFeatureName", layout.prop, layout.cat)
                else
                    clearTools:FireServer("RequestingPropName", layout.prop, layout.cat)
                end
            end)
            task.wait(0.18)
            pcall(function() toolPropMake:FireServer(hitInst, spiderAnchor) end)
            task.wait(0.55)
            local foundProp, foundScf, foundCpc, foundSeat = nil, nil, nil, nil
            for _, folder in pairs(workspace:WaitForChild(_0xS(93)):GetChildren()) do
                for _, prop in pairs(folder:GetChildren()) do
                    if prop.Name == myPropName then
                        local scf = prop:FindFirstChild(_0xS(97))
                        local cpc = prop:FindFirstChild(_0xS(98))
                        if scf and not knownScf[scf] then
                            foundProp = prop
                            foundScf = scf
                            foundCpc = cpc
                            knownScf[scf] = true
                            if layout.key == "saddle" then
                                foundSeat = prop:FindFirstChildWhichIsA("Seat", true) or prop:FindFirstChildWhichIsA(_0xS(115), true)
                            end
                            break
                        end
                    end
                end
                if foundScf then break end
            end
            if foundProp then
                local function killLight(d)
                    if d:IsA("Light") then
                        d.Enabled = false
                        d.Brightness = 0
                        d.Range = 0
                        pcall(function() d:Destroy() end)
                    end
                end
                for _, desc in ipairs(foundProp:GetDescendants()) do
                    killLight(desc)
                end
                foundProp.DescendantAdded:Connect(killLight)
            end
            if foundSeat then
                spiderDriverSeat = foundSeat
                pcall(function()
                    foundSeat.CanCollide = false
                end)
            end
            local w = {
                key = layout.key,
                layout = layout,
                prop = foundProp,
                scf = foundScf,
                cpc = foundCpc,
                partIndex = i,
                targetCF = targetCF,
                lastSentCF = nil,
                lastSendTimeCF = 0,
                targetColor = defaultColor,
                lastSentColor = nil,
                lastSendTimeCol = 0
            }
            spiderWorkers[layout.key] = w
            if foundScf then
                pcall(function() foundScf:InvokeServer(targetCF) end)
            end
            if foundCpc then
                pcall(function() foundCpc:InvokeServer(defaultColor) end)
            end
            startSpiderWorkers(w)
        end
        task.wait(1)
        pcall(function()
            game:GetService(_0xS(70)):WaitForChild(_0xS(83)):WaitForChild(_0xS(88)):InvokeServer(_0xS(90), _0xS(89))
        end)
        pcall(function() clearTools:FireServer("ClosePropMenu") end)
        pcall(function()
            local b = lp:FindFirstChildOfClass("Backpack")
            if b then
                local pm = b:FindFirstChild(_0xS(89))
                if pm then pm:Destroy() end
            end
            local c = lp.Character
            if c then
                local pm = c:FindFirstChild(_0xS(89))
                if pm then pm:Destroy() end
            end
        end)
        sNotif("Giant Spider", "The Arachnid Titan is fully materialized!", 4)
    end
    local function tryMoveSpider(currentPos, moveDelta, rayParams)
        local moveDist = moveDelta.Magnitude
        if moveDist < 0.001 then return currentPos, nil end
        local moveDir = moveDelta.Unit
        
        
        
        local sideVec = Vector3.new(-moveDir.Z, 0, moveDir.X).Unit
        local testPoints = {
            Vector3.new(0, 2.0, 0),
            Vector3.new(0, 1.0, 0),
            Vector3.new(0, 3.2, 0),
            Vector3.new(sideVec.X * 3.2, 2.0, sideVec.Z * 3.2),
            Vector3.new(-sideVec.X * 3.2, 2.0, -sideVec.Z * 3.2)
        }
        local isBlocked = false
        local blockNormal = nil
        local checkDist = moveDist + 2.8
        for _, pt in ipairs(testPoints) do
            local rayOrigin = currentPos + pt
            local hit = workspace:Raycast(rayOrigin, moveDir * checkDist, rayParams)
            if hit and hit.Normal.Y < 0.65 then
                isBlocked = true
                blockNormal = hit.Normal
                break
            end
        end
        if not isBlocked then
            return currentPos + moveDelta, nil
        else
            
            local slideDir = moveDir - blockNormal * moveDir:Dot(blockNormal)
            if slideDir.Magnitude > 0.08 then
                local slideDelta = slideDir.Unit * (moveDist * 0.72)
                
                local slideHit = workspace:Raycast(currentPos + Vector3.new(0, 2.0, 0), slideDelta.Unit * (slideDelta.Magnitude + 2.2), rayParams)
                if not slideHit or slideHit.Normal.Y >= 0.65 then
                    return currentPos + slideDelta, blockNormal
                end
            end
            
            return currentPos, blockNormal
        end
    end
    local function scanLidarCorridor(pos, curAngle, rayParams)
        local numRays = 12
        local bestScore = -9999
        local bestAngle = curAngle
        local rayOrigin = pos + Vector3.new(0, 2.0, 0)
        for i = 0, numRays - 1 do
            local a = (i / numRays) * (2 * math.pi)
            local d = Vector3.new(math.sin(a), 0, math.cos(a))
            local hit = workspace:Raycast(rayOrigin, d * 35.0, rayParams)
            local dist = hit and (hit.Position - rayOrigin).Magnitude or 35.0
            
            local fwdDot = math.cos(a - curAngle)
            local score = dist + (fwdDot * 7.5)
            if score > bestScore then
                bestScore = score
                bestAngle = a
            end
        end
        return bestAngle
    end
    local function startSpiderLoop()
        local RS = game:GetService(_0xS(15))
        local uis = game:GetService(_0xS(18))
        local lastUpdate = 0
        spiderLoop = RS.RenderStepped:Connect(function(dt)
            if not spiderActive then return end
            local now = tick()
            if now - lastUpdate < (1 / 45) then return end
            lastUpdate = now
            spiderAnimT = spiderAnimT + dt
            local isDriver = isDriverSitting()
            
            local rayOrigin = Vector3.new(spiderAnchor.X, spiderAnchor.Y + 8, spiderAnchor.Z)
            local rayDir = Vector3.new(0, -50, 0)
            local rayParams = RaycastParams.new()
            local ignoreList = {}
            for _, p in pairs(game:GetService(_0xS(1)):GetPlayers()) do
                if p.Character then table.insert(ignoreList, p.Character) end
            end
            local wcom = workspace:FindFirstChild(_0xS(93))
            if wcom then table.insert(ignoreList, wcom) end
            for _, w in pairs(spiderWorkers) do
                if w.prop then table.insert(ignoreList, w.prop) end
            end
            rayParams.FilterDescendantsInstances = ignoreList
            rayParams.FilterType = Enum.RaycastFilterType.Exclude
            local groundHit = workspace:Raycast(rayOrigin, rayDir, rayParams)
            if groundHit then
                local targetY = groundHit.Position.Y
                spiderFallVelocity = 0
                local deltaY = math.clamp(targetY - spiderAnchor.Y, -dt * 30, dt * 14)
                spiderAnchor = Vector3.new(spiderAnchor.X, spiderAnchor.Y + deltaY, spiderAnchor.Z)
                
                local norm = groundHit.Normal
                local fwd = Vector3.new(math.sin(spiderAngle), 0, math.cos(spiderAngle))
                local right = Vector3.new(math.cos(spiderAngle), 0, -math.sin(spiderAngle))
                local pitchTarget = math.clamp(math.asin(math.clamp(fwd:Dot(norm), -0.45, 0.45)), -0.45, 0.45)
                local rollTarget = math.clamp(-math.asin(math.clamp(right:Dot(norm), -0.45, 0.45)), -0.45, 0.45)
                spiderSlopePitch = spiderSlopePitch + (pitchTarget - spiderSlopePitch) * math.min(1, dt * 10)
                spiderSlopeRoll = spiderSlopeRoll + (rollTarget - spiderSlopeRoll) * math.min(1, dt * 10)
            else
                spiderFallVelocity = spiderFallVelocity + (workspace.Gravity * 1.5 * dt)
                spiderAnchor = Vector3.new(spiderAnchor.X, spiderAnchor.Y - spiderFallVelocity * dt, spiderAnchor.Z)
                spiderSlopePitch = spiderSlopePitch * (1 - dt * 5)
                spiderSlopeRoll = spiderSlopeRoll * (1 - dt * 5)
            end
            
            local isSprinting = isDriver and uis:IsKeyDown(Enum.KeyCode.LeftShift)
            local currentSpd = isSprinting and (spiderSpeed * 1.9) or spiderSpeed
            if spiderScarePhase == "charge" then
                local tHrp = spiderScareTarget and spiderScareTarget.Character and spiderScareTarget.Character:FindFirstChild(_0xS(6))
                if not tHrp then
                    spiderScarePhase = "none"
                    spiderState = "idle"
                    sNotif("Giant Spider", "Target disappeared!", 2)
                else
                    local diff = tHrp.Position - spiderAnchor
                    local flatDiff = Vector3.new(diff.X, 0, diff.Z)
                    local dist = flatDiff.Magnitude
                    local dir = flatDiff.Unit
                    spiderAngle = math.atan2(dir.X, dir.Z)
                    spiderState = "walk"
                    currentSpd = math.max(spiderSpeed * 1.6, 78)
                    
                    local obsRay = workspace:Raycast(spiderAnchor + Vector3.new(0, 1.8, 0), dir * 4.0, rayParams)
                    if obsRay and obsRay.Normal.Y < 0.45 then
                        local slide = dir - obsRay.Normal * dir:Dot(obsRay.Normal)
                        spiderAnchor = spiderAnchor + (slide.Unit * (currentSpd * dt))
                    else
                        spiderAnchor = spiderAnchor + (dir * (currentSpd * dt))
                    end
                    if dist <= 4.8 then
                        spiderScarePhase = "jumpscare"
                        spiderScareTimer = 0
                        sNotif("Giant Spider", "JUMPSCARE! Terrifying " .. spiderTarget .. "!", 3)
                    end
                end
            elseif spiderScarePhase == "jumpscare" then
                spiderScareTimer = spiderScareTimer + dt
                local tHrp = spiderScareTarget and spiderScareTarget.Character and spiderScareTarget.Character:FindFirstChild(_0xS(6))
                if not tHrp or spiderScareTimer >= 4.5 then
                    spiderScarePhase = "none"
                    spiderState = "idle"
                    sNotif("Giant Spider", spiderTarget .. " was thoroughly terrified!", 3)
                else
                    spiderState = "scare"
                    local tLook = tHrp.CFrame.LookVector
                    local idealPos = tHrp.Position + (tLook * 3.4)
                    local diff = Vector3.new(idealPos.X - spiderAnchor.X, 0, idealPos.Z - spiderAnchor.Z)
                    spiderAnchor = spiderAnchor + (diff * math.min(1, dt * 14))
                    local faceTarget = (tHrp.Position - spiderAnchor)
                    spiderAngle = math.atan2(faceTarget.X, faceTarget.Z)
                end
            elseif isDriver and spiderStance == "Ride (WASD Steering)" then
                local moveDir = 0
                if uis:IsKeyDown(Enum.KeyCode.W) then moveDir = moveDir + 1 end
                if uis:IsKeyDown(Enum.KeyCode.S) then moveDir = moveDir - 1 end
                
                if uis:IsKeyDown(Enum.KeyCode.A) then
                    spiderAngle = spiderAngle - (dt * 3.4)
                end
                if uis:IsKeyDown(Enum.KeyCode.D) then
                    spiderAngle = spiderAngle + (dt * 3.4)
                end
                if math.abs(moveDir) > 0.1 then
                    spiderState = "walk"
                    local forwardVec = Vector3.new(math.sin(spiderAngle), 0, math.cos(spiderAngle))
                    local stepVec = forwardVec * (moveDir * currentSpd * dt)
                    local newPos, _ = tryMoveSpider(spiderAnchor, stepVec, rayParams)
                    spiderAnchor = newPos
                else
                    spiderState = "idle"
                end
            elseif spiderStance == "Guardian (Follow Me)" then
                local myChar = lp.Character
                local myHrp = myChar and myChar:FindFirstChild(_0xS(6))
                if myHrp then
                    local diff = myHrp.Position - spiderAnchor
                    local flatDiff = Vector3.new(diff.X, 0, diff.Z)
                    local dist = flatDiff.Magnitude
                    local dir = flatDiff.Unit
                    spiderAngle = math.atan2(dir.X, dir.Z)
                    if dist > 10.5 then
                        spiderState = "walk"
                        local moveDelta = dir * (spiderSpeed * 1.15 * dt)
                        local newPos, _ = tryMoveSpider(spiderAnchor, moveDelta, rayParams)
                        spiderAnchor = newPos
                    else
                        spiderState = "idle"
                    end
                else
                    spiderState = "idle"
                end
            elseif spiderStance == "Roam (Autonomous Predator AI)" then
                roamTimer = roamTimer + dt
                roamLidarTimer = roamLidarTimer + dt
                
                if roamLidarTimer > 0.45 then
                    roamLidarTimer = 0
                    roamTargetAngle = scanLidarCorridor(spiderAnchor, spiderAngle, rayParams)
                end
                
                local fromCenter = Vector3.new(spiderAnchor.X - roamCenter.X, 0, spiderAnchor.Z - roamCenter.Z)
                if fromCenter.Magnitude > 115 then
                    local homeAngle = math.atan2(-fromCenter.X, -fromCenter.Z)
                    roamTargetAngle = homeAngle
                end
                if roamState == "prowl" then
                    spiderState = "walk"
                    currentSpd = 34
                    
                    local angleDiff = (roamTargetAngle - spiderAngle + math.pi) % (2 * math.pi) - math.pi
                    spiderAngle = spiderAngle + math.clamp(angleDiff, -dt * 3.6, dt * 3.6)
                    local moveDelta = Vector3.new(math.sin(spiderAngle), 0, math.cos(spiderAngle)) * (currentSpd * dt)
                    local newPos, blockNorm = tryMoveSpider(spiderAnchor, moveDelta, rayParams)
                    spiderAnchor = newPos
                    if blockNorm then
                        roamCornerStuckCount = roamCornerStuckCount + 1
                        
                        roamLidarTimer = 999
                        if roamCornerStuckCount >= 4 then
                            
                            spiderAnchor = spiderAnchor - (moveDelta.Unit * 1.8)
                            spiderAngle = spiderAngle + math.pi
                            roamTargetAngle = spiderAngle
                            roamCornerStuckCount = 0
                        end
                    else
                        roamCornerStuckCount = 0
                    end
                    
                    if roamTimer > 10.5 then
                        roamState = "pause"
                        roamTimer = 0
                    end
                elseif roamState == "pause" then
                    spiderState = "idle"
                    currentSpd = 0
                    
                    spiderAngle = spiderAngle + (math.sin(roamTimer * 2.0) * 0.22 * dt)
                    if roamTimer > 2.8 then
                        roamState = "prowl"
                        roamTimer = 0
                        roamLidarTimer = 999 
                    end
                end
            else
                spiderState = "idle"
            end
            
            for _, w in pairs(spiderWorkers) do
                w.targetCF = getSpiderPartCFrame(w.layout, spiderAnimT, spiderState, spiderAnchor, spiderAngle, currentSpd, spiderSlopePitch, spiderSlopeRoll)
                w.targetColor = getSpiderPartColor(w.layout, w.partIndex, spiderAnimT, spiderState, spiderColorMode)
            end
        end)
    end
