    local rainbowRunning = false
    local function applyStickmanColors()
        if stickmanColorTheme == "Rainbow" then
            if not rainbowRunning then
                rainbowRunning = true
                task.spawn(function()
                    while stickmanActive and stickmanColorTheme == "Rainbow" do
                        local idx = 0
                        for key, w in pairs(stickmanWorkers) do
                            idx = idx + 1
                            if w then
                                if not w.cpc and w.prop then
                                    w.cpc = w.prop:FindFirstChild(_0xS(98))
                                end
                                if w.cpc then
                                    local col = Color3.fromHSV((tick() * 0.4 + idx * 0.08) % 1, 1, 1)
                                    pcall(function() w.cpc:InvokeServer(col) end)
                                end
                            end
                        end
                        task.wait(0.1)
                    end
                    rainbowRunning = false
                end)
            end
        else
            task.spawn(function()
                for key, w in pairs(stickmanWorkers) do
                    if w then
                        if not w.cpc and w.prop then
                            w.cpc = w.prop:FindFirstChild(_0xS(98))
                        end
                        if w.cpc then
                            local col = getStickmanPartColor(stickmanColorTheme, key, stickmanStyle)
                            pcall(function() w.cpc:InvokeServer(col) end)
                        end
                    end
                end
            end)
        end
    end
