    local function computeStickmanPartCFrames(blueprint, centerPos, yaw)
        local rootPos = centerPos + Vector3.new(0, groundClearance, 0)
        local baseCF = CFrame.new(rootPos) * CFrame.Angles(0, yaw, 0)
        local cfs = {}
        for _, part in ipairs(blueprint) do
            local offsetCF = CFrame.new(part.pos) * CFrame.Angles(
                math.rad(part.rot.X),
                math.rad(part.rot.Y),
                math.rad(part.rot.Z)
            )
            cfs[part.key] = baseCF * offsetCF
        end
        return cfs
    end
    local function startStickmanGravityAndAnimationLoop()
        task.spawn(function()
            while stickmanActive do
                animTime = animTime + 0.04
                local char = lp.Character
                local hrp = char and char:FindFirstChild(_0xS(6))
                local isWalk = false
                
                if stickmanFollow and hrp then
                    local fwdDist = (stickmanSize == "Ultra Giant") and 30 or ((stickmanSize == "Giant") and 24 or ((stickmanSize == "Large") and 18 or 14))
                    local targetPos = hrp.Position + (hrp.CFrame.LookVector * fwdDist)
                    stickmanAngle = math.atan2(hrp.CFrame.LookVector.X, hrp.CFrame.LookVector.Z)
                    local moveDir = (targetPos - stickmanAnchor)
                    local dist = Vector2.new(moveDir.X, moveDir.Z).Magnitude
                    if dist > 2.0 then
                        isWalk = true
                        walkCycle = walkCycle + 0.18
                        local moveStep = moveDir.Unit * math.min(dist, 16 * 0.05)
                        stickmanAnchor = stickmanAnchor + Vector3.new(moveStep.X, 0, moveStep.Z)
                    end
                end
                
                local ignoreList = {char}
                local wc = workspace:FindFirstChild(_0xS(93))
                if wc then table.insert(ignoreList, wc) end
                local rayParams = RaycastParams.new()
                rayParams.FilterDescendantsInstances = ignoreList
                rayParams.FilterType = Enum.RaycastFilterType.Exclude
                local rayOrigin = Vector3.new(stickmanAnchor.X, stickmanAnchor.Y + 35, stickmanAnchor.Z)
                local groundRay = workspace:Raycast(rayOrigin, Vector3.new(0, -80, 0), rayParams)
                if groundRay then
                    local targetGroundY = groundRay.Position.Y
                    stickmanAnchor = Vector3.new(stickmanAnchor.X, targetGroundY, stickmanAnchor.Z)
                else
                    stickmanAnchor = Vector3.new(stickmanAnchor.X, stickmanAnchor.Y - 1.5, stickmanAnchor.Z)
                end
                
                local bp = getStickmanBlueprint(stickmanSize, stickmanStyle, animTime, walkCycle, isWalk)
                local cfs = computeStickmanPartCFrames(bp, stickmanAnchor, stickmanAngle)
                for _, part in ipairs(bp) do
                    local w = stickmanWorkers[part.key]
                    if w and cfs[part.key] then
                        w.targetCF = cfs[part.key]
                    end
                end
                task.wait(0.04)
            end
        end)
    end
    local function startStickmanWorkerSync(w)
        task.spawn(function()
            while stickmanActive and w.scf do
                if w.targetCF then
                    local cf = w.targetCF
                    local send = false
                    if not w.lastSentCF then
                        send = true
                    else
                        local pDiff = (cf.Position - w.lastSentCF.Position).Magnitude
                        if pDiff > 0.03 then send = true end
                    end
                    if send then
                        w.lastSentCF = cf
                        pcall(function() w.scf:InvokeServer(cf) end)
                    end
                end
                task.wait(0.05)
            end
        end)
    end
    local function spawnStickmanTitan()
        stickmanSpawnThread = coroutine.running()
        local char = lp.Character or lp.CharacterAdded:Wait()
        local hrp = char:WaitForChild(_0xS(6))
        local modeLabel = (stickmanSize == "Ultra Giant") and "Ultra Giant Titan (15 Props Pure)" or (stickmanSize .. " " .. stickmanStyle)
        sNotif("Stickman Titan", "Summoning " .. modeLabel .. " (" .. stickmanColorTheme .. ")...", 4)
        local RE = game:GetService(_0xS(70)):WaitForChild(_0xS(83))
        local clearTools = RE:WaitForChild(_0xS(87))
        local toolRE = RE:WaitForChild(_0xS(88))
        local myPropName = "Prop" .. lp.Name
        pcall(function() clearTools:FireServer(_0xS(95)) end)
        task.wait(0.5)
        local propsTool = getOrFetchPropMaker()
        if not propsTool then
            sNotif("Stickman Titan", _0xS(224), 3)
            return
        end
        local humanoid = char:FindFirstChildOfClass("Humanoid")
        if humanoid then humanoid:EquipTool(propsTool) end
        task.wait(0.4)
        local toolPropMake = propsTool:FindFirstChild(_0xS(96)) or propsTool:WaitForChild(_0xS(96), 3)
        if not toolPropMake then return end
        pcall(function() clearTools:FireServer("OpenPropMenu") end)
        task.wait(0.2)
        local ignoreList = {char}
        local wc = workspace:FindFirstChild(_0xS(93))
        if wc then table.insert(ignoreList, wc) end
        local fwdDist = (stickmanSize == "Ultra Giant") and 30 or ((stickmanSize == "Giant") and 24 or ((stickmanSize == "Large") and 18 or 14))
        local forwardPos = hrp.Position + (hrp.CFrame.LookVector * fwdDist)
        local rayParams = RaycastParams.new()
        rayParams.FilterDescendantsInstances = ignoreList
        rayParams.FilterType = Enum.RaycastFilterType.Exclude
        local gRay = workspace:Raycast(forwardPos + Vector3.new(0, 35, 0), Vector3.new(0, -80, 0), rayParams)
        local groundY = gRay and gRay.Position.Y or (hrp.Position.Y - 2.5)
        local hitInst = gRay and gRay.Instance or workspace.Terrain
        local groundHitPos = gRay and gRay.Position or Vector3.new(forwardPos.X, groundY, forwardPos.Z)
        stickmanAnchor = Vector3.new(forwardPos.X, groundY, forwardPos.Z)
        stickmanAngle = math.atan2(hrp.CFrame.LookVector.X, hrp.CFrame.LookVector.Z)
        stickmanWorkers = {}
        local stagingPos = stickmanAnchor + Vector3.new(0, 35, 0)
        local knownScf = {}
        if wc then
            for _, folder in pairs(wc:GetChildren()) do
                for _, prop in pairs(folder:GetChildren()) do
                    if prop.Name == myPropName then
                        local scf = prop:FindFirstChild(_0xS(97))
                        if scf then knownScf[scf] = true end
                    end
                end
            end
        end
        local Telemetry = game:GetService(_0xS(70)):WaitForChild(_0xS(100)):WaitForChild(_0xS(101))
        local blueprint = getStickmanBlueprint(stickmanSize, stickmanStyle, 0, 0, false)
        
        for i, part in ipairs(blueprint) do
            if not stickmanActive then break end
            pcall(function() Telemetry:FireServer("filterClick", {name=part.cat, itemType="Props"}) end)
            task.wait(0.05)
            pcall(function() Telemetry:FireServer("filterClick", {name=part.prop, itemType="Props"}) end)
            task.wait(0.05)
            pcall(function() clearTools:FireServer("RequestingPropName", part.prop, part.cat) end)
            task.wait(0.20)
            pcall(function() toolPropMake:FireServer(hitInst, groundHitPos) end)
            task.wait(0.85) 
            local foundProp, foundScf, foundCpc = nil, nil, nil
            if wc then
                for _, folder in pairs(wc:GetChildren()) do
                    for _, prop in pairs(folder:GetChildren()) do
                        if prop.Name == myPropName then
                            local scf = prop:FindFirstChild(_0xS(97))
                            local cpc = prop:FindFirstChild(_0xS(98))
                            if scf and not knownScf[scf] then
                                foundProp = prop
                                foundScf = scf
                                foundCpc = cpc
                                knownScf[scf] = true
                                break
                            end
                        end
                    end
                    if foundScf then break end
                end
            end
            if foundProp then
                for _, d in ipairs(foundProp:GetDescendants()) do
                    if d:IsA("Light") then
                        d.Enabled = false
                        d.Brightness = 0
                        pcall(function() d:Destroy() end)
                    end
                end
            end
            local w = {
                key = part.key,
                prop = foundProp,
                scf = foundScf,
                cpc = foundCpc,
                targetCF = nil,
                lastSentCF = nil
            }
            stickmanWorkers[part.key] = w
            if foundScf then
                local floatCF = CFrame.new(stagingPos + Vector3.new(0, i * 2, 0))
                pcall(function() foundScf:InvokeServer(floatCF) end)
            end
            if foundCpc then
                local partColor = getStickmanPartColor(stickmanColorTheme, part.key, stickmanStyle, i)
                pcall(function() foundCpc:InvokeServer(partColor) end)
            end
            startStickmanWorkerSync(w)
        end
        
        task.wait(1)
        pcall(function() toolRE:InvokeServer(_0xS(90), _0xS(89)) end)
        pcall(function() clearTools:FireServer("ClosePropMenu") end)
        task.wait(0.3)
        
        local initialCFs = computeStickmanPartCFrames(blueprint, stickmanAnchor, stickmanAngle)
        for _, part in ipairs(blueprint) do
            local w = stickmanWorkers[part.key]
            if w then
                if initialCFs[part.key] then
                    w.targetCF = initialCFs[part.key]
                    if w.scf then
                        pcall(function() w.scf:InvokeServer(initialCFs[part.key]) end)
                    end
                end
            end
        end
        applyStickmanColors()
        task.wait(0.2)
        
        startStickmanGravityAndAnimationLoop()
        sNotif("Stickman Titan", modeLabel .. " online!", 4)
    end
    local function stopStickmanTitan()
        stickmanActive = false
        if stickmanSpawnThread then
            pcall(function() task.cancel(stickmanSpawnThread) end)
            stickmanSpawnThread = nil
        end
        stickmanWorkers = {}
        pcall(function()
            local RE = game:GetService(_0xS(70)):FindFirstChild(_0xS(83))
            if RE then
                local ct = RE:FindFirstChild(_0xS(87))
                if ct then
                    ct:FireServer(_0xS(95))
                    task.wait(0.05)
                    ct:FireServer("ClearAllTools")
                    ct:FireServer("ClosePropMenu")
                end
            end
        end)
        pcall(function()
            local char = lp.Character
            local hum = char and char:FindFirstChildOfClass("Humanoid")
            if hum then hum:UnequipTools() end
            cleanupPropMakerTool()
        end)
        sNotif("Stickman Titan", "Stickman Titan dismantled.", 2)
    end
