                catActive = false
                catSeat = nil
                if catLoop then catLoop:Disconnect() catLoop = nil end
                pcall(function()
                    game:GetService(_0xS(70)):WaitForChild(_0xS(83)):WaitForChild(_0xS(87)):FireServer(_0xS(95))
                end)
                catWorkers = {}
                catIsSleeping = false
                catFollowActive = false
                catMoveAlpha = 0
                catRunStride = 0
                catTargetSleepAlpha = 0
                cNotif("Cat Companion", "Cat dismissed.", 2)
            end
        end
    })
