    local function getPartColorForTheme(themeName, key)
        if themeName == "Realistic (Default)" then
            return Color3.fromRGB(52, 34, 22)
        end
        if themeName == "Full Black" then
            return Color3.fromRGB(12, 12, 14)
        end
        local theme = SCORPION_THEMES[themeName] or SCORPION_THEMES["Realistic (Default)"]
        if key == "Torso" or key == "Tail_1" or key == "Tail_2" then
            return theme.Torso or Color3.fromRGB(52, 34, 22)
        elseif key:sub(1, 4) == "Leg_" then
            return theme.Legs or Color3.fromRGB(52, 34, 22)
        elseif key:sub(1, 4) == "Arm_" or key:sub(1, 4) == "Claw" then
            return theme.Claws or Color3.fromRGB(52, 34, 22)
        elseif key == "Stinger" then
            return theme.Stinger or (theme.Torso or Color3.fromRGB(52, 34, 22))
        end
        return Color3.fromRGB(52, 34, 22)
    end
    local function paintScorpionWorker(w, col)
        if not w or w.key == "Saddle" or not col then return end
        if w.cpc then
            pcall(function() w.cpc:InvokeServer(col) end)
        end
        if w.prop then
            for _, d in ipairs(w.prop:GetDescendants()) do
                if d:IsA("BasePart") then
                    pcall(function()
                        d.Material = Enum.Material.SmoothPlastic
                        d.Color = col
                    end)
                end
            end
        end
    end
    local function applyTheme(themeName)
        currentTheme = themeName
        isRainbowMode = (themeName == "Rainbow")
        if isRainbowMode then
            sNotif("Scorpion", "Rainbow Mode On!", 2)
            return
        end
        for key, w in pairs(scorpionWorkers) do
            if w.key ~= "Saddle" then
                local col = getPartColorForTheme(themeName, key)
                paintScorpionWorker(w, col)
            end
        end
        sNotif("Scorpion", "Color: " .. themeName, 2)
    end
    local function computeScorpionPartCFrame(key, anchorCF, t, strikeAlpha, stride, isSprint, isMoving)
        local base = SCORPION_PARTS[key]
        local curOff = base and base.off or Vector3.new(0, 0, 0)
        local curRot = base and base.rot or Vector3.new(0, 0, 0)
        local breatheY = math.sin(t * 2.0) * 0.10
        if isSprint and isMoving then
            breatheY = breatheY - 0.35
        end
        if key == "Torso" or key == "Saddle" then
            curOff = curOff + Vector3.new(0, breatheY, 0)
        elseif key == "Arm_L" then
            local wave = math.sin(t * 1.8) * 0.20
            curOff = curOff + Vector3.new(wave, breatheY, 0)
        elseif key == "Arm_R" then
            local wave = math.cos(t * 1.8) * 0.20
            curOff = curOff + Vector3.new(-wave, breatheY, 0)
        elseif key == "Claw_L" then
            local armBase = SCORPION_PARTS["Arm_L"]
            local wave = math.sin(t * 1.8) * 0.20
            local armCF = anchorCF * CFrame.new(armBase.off + Vector3.new(wave, breatheY, 0)) * CFrame.Angles(
                math.rad(armBase.rot.X),
                math.rad(armBase.rot.Y),
                math.rad(armBase.rot.Z)
            )
            local pinch = math.sin(t * 2.5) * 4
            return armCF * CFrame.new(-4.85, 0, -0.3) * CFrame.Angles(0, math.rad(65 + pinch), 0)
        elseif key == "Claw_R" then
            local armBase = SCORPION_PARTS["Arm_R"]
            local wave = math.cos(t * 1.8) * 0.20
            local armCF = anchorCF * CFrame.new(armBase.off + Vector3.new(-wave, breatheY, 0)) * CFrame.Angles(
                math.rad(armBase.rot.X),
                math.rad(armBase.rot.Y),
                math.rad(armBase.rot.Z)
            )
            local pinch = math.sin(t * 2.5) * 4
            return armCF * CFrame.new(4.85, 0, -0.3) * CFrame.Angles(0, math.rad(-65 - pinch), 0)
        elseif key:sub(1, 4) == "Leg_" then
            if isMoving then
                local phase = 0
                if key == "Leg_FR" or key == "Leg_ML" or key == "Leg_BR" then
                    phase = math.pi
                end
                local p = stride + phase
                local liftMult = isSprint and 1.1 or 0.65
                local sweepMult = isSprint and 16 or 11
                local lift = math.max(0, math.sin(p)) * liftMult
                local sweep = math.cos(p) * sweepMult
                curOff = curOff + Vector3.new(0, lift, 0)
                curRot = curRot + Vector3.new(0, sweep, 0)
            end
        end
        if strikeAlpha and strikeAlpha ~= 0 then
            local s = strikeAlpha
            if s > 0 then
                if key == "Tail_1" then
                    curOff = curOff + Vector3.new(0, 0.5 * s, -2.8 * s)
                    curRot = curRot + Vector3.new(62 * s, 0, 0)
                elseif key == "Tail_2" then
                    curOff = curOff + Vector3.new(0, -1.2 * s, -8.8 * s)
                    curRot = curRot + Vector3.new(155 * s, 0, 0)
                elseif key == "Stinger" then
                    curOff = curOff + Vector3.new(0, -6.5 * s, -12.5 * s)
                    curRot = curRot + Vector3.new(-75 * s, 0, 0)
                end
            else
                local w = -s
                if key == "Tail_1" then
                    curOff = curOff + Vector3.new(0, 0.3 * w, 0.8 * w)
                    curRot = curRot + Vector3.new(-18 * w, 0, 0)
                elseif key == "Tail_2" then
                    curOff = curOff + Vector3.new(0, 0.8 * w, 1.2 * w)
                    curRot = curRot + Vector3.new(-25 * w, 0, 0)
                elseif key == "Stinger" then
                    curOff = curOff + Vector3.new(0, 1.5 * w, 1.0 * w)
                    curRot = curRot + Vector3.new(15 * w, 0, 0)
                end
            end
        end
        local cf = anchorCF * CFrame.new(curOff)
        cf = cf * CFrame.Angles(
            math.rad(curRot.X),
            math.rad(curRot.Y),
            math.rad(curRot.Z)
        )
        return cf
    end
    local function getGroundPos(pos)
        local char = lp.Character
        local wsCom = ws:FindFirstChild(_0xS(93))
        local ignoreList = {}
        if char then table.insert(ignoreList, char) end
        if wsCom then table.insert(ignoreList, wsCom) end
        local rayParams = RaycastParams.new()
        rayParams.FilterType = Enum.RaycastFilterType.Exclude
        rayParams.FilterDescendantsInstances = ignoreList
        local ray = ws:Raycast(Vector3.new(pos.X, pos.Y + 4.0, pos.Z), Vector3.new(0, -24.0, 0), rayParams)
        if ray and ray.Instance and ray.Instance.CanCollide then
            return Vector3.new(pos.X, ray.Position.Y, pos.Z)
        end
        local deepRay = ws:Raycast(Vector3.new(pos.X, pos.Y + 12.0, pos.Z), Vector3.new(0, -50.0, 0), rayParams)
        if deepRay and deepRay.Instance and deepRay.Instance.CanCollide then
            return Vector3.new(pos.X, deepRay.Position.Y, pos.Z)
        end
        return Vector3.new(pos.X, pos.Y, pos.Z)
    end
