        local forwardVec = hrp.CFrame.LookVector
        local flatFwd = Vector3.new(forwardVec.X, 0, forwardVec.Z).Unit
        local spawnPos = hrp.Position + flatFwd * 18.0
        local groundVec = getGroundPos(spawnPos)
        scorpionPos = groundVec
        scorpionYaw = math.atan2(-flatFwd.X, -flatFwd.Z)
        scorpionActive = true
        scorpionWorkers = {}
        scorpionSeat = nil
        local knownScf = {}
        for _, folder in pairs(wc:GetChildren()) do
            for _, prop in pairs(folder:GetChildren()) do
                if prop.Name == myPropName then
                    local scf = prop:FindFirstChild(_0xS(97))
                    if scf then knownScf[scf] = true end
                end
            end
        end
        for _, bp in ipairs(SCORPION_BLUEPRINT) do
            if not scorpionActive then break end
            local currentAnchorCF = CFrame.new(scorpionPos) * CFrame.Angles(0, scorpionYaw, 0)
            local initialCF = computeScorpionPartCFrame(bp.key, currentAnchorCF, 0, 0, 0, false, false)
            pcall(function()
                if bp.prop == "FloorCushion" then
                    clearTools:FireServer("RequestingPropFeatureName", bp.prop, bp.cat)
                else
                    clearTools:FireServer("RequestingPropName", bp.prop, bp.cat)
                end
            end)
            task.wait(0.18)
            pcall(function() toolPropMake:FireServer(ws.Terrain, scorpionPos) end)
            task.wait(0.65)
            local foundProp, foundScf, foundCpc = nil, nil, nil
            for _, folder in pairs(wc:GetChildren()) do
                for _, prop in pairs(folder:GetChildren()) do
                    if prop.Name == myPropName then
                        local scf = prop:FindFirstChild(_0xS(97))
                        local cpc = prop:FindFirstChild(_0xS(98))
                        if scf and not knownScf[scf] then
                            foundProp = prop
                            foundScf = scf
                            foundCpc = cpc
                            knownScf[scf] = true
                            break
                        end
                    end
                end
                if foundScf then break end
            end
            if foundProp and bp.key == "Saddle" then
                for _, d in ipairs(foundProp:GetDescendants()) do
                    if d:IsA("Seat") or d:IsA(_0xS(115)) then
                        pcall(function() d.CanCollide = false end)
                        scorpionSeat = d
                    elseif d:IsA("BasePart") then
                        pcall(function()
                            d.Transparency = 1
                            d.CanCollide = false
                        end)
                    end
                end
            end
            local worker = {
                key = bp.key,
                prop = foundProp,
                scf = foundScf,
                cpc = foundCpc,
                targetCF = initialCF,
                lastSentCF = nil,
                lastSendTimeCF = 0
            }
            scorpionWorkers[bp.key] = worker
            if foundScf then
                pcall(function() foundScf:InvokeServer(initialCF) end)
            end
            if bp.key ~= "Saddle" then
                local initialCol = getPartColorForTheme(currentTheme, bp.key)
                paintScorpionWorker(worker, initialCol)
            end
            startWorker(worker)
        end
        task.wait(1.0)
        applyTheme(currentTheme)
        pcall(function()
            toolRE:InvokeServer(_0xS(90), _0xS(89))
        end)
        pcall(function() clearTools:FireServer("ClosePropMenu") end)
        if scorpionLoop then scorpionLoop:Disconnect() scorpionLoop = nil end
        scorpionLoop = rs.Heartbeat:Connect(function(dt)
            if not scorpionActive then return end
            animTime = animTime + dt
            local myChar = lp.Character
            local myHum = myChar and myChar:FindFirstChildOfClass("Humanoid")
            isRiding = myHum and myHum.Sit and scorpionSeat and (myHum.SeatPart == scorpionSeat)
            local isMoving = false
            local isSprint = false
            if isRiding then
                local isFwd = uis:IsKeyDown(Enum.KeyCode.Z) or uis:IsKeyDown(Enum.KeyCode.W) or uis:IsKeyDown(Enum.KeyCode.Up)
                local isBwd = uis:IsKeyDown(Enum.KeyCode.S) or uis:IsKeyDown(Enum.KeyCode.Down)
                local isLeft = uis:IsKeyDown(Enum.KeyCode.Q) or uis:IsKeyDown(Enum.KeyCode.A) or uis:IsKeyDown(Enum.KeyCode.Left)
                local isRight = uis:IsKeyDown(Enum.KeyCode.D) or uis:IsKeyDown(Enum.KeyCode.Right)
                isSprint = uis:IsKeyDown(Enum.KeyCode.LeftShift) or uis:IsKeyDown(Enum.KeyCode.RightShift)
                if isLeft then
                    scorpionYaw = scorpionYaw + 2.8 * dt
                end
                if isRight then
                    scorpionYaw = scorpionYaw - 2.8 * dt
                end
                local targetSpeed = 0
                if isFwd then
                    targetSpeed = isSprint and 32 or 16
                elseif isBwd then
                    targetSpeed = -(isSprint and 18 or 10)
                end
                moveSpeed = moveSpeed + (targetSpeed - moveSpeed) * math.clamp(dt * 9, 0, 1)
                if math.abs(moveSpeed) > 0.4 then
                    isMoving = true
                    local lookDir = Vector3.new(-math.sin(scorpionYaw), 0, -math.cos(scorpionYaw))
                    local nextPos = scorpionPos + lookDir * (moveSpeed * dt)
                    local groundPos = getGroundPos(nextPos)
                    local diffY = groundPos.Y - scorpionPos.Y
                    local stepSpeed = diffY < 0 and 22 or 12
                    local smoothY = scorpionPos.Y + math.clamp(diffY * math.clamp(dt * stepSpeed, 0, 1), -30 * dt, 15 * dt)
                    scorpionPos = Vector3.new(nextPos.X, smoothY, nextPos.Z)
                    local strideRate = (isSprint and 10 or 6) * (moveSpeed > 0 and 1 or -1)
                    walkCycle = walkCycle + dt * strideRate
                else
                    local groundPos = getGroundPos(scorpionPos)
                    local diffY = groundPos.Y - scorpionPos.Y
                    local stepSpeed = diffY < 0 and 22 or 12
                    local smoothY = scorpionPos.Y + math.clamp(diffY * math.clamp(dt * stepSpeed, 0, 1), -30 * dt, 15 * dt)
                    scorpionPos = Vector3.new(scorpionPos.X, smoothY, scorpionPos.Z)
                end
                if uis:IsKeyDown(Enum.KeyCode.Space) or uis:IsKeyDown(Enum.KeyCode.F) then
                    triggerStingerStrike()
                end
            else
                local groundPos = getGroundPos(scorpionPos)
                local diffY = groundPos.Y - scorpionPos.Y
                local stepSpeed = diffY < 0 and 22 or 12
                local smoothY = scorpionPos.Y + math.clamp(diffY * math.clamp(dt * stepSpeed, 0, 1), -30 * dt, 15 * dt)
                scorpionPos = Vector3.new(scorpionPos.X, smoothY, scorpionPos.Z)
            end
            if isRainbowMode then
                rainbowHue = (rainbowHue + dt * 0.45) % 1
                for idx, bp in ipairs(SCORPION_BLUEPRINT) do
                    local w = scorpionWorkers[bp.key]
                    if w and w.prop and bp.key ~= "Saddle" then
                        local partHue = (rainbowHue + (idx / #SCORPION_BLUEPRINT)) % 1
                        local col = Color3.fromHSV(partHue, 0.95, 1)
                        for _, d in ipairs(w.prop:GetDescendants()) do
                            if d:IsA("BasePart") then
                                pcall(function() d.Color = col end)
                            end
                        end
                    end
                end
                if tick() - lastRainbowSync > 0.35 then
                    lastRainbowSync = tick()
                    rainbowIndex = (rainbowIndex % #RAINBOW_BRICKS) + 1
                    local brick = RAINBOW_BRICKS[rainbowIndex]
                    for _, w in pairs(scorpionWorkers) do
                        if w.cpc and w.key ~= "Saddle" then
                            pcall(function() w.cpc:InvokeServer(brick) end)
                        end
                    end
                end
            end
            local anchorCF = CFrame.new(scorpionPos) * CFrame.Angles(0, scorpionYaw, 0)
            for _, bp in ipairs(SCORPION_BLUEPRINT) do
                local w = scorpionWorkers[bp.key]
                if w and w.scf then
                    w.targetCF = computeScorpionPartCFrame(bp.key, anchorCF, animTime, strikeProgress, walkCycle, isSprint, isMoving)
                end
            end
        end)
        sNotif("Scorpion", "Titan Scorpion assembled! Ready to ride.", 3)
    end
    local function clearTitanScorpion()
        scorpionActive = false
