            scorpionLoop = nil
        end
        pcall(function()
            rep:WaitForChild(_0xS(83)):WaitForChild(_0xS(87)):FireServer(_0xS(95))
        end)
        sNotif("Scorpion", "Scorpion dismissed.", 2)
    end
