                            for _, p in ipairs(prop:GetDescendants()) do
                                if p:IsA("BasePart") then
                                    p.CanCollide = false
                                    p.CanTouch = false
                                    p.CanQuery = false
                                    p.Massless = true
                                end
                            end
                        end)
                    end
                end
            end
        end
        local chestScf = chestProp:FindFirstChild(_0xS(97)) or chestProp:FindFirstChild(_0xS(97), true) or chestProp:FindFirstChildWhichIsA("RemoteFunction", true)
        local chestCpc = chestProp:FindFirstChild(_0xS(98)) or chestProp:FindFirstChild(_0xS(98), true)
        if not chestScf then gNotif("Generator Titan", "Chest SetCurrentCFrame missing!", 3) return end
        pcall(function()
            for _, p in ipairs(chestProp:GetDescendants()) do
                if p:IsA("BasePart") then
                    p.CanCollide = false
                    p.CanTouch = false
                    p.CanQuery = false
                    p.Massless = true
                end
            end
        end)
        task.wait(0.3)
        smoothClimbTo(currentHipHeightVal, 2.0)
        setCharacterHidden(true)
        
        genPhysicsConn = rs.Stepped:Connect(function()
            if not genActive then return end
            local cc = lp.Character
            if cc then
                for _, part in ipairs(cc:GetDescendants()) do
                    if part:IsA("BasePart") and part.Name ~= _0xS(6) then
                        part.CanCollide = false
                        part.CanTouch = false
