    local function applyPlayerLift(newVal)
        local char = lp.Character
        if char then
            local hum = char:FindFirstChildOfClass("Humanoid")
            local hrp = char:FindFirstChild(_0xS(6))
            if hum and hrp then
                hum.HipHeight = newVal
                if newVal > 3.0 then
                    hrp.CFrame = hrp.CFrame + Vector3.new(0, 0.5, 0)
                end
            end
        end
    end
    local function smoothClimbTo(targetVal, step)
        step = step or 3.0
        task.spawn(function()
            local char = lp.Character
            local hum = char and char:FindFirstChildOfClass("Humanoid")
            local current = (hum and hum.HipHeight) or 2.0
            if current < targetVal then
                for v = current + step, targetVal, step do
                    if not apexActive then break end
                    applyPlayerLift(v)
                    task.wait(0.02)
                end
                if apexActive then applyPlayerLift(targetVal) end
            else
                for v = current - step, targetVal, -step do
                    applyPlayerLift(v)
                    task.wait(0.02)
                end
                applyPlayerLift(targetVal)
            end
        end)
    end
    local function setCharacterHidden(hide)
        local char = lp.Character
        if not char then return end
        for _, part in ipairs(char:GetDescendants()) do
            if part:IsA("BasePart") and part.Name ~= _0xS(6) then
                if hide then
                    if savedTransparencies[part] == nil then
                        savedTransparencies[part] = part.Transparency
                    end
                    part.Transparency = 1
                else
                    if savedTransparencies[part] ~= nil then
                        part.Transparency = savedTransparencies[part]
                    end
                end
            elseif part:IsA("Decal") then
                if hide then
                    if savedTransparencies[part] == nil then
                        savedTransparencies[part] = part.Transparency
                    end
                    part.Transparency = 1
                else
                    if savedTransparencies[part] ~= nil then
                        part.Transparency = savedTransparencies[part]
                    end
                end
            end
        end
        if not hide then savedTransparencies = {} end
    end
    local function getOrFetchPropMaker()
        local tool = lp.Character and lp.Character:FindFirstChild(_0xS(89))
        if not tool then
            tool = lp.Backpack:FindFirstChild(_0xS(89))
        end
        if not tool then
            local toolRE = rep:WaitForChild(_0xS(83)):WaitForChild(_0xS(88))
            pcall(function() toolRE:InvokeServer(_0xS(90), _0xS(89)) end)
            task.wait(0.3)
            tool = lp.Character and lp.Character:FindFirstChild(_0xS(89))
            if not tool then tool = lp.Backpack:FindFirstChild(_0xS(89)) end
        end
        return tool
    end
    local function duplicateExistingProp(firstProp, countNeeded)
        if not firstProp then return false end
        local dupRemote = firstProp:FindFirstChild(_0xS(92)) or firstProp:WaitForChild(_0xS(92), 2)
        if not dupRemote then return false end
        for i = 1, countNeeded do
            pcall(function() dupRemote:InvokeServer() end)
            task.wait(0.05)
        end
        return true
    end
    local senders = {}
    local RATE_LIMIT = 0.03
    local function sendCF(scf, cf, prop)
        if not apexActive or not scf then return end
        if prop then
            pcall(function()
                if prop:IsA("Model") then
                    prop:PivotTo(cf)
                elseif prop:IsA("BasePart") then
                    prop.CFrame = cf
                end
            end)
        end
        local entry = senders[scf]
        local now = tick()
        if not entry then
            entry = { lastSent = 0, nextCF = cf, sending = false }
            senders[scf] = entry
        else
            entry.nextCF = cf
        end
        if not entry.sending and (now - entry.lastSent >= RATE_LIMIT) then
            entry.sending = true
            entry.lastSent = now
            local toSend = entry.nextCF
            entry.nextCF = nil
            task.spawn(function()
                pcall(function() scf:InvokeServer(toSend) end)
                entry.sending = false
                if apexActive and entry.nextCF and (tick() - entry.lastSent >= RATE_LIMIT) then
                    entry.sending = true
                    entry.lastSent = tick()
                    local nextSend = entry.nextCF
                    entry.nextCF = nil
                    task.spawn(function()
                        pcall(function() scf:InvokeServer(nextSend) end)
                        entry.sending = false
                    end)
                end
            end)
        end
    end
    local function applyThemeToPart(prop, cpc, color)
        if prop then
            pcall(function()
                for _, p in ipairs(prop:GetDescendants()) do
                    if p:IsA("BasePart") then
                        p.Color = color
                    end
                end
            end)
        end
        if cpc then
            task.spawn(function()
                pcall(function() cpc:InvokeServer(color) end)
            end)
        end
    end
    local function applyApexTheme(themeName)
        apexColorTheme = themeName
        if not apexActive or #apexPartsList == 0 then return end
        if themeName == "Default" then
            for _, entry in ipairs(apexPartsList) do
                local col = (entry.name:find("Torso") or entry.name:find("Head"))
                    and Color3.fromRGB(140, 150, 165)
                    or Color3.fromRGB(180, 185, 195)
                applyThemeToPart(entry.prop, entry.cpc, col)
            end
            aNotif("Apex Titan", "Theme: Default Titanium", 2)
            return
        elseif themeName == "Rainbow" then
            aNotif("Apex Titan", "Theme: Rainbow Spectrum", 2)
            return
        elseif themeName == "Cyber Neon" then
            for i, entry in ipairs(apexPartsList) do
                local col = (i % 2 == 0) and Color3.fromRGB(0, 240, 255) or Color3.fromRGB(255, 20, 147)
                applyThemeToPart(entry.prop, entry.cpc, col)
            end
            aNotif("Apex Titan", "Theme: Cyber Neon", 2)
            return
        end
        local solidCol = APEX_THEMES[themeName] or Color3.fromRGB(150, 155, 165)
        for _, entry in ipairs(apexPartsList) do
            applyThemeToPart(entry.prop, entry.cpc, solidCol)
        end
        aNotif("Apex Titan", "Theme: " .. themeName, 2)
    end
    local function stopApexTitan()
        if not apexActive then return end
        apexActive = false
        if apexLoop then
            apexLoop:Disconnect()
            apexLoop = nil
        end
        currentApexOrigin = nil
        senders = {}
        apexPartsList = {}
        local char = lp.Character
        local hum = char and char:FindFirstChildOfClass("Humanoid")
        if hum then
            hum.WalkSpeed = savedWalkSpeed or 16
            if savedJumpPower then hum.JumpPower = savedJumpPower end
            if savedUseJumpPower ~= nil then hum.UseJumpPower = savedUseJumpPower end
            pcall(function() hum:SetStateEnabled(Enum.HumanoidStateType.Freefall, true) end)
            for _, track in ipairs(hum:GetPlayingAnimationTracks()) do
                if track.Priority == Enum.AnimationPriority.Action4 or track.Name:lower():find("run") then
                    pcall(function() track:Stop(0.1) end)
                end
            end
            pcall(function() hum:ChangeState(Enum.HumanoidStateType.Landed) end)
        end
