    local function spawnApexTitan()
        if apexActive then stopApexTitan() task.wait(0.5) end
        apexActive = true
        local char = lp.Character or lp.CharacterAdded:Wait()
        local hrp = char:WaitForChild(_0xS(6))
        local hum = char:WaitForChild(_0xS(94))
