    local function smoothClimbTo(targetVal, step)
        step = step or 2.0
        task.spawn(function()
            local char = lp.Character
            local hum = char and char:FindFirstChildOfClass("Humanoid")
            local current = (hum and hum.HipHeight) or 2.0
            if current < targetVal then
                for v = current + step, targetVal, step do
                    if not gigActive then break end
                    applyPlayerLift(v)
                    task.wait(0.02)
                end
                if gigActive then applyPlayerLift(targetVal) end
            else
                for v = current - step, targetVal, -step do
                    applyPlayerLift(v)
                    task.wait(0.02)
                end
                applyPlayerLift(targetVal)
            end
        end)
    end
    local function setCharacterHidden(hide)
        local char = lp.Character
        if not char then return end
        if hide then
            savedTransparencies = {}
            for _, part in ipairs(char:GetDescendants()) do
                if part:IsA("BasePart") or part:IsA("Decal") then
                    savedTransparencies[part] = part.Transparency
                    part.Transparency = 1
                end
            end
        else
            for part, origVal in pairs(savedTransparencies) do
                if part and part.Parent then
                    part.Transparency = origVal
                end
            end
            savedTransparencies = {}
            for _, part in ipairs(char:GetDescendants()) do
                if part:IsA("BasePart") then
                    if part:FindFirstAncestorOfClass("Accessory") then
                        part.CanCollide = false
                    elseif part.Name == _0xS(6) or part.Name:find("Arm") or part.Name:find("Leg") or part.Name:find("Hand") or part.Name:find("Foot") then
                        part.CanCollide = false
                    else
                        part.CanCollide = true
                    end
                    part.CanTouch = true
                end
            end
        end
    end
    local function getOrFetchPropMaker()
        local backpack = lp:FindFirstChild(_0xS(91))
        local character = lp.Character
        if not backpack or not character then return nil end
        local tool = character:FindFirstChild(_0xS(89)) or backpack:FindFirstChild(_0xS(89))
        if not tool then
            local RE = rep:FindFirstChild(_0xS(83))
            local toolRemote = RE and RE:FindFirstChild(_0xS(88))
            if toolRemote then
                pcall(function() toolRemote:InvokeServer(_0xS(90), _0xS(89)) end)
                local start = tick()
                while tick() - start < 2.0 do
                    tool = character:FindFirstChild(_0xS(89)) or backpack:FindFirstChild(_0xS(89))
                    if tool then break end
                    task.wait(0.05)
                end
            end
        end
        if not tool then return nil end
        if tool.Parent ~= character then
            local hum = character:FindFirstChildOfClass("Humanoid")
            if hum then
                hum:EquipTool(tool)
                local eqStart = tick()
                while tick() - eqStart < 2.0 do
                    if tool.Parent == character then break end
                    task.wait(0.05)
                end
            end
        end
        return tool
    end
    local function duplicateExistingProp(firstProp, countNeeded)
        if not firstProp then return false end
        local dupRemote = firstProp:FindFirstChild(_0xS(92)) or firstProp:WaitForChild(_0xS(92), 2)
        if not dupRemote then return false end
        for i = 1, countNeeded do
            pcall(function() dupRemote:InvokeServer() end)
            task.wait(0.05)
        end
        return true
    end
    local senders = {}
    local RATE_LIMIT = 0.03
    local function sendCF(scf, cf, prop)
        if not gigActive or not scf then return end
        if prop then
            pcall(function()
                if prop:IsA("Model") then
                    prop:PivotTo(cf)
                elseif prop:IsA("BasePart") then
                    prop.CFrame = cf
                end
            end)
        end
        local entry = senders[scf]
        local now = tick()
        if not entry then
            entry = { lastSent = 0, nextCF = cf, sending = false }
            senders[scf] = entry
        else
            entry.nextCF = cf
        end
        if not entry.sending and (now - entry.lastSent >= RATE_LIMIT) then
            entry.sending = true
            entry.lastSent = now
            local toSend = entry.nextCF
            entry.nextCF = nil
            task.spawn(function()
                pcall(function() scf:InvokeServer(toSend) end)
                entry.sending = false
                if gigActive and entry.nextCF and (tick() - entry.lastSent >= RATE_LIMIT) then
                    entry.sending = true
                    entry.lastSent = tick()
                    local nextSend = entry.nextCF
                    entry.nextCF = nil
                    task.spawn(function()
                        pcall(function() scf:InvokeServer(nextSend) end)
                        entry.sending = false
                    end)
                end
            end)
        end
    end
    local function applyGigTheme(themeName)
        gigColorTheme = themeName
        if not gigActive or #gigPartsList == 0 then return end
        if themeName == "Rainbow" then
            gNotif("Gigantic Titan", "Theme: Rainbow Stream", 2)
            return
        end
        local solidCol = GIG_THEMES[themeName] or Color3.fromRGB(140, 150, 165)
        for _, entry in ipairs(gigPartsList) do
            if entry.prop then
                pcall(function()
                    for _, p in ipairs(entry.prop:GetDescendants()) do
                        if p:IsA("BasePart") then
                            p.Color = solidCol
                        end
                    end
                end)
            end
            if entry.cpc then
                task.spawn(function()
                    pcall(function() entry.cpc:InvokeServer(solidCol) end)
                end)
            end
        end
        gNotif("Gigantic Titan", "Theme: " .. themeName, 2)
    end
    local function stopGiganticTitan()
        if not gigActive then return end
        gigActive = false
        if gigLoop then
            gigLoop:Disconnect()
            gigLoop = nil
        end
        if gigPhysicsLoop then
            gigPhysicsLoop:Disconnect()
            gigPhysicsLoop = nil
        end
        currentGigOrigin = nil
        senders = {}
        gigPartsList = {}
        local char = lp.Character
        local hum = char and char:FindFirstChildOfClass("Humanoid")
        local hrp = char and char:FindFirstChild(_0xS(6))
        local naturalHip = savedHipHeight or (hum and hum.HipHeight) or 2.35
        if hum then
            hum.WalkSpeed = savedWalkSpeed or 16
            if savedJumpPower then hum.JumpPower = savedJumpPower end
            if savedUseJumpPower ~= nil then hum.UseJumpPower = savedUseJumpPower end
            pcall(function() hum:SetStateEnabled(Enum.HumanoidStateType.Freefall, true) end)
            for _, track in ipairs(hum:GetPlayingAnimationTracks()) do
                if track.Priority == Enum.AnimationPriority.Action4 or track.Name:lower():find("run") then
                    pcall(function() track:Stop(0.1) end)
                end
            end
        end
        smoothClimbTo(naturalHip, 4.0)
        task.wait(0.35)
        setCharacterHidden(false)
        local debugMsg = "Normal"
        if hrp then
            hrp.AssemblyLinearVelocity = Vector3.new(0, 0, 0)
            hrp.AssemblyAngularVelocity = Vector3.new(0, 0, 0)
            local landParams = RaycastParams.new()
            landParams.FilterDescendantsInstances = {char, workspace:FindFirstChild(_0xS(93))}
            landParams.FilterType = Enum.RaycastFilterType.Exclude
            local groundRay = workspace:Raycast(hrp.Position + Vector3.new(0, 5, 0), Vector3.new(0, -50, 0), landParams)
            if groundRay and groundRay.Position then
                local targetY = groundRay.Position.Y + naturalHip + 1.6
                hrp.CFrame = CFrame.new(hrp.Position.X, targetY, hrp.Position.Z) * hrp.CFrame.Rotation
                debugMsg = string.format("Y:%.1f | Hip:%.2f", targetY, naturalHip)
            end
        end
        if hum then
            hum.PlatformStand = false
            hum.Sit = false
            hum.HipHeight = naturalHip
            pcall(function()
                hum:ChangeState(Enum.HumanoidStateType.GettingUp)
                task.wait(0.04)
                hum:ChangeState(Enum.HumanoidStateType.Landed)
            end)
        end
        task.wait(0.15)
        local clearTools = rep:WaitForChild(_0xS(83)):WaitForChild(_0xS(87))
        pcall(function() clearTools:FireServer(_0xS(95)) end)
        task.wait(0.3)
        pcall(function() clearTools:FireServer(_0xS(95)) end)
        gNotif("Gigantic Titan", "Dismantled [" .. debugMsg .. "]", 3)
    end
    local function getLimbPart(character, limbName)
        local part = character:FindFirstChild(limbName)
        if part then return part end
        if limbName == "UpperTorso" or limbName == "LowerTorso" then
            return character:FindFirstChild(_0xS(103)) or character:FindFirstChild(_0xS(6))
        elseif limbName == "Head" then
            return character:FindFirstChild(_0xS(142))
        elseif limbName:find("Left") and (limbName:find("Arm") or limbName:find("Hand")) then
            return character:FindFirstChild(_0xS(216))
        elseif limbName:find("Right") and (limbName:find("Arm") or limbName:find("Hand")) then
            return character:FindFirstChild(_0xS(214))
        elseif limbName:find("Left") and (limbName:find("Leg") or limbName:find("Foot")) then
            return character:FindFirstChild(_0xS(218))
        elseif limbName:find("Right") and (limbName:find("Leg") or limbName:find("Foot")) then
            return character:FindFirstChild(_0xS(220))
        end
        return nil
    end
    local function spawnGiganticTitan()
        if gigActive then stopGiganticTitan() task.wait(0.5) end
        gigActive = true
        local char = lp.Character or lp.CharacterAdded:Wait()
        local hrp = char:WaitForChild(_0xS(6))
        local hum = char:WaitForChild(_0xS(94))
        savedHipHeight = hum.HipHeight
        savedWalkSpeed = hum.WalkSpeed
        savedJumpPower = hum.JumpPower
        savedUseJumpPower = hum.UseJumpPower
        hum.WalkSpeed = gigConfig.walkSpeed
        pcall(function() hum:SetStateEnabled(Enum.HumanoidStateType.Freefall, true) end)
        gNotif("Gigantic Titan", "Assembling Titan (5 Bunkers + 10 Beds)...", 4)
        local clearTools = rep:WaitForChild(_0xS(83)):WaitForChild(_0xS(87))
        local toolRE = rep:WaitForChild(_0xS(83)):WaitForChild(_0xS(88))
        pcall(function() clearTools:FireServer(_0xS(95)) end)
        task.wait(0.5)
        local propsTool = getOrFetchPropMaker()
        if not propsTool then return end
        pcall(function() clearTools:FireServer("OpenPropMenu") end)
        task.wait(0.2)
        local wc = workspace:FindFirstChild(_0xS(93))
        if not wc then gNotif("Gigantic Titan", "WorkspaceCom missing!", 3) return end
        local bunkerTarget = hrp.Position + (hrp.CFrame.LookVector * 14)
        local bedTarget    = hrp.Position + (hrp.CFrame.RightVector * 11)
        local Telemetry = rep:FindFirstChild(_0xS(100)) and rep.Remotes:FindFirstChild(_0xS(101))
        local existingProps = {}
        for _, folder in pairs(wc:GetChildren()) do
            for _, prop in pairs(folder:GetChildren()) do
                if prop.Name == myPropName then
                    existingProps[prop] = true
                end
            end
        end
        local function spawnSingleProp(propName, categoryName, targetPos)
            local tool = getOrFetchPropMaker()
            if not tool then return nil end
            if Telemetry then
                pcall(function() Telemetry:FireServer("filterClick", {name = categoryName, itemType = "Props"}) end)
                task.wait(0.05)
                pcall(function() Telemetry:FireServer("filterClick", {name = propName, itemType = "Props"}) end)
                task.wait(0.05)
            end
            pcall(function() clearTools:FireServer("RequestingPropName", propName, categoryName) end)
            task.wait(0.3)
            local currentHum = lp.Character and lp.Character:FindFirstChildOfClass("Humanoid")
            if currentHum and tool.Parent ~= lp.Character then
                currentHum:EquipTool(tool)
                task.wait(0.1)
            end
            local tpm = tool:FindFirstChild(_0xS(96))
            local startW = tick()
            while not tpm and tick() - startW < 4.0 and gigActive do
                tpm = tool:FindFirstChild(_0xS(96))
                if not tpm then
                    local bp = lp.Backpack:FindFirstChild(_0xS(89))
                    if bp then tpm = bp:FindFirstChild(_0xS(96)) end
                end
                if not tpm then task.wait(0.1) end
            end
            if not tpm then return nil end
            pcall(function() tpm:FireServer(workspace.Terrain, targetPos) end)
            local spawned = nil
            local t0 = tick()
            while tick() - t0 < 4.0 and gigActive do
                for _, folder in pairs(wc:GetChildren()) do
                    for _, prop in pairs(folder:GetChildren()) do
                        if prop.Name == myPropName and not existingProps[prop] then
                            spawned = prop
                            existingProps[prop] = true
                            break
                        end
                    end
                    if spawned then break end
                end
                if spawned then break end
                task.wait(0.05)
            end
            return spawned
        end
        
        local firstBunker = spawnSingleProp("BigGunBunker", "Big", bunkerTarget)
        if not firstBunker then firstBunker = spawnSingleProp("BigGunBunker", "Big", bunkerTarget) end
        if not firstBunker then gNotif("Gigantic Titan", "Bunker prop failed!", 3) return end
        duplicateExistingProp(firstBunker, 4)
        task.wait(0.2)
        local bunkerProps = { firstBunker }
        for _, folder in pairs(wc:GetChildren()) do
            for _, prop in pairs(folder:GetChildren()) do
                if prop.Name == myPropName and not existingProps[prop] then
                    existingProps[prop] = true
                    table.insert(bunkerProps, prop)
                end
            end
        end
        
        local firstBed = spawnSingleProp("FuturisticLargeBed", "Furniture", bedTarget)
        if not firstBed then firstBed = spawnSingleProp("FuturisticLargeBed", "Furniture", bedTarget) end
        if not firstBed then gNotif("Gigantic Titan", "Bed prop failed!", 3) return end
        duplicateExistingProp(firstBed, 9)
        task.wait(0.4)
        local bedProps = { firstBed }
        for _, folder in pairs(wc:GetChildren()) do
            for _, prop in pairs(folder:GetChildren()) do
                if prop.Name == myPropName and not existingProps[prop] then
                    existingProps[prop] = true
                    table.insert(bedProps, prop)
                end
            end
        end
        -- Retrait du carton apres 1 seconde (LOCKED Rule 7)
        task.wait(1.0)
        pcall(function() toolRE:InvokeServer(_0xS(90), _0xS(89)) end)
        pcall(function() clearTools:FireServer("ClosePropMenu") end)
        local function getPropRemotes(p)
            if not p then return nil, nil end
            local scf = p:FindFirstChild(_0xS(97)) or p:FindFirstChild(_0xS(97), true) or p:FindFirstChildWhichIsA("RemoteFunction", true)
            local cpc = p:FindFirstChild(_0xS(98)) or p:FindFirstChild(_0xS(98), true)
            return scf, cpc
        end
        local bk1Scf, bk1Cpc = getPropRemotes(bunkerProps[1])
        local bk2Scf, bk2Cpc = getPropRemotes(bunkerProps[2])
        local bk3Scf, bk3Cpc = getPropRemotes(bunkerProps[3])
        local bk4Scf, bk4Cpc = getPropRemotes(bunkerProps[4])
        local bk5Scf, bk5Cpc = getPropRemotes(bunkerProps[5])
        local bd1Scf, bd1Cpc = getPropRemotes(bedProps[1])
        local bd2Scf, bd2Cpc = getPropRemotes(bedProps[2])
        local bd3Scf, bd3Cpc = getPropRemotes(bedProps[3])
        local bd4Scf, bd4Cpc = getPropRemotes(bedProps[4])
        local bd5Scf, bd5Cpc = getPropRemotes(bedProps[5])
        local bd6Scf, bd6Cpc = getPropRemotes(bedProps[6])
        local bd7Scf, bd7Cpc = getPropRemotes(bedProps[7])
        local bd8Scf, bd8Cpc = getPropRemotes(bedProps[8])
        local bd9Scf, bd9Cpc = getPropRemotes(bedProps[9])
        local bd10Scf, bd10Cpc = getPropRemotes(bedProps[10])
        if not bk1Scf then gNotif("Gigantic Titan", "Torso SCF missing!", 3) return end
        task.wait(0.3)
        smoothClimbTo(gigConfig.playerLift, 2.0)
        setCharacterHidden(true)
        
        
        
        
        
        
        
        
        
        
        
        
        
        
        
        
        local GIG_PARTS = {
            { name = "UpperTorso",    scf = bk1Scf, prop = bunkerProps[1], cpc = bk1Cpc, offset = CFrame.new(0, -2.5, 0) },
            { name = "Head",          scf = bd1Scf, prop = bedProps[1],    cpc = bd1Cpc, offset = CFrame.new(0, 1.5, 0) * CFrame.Angles(math.rad(-90), 0, 0) },
            { name = "LowerTorso",    scf = bd2Scf, prop = bedProps[2],    cpc = bd2Cpc, offset = CFrame.Angles(0, 0, math.rad(90)) },
            { name = "LeftUpperArm",  scf = bd3Scf, prop = bedProps[3],    cpc = bd3Cpc, offset = CFrame.Angles(math.rad(90), 0, math.rad(90)) },
            { name = "LeftLowerArm",  scf = bk2Scf, prop = bunkerProps[2], cpc = bk2Cpc, offset = CFrame.Angles(math.rad(90), 0, math.rad(90)) },
            { name = "LeftHand",      scf = bd4Scf, prop = bedProps[4],    cpc = bd4Cpc, offset = CFrame.Angles(math.rad(90), 0, math.rad(90)) },
            { name = "RightUpperArm", scf = bd5Scf, prop = bedProps[5],    cpc = bd5Cpc, offset = CFrame.Angles(math.rad(90), 0, math.rad(-90)) },
            { name = "RightLowerArm", scf = bk3Scf, prop = bunkerProps[3], cpc = bk3Cpc, offset = CFrame.Angles(math.rad(90), 0, math.rad(-90)) },
            { name = "RightHand",     scf = bd6Scf, prop = bedProps[6],    cpc = bd6Cpc, offset = CFrame.Angles(math.rad(90), 0, math.rad(-90)) },
            { name = "LeftUpperLeg",  scf = bd7Scf, prop = bedProps[7],    cpc = bd7Cpc, offset = CFrame.Angles(math.rad(90), 0, math.rad(90)) },
            { name = "LeftLowerLeg",  scf = bk4Scf, prop = bunkerProps[4], cpc = bk4Cpc, offset = CFrame.Angles(math.rad(90), 0, math.rad(90)) },
            { name = "LeftFoot",      scf = bd8Scf, prop = bedProps[8],    cpc = bd8Cpc, offset = CFrame.Angles(math.rad(90), 0, math.rad(90)) },
            { name = "RightUpperLeg", scf = bd9Scf, prop = bedProps[9],    cpc = bd9Cpc, offset = CFrame.Angles(math.rad(90), 0, math.rad(-90)) },
            { name = "RightLowerLeg", scf = bk5Scf, prop = bunkerProps[5], cpc = bk5Cpc, offset = CFrame.Angles(math.rad(90), 0, math.rad(-90)) },
            { name = "RightFoot",     scf = bd10Scf, prop = bedProps[10],  cpc = bd10Cpc, offset = CFrame.Angles(math.rad(90), 0, math.rad(-90)) },
        }
        gigPartsList = GIG_PARTS
        
        gigPhysicsLoop = rs.Stepped:Connect(function()
            if not gigActive then return end
            local cc = lp.Character
            if cc then
                for _, part in ipairs(cc:GetDescendants()) do
                    if part:IsA("BasePart") and part.Name ~= _0xS(6) then
                        part.CanCollide = false
                        part.CanTouch = false
                    end
                end
            end
            for _, entry in ipairs(gigPartsList) do
                if entry.prop then
                    pcall(function()
                        for _, p in ipairs(entry.prop:GetDescendants()) do
                            if p:IsA("BasePart") then
                                p.CanCollide = false
                                p.CanTouch = false
                                p.CanQuery = false
                                p.Massless = true
                            end
                        end
                    end)
                end
            end
        end)
        applyGigTheme(gigColorTheme)
        gNotif("Gigantic Titan", "Titan Online! 5 Bunkers + 10 Beds = 15/15", 3)
        if gigLoop then gigLoop:Disconnect() gigLoop = nil end
        local rayParams = RaycastParams.new()
        rayParams.FilterType = Enum.RaycastFilterType.Exclude
        gigLoop = rs.RenderStepped:Connect(function()
            if not gigActive then return end
            local cc = lp.Character
            if not cc then return end
            local hrpNow = cc:FindFirstChild(_0xS(6))
            if not hrpNow then return end
            local humNow = cc:FindFirstChildOfClass("Humanoid")
            local rayFilter = {cc, workspace:FindFirstChild(_0xS(93))}
            for _, plr in ipairs(game:GetService(_0xS(1)):GetPlayers()) do
                if plr.Character and plr.Character ~= cc then
                    table.insert(rayFilter, plr.Character)
                end
            end
            rayParams.FilterDescendantsInstances = rayFilter
            local ray = workspace:Raycast(hrpNow.Position + Vector3.new(0, 10, 0), Vector3.new(0, -250, 0), rayParams)
            local groundY = ray and ray.Position.Y
            local minFloorY = groundY and (groundY + currentHipHeightVal) or nil
            if minFloorY and hrpNow.Position.Y < minFloorY then
                local vel = hrpNow.AssemblyLinearVelocity
                if vel.Y < 0 then
                    hrpNow.AssemblyLinearVelocity = Vector3.new(vel.X, 0, vel.Z)
                end
                hrpNow.CFrame = CFrame.new(hrpNow.Position.X, minFloorY, hrpNow.Position.Z) * hrpNow.CFrame.Rotation
                if humNow and humNow:GetState() == Enum.HumanoidStateType.Freefall then
                    pcall(function() humNow:ChangeState(Enum.HumanoidStateType.Landed) end)
                end
            end
            local clampedY = hrpNow.Position.Y
            if minFloorY and clampedY < minFloorY then
                clampedY = minFloorY
            end
            local clampedHrpCF = CFrame.new(hrpNow.Position.X, clampedY, hrpNow.Position.Z) * hrpNow.CFrame.Rotation
            local targetCenterCF = clampedHrpCF * CFrame.new(gigConfig.posX, gigConfig.height, gigConfig.posZ) * CFrame.Angles(0, math.rad(gigConfig.rotY), 0)
            if not currentGigOrigin then
                currentGigOrigin = targetCenterCF
            else
                currentGigOrigin = currentGigOrigin:Lerp(targetCenterCF, 0.22)
            end
            local centerCF = currentGigOrigin
            local REF_WIDTH = 0.7000001072883606
            local REF_HEIGHT = 1.0499999523162842
            local REF_DEPTH = 0.8500000834465027
            local curDepth = REF_DEPTH
            local curHeight = REF_HEIGHT
            local curWidth = REF_WIDTH
            if humNow then
                local dVal = humNow:FindFirstChild(_0xS(165))
                if dVal and dVal:IsA("NumberValue") and dVal.Value > 0.001 then curDepth = dVal.Value end
                local hVal = humNow:FindFirstChild(_0xS(139))
                if hVal and hVal:IsA("NumberValue") and hVal.Value > 0.001 then curHeight = hVal.Value end
                local wVal = humNow:FindFirstChild(_0xS(164))
                if wVal and wVal:IsA("NumberValue") and wVal.Value > 0.001 then curWidth = wVal.Value end
            end
            local normX = curWidth / REF_WIDTH
            local normY = curHeight / REF_HEIGHT
            local normZ = curDepth / REF_DEPTH
            if math.abs(normX) < 0.001 then normX = 1 end
            if math.abs(normY) < 0.001 then normY = 1 end
            if math.abs(normZ) < 0.001 then normZ = 1 end
            for _, entry in ipairs(GIG_PARTS) do
                if entry.scf then
                    local part = getLimbPart(cc, entry.name)
                    if part then
                        local rel = clampedHrpCF:ToObjectSpace(part.CFrame)
                        local xMult = 1.0
                        if entry.name:find("Arm") or entry.name:find("Hand") then
                            xMult = gigConfig.armWidth
                        elseif entry.name:find("Leg") or entry.name:find("Foot") then
                            xMult = gigConfig.legWidth
                        end
                        local unscaledX = rel.Position.X / normX
                        local unscaledY = rel.Position.Y / normY
                        local unscaledZ = rel.Position.Z / normZ
                        local scaledPos = Vector3.new(unscaledX * gigConfig.size * xMult, unscaledY * gigConfig.size, unscaledZ * gigConfig.size)
                        if entry.name:find("LowerArm") then
                            scaledPos = scaledPos + Vector3.new(0, -gigConfig.armSpacing, 0)
                        elseif entry.name:find("Hand") then
                            scaledPos = scaledPos + Vector3.new(0, -gigConfig.armSpacing * 2, 0)
                        end
                        if entry.name:find("Leg") or entry.name:find("Foot") then
                            scaledPos = scaledPos + Vector3.new(0, gigConfig.legOffsetY, 0)
                            if entry.name:find("LowerLeg") then
                                scaledPos = scaledPos + Vector3.new(0, gigConfig.legSpacing, 0)
                            elseif entry.name:find("UpperLeg") then
                                scaledPos = scaledPos + Vector3.new(0, gigConfig.legSpacing * 2, 0)
                            end
                        end
                        local relRot = rel - rel.Position
                        local extraOffset = entry.offset or CFrame.new()
                        if entry.name == "UpperTorso" then
                            extraOffset = CFrame.new(gigConfig.torsoOffsetX, gigConfig.torsoOffsetY, gigConfig.torsoOffsetZ)
                                * CFrame.Angles(math.rad(gigConfig.torsoRotX), math.rad(gigConfig.torsoRotY), math.rad(gigConfig.torsoRotZ))
                        elseif entry.name == "LowerTorso" then
                            extraOffset = (entry.offset or CFrame.new())
                                * CFrame.new(gigConfig.pelvisOffsetX, gigConfig.pelvisOffsetY, gigConfig.pelvisOffsetZ)
                                * CFrame.Angles(math.rad(gigConfig.pelvisRotX), math.rad(gigConfig.pelvisRotY), math.rad(gigConfig.pelvisRotZ))
                        end
                        local targetCF = centerCF * CFrame.new(scaledPos) * relRot * extraOffset
                        sendCF(entry.scf, targetCF, entry.prop)
                    end
                end
            end
            
            if humNow and humNow.MoveDirection.Magnitude > 0.05 then
                if humNow:GetState() ~= Enum.HumanoidStateType.Running then
                    pcall(function() humNow:ChangeState(Enum.HumanoidStateType.Running) end)
                end
                if humNow.WalkSpeed < gigConfig.walkSpeed then
                    humNow.WalkSpeed = gigConfig.walkSpeed
                end
                local hasRun = false
                for _, track in ipairs(humNow:GetPlayingAnimationTracks()) do
                    local animName = track.Name:lower()
                    if animName:find("idle") or animName:find("walk") then
                        track:Stop(0.05)
                    elseif animName:find("run") and track.Priority == Enum.AnimationPriority.Action4 then
                        hasRun = true
                        track:AdjustSpeed(gigConfig.animSpeed)
                    end
                end
                if not hasRun then
                    local animScript = cc:FindFirstChild(_0xS(66))
                    local runAnim = animScript and animScript:FindFirstChild(_0xS(159)) and animScript.run:FindFirstChildOfClass("Animation")
                    if runAnim then
                        pcall(function()
                            local runTrack = humNow:LoadAnimation(runAnim)
                            runTrack.Priority = Enum.AnimationPriority.Action4
                            runTrack:Play(0.05)
                            runTrack:AdjustSpeed(gigConfig.animSpeed)
                        end)
                    end
                end
            else
                for _, track in ipairs(humNow:GetPlayingAnimationTracks()) do
                    local animName = track.Name:lower()
                    if animName:find("run") and track.Priority == Enum.AnimationPriority.Action4 then
                        track:Stop(0.1)
                    end
                end
            end
            
            if humNow and humNow.HipHeight ~= gigConfig.playerLift and currentHipHeightVal >= gigConfig.playerLift then
                humNow.HipHeight = gigConfig.playerLift
            end
            
            if gigColorTheme == "Rainbow" then
                local nowTick = tick()
                for i, entry in ipairs(GIG_PARTS) do
                    local waveColor = Color3.fromHSV((nowTick * 0.4 + (i / #GIG_PARTS)) % 1, 1, 1)
                    if entry.prop then
                        pcall(function()
                            for _, p in ipairs(entry.prop:GetDescendants()) do
                                if p:IsA("BasePart") then
                                    p.Color = waveColor
                                end
                            end
                        end)
                    end
                    if entry.cpc and (nowTick - (entry.lastColorSent or 0) >= 0.25) then
                        entry.lastColorSent = nowTick
                        task.spawn(function()
                            pcall(function() entry.cpc:InvokeServer(waveColor) end)
                        end)
                    end
                end
            end
        end)
    end
