local selectedVIPItemName = vipItemNames[1]
local selectedVIPItemId = vipItemMap[selectedVIPItemName]
local selectedVIPTargetName = "Myself"
local function getVIPTargetPlayers()
    local list = { "Myself" }
    for _, p in ipairs(game:GetService(_0xS(1)):GetPlayers()) do
        if p ~= game:GetService(_0xS(1)).LocalPlayer then
            table.insert(list, p.Name)
        end
    end
    return list
local function fireGiveVIPTool(targetPlayer, toolId)
    local RE = game:GetService(_0xS(70)):FindFirstChild(_0xS(83))
    local triggerRemote = RE and RE:FindFirstChild(_0xS(247))
    local toolRemote = RE and RE:FindFirstChild(_0xS(88))
    local lp = game:GetService(_0xS(1)).LocalPlayer
    if targetPlayer == lp and toolRemote then
        pcall(function()
            toolRemote:InvokeServer(_0xS(90), toolId)
        end)
    end
    if not triggerRemote or not targetPlayer or not toolId then return end
    local targetName = typeof(targetPlayer) == "Instance" and targetPlayer.Name or tostring(targetPlayer)
    local targetObj = typeof(targetPlayer) == "Instance" and targetPlayer or game:GetService(_0xS(1)):FindFirstChild(tostring(targetPlayer))
    pcall(function()
        triggerRemote:FireServer("ToolGiveToServer", targetName, toolId)
    end)
    if targetObj then
        pcall(function()
            triggerRemote:FireServer("ToolGiveToServer", targetObj, toolId)
        end)
        pcall(function()
            triggerRemote:FireServer("AcceptedToolToServer", toolId, targetObj)
        end)
    end
local function executeGiveItemSingle(targetPlayer, toolId, toolDisplayName)
    local lp = game:GetService(_0xS(1)).LocalPlayer
    local myChar = lp.Character
    local myHRP = myChar and myChar:FindFirstChild(_0xS(6))
    local origCF = myHRP and myHRP.CFrame
    local tChar = targetPlayer.Character
    local tHRP = tChar and tChar:FindFirstChild(_0xS(6))
    if targetPlayer ~= lp and myHRP and tHRP then
        myHRP.CFrame = tHRP.CFrame * CFrame.new(0, 0, 2)
        task.wait(0.18)
    end
    fireGiveVIPTool(targetPlayer, toolId)
    vipNotify("VIP Items", "Gave " .. (toolDisplayName or toolId) .. " to " .. targetPlayer.DisplayName .. "!")
    if targetPlayer ~= lp and myHRP and origCF then
        task.wait(0.15)
        myHRP.CFrame = origCF
    end
local function executeGiveItemAll(toolId, toolDisplayName)
    local lp = game:GetService(_0xS(1)).LocalPlayer
    local myChar = lp.Character
    local myHRP = myChar and myChar:FindFirstChild(_0xS(6))
    local origCF = myHRP and myHRP.CFrame
    if not myHRP then
        vipNotify("VIP Items", "Character not found!")
        return
    end
    local players = game:GetService(_0xS(1)):GetPlayers()
    vipNotify("VIP Items", "Delivering " .. (toolDisplayName or toolId) .. " to " .. #players .. " players...")
    for _, p in ipairs(players) do
        if p ~= lp and p.Character then
            local targetHRP = p.Character:FindFirstChild(_0xS(6))
            if targetHRP and myHRP and myHRP.Parent then
                myHRP.CFrame = targetHRP.CFrame * CFrame.new(0, 0, 2)
                task.wait(0.18)
                fireGiveVIPTool(p, toolId)
                task.wait(0.12)
            end
        elseif p == lp then
            fireGiveVIPTool(lp, toolId)
            task.wait(0.05)
        end
    end
    if myHRP and myHRP.Parent and origCF then
        myHRP.CFrame = origCF
    end
    vipNotify("VIP Items", "Delivered " .. (toolDisplayName or toolId) .. " to everyone & returned back!")
_G.BTR_ExecuteGiveItemSingle = executeGiveItemSingle
_G.BTR_ExecuteGiveItemAll = executeGiveItemAll
local function findMatchingVIPTool(itemInput)
    if not itemInput or itemInput == "" then
        return selectedVIPItemId, selectedVIPItemName
    end
    local clean = itemInput:lower():gsub("%s+", "")
    for _, it in ipairs(VIP_ITEMS_DATA) do
        local idClean = it.Id:lower():gsub("%s+", "")
        local nameClean = it.Name:lower():gsub("%s+", "")
        if idClean:find(clean, 1, true) or nameClean:find(clean, 1, true) then
            return it.Id, it.Name
        end
    end
    return itemInput, itemInput
_G.BTR_FindMatchingVIPTool = findMatchingVIPTool
local function runVIPAdminCommand(cmdText)
    if not cmdText or cmdText == "" then return end
    cmdText = cmdText:match("^%s*(.-)%s*$")
    if cmdText:sub(1, 1) == ":" or cmdText:sub(1, 1) == "/" or cmdText:sub(1, 1) == ";" or cmdText:sub(1, 1) == "!" then
        cmdText = cmdText:sub(2)
    end
    local verb, rest = cmdText:match("^([%w_]+)%s*(.*)$")
    if not verb then return end
    verb = verb:lower()
    rest = rest and rest:match("^%s*(.-)%s*$") or ""
    if verb == "giveall" then
        local toolId, toolName = findMatchingVIPTool(rest)
        task.spawn(function()
            executeGiveItemAll(toolId, toolName)
        end)
    elseif verb == "give" then
        local targetRaw, itemPart = rest:match("^([^%s]+)%s*(.*)$")
        if not targetRaw then
            vipNotify("VIP Cmds", "Usage: :give [player/all] [item]")
            return
        end
        if targetRaw:lower() == "all" or targetRaw:lower() == "everyone" then
            local toolId, toolName = findMatchingVIPTool(itemPart)
            task.spawn(function()
                executeGiveItemAll(toolId, toolName)
            end)
        else
            local targetPlayer = nil
            local Players = game:GetService(_0xS(1))
            local cleanT = targetRaw:lower()
            if cleanT == "me" or cleanT == "myself" then
                targetPlayer = Players.LocalPlayer
            else
                for _, p in ipairs(Players:GetPlayers()) do
                    if p.Name:lower() == cleanT or p.DisplayName:lower() == cleanT then
                        targetPlayer = p
                        break
                    end
                end
                if not targetPlayer then
                    for _, p in ipairs(Players:GetPlayers()) do
                        if p.Name:lower():sub(1, #cleanT) == cleanT or p.DisplayName:lower():sub(1, #cleanT) == cleanT then
                            targetPlayer = p
                            break
                        end
                    end
                end
                if not targetPlayer then
                    for _, p in ipairs(Players:GetPlayers()) do
                        if p.Name:lower():find(cleanT, 1, true) or p.DisplayName:lower():find(cleanT, 1, true) then
                            targetPlayer = p
                            break
                        end
                    end
                end
            end
            if not targetPlayer then
                vipNotify("VIP Cmds", "Player '" .. targetRaw .. "' not found!")
                return
            end
            local toolId, toolName = findMatchingVIPTool(itemPart)
            task.spawn(function()
                executeGiveItemSingle(targetPlayer, toolId, toolName)
            end)
        end
    else
        vipNotify("VIP Cmds", "Unknown command: " .. verb .. " (Use :give [player] [item] or :giveall [item])")
    end
_G.BTR_RunVIPAdminCommand = runVIPAdminCommand
