        local backpack = player:WaitForChild(_0xS(91), 5)
        local assault
        for _ = 1, 20 do
            assault = backpack:FindFirstChild(_0xS(250))
            if assault then break end
            task.wait(0.15)
        end
        if assault and player.Character then
            assault.Parent = player.Character
            task.wait(0.3)
        end
    end)
