-- [LOCKED: WORK PERFECTLY] Car Dislocator System (FE Wheel Tear)
_G.BTR_CarDislocator = {}
    local function enableSimulationRadius()
        pcall(function()
            local lp = game:GetService(_0xS(1)).LocalPlayer
            lp.ReplicationFocus = workspace
            if setscriptable then
                setscriptable(lp, "SimulationRadius", true)
                setscriptable(lp, "MaximumSimulationRadius", true)
            end
            if sethiddenproperty then
                sethiddenproperty(lp, "MaximumSimulationRadius", 1e9)
                sethiddenproperty(lp, "SimulationRadius", 1e9)
            end
        end)
    end
    function _G.BTR_CarDislocator.getNearbyVehicles(radius)
        local lp = game:GetService(_0xS(1)).LocalPlayer
        local char = lp and lp.Character
        local root = char and char:FindFirstChild(_0xS(6))
        if not root then return {} end
        local myPos = root.Position
        local found = {}
        local seenModels = {}
        local function checkModel(model)
            if not model or not model:IsA("Model") or seenModels[model] then return end
            if char and model:IsDescendantOf(char) then return end
            local seat = model:FindFirstChildWhichIsA(_0xS(115), true)
            if not seat then return end
            local primary = model.PrimaryPart or (seat and seat.Parent and seat.Parent:FindFirstChildWhichIsA("BasePart")) or seat
            if not primary then return end
            local dist = (primary.Position - myPos).Magnitude
            if not radius or dist <= radius then
                seenModels[model] = true
                table.insert(found, {
                    Model = model,
                    Seat = seat,
                    Primary = primary,
                    Distance = dist
                })
            end
        end
        local vehiclesFolder = workspace:FindFirstChild(_0xS(111))
        if vehiclesFolder then
            for _, veh in ipairs(vehiclesFolder:GetChildren()) do
                checkModel(veh)
            end
        end
        for _, obj in ipairs(workspace:GetChildren()) do
            if obj:IsA("Model") and obj ~= char then
                checkModel(obj)
            end
        end
        local wc = workspace:FindFirstChild(_0xS(93))
        local helis = wc and wc:FindFirstChild(_0xS(119))
        if helis then
            for _, h in ipairs(helis:GetChildren()) do
                checkModel(h)
            end
        end
        table.sort(found, function(a, b) return a.Distance < b.Distance end)
        return found
    end
    function _G.BTR_CarDislocator.dislocate(target, returnCF)
        local lp = game:GetService(_0xS(1)).LocalPlayer
        local char = lp and lp.Character or lp.CharacterAdded:Wait()
        local hum = char and char:FindFirstChildOfClass("Humanoid")
        local root = char and char:FindFirstChild(_0xS(6))
        if not char or not hum or not root then return false end
        local model = target.Model or target.model or target
        local seat = target.Seat or target.seat or (model and model:FindFirstChildWhichIsA(_0xS(115), true))
        local primary = target.Primary or target.primary or (model and model.PrimaryPart) or seat
        if not seat or not seat.Parent or not model or not model.Parent or not primary then return false end
        if seat.Occupant and seat.Occupant ~= hum then return false end
        enableSimulationRadius()
        local origCF = returnCF or root.CFrame
        pcall(function()
            seat.Disabled = false
            seat.HandBrake = false
        end)
        if firetouchinterest then
            pcall(function() firetouchinterest(root, seat, 0) end)
        end
        pcall(function() seat:Sit(hum) end)
        pcall(function() hum:ChangeState(Enum.HumanoidStateType.Seated) end)
        local sitStart = tick()
        while not hum.Sit and (tick() - sitStart < 0.7) do
            root.CFrame = seat.CFrame * CFrame.new(0, 0.9, 0)
            root.AssemblyLinearVelocity = Vector3.zero
            pcall(function()
                hum:ChangeState(Enum.HumanoidStateType.Seated)
                seat:Sit(hum)
            end)
            task.wait(0.03)
        end
        if firetouchinterest then
            pcall(function() firetouchinterest(root, seat, 1) end)
        end
        task.wait(0.08)
        pcall(function()
            seat.HandBrake = false
        end)
        pcall(function()
            local wheelParts = {}
            for _, constraint in ipairs(model:GetDescendants()) do
                if constraint:IsA("Constraint") then
                    if constraint.Attachment0 and constraint.Attachment0.Parent and constraint.Attachment0.Parent:IsA("BasePart") then
                        local p = constraint.Attachment0.Parent
                        if p ~= primary and p ~= seat and not p:IsDescendantOf(char) then
                            wheelParts[p] = true
                        end
                    end
                    if constraint.Attachment1 and constraint.Attachment1.Parent and constraint.Attachment1.Parent:IsA("BasePart") then
                        local p = constraint.Attachment1.Parent
                        if p ~= primary and p ~= seat and not p:IsDescendantOf(char) then
                            wheelParts[p] = true
                        end
                    end
                end
            end
            for _, p in ipairs(model:GetDescendants()) do
                if p:IsA("BasePart") and p ~= primary and p ~= seat and not p:IsDescendantOf(char) then
                    local n = p.Name:lower()
                    if n:find("wheel") or n:find("tire") or n:find("rim") or n:find("roue") or n:find("fl") or n:find("fr") or n:find("rl") or n:find("rr") then
                        wheelParts[p] = true
                    end
                end
            end
            primary.Anchored = true
            seat.Anchored = true
            primary.AssemblyLinearVelocity = Vector3.zero
            primary.AssemblyAngularVelocity = Vector3.zero
            for _, constraint in ipairs(model:GetDescendants()) do
                if constraint:IsA("SpringConstraint") then
                    pcall(function()
                        constraint.Stiffness = 0
                        constraint.Damping = 0
                        constraint.FreeLength = 12
                        constraint.MaxLength = 50
                    end)
                elseif constraint:IsA("CylindricalConstraint") or constraint:IsA("PrismaticConstraint") or constraint:IsA("HingeConstraint") then
                    pcall(function()
                        if constraint.LimitsEnabled ~= nil then constraint.LimitsEnabled = false end
                        if constraint.UpperLimit ~= nil then constraint.UpperLimit = 50 end
                        if constraint.LowerLimit ~= nil then constraint.LowerLimit = -50 end
                    end)
                end
            end
            local chassisCF = primary.CFrame
            for step = 1, 3 do
                for wheel, _ in pairs(wheelParts) do
                    if wheel and wheel.Parent then
                        local relPos = chassisCF:PointToObjectSpace(wheel.Position)
                        local isRight = (relPos.X >= 0)
                        local sideSign = isRight and 1 or -1
                        local sideDir = chassisCF.RightVector * sideSign
                        local targetPos = wheel.Position + (sideDir * 4.5) - Vector3.new(0, 1.2, 0)
                        wheel.CFrame = CFrame.new(targetPos, targetPos + chassisCF.LookVector) * CFrame.Angles(math.rad(90), 0, 0)
                        wheel.AssemblyLinearVelocity = (sideDir * 6) + Vector3.new(0, -8, 0)
                        wheel.AssemblyAngularVelocity = Vector3.new(0, 2, 0)
                    end
                end
                task.wait(0.04)
            end
            task.wait(0.1)
            primary.Anchored = false
            seat.Anchored = false
            primary.AssemblyLinearVelocity = Vector3.new(0, -10, 0)
            primary.AssemblyAngularVelocity = Vector3.zero
            task.wait(0.08)
        end)
        hum.Sit = false
        task.wait(0.04)
        if root and root.Parent and origCF then
            root.CFrame = origCF
            root.AssemblyLinearVelocity = Vector3.zero
            root.AssemblyAngularVelocity = Vector3.zero
        end
        return true
    end
