    local Players = game:GetService(_0xS(1))
    local RunService = game:GetService(_0xS(15))
    local LocalPlayer = Players.LocalPlayer
    local Workspace = game:GetService(_0xS(117))
    local StarterGui = game:GetService(_0xS(5))
    _G.VehicleFlingActive = false
    _G.VehicleFlingCar = nil
    local function isOurFlingVehicle(item)
        
        if (_G.VehicleFlingActive or _G.TornadoLock) and item.Name == LocalPlayer.Name .. "Car" then
            return true
        end
        
        if LocalPlayer.Character then
            for _, seat in ipairs(item:GetDescendants()) do
                if (seat:IsA(_0xS(115)) or seat:IsA("Seat")) and seat.Occupant and seat.Occupant.Parent == LocalPlayer.Character then
                    return true
                end
            end
        end
        return false
    end
    do
        local antiSitConnections = {}
        local disabledSeats = {}
        local isAntiSitActive = false
        local function disableSingleSeat(seat)
            if seat and (seat:IsA("Seat") or seat:IsA(_0xS(115))) then
                disabledSeats[seat] = true
                pcall(function()
                    seat.Disabled = true
                    seat.CanTouch = false
                end)
            end
        end
        local function restoreAllSeats()
            for seat in pairs(disabledSeats) do
                if seat and seat.Parent then
                    pcall(function()
                        seat.Disabled = false
                        seat.CanTouch = true
                    end)
                end
            end
            disabledSeats = {}
        end
        local function resetSitting()
            local player = game.Players.LocalPlayer
            for _, connection in ipairs(antiSitConnections) do
                if connection and connection.Connected then
                    connection:Disconnect()
                end
            end
            antiSitConnections = {}
            restoreAllSeats()
            local humanoid = player.Character and player.Character:FindFirstChildOfClass("Humanoid")
            if humanoid then
                humanoid:SetStateEnabled(Enum.HumanoidStateType.Seated, true)
            end
            isAntiSitActive = false
        end
        local function activateAntiSit()
            local player = game.Players.LocalPlayer
            resetSitting()
            isAntiSitActive = true
            
            local vFolder = workspace:FindFirstChild(_0xS(111))
            if vFolder then
                for _, car in ipairs(vFolder:GetChildren()) do
                    for _, s in ipairs(car:GetDescendants()) do
                        disableSingleSeat(s)
                    end
                end
                local vAddedConn = vFolder.DescendantAdded:Connect(function(inst)
                    if _G.AntiSitValue and not _G.VehicleFlingActive and not _G.CanoeSpamActive then
                        disableSingleSeat(inst)
                    end
                end)
                table.insert(antiSitConnections, vAddedConn)
            end
            local function preventSitting(humanoid, character)
                if humanoid then
                    humanoid:SetStateEnabled(Enum.HumanoidStateType.Seated, false)
                    local sitConnection = humanoid.StateChanged:Connect(function(_, newState)
                        if newState == Enum.HumanoidStateType.Seated and _G.AntiSitValue and not _G.VehicleFlingActive and not _G.CanoeSpamActive then
                            humanoid.Sit = false
                            humanoid.PlatformStand = false
                            humanoid:ChangeState(Enum.HumanoidStateType.Running)
                        end
                    end)
                    table.insert(antiSitConnections, sitConnection)
                end
            end
            local function onCharacterAdded(character)
                local humanoid = character:WaitForChild(_0xS(94))
                preventSitting(humanoid, character)
            end
            local characterAddedConnection = player.CharacterAdded:Connect(onCharacterAdded)
            table.insert(antiSitConnections, characterAddedConnection)
            if player.Character then
                onCharacterAdded(player.Character)
            end
            local heartbeatConnection = RunService.Heartbeat:Connect(function()
                local charObj = player.Character
                local humanoid = charObj and charObj:FindFirstChildOfClass("Humanoid")
                if humanoid then
                    if _G.AntiSitValue and not _G.VehicleFlingActive and not _G.CanoeSpamActive then
                        humanoid:SetStateEnabled(Enum.HumanoidStateType.Seated, false)
                        if humanoid.Sit or humanoid.SeatPart then
                            local sp = humanoid.SeatPart
                            if sp then
                                disableSingleSeat(sp)
                            end
                            humanoid.Sit = false
                            humanoid.PlatformStand = false
                            humanoid:ChangeState(Enum.HumanoidStateType.Running)
                        end
                    elseif _G.VehicleFlingActive or _G.CanoeSpamActive then
                        humanoid:SetStateEnabled(Enum.HumanoidStateType.Seated, true)
                    end
                end
            end)
            table.insert(antiSitConnections, heartbeatConnection)
        end
        local function setAntiSitCallback(Value)
            _G.AntiSitValue = Value
            if Value then
                activateAntiSit()
            else
                resetSitting()
            end
        end
        _G.BTR_PROT_CALLBACKS.AntiSit = setAntiSitCallback
        _G.AntiSitToggle = ProtectionTab:AddToggle({
            Name = "منع الجلوس",
            Description = "No sitting (auto-paused during your own Vehicle Fling)",
            Default = (_G.BTR_AUTORUN and _G.BTR_AUTORUN.AntiSit ~= false),
            Callback = function(Value)
                _G.setBTRProtection("AntiSit", Value, "ProtectionTab")
            end
        })
        _G.BTR_PROT_TOGGLES.AntiSit = _G.AntiSitToggle
        _G.AntiSitValue = (_G.BTR_AUTORUN and _G.BTR_AUTORUN.AntiSit ~= false)
        -- [LOCKED Keito] Force OFF/ON de l'anti-sit SANS passer par Toggle:Set()
        
        
        _G.AntiSitForceOff = function()
            _G.AntiSitValue = false
            resetSitting()  
            
            if _G.AntiSitToggle then
                pcall(function() _G.AntiSitToggle:Set(false) end)
            end
        end
        _G.AntiSitForceOn = function()
            _G.AntiSitValue = true
            activateAntiSit()
            
            if _G.AntiSitToggle then
                pcall(function() _G.AntiSitToggle:Set(true) end)
            end
        end
    end
    local antiFlingStates = {
        Vehicles = false,
        Canoes = false,
        Jets = false,
        Helis = false,
        Balls = false,
        Doors = false
    local function destroyForeignIn(folder)
        if not folder then return end
        local lpName = LocalPlayer and LocalPlayer.Name or ""
        for _, item in ipairs(folder:GetChildren()) do
            
            if isOurFlingVehicle(item) then continue end
            if item.Name == ("Soccer" .. lpName) then continue end
            if item.Name:find(lpName) then continue end
            if _G.CanoeSpamActive and (item.Name == "Canoe" or item.Name:find("Canoe")) then continue end
            local occupiedByUs = false
            if LocalPlayer.Character then
                for _, seat in ipairs(item:GetDescendants()) do
                    if (seat:IsA(_0xS(115)) or seat:IsA("Seat")) and seat.Occupant and seat.Occupant.Parent == LocalPlayer.Character then
                        occupiedByUs = true
                        break
                    end
                end
            end
            if not occupiedByUs then
                pcall(function()
                    if item:IsA("BasePart") then
                        item.CanCollide = false
                        item.AssemblyLinearVelocity = Vector3.new(0, 0, 0)
                        item.AssemblyAngularVelocity = Vector3.new(0, 0, 0)
                    end
                    for _, p in ipairs(item:GetDescendants()) do
                        if p:IsA("BasePart") then
                            p.CanCollide = false
                            p.AssemblyLinearVelocity = Vector3.new(0, 0, 0)
                        end
                    end
                    item:Destroy()
                end)
            end
        end
    end
    local function hideDoors()
        for _, v in ipairs(Workspace:GetDescendants()) do
            if v:IsA("BasePart") and v.Name:lower():find("door") then
                v.Transparency = 1
                v.CanCollide = false
            end
        end
    end
    local lastVehFlingCheck = 0
    local vehSteppedConn = RunService.Stepped:Connect(function()
        if not antiFlingStates.Vehicles then return end
        local now = tick()
        if now - lastVehFlingCheck < 0.1 then return end
        lastVehFlingCheck = now
        pcall(function()
            local vehicles = Workspace:FindFirstChild(_0xS(111))
            if not vehicles then return end
            for _, item in ipairs(vehicles:GetChildren()) do
                if not isOurFlingVehicle(item) then
                    local root = item.PrimaryPart or item:FindFirstChildWhichIsA("BasePart")
                    if root and (root.AssemblyLinearVelocity.Magnitude > 80 or root.Velocity.Magnitude > 80) then
                        for _, veh in ipairs(item:GetDescendants()) do
                            if veh:IsA("BasePart") then
                                veh.CanCollide = false
                                veh.AssemblyLinearVelocity = Vector3.zero
                                veh.AssemblyAngularVelocity = Vector3.zero
                                veh.Velocity = Vector3.zero
                                veh.RotVelocity = Vector3.zero
                            end
                        end
                    end
                end
            end
        end)
    end)
    table.insert(_G.BTR_CONNECTIONS, vehSteppedConn)
    local function antiFlingTick()
        local anyActive = antiFlingStates.Canoes or antiFlingStates.Jets
            or antiFlingStates.Helis or antiFlingStates.Balls
        if not anyActive then return end
        if antiFlingStates.Canoes and not _G.CanoeSpamActive then
            local wc = Workspace:FindFirstChild(_0xS(93))
            local canoes = wc and wc:FindFirstChild(_0xS(266))
            if canoes then destroyForeignIn(canoes) end
        end
        if antiFlingStates.Jets then
            local wc = Workspace:FindFirstChild(_0xS(93))
            local airport = wc and wc:FindFirstChild(_0xS(268))
            local hangar = airport and airport:FindFirstChild(_0xS(269))
            local jetStorage = hangar and hangar:FindFirstChild(_0xS(270))
            local jets = jetStorage and jetStorage:FindFirstChild(_0xS(271))
            if jets then destroyForeignIn(jets) end
        end
        if antiFlingStates.Helis then
            local wc = Workspace:FindFirstChild(_0xS(93))
            local helis = wc and wc:FindFirstChild(_0xS(119))
            local heli = helis and helis:FindFirstChild(_0xS(272))
            if heli then destroyForeignIn(heli) end
        end
        if antiFlingStates.Balls then
            local wc = Workspace:FindFirstChild(_0xS(93))
            local balls = wc and wc:FindFirstChild(_0xS(124))
            if balls then destroyForeignIn(balls) end
        end
    end
    task.spawn(function()
        local currentSession = _G.BTR_SESSION_ID
        local wc = Workspace:WaitForChild(_0xS(93), 10)
        local ballsFolder = wc and (wc:FindFirstChild(_0xS(124)) or wc:WaitForChild(_0xS(124), 5))
        if ballsFolder then
            local ballConn = ballsFolder.ChildAdded:Connect(function(child)
                if antiFlingStates.Balls then
                    local lpName = LocalPlayer and LocalPlayer.Name or ""
                    if child.Name ~= ("Soccer" .. lpName) and not child.Name:find(lpName) then
                        pcall(function()
                            if child:IsA("BasePart") then
                                child.CanCollide = false
                                child.AssemblyLinearVelocity = Vector3.new(0, 0, 0)
                            end
                            for _, p in ipairs(child:GetDescendants()) do
                                if p:IsA("BasePart") then p.CanCollide = false end
                            end
                            child:Destroy()
                        end)
                    end
                end
            end)
            table.insert(_G.BTR_CONNECTIONS, ballConn)
        end
        while currentSession == _G.BTR_SESSION_ID do
            antiFlingTick()
            task.wait(0.25)
        end
    end)
