    local _antiDumpRunning = false
    local function setAntiDump(state)
        _antiDumpRunning = state
        if state then
            task.spawn(function()
                while _antiDumpRunning do
                    for _, plr in ipairs(Players:GetPlayers()) do
                        if plr ~= LocalPlayer then
                            local char = plr.Character
                            local backpack = plr:FindFirstChildOfClass("Backpack")
                            if char then
                                for _, tool in ipairs(char:GetChildren()) do
                                    if tool:IsA("Tool") and tool.Name:lower():find("dump") then
                                        pcall(function() tool:Destroy() end)
                                    end
                                end
                            end
                            if backpack then
                                for _, tool in ipairs(backpack:GetChildren()) do
                                    if tool:IsA("Tool") and tool.Name:lower():find("dump") then
                                        pcall(function() tool:Destroy() end)
                                    end
                                end
                            end
                        end
                    end
                    task.wait(0.1)
                end
            end)
        end
    end
    _G.BTR_PROT_CALLBACKS.Dump = setAntiDump
    _G.BTR_PROT_TOGGLES.Dump = ProtectionTab:AddToggle({
