--  [PROTECTION PROPS v3] Unlock House Props - REMOTE ENGINE [LOCKED: WORK PERFECTLY]
    local PropSystem = {
        active = false,
        running = false,
    local lotAddedConn = nil
    local lotRemotes = {}
    local function getLotRemotes(lot)
        if not lot or not lot:IsA("Instance") then return nil, nil end
        local cached = lotRemotes[lot]
        if cached and cached.set and cached.set.Parent then
            return cached.set, cached.is
        end
        local setBlocked = lot:FindFirstChild(_0xS(275), true)
        local isBlocked = lot:FindFirstChild(_0xS(276), true)
        if setBlocked and setBlocked:IsA("RemoteFunction") then
            lotRemotes[lot] = { set = setBlocked, is = isBlocked }
            return setBlocked, isBlocked
        end
        return nil, nil
    end
    local function unlockLotRemote(lot)
        local setBlocked, isBlocked = getLotRemotes(lot)
        if setBlocked then
            task.spawn(function()
                local etat = nil
                if isBlocked and isBlocked:IsA("RemoteFunction") then
                    pcall(function() etat = isBlocked:InvokeServer() end)
                end
                if etat == true or etat == nil then
                    pcall(function() setBlocked:InvokeServer(false) end)
                end
            end)
        end
    end
    local function sweepRemoteLots()
        local lots = workspace:FindFirstChild(_0xS(107))
        if lots then
            for _, lot in pairs(lots:GetChildren()) do
                if not PropSystem.active then break end
                unlockLotRemote(lot)
                task.wait(0.05)
            end
        end
    end
    local function propProtectLoop()
        PropSystem.running = true
        while PropSystem.active do
            sweepRemoteLots()
            task.wait(12)
        end
        PropSystem.running = false
    end
    local function ensurePropLoop()
        if PropSystem.active and not PropSystem.running then
            task.spawn(function()
                pcall(function() propProtectLoop() end)
            end)
        end
    end
    local function setupListener()
        if lotAddedConn then
            pcall(function() lotAddedConn:Disconnect() end)
            lotAddedConn = nil
        end
        local lots = workspace:FindFirstChild(_0xS(107))
        if not lots then return end
        lotAddedConn = lots.DescendantAdded:Connect(function(descendant)
            if not PropSystem.active then return end
            if descendant.Name == "Permissions:SetPropPlacementBlockedForOthers" and descendant:IsA("RemoteFunction") then
                local lot = descendant:FindFirstAncestorOfClass("Model") or descendant.Parent
                if lot then
                    task.defer(function()
                        unlockLotRemote(lot)
                    end)
                end
            end
        end)
    end
    local function setPropPlacement(state)
        if state then
            if PropSystem.active then return end
            PropSystem.active = true
            setupListener()
            ensurePropLoop()
            task.spawn(function()
                pcall(function() sweepRemoteLots() end)
            end)
        else
            PropSystem.active = false
            if lotAddedConn then
                pcall(function() lotAddedConn:Disconnect() end)
                lotAddedConn = nil
            end
        end
    end
    _G.BTR_PROT_CALLBACKS.PropPlacement = setPropPlacement
    _G.setBTRPropBypassMode = function(newMode)
        _G.BTR_PROP_BYPASS_MODE = "Remote"
        if _G.saveBTRConfig then _G.saveBTRConfig() end
    end
