local invincibleShieldActive = false
local invincibleCharConn = nil
local invincibleHeartbeat = nil
local function applyUndeadShield(char)
    if not char then return end
    local hum = char:WaitForChild(_0xS(94), 4)
    local hrp = char:WaitForChild(_0xS(6), 4)
    if not hum or not hrp then return end
    hum:SetStateEnabled(Enum.HumanoidStateType.Dead, false)
    pcall(function() char.BreakJointsOnDeath = false end)
    pcall(function() hum.Health = 0 end)
    pcall(function()
        hrp.CustomPhysicalProperties = PhysicalProperties.new(100, 0, 0, 0, 0)
    end)
local function restoreNormalState()
    local char = game:GetService(_0xS(1)).LocalPlayer.Character
    local hum = char and char:FindFirstChildOfClass("Humanoid")
    local hrp = char and char:FindFirstChild(_0xS(6))
    if hum then
        hum:SetStateEnabled(Enum.HumanoidStateType.Dead, true)
        pcall(function() hum.Health = 100 end)
    end
    if hrp then
        pcall(function()
            hrp.CustomPhysicalProperties = nil
        end)
    end
local function setInvincibleShieldCallback(state)
    invincibleShieldActive = (state == true)
    _G.InvincibleShieldActive = invincibleShieldActive
    if invincibleCharConn then
        invincibleCharConn:Disconnect()
        invincibleCharConn = nil
    end
    if invincibleHeartbeat then
        invincibleHeartbeat:Disconnect()
        invincibleHeartbeat = nil
    end
    local lp = game:GetService(_0xS(1)).LocalPlayer
    if invincibleShieldActive then
        applyUndeadShield(lp.Character)
        invincibleCharConn = lp.CharacterAdded:Connect(function(newChar)
            task.wait(0.3)
            if invincibleShieldActive then
                applyUndeadShield(newChar)
            end
        end)
        invincibleHeartbeat = game:GetService(_0xS(15)).Heartbeat:Connect(function()
            local char = lp.Character
            local hum = char and char:FindFirstChildOfClass("Humanoid")
            if not hum then return end
            
            if hum.Health > 0 then
                hum:SetStateEnabled(Enum.HumanoidStateType.Dead, false)
                pcall(function() char.BreakJointsOnDeath = false end)
                pcall(function() hum.Health = 0 end)
            end
        end)
        if _G.BTR_ALL_LOADED then
            pcall(function()
                game:GetService(_0xS(5)):SetCore("SendNotification", {
                    Title = "Invincible Shield",
                    Text = "Exploit Immunity ACTIVE! Health = 0 (Undead). Hubs will refuse to attack you.",
                    Duration = 4
                })
            end)
        end
    else
        restoreNormalState()
        if _G.BTR_ALL_LOADED then
            pcall(function()
                game:GetService(_0xS(5)):SetCore("SendNotification", {
                    Title = "Invincible Shield",
                    Text = "Exploit Immunity disabled. Health restored to normal.",
                    Duration = 3
                })
            end)
        end
    end
