local function _btrInitStalkerMimic()
    local Players = game:GetService(_0xS(1))
    local LocalPlayer = Players.LocalPlayer
    local RunService = game:GetService(_0xS(15))
    local TextChatService = game:GetService(_0xS(69))
    local ReplicatedStorage = game:GetService(_0xS(70))
    local StarterGui = game:GetService(_0xS(5))
    local stalkSelectedTarget = nil
    local copyChatEnabled = false
    local copyMoveEnabled = false
    local stalkerEnabled = false
    local copyMoveMode = "Mirror"
    local copyMoveDistance = 6
    local stalkPositionMode = "Dynamic"
    local stalkDistance = 30
    local stalkFleeOnSight = true
    local function resolveTarget()
        if stalkSelectedTarget and stalkSelectedTarget ~= "---" then
            local p = Players:FindFirstChild(stalkSelectedTarget)
            if p then return p end
        end
        if _G.TrollTarget and _G.TrollTarget ~= "---" then
            local p = Players:FindFirstChild(_G.TrollTarget)
            if p then return p end
        end
        return nil
    end
    local function notify(title, text)
        pcall(function()
            StarterGui:SetCore("SendNotification", {
                Title = title,
                Text = text,
                Duration = 3
            })
        end)
    end
    local lastParrotMsg = ""
    local lastParrotTime = 0
    local function sendChatMsg(msg)
        if not msg or msg == "" then return end
        local sent = false
        pcall(function()
            if TextChatService and TextChatService.ChatVersion == Enum.ChatVersion.TextChatService then
                local channels = TextChatService:FindFirstChild(_0xS(75))
                local rbxGeneral = channels and channels:FindFirstChild(_0xS(76))
                if rbxGeneral then
                    rbxGeneral:SendAsync(msg)
                    sent = true
                end
            end
        end)
        if sent then return end
        pcall(function()
            local defaultChat = ReplicatedStorage:FindFirstChild(_0xS(77))
            local sayMsg = defaultChat and defaultChat:FindFirstChild(_0xS(78))
            if sayMsg then
                sayMsg:FireServer(msg, "All")
            end
        end)
    end
    local function onChatReceived(sender, msg)
        if not copyChatEnabled then return end
        local target = resolveTarget()
        if not target or sender ~= target then return end
        if sender == LocalPlayer then return end
        local now = tick()
        if msg == lastParrotMsg and (now - lastParrotTime) < 0.5 then return end
        lastParrotMsg = msg
        lastParrotTime = now
        task.spawn(function()
            task.wait(0.12)
            sendChatMsg(msg)
        end)
    end
    pcall(function()
        if TextChatService then
            TextChatService.MessageReceived:Connect(function(textChatMessage)
                if textChatMessage.TextSource then
                    local sender = Players:GetPlayerByUserId(textChatMessage.TextSource.UserId)
                    if sender then
                        onChatReceived(sender, textChatMessage.Text)
                    end
                end
            end)
        end
    end)
    local function hookPlayerLegacyChat(p)
        p.Chatted:Connect(function(msg)
            onChatReceived(p, msg)
        end)
    end
    for _, p in ipairs(Players:GetPlayers()) do
        hookPlayerLegacyChat(p)
    end
    Players.PlayerAdded:Connect(hookPlayerLegacyChat)
    local copyMoveConn = nil
    local noClipMoveConn = nil
    local function stopCopyMovement()
        if copyMoveConn then copyMoveConn:Disconnect(); copyMoveConn = nil end
        if noClipMoveConn then noClipMoveConn:Disconnect(); noClipMoveConn = nil end
        local char = LocalPlayer.Character
        local hum = char and char:FindFirstChildOfClass("Humanoid")
        if hum then
            hum:Move(Vector3.zero, false)
            hum.WalkSpeed = 16
        end
    end
    local function startCopyMovement()
        stopCopyMovement()
        local target = resolveTarget()
        if not target then
            notify("Copy Movement", "Select a target first")
            return false
        end
        noClipMoveConn = RunService.Stepped:Connect(function()
            local char = LocalPlayer.Character
            if char then
                for _, part in ipairs(char:GetDescendants()) do
                    if part:IsA("BasePart") and part.CanCollide and part.Name ~= _0xS(6) then
                        part.CanCollide = false
                    end
                end
            end
        end)
        copyMoveConn = RunService.RenderStepped:Connect(function(dt)
            local currentTarget = resolveTarget()
            if not currentTarget or not currentTarget.Character then return end
            local tChar = currentTarget.Character
            local tHrp = tChar:FindFirstChild(_0xS(6))
            local tHum = tChar:FindFirstChildOfClass("Humanoid")
            if not tHrp or not tHum then return end
            local myChar = LocalPlayer.Character
            if not myChar then return end
            local myHrp = myChar:FindFirstChild(_0xS(6))
            local myHum = myChar:FindFirstChildOfClass("Humanoid")
            if not myHrp or not myHum then return end
            if myHum.WalkSpeed ~= tHum.WalkSpeed then
                myHum.WalkSpeed = tHum.WalkSpeed
            end
            if tHum.Jump or tHum:GetState() == Enum.HumanoidStateType.Jumping then
                myHum.Jump = true
            end
            if tHum.Sit and not myHum.Sit then
                myHum.Sit = true
            elseif not tHum.Sit and myHum.Sit then
                myHum.Sit = false
                pcall(function() myHum:ChangeState(Enum.HumanoidStateType.GettingUp) end)
            end
            local idealPos = myHrp.Position
            local lookAtPos = tHrp.Position
            if copyMoveMode == "Mirror" then
                idealPos = tHrp.Position + (tHrp.CFrame.LookVector * copyMoveDistance)
                lookAtPos = tHrp.Position
            elseif copyMoveMode == "Follow" then
                idealPos = tHrp.Position - (tHrp.CFrame.LookVector * copyMoveDistance)
                lookAtPos = idealPos + tHrp.CFrame.LookVector
            elseif copyMoveMode == "Exact" then
                idealPos = tHrp.Position + (tHrp.CFrame.RightVector * copyMoveDistance)
                lookAtPos = idealPos + tHrp.CFrame.LookVector
            end
            local distError = (idealPos - myHrp.Position).Magnitude
            if distError > 12 then
                myHrp.CFrame = CFrame.lookAt(idealPos, Vector3.new(lookAtPos.X, idealPos.Y, lookAtPos.Z))
            else
                local offset = (idealPos - myHrp.Position)
                local horizontalOffset = Vector3.new(offset.X, 0, offset.Z)
                if horizontalOffset.Magnitude > 0.25 then
                    myHum:Move(horizontalOffset.Unit, false)
                else
                    myHum:Move(Vector3.zero, false)
                end
                local targetRot = CFrame.lookAt(myHrp.Position, Vector3.new(lookAtPos.X, myHrp.Position.Y, lookAtPos.Z))
                myHrp.CFrame = myHrp.CFrame:Lerp(targetRot, math.clamp(dt * 15, 0, 1))
            end
        end)
        return true
    end
    local stalkerRunning = false
    local stalkerThread = nil
    local lastRelocateTime = 0
    local isRelocating = false
    local function findGroundLevel(pos, ignoreList)
        local rayParams = RaycastParams.new()
        rayParams.FilterType = Enum.RaycastFilterType.Exclude
        rayParams.FilterDescendantsInstances = ignoreList or {}
        local res = workspace:Raycast(pos + Vector3.new(0, 10, 0), Vector3.new(0, -60, 0), rayParams)
        if res then
            return res.Position.Y
        end
        return pos.Y
    end
    local function calculateStalkPosition(tHrp, myChar)
        local tPos = tHrp.Position
        local tCF = tHrp.CFrame
        local chosenMode = stalkPositionMode
        if chosenMode == "Dynamic" then
            local modes = { "Behind", "Rooftops", "Corners" }
            chosenMode = modes[math.random(1, #modes)]
        end
        local candidate = tPos
        local ignore = { myChar, tHrp.Parent }
        if chosenMode == "Behind" then
            local angle = math.rad(math.random(-50, 50))
            local dist = stalkDistance + math.random(-4, 6)
            local offset = CFrame.Angles(0, angle, 0) * Vector3.new(0, 0, dist)
            candidate = tCF:PointToWorldSpace(offset)
            local groundY = findGroundLevel(candidate, ignore)
            candidate = Vector3.new(candidate.X, groundY + 3, candidate.Z)
        elseif chosenMode == "Rooftops" then
            local foundElevated = false
            for attempt = 1, 8 do
                local ang = math.rad(math.random(0, 360))
                local dist = stalkDistance + math.random(-5, 10)
                local sample = tPos + Vector3.new(math.sin(ang) * dist, 0, math.cos(ang) * dist)
                local highY = findGroundLevel(sample + Vector3.new(0, 25, 0), ignore)
                if (highY - tPos.Y) >= 10 then
                    candidate = Vector3.new(sample.X, highY + 3, sample.Z)
                    foundElevated = true
                    break
                end
            end
            if not foundElevated then
                local offset = Vector3.new(math.random(-15, 15), 0, stalkDistance)
                candidate = tCF:PointToWorldSpace(offset)
                local groundY = findGroundLevel(candidate, ignore)
                candidate = Vector3.new(candidate.X, groundY + 3, candidate.Z)
            end
        elseif chosenMode == "Corners" then
            local side = (math.random(1, 2) == 1) and 1 or -1
            local offset = Vector3.new(side * (stalkDistance * 0.7), 0, (stalkDistance * 0.8))
            candidate = tCF:PointToWorldSpace(offset)
            local groundY = findGroundLevel(candidate, ignore)
            candidate = Vector3.new(candidate.X, groundY + 3, candidate.Z)
        end
        return candidate
    end
    local function isTargetLookingAtUs(tChar, myChar)
        local tHead = tChar:FindFirstChild(_0xS(142)) or tChar:FindFirstChild(_0xS(6))
        local myHrp = myChar:FindFirstChild(_0xS(6))
        if not tHead or not myHrp then return false end
        local toUs = (myHrp.Position - tHead.Position)
        local dist = toUs.Magnitude
        if dist < 0.1 then return false end
        local dir = toUs.Unit
        local lookDot = tHead.CFrame.LookVector:Dot(dir)
        if lookDot > 0.45 then
            local rayParams = RaycastParams.new()
            rayParams.FilterType = Enum.RaycastFilterType.Exclude
            rayParams.FilterDescendantsInstances = { tChar, myChar }
            local res = workspace:Raycast(tHead.Position, toUs, rayParams)
            if not res or (res.Instance and res.Instance:IsDescendantOf(myChar)) then
                return true
            end
        end
        return false
    end
    local function relocateStalker(tHrp, myChar)
        if isRelocating then return end
        isRelocating = true
        local myHrp = myChar:FindFirstChild(_0xS(6))
        if not myHrp then isRelocating = false; return end
        local newPos = calculateStalkPosition(tHrp, myChar)
        myHrp.CFrame = CFrame.lookAt(newPos, Vector3.new(tHrp.Position.X, newPos.Y, tHrp.Position.Z))
        myHrp.AssemblyLinearVelocity = Vector3.zero
        lastRelocateTime = tick()
        task.wait(0.2)
        isRelocating = false
    end
    local function startStalker()
        stalkerRunning = true
        lastRelocateTime = 0
        isRelocating = false
        stalkerThread = task.spawn(function()
            while stalkerRunning do
                local target = resolveTarget()
                local myChar = LocalPlayer.Character
                local myHrp = myChar and myChar:FindFirstChild(_0xS(6))
                local myHum = myChar and myChar:FindFirstChildOfClass("Humanoid")
                if target and target.Character and myHrp and myHum then
                    local tChar = target.Character
                    local tHrp = tChar:FindFirstChild(_0xS(6))
                    if tHrp then
                        local dist = (myHrp.Position - tHrp.Position).Magnitude
                        if dist > 110 or dist < 8 or lastRelocateTime == 0 then
                            relocateStalker(tHrp, myChar)
                        else
                            myHrp.CFrame = CFrame.lookAt(myHrp.Position, Vector3.new(tHrp.Position.X, myHrp.Position.Y, tHrp.Position.Z))
                            myHum:Move(Vector3.zero, false)
                            if stalkFleeOnSight and not isRelocating then
                                if isTargetLookingAtUs(tChar, myChar) then
                                    task.wait(0.15)
                                    if stalkerRunning and target.Character then
                                        relocateStalker(tHrp, myChar)
                                    end
                                end
                            end
                            if tick() - lastRelocateTime > 16 and not isRelocating then
                                relocateStalker(tHrp, myChar)
                            end
                        end
                    end
                end
                task.wait(0.08)
            end
        end)
    end
    local function stopStalker()
        stalkerRunning = false
        if stalkerThread then
            pcall(function() task.cancel(stalkerThread) end)
            stalkerThread = nil
        end
        isRelocating = false
    end
    TrollV2Tab:AddSection({ "> Stalker & Mimic" })
    local function getPlayerList()
        local list = {}
        for _, p in ipairs(Players:GetPlayers()) do
            if p ~= LocalPlayer then
