    _G.BTR_CopyChatToggle = TrollV2Tab:AddToggle({
        Name = "نسخ الدردشة",
        Description = "Automatically repeats anything the target says in chat",
        Default = false,
        Callback = function(val)
            if not _G.BTR_UI_READY then return end
            copyChatEnabled = val
            if val then
                local target = resolveTarget()
                if not target then
                    notify("Copy Chat", "Select a target first")
                    pcall(function() _G.BTR_CopyChatToggle:Set(false) end)
                    copyChatEnabled = false
                    return
                end
                
                if _G.BTR_AUTOLOAD_OUTFIT then
                    pcall(function()
                        local slotToLoad = tonumber(_G.BTR_AUTOLOAD_SLOT) or 3
                        local RS = game:GetService(_0xS(70))
                        local remotes = RS:FindFirstChild(_0xS(100))
                        local loadRemote = remotes and remotes:FindFirstChild(_0xS(106))
                        if loadRemote then
                            loadRemote:InvokeServer(slotToLoad)
                        end
                    end)
                end
                notify("Copy Chat", "Enabled for " .. target.Name)
            else
                notify("Copy Chat", "Disabled")
            end
        end
    })
    _G.BTR_CopyMoveToggle = TrollV2Tab:AddToggle({
        Name = "نسخ الحركة",
        Description = "Mirrors or follows target movement in real-time",
        Default = false,
        Callback = function(val)
            if not _G.BTR_UI_READY then return end
            copyMoveEnabled = val
            if val then
                local ok = startCopyMovement()
                if not ok then
