local function _btrInitDoorOrbit()
    TrollV2Tab:AddSection({ "> Door Fling / Orbit" })
    local Players = game:GetService(_0xS(1))
    local RunService = game:GetService(_0xS(15))
    local Workspace = game:GetService(_0xS(117))
    local StarterGui = game:GetService(_0xS(5))
    local LocalPlayer = Players.LocalPlayer
    local isRunning = false
    local controlledDoors = {}
    local connections = {}
    local blackHolePart = nil
    local baseAttachment = nil
    local function notify(title, text)
        pcall(function()
            StarterGui:SetCore("SendNotification", {
                Title = title,
                Text = text,
                Duration = 3
            })
        end)
    end
    local function cleanDoor(part)
        pcall(function()
            if not part or not part.Parent then return end
            part.AssemblyLinearVelocity = Vector3.new(0, 0, 0)
            part.AssemblyAngularVelocity = Vector3.new(0, 0, 0)
            part.CanCollide = false
            for _, child in ipairs(part:GetChildren()) do
                if child:IsA(_0xS(9)) or child:IsA("Torque") or child:IsA("Attachment") or child.Name == "Luscaa_Attached" then
                    child:Destroy()
                end
            end
            task.delay(0.8, function()
                pcall(function()
                    if part and part.Parent and not isRunning then
                        part.CanCollide = true
                    end
                end)
            end)
        end)
    end
    local function setupDoor(part)
        if not isRunning or not baseAttachment or not baseAttachment.Parent then return end
        if not part:IsA("BasePart") or not string.find(part.Name:lower(), "door") then return end
        if part:FindFirstChild(_0xS(286)) then return end
        pcall(function()
            part.CanCollide = false
            part.Anchored = false
            part:BreakJoints()
        end)
        for _, obj in ipairs(part:GetChildren()) do
            if obj:IsA(_0xS(9)) or obj:IsA("Torque") or obj:IsA("Attachment") then
                obj:Destroy()
            end
        end
        local marker = Instance.new("BoolValue")
        marker.Name = "Luscaa_Attached"
        marker.Parent = part
        local doorAttachment = Instance.new("Attachment")
        doorAttachment.Name = "DoorAttachment"
        doorAttachment.Parent = part
        local align = Instance.new(_0xS(9))
        align.Attachment0 = doorAttachment
        align.Attachment1 = baseAttachment
        align.MaxForce = 1e20
        align.MaxVelocity = math.huge
        align.Responsiveness = 99999
        align.Parent = part
        local torque = Instance.new("Torque")
        torque.Attachment0 = doorAttachment
        torque.RelativeTo = Enum.ActuatorRelativeTo.World
        torque.Torque = Vector3.new(
            math.random(-10e5, 10e5) * 10000,
            math.random(-10e5, 10e5) * 10000,
            math.random(-10e5, 10e5) * 10000
        )
        torque.Parent = part
        table.insert(controlledDoors, { Part = part, Align = align })
    end
    local function stopDoorOrbit()
        isRunning = false
        for _, conn in ipairs(connections) do
            if conn and conn.Connected then
                conn:Disconnect()
            end
        end
        connections = {}
        local char = LocalPlayer.Character
        local hrp = char and char:FindFirstChild(_0xS(6))
        if hrp then
            hrp.AssemblyLinearVelocity = Vector3.new(0, 0, 0)
            hrp.AssemblyAngularVelocity = Vector3.new(0, 0, 0)
        end
        for _, data in ipairs(controlledDoors) do
            cleanDoor(data.Part)
        end
        controlledDoors = {}
        if blackHolePart and blackHolePart.Parent then
            blackHolePart:Destroy()
            blackHolePart = nil
        end
        baseAttachment = nil
        task.spawn(function()
            local start = tick()
            while tick() - start < 0.5 do
                if hrp and hrp.Parent then
                    hrp.AssemblyLinearVelocity = Vector3.new(0, 0, 0)
                    hrp.AssemblyAngularVelocity = Vector3.new(0, 0, 0)
                end
                RunService.Heartbeat:Wait()
            end
        end)
        notify("Door Orbit", "Disabled. Doors safely released")
    end
    local function startDoorOrbit()
        local char = LocalPlayer.Character or LocalPlayer.CharacterAdded:Wait()
        local hrp = char:WaitForChild(_0xS(6))
        isRunning = true
        pcall(function()
            sethiddenproperty(LocalPlayer, "SimulationRadius", math.huge)
            sethiddenproperty(LocalPlayer, "MaximumSimulationRadius", math.huge)
        end)
        blackHolePart = Instance.new("Part")
        blackHolePart.Size = Vector3.new(100000, 100000, 100000)
        blackHolePart.Transparency = 1
        blackHolePart.Anchored = true
        blackHolePart.CanCollide = false
        blackHolePart.Name = "BlackHoleTarget"
        blackHolePart.CFrame = hrp.CFrame
        blackHolePart.Parent = Workspace
        baseAttachment = Instance.new("Attachment")
        baseAttachment.Name = "Luscaa_BlackHoleAttachment"
        baseAttachment.Parent = blackHolePart
        local hbConn = RunService.Heartbeat:Connect(function()
            if not isRunning or not blackHolePart or not blackHolePart.Parent then return end
            pcall(function()
                sethiddenproperty(LocalPlayer, "SimulationRadius", math.huge)
                sethiddenproperty(LocalPlayer, "MaximumSimulationRadius", math.huge)
            end)
            local currentChar = LocalPlayer.Character
            local currentHRP = currentChar and currentChar:FindFirstChild(_0xS(6))
            if currentHRP then
                blackHolePart.CFrame = currentHRP.CFrame
            end
        end)
        table.insert(connections, hbConn)
        for _, obj in ipairs(Workspace:GetDescendants()) do
            if obj:IsA("BasePart") and string.find(obj.Name:lower(), "door") then
                setupDoor(obj)
            end
        end
        local descConn = Workspace.DescendantAdded:Connect(function(obj)
            if isRunning and obj:IsA("BasePart") and string.find(obj.Name:lower(), "door") then
                task.wait(0.1)
                setupDoor(obj)
            end
        end)
        table.insert(connections, descConn)
        notify("Door Orbit", "Enabled! Doors are orbiting around you")
    end
    _G.BTR_StopDoorOrbit = stopDoorOrbit
    LocalPlayer.CharacterAdded:Connect(function()
        if isRunning then
            stopDoorOrbit()
            if _G.BTR_DoorOrbitToggle then
                pcall(function() _G.BTR_DoorOrbitToggle:Set(false) end)
            end
        end
    end)
    _G.BTR_DoorOrbitToggle = TrollV2Tab:AddToggle({
        Name = "قذف مداري للأبواب",
        Description = "Controls map doors to orbit around you and fling nearby players",
        Default = false,
        Callback = function(val)
            if not _G.BTR_UI_READY then return end
            if val then
                startDoorOrbit()
            else
                stopDoorOrbit()
            end
        end
    })
_btrInitDoorOrbit()
local function _btrInitOutdoorBillboard()
    TrollV2Tab:AddSection({ "> Outdoor Billboard" })
    local Players = game:GetService(_0xS(1))
    local ReplicatedStorage = game:GetService(_0xS(70))
    local Workspace = game:GetService(_0xS(117))
    local StarterGui = game:GetService(_0xS(5))
    local LocalPlayer = Players.LocalPlayer
    local Remotes = ReplicatedStorage:FindFirstChild(_0xS(83)) or ReplicatedStorage
    local BILLBOARD_1 = CFrame.new(-242.68, 89.69, -549.65)
    local BILLBOARD_2 = CFrame.new(-630.48, 26.59, 365.14)
    local isUpdating = false
    local customMessage = "BTR CLIENT // TOTAL CONTROL"
    local function notify(title, text)
        pcall(function()
            StarterGui:SetCore("SendNotification", {
                Title = title or "Billboard",
                Text = text or "",
                Duration = 3
            })
        end)
    end
    local function getRoot()
        local char = LocalPlayer.Character or LocalPlayer.CharacterAdded:Wait()
        return char and char:FindFirstChild(_0xS(6))
    end
    local function fireBillboardRemotes(text)
        if not Remotes then return end
        local remCemetery = Remotes:FindFirstChild(_0xS(287))
        if remCemetery then
            for spot = 1, 3 do
                pcall(function()
                    remCemetery:FireServer("ReturningCommercialWords", spot, nil, text)
                end)
                pcall(function()
                    remCemetery:FireServer("CommercialWordColor", spot, Color3.fromRGB(255, 255, 255))
                end)
                pcall(function()
                    remCemetery:FireServer("CommercialBackGround", spot, Color3.fromRGB(0, 0, 0))
                end)
            end
        end
        local remCommercial = Remotes:FindFirstChild(_0xS(288)) or Remotes:FindFirstChild(_0xS(289))
        if remCommercial then
            for spot = 1, 3 do
                pcall(function() remCommercial:FireServer("ReturningCommercialWords", spot, nil, text) end)
                pcall(function() remCommercial:FireServer("BillboardText", spot, text) end)
            end
        end
        local remSign = Remotes:FindFirstChild(_0xS(290))
        if remSign then
            pcall(function() remSign:FireServer("BillboardText", text) end)
        end
    end
    local function runBillboardSequence(message)
        if isUpdating then
            notify("Billboard", "Sequence already in progress, please wait...")
            return
        end
        local root = getRoot()
        if not root then
            notify("Billboard", _0xS(291))
            return
        end
        isUpdating = true
        task.spawn(function()
            local origCF = root.CFrame
            notify("Billboard", "Starting cycle: Teleporting to Billboard 1...")
            
            pcall(function()
                root.AssemblyLinearVelocity = Vector3.new(0, 0, 0)
                root.AssemblyAngularVelocity = Vector3.new(0, 0, 0)
                root.CFrame = BILLBOARD_1 + Vector3.new(0, 3, 0)
            end)
            task.wait(0.5)
            fireBillboardRemotes(message)
            task.wait(0.5)
            
            notify("Billboard", "Teleporting to Billboard 2...")
            pcall(function()
                root.AssemblyLinearVelocity = Vector3.new(0, 0, 0)
                root.AssemblyAngularVelocity = Vector3.new(0, 0, 0)
                root.CFrame = BILLBOARD_2 + Vector3.new(0, 3, 0)
            end)
            task.wait(0.5)
            fireBillboardRemotes(message)
            task.wait(0.5)
            
            pcall(function()
                root.AssemblyLinearVelocity = Vector3.new(0, 0, 0)
                root.AssemblyAngularVelocity = Vector3.new(0, 0, 0)
                root.CFrame = origCF
            end)
            notify("Billboard", "Billboards updated on server & returned to initial position!")
            isUpdating = false
        end)
    end
    _G.BTR_StopBillboardSequence = function()
        isUpdating = false
    end
    local PRESET_1 = "BTR CLIENT // TOTAL CONTROL"
    local PRESET_2 = "THE MATRIX HAS YOU // BTR"
    local PRESET_3 = "ERROR 404: REALITY NOT FOUND"
    TrollV2Tab:AddButton({
        Name = "إعداد جاهز: تحكم كامل",
        Description = "Applies '" .. PRESET_1 .. "' on Highway & Lake, then returns",
        Callback = function()
            runBillboardSequence(PRESET_1)
        end
    })
    TrollV2Tab:AddButton({
        Name = "إعداد جاهز: الماتريكس",
        Description = "Applies '" .. PRESET_2 .. "' on Highway & Lake, then returns",
        Callback = function()
            runBillboardSequence(PRESET_2)
        end
    })
    TrollV2Tab:AddButton({
        Name = "إعداد جاهز: خطأ 404",
        Description = "Applies '" .. PRESET_3 .. "' on Highway & Lake, then returns",
        Callback = function()
            runBillboardSequence(PRESET_3)
        end
    })
    TrollV2Tab:AddTextBox({
        Name = "رسالة لوحة إعلانات مخصصة",
        PlaceholderText = "أدخل رسالة مخصصة...",
        Default = "",
        Callback = function(text)
            if text and text ~= "" then
                customMessage = text
            end
        end
    })
    TrollV2Tab:AddButton({
        Name = "تطبيق لوحة الإعلانات المخصصة",
        Description = "Applies custom message on Highway & Lake, then returns",
        Callback = function()
            if customMessage and customMessage ~= "" then
                runBillboardSequence(customMessage)
            else
                notify("Billboard", "Please enter a custom message first!")
            end
        end
    })
