    local function createVaultHighlight(targetObj, labelName)
        if not targetObj then return end
        local coreGuiService = game:GetService(_0xS(12))
        local localPlr = game:GetService(_0xS(1)).LocalPlayer
        local hl = Instance.new(_0xS(67))
