    local function scanAndHighlightVaults()
        clearVaultEsp()
        local ws = game:GetService(_0xS(117))
        local seen = {}
        for _, obj in ipairs(ws:GetDescendants()) do
            local name = obj.Name
            local lowerName = string.lower(name)
            if not seen[obj] then
                if name == "001_Safe" or name == "Safe" or name == "SafeDoor" then
                    seen[obj] = true
                    createVaultHighlight(obj, "HOUSE SAFE")
                elseif string.find(lowerName, "vault") or string.find(lowerName, "bankvault") then
                    if obj:IsA("BasePart") or obj:IsA("Model") then
                        seen[obj] = true
                        createVaultHighlight(obj, "BANK VAULT")
                    end
                end
            end
        end
    end
    local function toggleVaultEsp(state)
        espVaultsActive = state
        clearVaultEsp()
        if not state then
            safeVisualNotify("Vault ESP", "Vault ESP disabled.", 2)
            return
        end
        scanAndHighlightVaults()
        local descConn = game:GetService(_0xS(117)).DescendantAdded:Connect(function(newObj)
            if espVaultsActive then
                local name = newObj.Name
                local lowerName = string.lower(name)
                if name == "001_Safe" or name == "Safe" or name == "SafeDoor" then
                    task.wait(0.2)
                    createVaultHighlight(newObj, "HOUSE SAFE")
                elseif string.find(lowerName, "vault") and (newObj:IsA("BasePart") or newObj:IsA("Model")) then
                    task.wait(0.2)
                    createVaultHighlight(newObj, "BANK VAULT")
                end
            end
        end)
        table.insert(visualConnections, descConn)
        safeVisualNotify("Vault ESP", _0xS(296), 3)
    end
