    local function applySinglePlayerEsp(plr)
        if not espPlayersActive or not plr or not plr.Character then return end
        if blacklistedKickedPlayers[plr.Name] then return end
        local coreGuiService = game:GetService(_0xS(12))
        local localPlr = game:GetService(_0xS(1)).LocalPlayer
        if plr == localPlr then return end
        local char = plr.Character
        local existing = char:FindFirstChild(_0xS(297))
        if existing then return end
        local highlight = Instance.new(_0xS(67))
        highlight.Name = _0xS(297)
        highlight.Adornee = char
        highlight.FillColor = Color3.fromRGB(0, 255, 180)
        highlight.OutlineColor = Color3.fromRGB(0, 100, 255)
        highlight.FillTransparency = 0.5
        highlight.DepthMode = Enum.HighlightDepthMode.AlwaysOnTop
        local ok = pcall(function() highlight.Parent = coreGuiService end)
        if not ok or not highlight.Parent then
            pcall(function()
                highlight.Parent = (localPlr and localPlr:FindFirstChild(_0xS(13))) or char
            end)
        end
        table.insert(espPlayerObjects, highlight)
    end
    local function refreshPlayerEsp()
        clearPlayerEsp()
        if not espPlayersActive then return end
        local playersService = game:GetService(_0xS(1))
        for _, plr in ipairs(playersService:GetPlayers()) do
            applySinglePlayerEsp(plr)
        end
    end
    local function togglePlayerEsp(state)
        espPlayersActive = state
        clearPlayerEsp()
        if playerEspThread then
            pcall(function() task.cancel(playerEspThread) end)
            playerEspThread = nil
        end
        if not state then
            safeVisualNotify("Player ESP", "Player ESP disabled.", 2)
            return
        end
        refreshPlayerEsp()
        playerEspThread = task.spawn(function()
            while espPlayersActive do
                task.wait(1.5)
                local playersService = game:GetService(_0xS(1))
                local localPlr = playersService.LocalPlayer
                for _, plr in ipairs(playersService:GetPlayers()) do
                    if plr ~= localPlr and plr.Character and not blacklistedKickedPlayers[plr.Name] then
                        applySinglePlayerEsp(plr)
                    end
                end
            end
        end)
        safeVisualNotify("Player ESP", _0xS(298), 3)
    end
    local function fakeUnlockGamepasses()
        local localPlr = game:GetService(_0xS(1)).LocalPlayer
        local pg = localPlr and localPlr:FindFirstChild(_0xS(13))
        local count = 0
        
        if hookmetamethod and getnamecallmethod then
            pcall(function()
                local oldHook; oldHook = hookmetamethod(game, "__namecall", function(self, ...)
                    local m = getnamecallmethod()
                    if m == "UserOwnsGamePassAsync" or m == "PlayerOwnsAsset" then
                        return true
                    end
                    if m == "PromptGamePassPurchase" or m == "PromptPurchase" then
                        return nil
                    end
                    return oldHook(self, ...)
                end)
            end)
        end
        
        local function processStoreItem(desc)
            if not desc or not desc.Parent then return end
            pcall(function()
                local lname = string.lower(desc.Name)
                
                if desc:IsA("TextLabel") or desc:IsA("TextButton") then
                    local rawText = desc.Text
                    local cleanDigits = rawText:gsub("%D", "")
                    local priceNum = tonumber(cleanDigits)
                    local isPrice = false
                    if priceNum and priceNum >= 15 and priceNum <= 50000 and #rawText <= 30 then
                        isPrice = true
                    end
                    local t = string.lower(rawText)
                    if string.find(t, "buy") or string.find(t, "robux") or string.find(t, "r%$") or string.find(t, "pass") or string.find(t, "acheter") then
                        isPrice = true
                    end
                    if isPrice then
                        desc.Text = "OWNED"
                        desc.TextColor3 = Color3.fromRGB(0, 255, 120)
                        count = count + 1
                        
                        local p = desc.Parent
                        if p then
                            for _, child in ipairs(p:GetChildren()) do
                                if child ~= desc and (child:IsA("ImageLabel") or child:IsA("ImageButton") or child.Name:lower():find("robux") or child.Name:lower():find("icon")) then
                                    child.Visible = false
                                end
                            end
                            if p:IsA("GuiObject") then
                                pcall(function() p.BackgroundColor3 = Color3.fromRGB(20, 160, 60) end)
                            end
                        end
                        for _, child in ipairs(desc:GetChildren()) do
                            if child:IsA("ImageLabel") or child:IsA("ImageButton") then
                                child.Visible = false
                            end
                        end
                    end
                    
                    if string.find(t, "cadeau") or string.find(t, "gift") then
                        desc.Text = "UNLOCKED"
                        desc.TextColor3 = Color3.fromRGB(180, 240, 200)
                    end
                end
                
                if desc:IsA("ImageButton") or desc:IsA("TextButton") then
                    if string.find(lname, "buy") or string.find(lname, "price") or string.find(lname, "purchase") or string.find(lname, "robux") then
                        local lbl = desc:FindFirstChildWhichIsA("TextLabel", true)
                        if lbl then
                            lbl.Text = "OWNED"
                            lbl.TextColor3 = Color3.fromRGB(0, 255, 120)
                        end
                        for _, img in ipairs(desc:GetDescendants()) do
                            if img:IsA("ImageLabel") then
                                img.Visible = false
                            end
                        end
                        pcall(function() desc.BackgroundColor3 = Color3.fromRGB(20, 160, 60) end)
                    end
                end
                
                if string.find(lname, "speed") then
                    if desc:IsA("NumberValue") or desc:IsA("IntValue") then
                        desc.Value = 120
                    end
                end
                
                if string.find(lname, "lock") or string.find(lname, "buypass") then
                    if desc:IsA("GuiObject") then
                        desc.Visible = false
                        count = count + 1
                    end
                end
                
                if desc:IsA("TextButton") or desc:IsA("ImageButton") then
                    desc.Active = true
                    desc.Selectable = true
                end
            end)
        end
        
        if pg then
            for _, desc in ipairs(pg:GetDescendants()) do
                processStoreItem(desc)
            end
            
            if not _G.BTR_StoreDescendantHook then
                _G.BTR_StoreDescendantHook = pg.DescendantAdded:Connect(function(desc)
                    task.defer(function()
                        processStoreItem(desc)
                    end)
                end)
                table.insert(visualConnections, _G.BTR_StoreDescendantHook)
            end
        end
        
        pcall(function()
            local bag = localPlr:FindFirstChild(_0xS(294))
            if bag then
                for _, v in ipairs(bag:GetChildren()) do
                    if v:IsA("BoolValue") then
                        v.Value = true
                    end
                end
            end
        end)
        safeVisualNotify("Pass Unlocker", "Gamepasses & Premium menus UNLOCKED client-side! (" .. count .. " items modified)", 4)
    end
    local function getOnlinePlayerNames()
        local playersService = game:GetService(_0xS(1))
        local localPlr = playersService.LocalPlayer
        local list = {}
        for _, plr in ipairs(playersService:GetPlayers()) do
            if plr ~= localPlr and not blacklistedKickedPlayers[plr.Name] then
                table.insert(list, plr.Name)
            end
        end
        if #list == 0 then table.insert(list, "None") end
        return list
    end
