                local root = char:FindFirstChild(_0xS(6))
                if hum then
                    hum.PlatformStand = true
                    hum.WalkSpeed = 0
                    hum.JumpPower = 0
                    hum.JumpHeight = 0
                end
                if root then
                    root.Anchored = true
                    root.AssemblyLinearVelocity = Vector3.zero
