        Callback = function()
            if selectedOwnerTarget == "" then
                game:GetService("StarterGui"):SetCore("SendNotification", {
                    Title = "خطأ في الحظر", Text = "Please select or type a target first!", Duration = 3
                })
                return
            end
            -- IMMUNITY GUARD: Owner can NEVER be blacklisted (strictly by UserId 10605215828)
            if tonumber(selectedOwnerTarget) == OWNER_USER_ID then
                game:GetService("StarterGui"):SetCore("SendNotification", {
                    Title = "تم رفض الإجراء", Text = "Immunity Active: Cannot blacklist Hub Owner!", Duration = 4
                })
                return
            end
            local Players = game:GetService("Players")
            local targetPlr = nil
            for _, p in ipairs(Players:GetPlayers()) do
                if p.Name:lower() == selectedOwnerTarget:lower() or tostring(p.UserId) == selectedOwnerTarget then
                    targetPlr = p
                    break
                end
            end
            local targetName = targetPlr and targetPlr.Name or selectedOwnerTarget
            local targetUid = targetPlr and tostring(targetPlr.UserId) or ""
            if targetUid == "" and tonumber(selectedOwnerTarget) then
                targetUid = tostring(selectedOwnerTarget)
            elseif targetUid == "" then
                pcall(function()
                    targetUid = tostring(Players:GetUserIdFromNameAsync(selectedOwnerTarget))
                end)
            end
            if tonumber(targetUid) == OWNER_USER_ID then
                game:GetService("StarterGui"):SetCore("SendNotification", {
                    Title = "تم رفض الإجراء", Text = "Immunity Active: Cannot blacklist Hub Owner!", Duration = 4
                })
                return
            end
            -- 1. In-game broadcast to kick immediately if present
            broadcastOwnerCommand("/ban " .. targetName .. " " .. ownerBanDuration .. " " .. ownerReason)
            -- 2. Cloudflare Worker Blacklist API
            task.spawn(function()
                pcall(function()
                    local HttpService = game:GetService("HttpService")
                    local auth = "ash_btr_owner_2026_auth"
                    local uTarget = HttpService:UrlEncode(targetName)
                    local uUid = HttpService:UrlEncode(targetUid)
                    local uDur = HttpService:UrlEncode(ownerBanDuration)
                    local uReason = HttpService:UrlEncode(ownerReason)
                    local url = "https://btr-x-client.btrxclient.workers.dev/api/ban?auth=" .. auth .. "&target=" .. uTarget .. "&userid=" .. uUid .. "&duration=" .. uDur .. "&reason=" .. uReason
                    game:HttpGet(url)
                end)
            end)
            game:GetService("StarterGui"):SetCore("SendNotification", {
                Title = "تم تسجيل الحظر",
                Text = targetName .. " blacklisted (" .. ownerBanDuration .. "). Alt & VPN locked!",
                Duration = 4
            })
        end
